1	// The one vendored place that computes a repo's stable scheduler cron MINUTE
2	// (docs/PRINCIPLES.md). The per-repo scheduler workflow runs on its own cron
3	// on a repo-hashed minute constrained to :10–:50 — spreading the fleet across the
4	// band, dodging GitHub's :00 stampede, and staying clear of the hour boundary the
5	// anchor arithmetic works from.
6	//
7	// This is the minute the stub's placeholder (`cron: '10 * * * *'`) is rewritten to
8	// when the workflow lands in a repo: bootstrap assigns it, and the update flows'
9	// self-refresh preserves it (the one repo-specific value in the otherwise-identical
10	// vendored stub). Deriving it from the full name — not storing it — means any
11	// session can recompute the canonical value and detect drift.
12	//
13	// Self-contained by the engine's module rule: imports nothing, so bootstrap, the
14	// update runner, and a human can load or run it standalone.
15	
16	// The inclusive minute band. 41 slots (10..50) — the widest window that clears the
17	// :00 stampede and the hour boundary on both sides.
18	export const MINUTE_MIN = 10;
19	export const MINUTE_MAX = 50;
20	const BAND = MINUTE_MAX - MINUTE_MIN + 1; // 41
21	
22	// FNV-1a over the lowercased full name → a minute in [MINUTE_MIN, MINUTE_MAX].
23	// Same hash family as the retired central planner's weekday bucket: deterministic,
24	// well-spread, and Math.imul keeps the multiply in 32-bit range. Keyed on the repo
25	// full name ("owner/repo") so the value is stable across re-vendors and re-derivable
26	// anywhere the name is known.
27	function hashOf(fullName) {
28	  let h = 0x811c9dc5;
29	  const s = String(fullName).toLowerCase();
30	  for (let i = 0; i < s.length; i += 1) {
31	    h ^= s.charCodeAt(i);
32	    h = Math.imul(h, 0x01000193);
33	  }
34	  return h >>> 0;
35	}
36	
37	export function hashedMinute(fullName) {
38	  return MINUTE_MIN + (hashOf(fullName) % BAND);
39	}
40	
41	// THE CRON LINE a repo's scheduler workflow carries, minute and hours both derived
42	// from the repo's own name. TWO TICKS A DAY (PRINCIPLES.md): the anchor tick, and the
43	// drain tick twelve hours later for the work that has no period of its own, adopting a
44	// marked issue, releasing a `Not-before:`, reclaiming a dead claim.
45	//
46	// THE HOUR IS HASHED, NOT CONFIGURED (#1995). It used to come from the repo's own
47	// `taskScheduler.dailyHour`, which existed to order members ahead of the canon by an
48	// hour; this repo's own record showed Actions firing up to 78 minutes off schedule
49	// across one week, so the stagger never guaranteed the order it was there for. Hashing
50	// it spreads the fleet across the clock, which is the only thing the knob reliably did.
51	//
52	// Hours 0 through 11 for the anchor, so the drain always lands on a different hour of
53	// the same day. Shifted off the minute's own bits so two repos sharing a minute rarely
54	// share an hour.
55	const ANCHOR_HOURS = 12;
56	export const hashedHours = (fullName) => {
57	  const anchor = (hashOf(fullName) >>> 8) % ANCHOR_HOURS;
58	  return { anchor, drain: anchor + ANCHOR_HOURS };
59	};
60	
61	// WRITTEN ONCE, AT SCAFFOLD. The update preserves whatever cron a repo's workflow
62	// already carries (converge-workflows.mjs), because `.github/workflows/` lands only
63	// through a pull request a person merges: restamping it would put every member's
64	// scheduler behind a human gate every time this derivation changed.
65	export const hashedCron = (fullName) => {
66	  const { anchor, drain } = hashedHours(fullName);
67	  return `${hashedMinute(fullName)} ${anchor},${drain} * * *`;
68	};
69	
70	// The shape a scheduler cron must have for the update to keep it: a minute in the
71	// band, and two hours twelve apart. Anything else is not a cron this repo wrote.
72	const CRON_RE = /^(\d{1,2}) (\d{1,2}),(\d{1,2}) \* \* \*$/;
73	export function isSchedulerCron(text) {
74	  const m = CRON_RE.exec(String(text ?? '').trim());
75	  if (!m) return false;
76	  const [minute, anchor, drain] = m.slice(1).map(Number);
77	  return minute >= MINUTE_MIN && minute <= MINUTE_MAX
78	    && anchor >= 0 && anchor < ANCHOR_HOURS && drain === anchor + ANCHOR_HOURS;
79	}
80	
81	// CLI: `node hash-minute.mjs <owner/repo>` prints the minute (bootstrap / update
82	// use this to stamp or verify the workflow's cron without re-implementing the hash).
83	if (import.meta.url === `file://${process.argv[1]}`) {
84	
85	  const fullName = process.argv[2];
86	  if (!fullName) {
87	    process.stderr.write('usage: node hash-minute.mjs <owner/repo>\n');
88	    process.exitCode = 2;
89	  } else {
90	    process.stdout.write(`${hashedMinute(fullName)}\n`);
91	  }
92	}
