1	// The delivery lane, published for every pack: how a task's output becomes a landed
2	// pull request or a regenerated file, honoring the repo's delivery settings.
3	//
4	// TWO HALVES. `deliverGenerated` and its helpers are DEFINED here — the write half of
5	// an agentless task whose whole output is a regenerated file, which this pack's own
6	// fold workers and any other pack's use alike. The five landing names below it are
7	// the executor's own lane (`src/deliver/land-pr.mjs`), re-exported for a worker that
8	// lands its own pull request the way the executor would.
9	//
10	// Deliver GENERATED files on a pull request that lands itself. It exists because two tasks need exactly this and must not each grow their own
11	// copy: the per-repo skill-usage fold and the fleet-enforcer's cross-repo aggregate both
12	// recompute a `*.GENERATED.json` from scratch and want it landed without a human in
13	// the loop. (the update runner's own delivery is deliberately NOT folded in here: it
14	// commits a whole working tree from a checkout it converged in place — a
15	// different job that happens to end in a PR too. What the two DO share — every
16	// nuance of actually landing the PR under the member's `maintenance.delivery` and
17	// the repo's own shape — lives in land-pr.mjs, and both call it.)
18	//
19	// Two properties everything here is shaped around:
20	//
21	//   NOTHING TOUCHES THE CHECKOUT. One executor run drains several items from ONE
22	//   checkout, so a task that checks a branch out hands the next one a tree it did not
23	//   expect.
24	//   Every write goes through git plumbing (hash-object / read-tree into a throwaway
25	//   index / write-tree / commit-tree / push), against the fetched base tip — HEAD,
26	//   the index and the working tree are never touched, and there is nothing to clean
27	//   up if the run dies.
28	//
29	//   THE BASE IS THE ONLY AUTHORITY. Both the prior state a generator reads and the
30	//   tree it builds on come from the remote base branch, never from local HEAD. A
31	//   previous run's PR still sitting open is simply rebuilt from the base, so a
32	//   stateless generator stays idempotent no matter how many runs stack up. The
33	//   member's delivery preference is read from the base too, for the same reason.
34	//
35	// Idempotence is the caller's to keep: pass files whose content is a pure function of
36	// the inputs, and compare against `readAtBase` before calling — an identical
37	// recompute should open nothing at all.
38	
39	import { rmSync } from 'node:fs';
40	import { tmpdir } from 'node:os';
41	import { join } from 'node:path';
42	import { deliveryForText, pullCreateError, landDelivery } from '../src/deliver/land-pr.mjs';
43	import { SETTINGS_FILE } from '../../../engine/settings-file.mjs';
44	import { withTaskTrailer } from './work-item-grammar.mjs';
45	import { restCall } from './github.mjs';
46	import { runGit } from '../src/world/processes.mjs';
47	import { nowMs } from '../src/world/clock.mjs';
48	import { actionsEnv } from '../src/world/actions.mjs';
49	
50	// This lane runs git in the checkout and calls GitHub with the run's own token;
51	// both go through the world's ports, which is what keeps the REST paths and the
52	// subprocess in one place.
53	const git = (root, args, opts = {}) => runGit(['-C', root, ...args], opts);
54	
55	const gh = (token, path, opts) => restCall(token, path, opts);
56	
57	export const remoteUrl = (repo, token) => `https://x-access-token:${token}@github.com/${repo}.git`;
58	
59	// The base branch's remote tip, fetched into this checkout's object store. Read from
60	// the REMOTE, never from HEAD — see the header.
61	export function baseTip(root, remote, base) {
62	  git(root, ['fetch', '--quiet', remote, base]);
63	  return git(root, ['rev-parse', 'FETCH_HEAD']).trim();
64	}
65	
66	// One file's content at a commit, or null when the path does not exist there.
67	export function readAt(root, sha, path) {
68	  try { return git(root, ['show', `${sha}:${path}`]); } catch { return null; }
69	}
70	
71	// Commit `files` ({ path: content }) onto the base tip and push to `branch`,
72	// force — the content is regenerated wholesale each run, so the branch is a
73	// regenerate-not-reconcile surface.
74	export function pushGenerated(root, { remote, baseSha, branch, files, message }) {
75	  const index = join(tmpdir(), `claudinite-deliver-${process.pid}-${nowMs()}.index`);
76	  const plumb = (args, opts) => git(root, args, { ...opts, env: { ...actionsEnv(), GIT_INDEX_FILE: index } });
77	  try {
78	    plumb(['read-tree', baseSha]);
79	    for (const [path, content] of Object.entries(files)) {
80	      const blob = git(root, ['hash-object', '-w', '--stdin'], { input: content }).trim();
81	      plumb(['update-index', '--add', '--cacheinfo', `100644,${blob},${path}`]);
82	    }
83	    const tree = plumb(['write-tree']).trim();
84	    const commit = git(root, [
85	      '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
86	      'commit-tree', tree, '-p', baseSha, '-m', message,
87	    ]).trim();
88	    git(root, ['push', '--quiet', '--force', remote, `${commit}:refs/heads/${branch}`]);
89	    return commit;
90	  } finally { rmSync(index, { force: true }); }
91	}
92	
93	// Which branch the regenerate lands on and which pull request it updates — THE
94	// EXECUTOR'S DECISION, handed in (docs/PRINCIPLES.md): `branch` is the
95	// one it resolved, `pr` the open pull request it said to amend, or null for a fresh
96	// one on that branch. A named pull request the open list no longer carries was
97	// closed under the run; the branch is still the one to push to, and a new pull
98	// request opens on it.
99	//
100	// The branch is REQUIRED. The lane used to reuse an open pull request whose head
101	// carried a prefix and mint `<prefix>/<stamp>` where it found none — a second
102	// decision site beside the executor's, held only while a member's vendored executor
103	// could predate the hand-off (#1698). An outcome that opens a pull request always
104	// resolves one, so an absent branch is a caller the executor is not driving, and
105	// delivering on a branch nothing is watching is worse than saying so.
106	export function generatedTarget({ pulls, branch = null, pr = null }) {
107	  if (!branch) {
108	    throw new Error('no branch to deliver on — the executor resolves it and hands it in as CLAUDINITE_TARGET_BRANCH');
109	  }
110	  const open = Array.isArray(pulls) ? pulls : [];
111	  const named = pr == null ? null : open.find((p) => p.number === Number(pr)) ?? null;
112	  return { branch, pr: named, reused: Boolean(named) };
113	}
114	
115	// Deliver `files` on a PR that lands itself where the member allows it, on the
116	// branch and pull request the executor resolved (`branch`, `pr` — see
117	// `generatedTarget`): amending an open pull request updates it in place, so a
118	// daily regenerate that runs before yesterday's merged does not stack a second one.
119	//
120	// How the PR lands is land-pr.mjs's business, not the calling task's: the member's
121	// `dailyClaudiniteUpdatesRequirePrReview` (read from the BASE tip — a repo that
122	// declares it gets its PR opened and left for the owner), then the repo's own shape (no PR CI → direct merge; ungated base → verify-then-
123	// land; a gate → arm auto-merge, landing poll as fallback). A PR this run could not
124	// land stays open — the next run rebuilds it from the base, so nothing is lost.
125	//
126	// Returns { branch, number, reused, delivery, merged }.
127	export async function deliverGenerated({ root, repo, base, token, branch: targetBranch = null, pr: targetPr = null, files, title, body, message, task = null, log = console.log }) {
128	  const { json: pulls } = await gh(token, `/repos/${repo}/pulls?state=open&per_page=100`);
129	  const chosen = generatedTarget({ pulls, branch: targetBranch, pr: targetPr });
130	  let { pr } = chosen;
131	  const { branch, reused } = chosen;
132	  const remote = remoteUrl(repo, token);
133	
134	  const baseSha = baseTip(root, remote, base);
135	  // The member's delivery override gates everything after the push, read from the
136	  // BASE tip.
137	  const settingsText = readAt(root, baseSha, SETTINGS_FILE);
138	  const delivery = deliveryForText(settingsText);
139	
140	  // Every commit this lane writes says which task wrote it. That trailer is what
141	  // the movement signals classify as machinery rather than the project moving, so
142	  // one task's delivery can never be the activity that wakes another.
143	  const commit = pushGenerated(root, { remote, baseSha, branch, files, message: withTaskTrailer(message, task) });
144	
145	  if (!reused) {
146	    const created = await gh(token, `/repos/${repo}/pulls`, { method: 'POST', body: { head: branch, base, title, body } });
147	    const failure = pullCreateError(created.status, created.json);
148	    if (failure) throw new Error(`opening the pull request for ${branch}: ${failure}`);
149	    pr = created.json;
150	  }
151	
152	  let merged = false;
153	  if (pr?.number) {
154	    // Runs for review members too: landDelivery still starts the PR's checks
155	    // (#565 — the GITHUB_TOKEN push emitted no pull_request run, and the owner
156	    // reviews against a green), then does nothing further for `review`.
157	    // The head sha must be THIS run's commit: a reused PR's listing still carries
158	    // the previous push, and polling a stale sha waits on runs that never come.
159	    const landed = await landDelivery({
160	      token, repo, base, delivery, log, task,
161	      pr: { ...pr, head: { ...pr.head, ref: branch, sha: commit } },
162	    });
163	    merged = landed.merged;
164	  }
165	  return { branch, number: pr?.number ?? null, reused, delivery, merged };
166	}
167	
168	// --- the landing lane, re-exported -----------------------------------------------
169	export {
170	  deliveryFor, landDelivery, pullCreateError,
171	} from '../src/deliver/land-pr.mjs';
172

1	// THE SECURITY CHECK for the request implementer, as a precondition term — the
2	// one gate that decides whether a marked issue actually runs. It happens where
3	// every verdict happens: once, at pickup, on the executor (docs/PRINCIPLES.md
4	// PRINCIPLES.md). It is task-local because its subject is one named issue rather than a
5	// window of repo activity, which is also why the term reads the `item` it is
6	// handed.
7	//
8	// Three refusals, each a plain no-go that converges the item to the rejected
9	// terminal — a refusal is nobody's inbox, and an ad-hoc item has no anchor to
10	// roll to. The terminal closes the issue it stands on, marked or filed: nothing
11	// ran and nothing will, so there is no question left open (PRINCIPLES.md).
12	//
13	// A READ FAILURE IS NOT A VERDICT (F27). The decline's write-back cannot reach an
14	// issue it cannot read, so declining on a rate limit or a 500 would strand the
15	// mark on the issue forever over nothing — the request silently eaten. Only a
16	// definitive `gone` declines; anything else ERRORS, which parks the item open in
17	// the failure lane where the ordinary re-queue lever retries it.
18	
19	// Push permission, as the permission API answers it. `triage` and `read` are
20	// deliberately not here: the ask was push access, and a read-only collaborator
21	// rides every webhook payload as `COLLABORATOR` (F30).
22	export const PUSH_PERMISSIONS = ['admin', 'maintain', 'write'];
23	
24	// Who, if anyone, with push access asked for this. Pure over the `request`
25	// signal's read, so the judgment is testable without GitHub and the reads stay
26	// where every other read is.
27	export function eligibility(req) {
28	  if (PUSH_PERMISSIONS.includes(req.authorPermission)) {
29	    return { ok: true, why: `opened by @${req.author}, who has push access` };
30	  }
31	  const blessed = (req.approvals ?? []).find((a) => PUSH_PERMISSIONS.includes(a.permission));
32	  if (blessed) return { ok: true, why: `approved by @${blessed.login} with \`/claude go\`` };
33	  return { ok: false, why: 'neither opened nor approved with `/claude go` by anyone with push access on this repository' };
34	}
35	
36	export const terms = {
37	  'request-eligible': {
38	    signals: ['request'],
39	    // About one named issue, so there is nothing to judge at the scheduler's own
40	    // ask — which is why this task declares `trigger: 'request'` and runs only from
41	    // a marked issue. The shape check holds the two together.
42	    needsItem: true,
43	    holds(signals, { item }) {
44	      const req = signals.request;
45	      if (!req) {
46	        return { error: `this item names no readable request (its \`Request:\` field is ${item?.request ? `#${item.request}` : 'missing'})` };
47	      }
48	      if (req.unreadable) return { error: `issue #${req.number} could not be read: ${req.error} — refusing to guess` };
49	      if (req.gone) return { holds: false, reason: `issue #${req.number} does not exist` };
50	      if (req.state !== 'open') return { holds: false, reason: `issue #${req.number} was closed before this ran` };
51	      if (!req.queued) {
52	        return { holds: false, reason: `issue #${req.number} no longer carries the mark — the request was withdrawn` };
53	      }
54	      const verdict = eligibility(req);
55	      // No `context`: adoption already bound this item to its issue, and a second
56	      // line saying the same thing renders as two near-identical bullets in the one
57	      // section the session is told to read as its scope (#1074/#1075).
58	      return { holds: verdict.ok, reason: `#${req.number}: ${verdict.why}` };
59	    },
60	  },
61	};
