1	// Code-work, executor-side (docs/PRINCIPLES.md). The contract is
2	// unchanged from the slot mechanism — a subprocess with the task dir as cwd, the
3	// declared `code_work_required_secrets` as environment, a hard timeout, and the conditional
4	// `CLAUDINITE_REQUEST_AGENT` hand-off — so this module is a thin adapter that
5	// gives the queue's item identity where the slot id used to go, and adds the two
6	// things the queue states explicitly:
7	//
8	//  - RE-ENTRANCY IS THE REQUIREMENT, NOT IDEMPOTENCY (PRINCIPLES.md). A dead executor's
9	//    claim is reclaimed and the item re-picked, so code-work can run again over its
10	//    own half-done work. That is convergence — check what exists, continue from
11	//    there — and it was always true of code-work; the contract simply never said so.
12	//    Since the heartbeat replaced the run cap (PRINCIPLES.md), overlap is no longer
13	//    excluded by construction: a partitioned runner keeps working while its beats
14	//    fail to post, its claim is reclaimed on that silence, and the replacement
15	//    starts. Re-entrancy is what makes that safe, which is why it is the contract.
16	//  - A DECLARED SECRET THAT IS NOT CONFIGURED IS NAMED, NOT GUESSED AT (PRINCIPLES.md).
17	//    Code-work is the only task code that ever sees a secret VALUE, so this is the
18	//    one place that can tell "unset" from "empty", and the item converges to
19	//    triage naming exactly which one is missing.
20	
21	import { fileURLToPath } from 'node:url';
22	import { runCodeWork, codeWorkFailure, agentRequestPath, clearAgentRequest, agentRequested, readAgentRequest, readTriageMarker, readRequeueMarker } from './code-work.mjs';
23	import { SECRETS_BAG_ENV, secretsBag, secretValue, secretsFor } from '../world/secrets-bag.mjs';
24	import { VARS_BAG_ENV, varsEnv } from '../world/vars-bag.mjs';
25	import { targetEnv } from './target.mjs';
26	import { actionsEnv } from '../world/actions.mjs';
27	
28	// The declared secrets this environment does not carry. Absent is missing; a
29	// set-but-empty one is the repo's own choice and is passed through. Read through
30	// the bag, which also answers for a legacy workflow that still stamps by name.
31	export const missingSecrets = (names = [], env = actionsEnv()) =>
32	  names.filter((n) => secretValue(n, env) === undefined);
33	
34	// The environment a task's work step runs under: this job's, minus every secret, plus
35	// the ones this task declared, plus every repository variable.
36	//
37	// The two bags are treated differently on purpose. Secrets are SELECTED — the bag
38	// carries the whole repository's, and a task's blast radius should be the list it wrote
39	// down (#1336). Variables are not: `vars` is non-sensitive by construction, so there is
40	// no blast radius to narrow and a declaration would buy nothing but a second place to
41	// keep in sync. vars-bag.mjs states why they are additive rather than overriding.
42	//
43	// Under a workflow that names its secrets there is no bag to subtract, so the stamped
44	// names stay inherited until that member's own executor workflow lands; the fallback in
45	// secrets-bag.mjs states the retirement condition. Neither raw blob is ever handed on.
46	export function taskEnv(names = [], env = actionsEnv()) {
47	  const out = { ...env };
48	  delete out[SECRETS_BAG_ENV];
49	  delete out[VARS_BAG_ENV];
50	  for (const name of Object.keys(secretsBag(env) ?? {})) delete out[name];
51	  return { ...out, ...varsEnv(env), ...secretsFor(names, env) };
52	}
53	
54	// The CLAUDINITE_* variables code-work is handed, and the whole of them: a worker
55	// reading any other one is reading something nobody sets, which is silent and
56	// permanent (a `CLAUDINITE_OVERRIDES` left over from the slot scheduler read as an
57	// empty bag, so a fleet sweep's REPOS filter and DRY_RUN switch were inert and
58	// every run was unscoped and live — #974).
59	//
60	// Built as one object so the NAMES cannot drift from what is actually passed:
61	// `CODE_WORK_ENV_VARS` below is this function's own key set, and the check that
62	// polices task workers reads it rather than a hand-kept list.
63	export const codeWorkEnv = ({ root, repo, defaultBranch, task, item, context = [], requestPath, target = null }) => ({
64	  CLAUDINITE_REPO_ROOT: root,
65	  CLAUDINITE_REPO: repo,
66	  CLAUDINITE_DEFAULT_BRANCH: defaultBranch ?? '',
67	  // The item's identity where the slot id used to be: the queue has no slot, and
68	  // the issue number IS the occurrence (PRINCIPLES.md).
69	  CLAUDINITE_ITEM: String(item.number),
70	  CLAUDINITE_PACK: task.pack,
71	  CLAUDINITE_TASK: task.id,
72	  // The item's binding scope, one line per Context bullet — and the channel an
73	  // operator's parameters ride (PRINCIPLES.md).
74	  CLAUDINITE_CONTEXT: context.join('\n'),
75	  CLAUDINITE_REQUEST_AGENT: requestPath,
76	  // WHICH BRANCH AND PULL REQUEST THIS RUN WORKS ON (PRINCIPLES.md), decided by the
77	  // executor before this subprocess started. A worker pushes to the branch and
78	  // opens or updates the pull request it is told about — never finds one itself.
79	  ...targetEnv(target),
80	});
81	
82	export const CODE_WORK_ENV_VARS = Object.freeze(
83	  Object.keys(codeWorkEnv({ task: { pack: '', id: '' }, item: { number: 0 }, requestPath: '' })),
84	);
85	
86	// The command this phase actually spawns. A `code_work` declaration IS the command;
87	// a `code_worker_mjs` one names a module, and the command is the runner's own entry
88	// point around it - which is the whole point of the field: the wrapping is ours to
89	// write once rather than every worker's to re-implement (worker-entry.mjs).
90	//
91	// The entry point is addressed absolutely because the subprocess runs with the TASK
92	// directory as cwd, and it is resolved from this module's own URL so the path holds
93	// wherever the pack is mounted. Both parts are quoted: the command goes through a
94	// shell, and a checkout path can carry a space.
95	export function codeWorkCommand(decl) {
96	  if (decl.code_worker_mjs === undefined) return decl.code_work;
97	  const entry = fileURLToPath(new URL('./worker-entry.mjs', import.meta.url));
98	  return `node "${entry}" "${decl.code_worker_mjs}"`;
99	}
100	
101	export function codeWorkRunner({ root, repo, defaultBranch, env = actionsEnv() }) {
102	  return async function runFor(task, { item, context = [], target = null }) {
103	    const missing = missingSecrets(task.decl.code_work_required_secrets ?? [], env);
104	    if (missing.length) return { ok: true, agentRequested: false, missingSecrets: missing };
105	
106	    const requestPath = agentRequestPath({ pack: task.pack, task: task.id, slotId: `item-${item.number}` });
107	    clearAgentRequest(requestPath);
108	
109	    console.log(`::group::code_work ${task.pack}/${task.id} [#${item.number}]`);
110	    const result = await runCodeWork(codeWorkCommand(task.decl), {
111	      taskDir: task.taskDir,
112	      env: { ...taskEnv(task.decl.code_work_required_secrets ?? [], env), ...codeWorkEnv({ root, repo, defaultBranch, task, item, context, requestPath, target }) },
113	      timeoutSeconds: task.decl.code_work_timeout,
114	    });
115	    console.log('::endgroup::');
116	
117	    if (!result.ok) {
118	      clearAgentRequest(requestPath);
119	      const tail = result.stderr?.trim().split('\n').slice(-5).join('\n') ?? '';
120	      // Repeated OUTSIDE the group: Actions renders a group collapsed, so a failure
121	      // whose only evidence sits inside one still reads as unexplained.
122	      if (tail) console.log(tail);
123	      // The worker's own verdict on its failure, if it left one — read over BOTH
124	      // streams, since a marker is a diagnosis and workers print those wherever
125	      // they print everything else.
126	      return { ok: false, why: codeWorkFailure(result), detail: tail, triage: readTriageMarker(`${result.stdout}\n${result.stderr}`) };
127	    }
128	
129	    const requested = agentRequested(requestPath);
130	    const payload = requested ? readAgentRequest(requestPath) : null;
131	    clearAgentRequest(requestPath);
132	    return {
133	      ok: true,
134	      agentRequested: requested,
135	      // The worker's come-back-later ask, honoured only on this OK path — a failed
136	      // run is a failure whatever it printed. Read over both streams like the
137	      // triage marker, and null for the workers that never ask, which is all of
138	      // them before #1530.
139	      requeue: readRequeueMarker(`${result.stdout}\n${result.stderr}`),
140	      delivered: deliveredLines(payload?.delivered),
141	      // The unmerged PR, structured, beside its rendered line: an item whose run
142	      // left one parks for approval instead of closing, and that decision cannot
143	      // be made off a prose line.
144	      openPr: payload?.delivered?.pr && !payload.delivered.merged ? payload.delivered.pr : null,
145	      // The pull request this run delivered, open OR merged — what a supersede's
146	      // incumbents were waiting to be replaced by, whichever way it landed.
147	      deliveredPr: payload?.delivered?.pr ?? null,
148	      reason: payload?.reason ? (payload.reason.detail || payload.reason.code) : null,
149	    };
150	  };
151	}
152	
153	// What code-work created, by identity — the agent's only source for those
154	// artifacts, and (absent an agent) what makes an outcome `delivered` rather than
155	// `done`. Absence is meaningful: a worker that created nothing writes no
156	// `delivered`, and the item then says nothing about artifacts rather than
157	// asserting something false.
158	export function deliveredLines(delivered) {
159	  const { branch = null, pr = null, merged = false, issue = null } = delivered ?? {};
160	  const out = [];
161	  if (pr) out.push(`PR: #${pr}${merged ? ' (already merged — open your own PR for further work)' : ' (open)'}`);
162	  if (branch) out.push(`Branch: \`${branch}\``);
163	  // An ISSUE this run resolved for the agent to write to — a task's standing
164	  // tracker, typically, found or created by its own code-work. Rendered for the same
165	  // reason a PR number is: the agent's only source for it is this line, and without
166	  // it a worker that took the trouble to resolve one hands over nothing.
167	  if (issue) out.push(`Issue: #${issue} — write this run's record there.`);
168	  return out;
169	}
