1	// The precondition engine (docs/PRINCIPLES.md): may THIS task run now? A
2	// task declares `preconditions` — a list of named conditions — and this module
3	// turns that declaration plus the collected signals into a verdict. Sibling of
4	// merge-policy.mjs beside it, and deliberately its mirror image in two ways:
5	//
6	//   THE LIST IS A CONJUNCTION. `['X', 'Y || Z']` is `X && (Y || Z)`. An automerge
7	//   policy GRANTS, so its comma is a union; preconditions REQUIRE, so the comma
8	//   is `&&` and `||` lives inside one entry. Each field then reads against its
9	//   own English.
10	//
11	//   IT FAILS LOUD, NOT CLOSED. An unresolvable merge policy authorizes nothing,
12	//   which parks a PR in front of a person. An unresolvable precondition that
13	//   declined would be permanent, silent staleness — nothing goes red when a task
14	//   stops running — so an unknown term, a malformed argument or an unreadable
15	//   signal returns `{ error }`, a failed run in the queue's failure lane.
16	//
17	// THE EXPRESSION IS WHAT MUST HOLD, NEVER WHO ASKS (docs/PRINCIPLES.md). The
18	// engine keeps no calendar: every scheduler tick asks every task whose declaration
19	// says `trigger: 'schedule'`, and the cadence such a task keeps is one of its own
20	// conditions, read off its own run history, `schedule:at-most-<cadence>`, beside
21	// whatever else it requires. The same conditions are judged, identically, at the
22	// pick of an item somebody created, so this module never asks which of the two
23	// happened. `none` is retired: a task with nothing to require states no condition,
24	// and the empty expression holds.
25	//
26	// THE VOCABULARY HAS TWO HOMES. The built-ins below are the run-history, movement
27	// and pending-PR conditions every repo shares. A task whose gate is its own ships a
28	// `preconditions.mjs` beside its `task.json` exporting `terms`, resolved after the
29	// built-ins in one flat namespace where a collision is loud — so the declaration
30	// and the gate it names are one directory apart.
31	//
32	// Import-light and pure over the signals: no I/O, so the same evaluation runs at
33	// the scheduler's tick and at the executor's pick.
34	
35	import {
36	  anchorInstant, cadenceOfScheduleArg, scheduleTermFor, AT_MOST_PREFIX, CADENCES,
37	  DUE_TERM, SCHEDULE_TERM, NOT_FAILED_TERM, NOT_PARKED_TERM,
38	} from './calendar.mjs';
39	
40	// The retired empty precondition. A declaration requiring nothing says so by
41	// stating no conditions at all; the word on its own is an error, named below.
42	export const NONE = 'none';
43	
44	const ALTERNATIVE = '||';
45	
46	// How many paths or numbers a term's context names before it says how many it
47	// dropped. A window can carry more files than one session should read, and a
48	// silently truncated list reads as the whole window.
49	export const MAX_CONTEXT_ITEMS = 40;
50	
51	// --- the grammar --------------------------------------------------------------
52	
53	// One term reference: its name, and the inline argument after its first colon
54	// (`commits-under:.claudinite/local`). The rest of the string is the argument
55	// verbatim, so a path argument may itself contain colons.
56	function parseTerm(text) {
57	  const raw = String(text ?? '').trim();
58	  const colon = raw.indexOf(':');
59	  return colon === -1
60	    ? { name: raw, arg: null, text: raw }
61	    : { name: raw.slice(0, colon).trim(), arg: raw.slice(colon + 1).trim(), text: raw };
62	}
63	
64	// Parse a declaration into `{ kind: 'conditions', conditions }` (each condition an
65	// array of alternatives) or `{ kind: 'invalid', reason }`. Names are not resolved
66	// here — that needs the task's own terms, which the static check and the
67	// evaluator each supply.
68	export function parsePreconditions(preconditions) {
69	  const invalid = (reason) => ({ kind: 'invalid', reason });
70	  if (!Array.isArray(preconditions)) {
71	    return invalid('it is not an array of condition strings');
72	  }
73	  if (!preconditions.every((e) => typeof e === 'string' && e.trim() !== '')) {
74	    return invalid('every entry must be a non-empty string');
75	  }
76	  const conditions = preconditions.map((entry) => String(entry).split(ALTERNATIVE).map(parseTerm));
77	  if (conditions.some((alts) => alts.some((t) => t.name === ''))) {
78	    return invalid(`an alternative around "${ALTERNATIVE}" is empty`);
79	  }
80	  if (conditions.flat().some((t) => t.name === NONE)) {
81	    return invalid(`"${NONE}" is retired. A task with no condition states none: leave "preconditions" out, and the task runs only from an item somebody creates. Otherwise state when it runs: a cadence (\`${scheduleTermFor('daily')}\`) or the movement it waits for`);
82	  }
83	  return { kind: 'conditions', conditions };
84	}
85	
86	// The task's own terms, as a Map, from whatever its `preconditions.mjs` exported.
87	// A non-object export is no terms at all rather than a crash; the shape check is
88	// what reports it.
89	export function termsMap(exported) {
90	  if (exported instanceof Map) return exported;
91	  if (exported && typeof exported === 'object') return new Map(Object.entries(exported));
92	  return new Map();
93	}
94	
95	// Resolve a term name: built-ins first, then the task's own.
96	export const resolveTerm = (name, taskTerms) => BUILTIN_TERMS.get(name) ?? taskTerms?.get?.(name) ?? null;
97	
98	// --- the signal union, derived ------------------------------------------------
99	
100	// Every signal the expression's terms read. The collector union cannot disagree
101	// with what the gate actually consults, because it IS what the gate consults —
102	// which a separately declared list could not guarantee.
103	export function preconditionSignals(preconditions, taskTerms) {
104	  const parsed = parsePreconditions(preconditions);
105	  if (parsed.kind !== 'conditions') return [];
106	  const out = new Set();
107	  for (const ref of parsed.conditions.flat()) {
108	    for (const s of resolveTerm(ref.name, taskTerms)?.signals ?? []) out.add(s);
109	  }
110	  return [...out];
111	}
112	
113	// Whether the expression reads the item itself — a term declaring `needsItem`
114	// (the request implementer's `request-eligible`, about one named issue). The
115	// scheduler's own ask has no item, so there is nothing to judge such a task
116	// against at a tick: it runs only from an item somebody created.
117	export function preconditionNeedsItem(preconditions, taskTerms) {
118	  const parsed = parsePreconditions(preconditions);
119	  if (parsed.kind !== 'conditions') return false;
120	  return parsed.conditions.flat().some((ref) => resolveTerm(ref.name, taskTerms)?.needsItem === true);
121	}
122	
123	// --- static validation --------------------------------------------------------
124	
125	// Everything about a declaration that is decidable without signals: the grammar,
126	// the term names, their arguments, and a task-local term shadowing a built-in.
127	// Returns `{ what, fix }` problems — empty means well-formed.
128	export function validatePreconditions(preconditions, taskTerms = new Map()) {
129	  const problems = [];
130	  const bad = (what, fix) => problems.push({ what, fix });
131	  for (const name of taskTerms.keys?.() ?? []) {
132	    if (BUILTIN_TERMS.has(name)) {
133	      bad(`the task's preconditions.mjs redefines the built-in term "${name}"`,
134	        `rename the task-local term — the term namespace is flat, and the built-ins are: ${[...BUILTIN_TERMS.keys()].join(', ')}`);
135	    }
136	  }
137	  const parsed = parsePreconditions(preconditions);
138	  if (parsed.kind === 'invalid') {
139	    bad(`"preconditions" is not a legal expression: ${parsed.reason}`,
140	      `write a list of conditions, all of which must hold, a cadence first where the task keeps one ("${SCHEDULE_TERM}:${AT_MOST_PREFIX}<daily|weekly|monthly>"), then what it waits for, e.g. ["${scheduleTermFor('weekly')}", "substantive-change", "no-open-pr-titled:My sweep"]; a task that runs only from an item somebody creates states no "preconditions" at all`);
141	    return problems;
142	  }
143	  for (const ref of parsed.conditions.flat()) {
144	    const term = resolveTerm(ref.name, taskTerms);
145	    if (!term) {
146	      bad(`"preconditions" names the unknown condition "${ref.name}"`,
147	        `use a built-in (${[...BUILTIN_TERMS.keys()].join(', ')}) or a term this task's preconditions.mjs exports`);
148	      continue;
149	    }
150	    const argProblem = argumentProblem(term, ref);
151	    if (argProblem) bad(argProblem.what, argProblem.fix);
152	  }
153	  return problems;
154	}
155	
156	// A term's argument, judged statically: present where it takes one, absent where
157	// it does not, and — for a term that names its legal values — one of them. The
158	// evaluator asks the same question, so an author-time finding and a run-time
159	// error can never disagree about a declaration.
160	function argumentProblem(term, ref) {
161	  if (term.takesArg && !ref.arg) {
162	    return { what: `the precondition "${ref.name}" takes an inline argument and was given none`, fix: `write it as "${ref.name}:<${term.argName ?? 'value'}>"` };
163	  }
164	  if (!term.takesArg && ref.arg !== null) {
165	    return { what: `the precondition "${ref.name}" takes no argument but was given "${ref.arg}"`, fix: `write it as "${ref.name}"` };
166	  }
167	  if (term.takesArg && term.argOk && !term.argOk(ref.arg)) {
168	    return { what: `"${ref.name}" takes ${term.argHint}, not "${ref.arg}"`, fix: `write it as "${ref.name}:<${term.argName ?? 'value'}>" — ${term.argHint}` };
169	  }
170	  return null;
171	}
172	
173	// --- the built-in vocabulary --------------------------------------------------
174	// A term is `{ signals, takesArg?, argName?, holds(signals, opts) }`, where
175	// `holds` returns `{ holds, reason?, context? }` or `{ error }`. `opts` carries
176	// the inline `arg`, the pack's `config`, this occurrence's `item` fields,
177	// `windowDays` — the lookback the signals were collected over, which the
178	// dimensions with no windowed field of their own (the logs branch) need — and
179	// `now`, the instant this verdict is being taken at.
180	//
181	// `now` is passed rather than read, because a term whose subject IS the instant
182	// ("are we inside the festival month") has nothing in the signal bundle to read:
183	// a term reaching for the process clock would be untestable at a chosen moment
184	// and impure, in the one module that promises to be neither. Both callers already
185	// hold the instant they are deciding for, so passing it costs nothing and keeps
186	// every term a pure function of its inputs.
187	//
188	// EVERY MOVEMENT TERM IS NON-TASK BY CONSTRUCTION: the fields they read are
189	// already classified by the collectors, which drop a commit or a PR carrying the
190	// `Claudinite-Task:` trailer. That is the whole silence gate — a movement-gated
191	// task cannot be woken by another task's output, and no operator or marker says
192	// so in the declaration.
193	
194	const commitsOf = (s) => s?.commits ?? {};
195	const touchedPaths = (s) => commitsOf(s).touchedPaths ?? [];
196	
197	// THE RUN HISTORY: this task's own unqualified work items, newest first, other
198	// than the item under evaluation — what the `runs` collector reads off the issue
199	// list over a fixed horizon. Each `{ number, createdAt, closedAt, state, status,
200	// park, outcome }`. The engine keeps no other memory of a task: the queue IS the
201	// record, which is why a renamed task simply reads as never having run.
202	const runsOf = (s) => s?.runs?.list ?? [];
203	const newestRun = (s) => runsOf(s)[0] ?? null;
204	const ms = (t) => (t == null ? null : new Date(t).getTime());
205	
206	// A person's wake stands in for the cadence: the cadence terms hold on a woken
207	// item, and everything else the task requires still applies, so a force that
208	// finds no work still says so.
209	const wokenReason = (item) => (item?.woken === true
210	  ? { holds: true, reason: `#${item.number ?? '?'} was woken by hand — the wake stands in for the cadence` }
211	  : null);
212	const substantiveShas = (s) => (commitsOf(s).list ?? []).filter((c) => c.substantive).map((c) => c.sha.slice(0, 7));
213	
214	// A capped list plus what it dropped — the shape every scope-naming context uses.
215	const cappedContext = (items, lead, dropTail) => {
216	  const scope = items.slice(0, MAX_CONTEXT_ITEMS);
217	  const dropped = items.length - scope.length;
218	  return [
219	    `${lead}: ${scope.join(', ')}.`,
220	    ...(dropped ? [`${dropped} further ${dropTail}`] : []),
221	  ];
222	};
223	
224	// The scheduler's own work items wear a `task:*` label for their whole life. The
225	// issues collector hides them by title, so one filed under any other title still
226	// reaches here; the label is the invariant, and it filters BOTH ways — such an
227	// issue is neither a touch that triggers a run nor a target inside one.
228	const nonTaskIssues = (s) => {
229	  const open = (s?.issues?.open ?? []).filter((i) => !(i.labels ?? []).some((l) => String(l).startsWith('task:')));
230	  const inScope = new Set(open.map((i) => i.number));
231	  return { open, touched: (s?.issues?.touched ?? []).filter((n) => inScope.has(n)) };
232	};
233	
234	const capturedInWindow = (s, windowDays) => {
235	  const age = s?.conversationLogs?.newestLogAgeDays;
236	  if (typeof windowDays !== 'number') return { error: 'the lookback window is unknown, so "a session captured in the window" cannot be decided' };
237	  // null/undefined is UNKNOWN — no branch, or no readable stamp — which is not movement.
238	  return { holds: typeof age === 'number' && age <= windowDays };
239	};
240	
241	const openPrs = (s) => s?.prs?.open ?? [];
242	
243	const BUILTIN_TERMS = new Map(Object.entries({
244	  // --- the run-history terms (docs/PRINCIPLES.md) ----------------------
245	  // Judged before any other signal is collected — the `runs` bundle comes off the
246	  // issue list the scheduler already holds — so a task whose cadence declines
247	  // costs no read at all on the ticks it does not run.
248	
249	  // No run since this UTC period opened. Both halves of the old occurrence guard: an
250	  // item CREATED since it opened is this period's, and so is one CLOSED since then,
251	  // because an item that started before the boundary and ran past it consumed this
252	  // period too, and a second one beside it is a double run.
253	  [SCHEDULE_TERM]: {
254	    signals: ['runs'],
255	    takesArg: true,
256	    argName: CADENCES.map((c) => `${AT_MOST_PREFIX}${c}`).join('|'),
257	    argOk: (arg) => cadenceOfScheduleArg(arg) !== null,
258	    argHint: `one of ${CADENCES.map((c) => `${AT_MOST_PREFIX}${c}`).join(', ')}`,
259	    holds(s, { arg, item, now }) {
260	      const woken = wokenReason(item);
261	      if (woken) return woken;
262	      const cadence = cadenceOfScheduleArg(arg);
263	      // The instant is the caller's to supply, since a term never reads the clock.
264	      if (ms(now) === null || Number.isNaN(ms(now))) return { error: `${SCHEDULE_TERM}:${arg} has no instant to place in a period: the caller supplied no \`now\`` };
265	      const opened = anchorInstant(cadence, now);
266	      const openedMs = opened.getTime();
267	      const since = runsOf(s).find((r) => (ms(r.createdAt) ?? -Infinity) >= openedMs || (ms(r.closedAt) ?? -Infinity) >= openedMs);
268	      return since
269	        ? { holds: false, reason: `#${since.number} already ran in the ${cadence} period that opened ${opened.toISOString()}` }
270	        : { holds: true, reason: `no run in the ${cadence} period that opened ${opened.toISOString()}` };
271	    },
272	  },
273	
274	  // The same term under the name it was introduced with, so a member's own task file
275	  // carrying the old spelling keeps working forever (calendar.mjs, DUE_TERM). It is
276	  // not a second behaviour: it translates its argument and delegates, so the two can
277	  // never answer differently. `normalizeTaskDeclaration` rewrites a LOADED declaration
278	  // to the current spelling, which is why this is reached only by a caller that did
279	  // not come through that door.
280	  [DUE_TERM]: {
281	    signals: ['runs'],
282	    takesArg: true,
283	    argName: CADENCES.join('|'),
284	    argOk: (arg) => CADENCES.includes(arg),
285	    argHint: `one of ${CADENCES.join(', ')}`,
286	    holds(s, ctx) {
287	      return BUILTIN_TERMS.get(SCHEDULE_TERM).holds(s, { ...ctx, arg: `${AT_MOST_PREFIX}${ctx.arg}` });
288	    },
289	  },
290	
291	  // Whether a failed run stops the next one is the task's to say, and only by
292	  // stating this: absent, the next occurrence is filed beside the park. Only the
293	  // newest run speaks — a failure behind a later clean run is history.
294	  [NOT_FAILED_TERM]: {
295	    signals: ['runs'],
296	    holds(s) {
297	      const newest = newestRun(s);
298	      if (!newest) return { holds: true, reason: 'no run of this task to have failed' };
299	      return newest.park === 'failure'
300	        ? { holds: false, reason: `the newest run, #${newest.number}, stands at a failure park — this task declares it does not run past its own failure` }
301	        : { holds: true, reason: `the newest run, #${newest.number}, did not fail` };
302	    },
303	  },
304	
305	  // The wider statement of the same thing: this task does not run while its
306	  // newest run stands at ANY of the four parks — the three a person's inbox owns
307	  // as much as the failure. What a task states when its round is not finished
308	  // until a person has dealt with it, an unmerged pull request above all: that
309	  // run parks on approval, which is not a fault and which `last-run-not-failed`
310	  // reads as clear. Re-queueing the parked item is what puts a run in front of it.
311	  [NOT_PARKED_TERM]: {
312	    signals: ['runs'],
313	    holds(s) {
314	      const newest = newestRun(s);
315	      if (!newest) return { holds: true, reason: 'no run of this task to be parked' };
316	      return newest.park
317	        ? { holds: false, reason: `the newest run, #${newest.number}, stands at a ${newest.park} park — this task declares it does not run past a park of its own` }
318	        : { holds: true, reason: `the newest run, #${newest.number}, is not parked` };
319	    },
320	  },
321	
322	  // --- the movement terms -----------------------------------------------------
323	  // The positive umbrella over all four activity dimensions — what a
324	  // cadence-triggered task states when its value is zero on a repo nobody works
325	  // in. The first active window resumes it.
326	  'repo-active': {
327	    signals: ['commits', 'issues', 'prs', 'conversationLogs'],
328	    holds(s, { windowDays }) {
329	      const captured = capturedInWindow(s, windowDays);
330	      if (captured.error) return captured;
331	      const moved = [];
332	      if (commitsOf(s).substantiveChange === true) moved.push('a substantive commit landed');
333	      if (nonTaskIssues(s).touched.length) moved.push(`${nonTaskIssues(s).touched.length} issue(s) moved`);
334	      if ((s?.prs?.touched ?? []).length) moved.push(`${(s.prs.touched ?? []).length} open PR(s) moved`);
335	      if (captured.holds) moved.push('a session was captured');
336	      return moved.length
337	        ? { holds: true, reason: `the repo was active in the window — ${moved.join(', ')}` }
338	        : { holds: false, reason: 'the repo was silent in the window — no substantive commit, no issue or PR of its own moved, and no session was captured' };
339	    },
340	  },
341	
342	  'substantive-change': {
343	    signals: ['commits'],
344	    holds(s) {
345	      // The collector's own verdict is the condition — it is where a commit is
346	      // classified, trailer and all. The sha list is only what the context names,
347	      // and a collector that could not detail the commits still answers the gate.
348	      if (commitsOf(s).substantiveChange !== true) {
349	        return { holds: false, reason: 'no substantive default-branch change in the window' };
350	      }
351	      const shas = substantiveShas(s);
352	      return {
353	        holds: true,
354	        reason: `${shas.length || 'a'} substantive default-branch commit(s) in the window`,
355	        context: shas.length ? cappedContext(shas, 'Substantive commits in the window', 'commit(s) are not named here.') : [],
356	      };
357	    },
