387	      return touched.length
388	        ? { holds: true, reason: `${touched.length} issue(s) moved in the window`, context: cappedContext(touched.map((n) => `#${n}`), 'Issues touched in the window', 'touched issue(s) are not named here.') }
389	        : { holds: false, reason: 'no issue of this repo\'s own moved in the window' };
390	    },
391	  },
392	
393	  'prs-touched': {
394	    signals: ['prs'],
395	    holds(s) {
396	      const touched = s?.prs?.touched ?? [];
397	      return touched.length
398	        ? { holds: true, reason: `${touched.length} open PR(s) moved in the window`, context: cappedContext(touched.map((n) => `#${n}`), 'PRs opened or updated in the window', 'moved PR(s) are not named here.') }
399	        : { holds: false, reason: 'no open PR was opened or updated in the window' };
400	    },
401	  },
402	
403	  'mount-moved': {
404	    signals: ['sharedMount'],
405	    holds(s) {
406	      const packs = s?.sharedMount?.changedPacks ?? [];
407	      return packs.length
408	        ? { holds: true, reason: `declared pack(s) changed in the mounted canon: ${packs.join(', ')}`, context: [`Canon packs that changed in the window: ${packs.join(', ')}.`] }
409	        : { holds: false, reason: 'no declared pack\'s vendored files changed in the window' };
410	    },
411	  },
412	
413	  'commits-under': {
414	    signals: ['commits'],
415	    takesArg: true,
416	    argName: 'path-prefix',
417	    holds(s, { arg }) {
418	      const under = touchedPaths(s).filter((p) => p.startsWith(arg));
419	      return under.length
420	        ? { holds: true, reason: `${under.length} path(s) under ${arg} changed in the window`, context: cappedContext(under, `Paths under ${arg} that changed in the window`, `path(s) under ${arg} are not named here.`) }
421	        : { holds: false, reason: `no path under ${arg} changed in the window` };
422	    },
423	  },
424	
425	  'commits-outside': {
426	    signals: ['commits'],
427	    takesArg: true,
428	    argName: 'path-prefix',
429	    holds(s, { arg }) {
430	      const outside = touchedPaths(s).filter((p) => !p.startsWith(arg));
431	      return outside.length
432	        ? {
433	          holds: true,
434	          reason: `${outside.length} path(s) outside ${arg} changed in the window`,
435	          context: cappedContext(outside, `Paths outside ${arg} that changed in the window — work exactly these, and no others`,
436	            `path(s) changed in the window and are NOT in scope this round — say so in the wrap-up, so it is not read as a full sweep.`),
437	        }
438	        : { holds: false, reason: `nothing outside ${arg} changed in the window` };
439	    },
440	  },
