442	  // The two pending-round conditions. Both exist so an unreviewed round is never
443	  // stacked on one already in flight, which is why an open PR whose paths could
444	  // not be read counts as PENDING: unknown is not clear.
445	  'no-open-pr-touching': {
446	    signals: ['prs'],
447	    takesArg: true,
448	    argName: 'path-prefix',
