451	      if (pending) return { holds: false, reason: `PR #${pending.number} has a pending ${arg} change — this round waits for its review rather than stack a second unreviewed one on it` };
452	      const opaque = openPrs(s).find((p) => !Array.isArray(p.changedPaths));
453	      if (opaque) return { holds: false, reason: `PR #${opaque.number}'s changed paths could not be read, so whether a ${arg} change is pending is unknown — a skipped round is cheaper than an unreviewed one stacked on it` };
454	      return { holds: true, reason: `no open PR changes a path under ${arg}` };
455	    },
456	  },
457	
458	  'no-open-pr-titled': {
459	    signals: ['prs'],
460	    takesArg: true,
461	    argName: 'title-prefix',
462	    holds(s, { arg }) {
463	      const pending = openPrs(s).find((p) => String(p.title ?? '').startsWith(arg));
464	      return pending
465	        ? { holds: false, reason: `PR #${pending.number} is this pass's previous round, still open — this round waits for it to land rather than stack a second sweep on it` }
466	        : { holds: true, reason: `no open PR titled "${arg}…" — the previous round has landed` };
467	    },
468	  },
469	}));
470	
471	export const BUILTIN_TERM_NAMES = [...BUILTIN_TERMS.keys()];
472	
473	// --- the verdict --------------------------------------------------------------
474	
475	// Evaluate a declaration over collected signals. Returns `{ run, reason, context }`
476	// — or `{ error }`, which is a failed run rather than a decline.
477	//
478	// PARTIAL MODE (`partial: true`) judges what the bundle so far can decide: a term
479	// whose signal has not been collected is UNKNOWN rather than false, a conjunct
480	// with an unknown alternative and no held one stays open, and the verdict is `{
481	// run: null, undecided: true, missing }` unless some conjunct is already decided
482	// false — a decline that cost nothing beyond the run history — or every conjunct
483	// held. The scheduler asks this way first, with the `runs` bundle alone, so a
484	// task whose cadence declines never collects its other signals. In full mode a
485	// missing signal is a term that does not hold, as it always was.
486	export function evaluatePreconditions({
487	  preconditions, signals = {}, config = {}, item = null, terms = new Map(), windowDays = null, now = null,
488	  partial = false,
489	}) {
490	  const parsed = parsePreconditions(preconditions);
491	  if (parsed.kind === 'invalid') return { error: `the "preconditions" declaration is not legal: ${parsed.reason}` };
492	
493	  const held = [];
494	  const context = [];
495	  const missing = new Set();
496	  let declined = null;
497	  let undecided = false;
498	  for (const alternatives of parsed.conditions) {
499	    const outcomes = [];
500	    let unknown = false;
501	    for (const ref of alternatives) {
502	      const term = resolveTerm(ref.name, terms);
503	      if (!term) return { error: `unknown precondition "${ref.name}" — no built-in and none this task's preconditions.mjs exports` };
504	      const argProblem = argumentProblem(term, ref);
505	      if (argProblem) return { error: argProblem.what };
506	      // An unreadable signal is never a verdict: the term would be ruling on data
507	      // that was not there, and a decline taken that way is permanent silence.
508	      const unreadable = (term.signals ?? []).find((n) => signals?.[n]?.error);
509	      if (unreadable) return { error: `${ref.name}: the \`${unreadable}\` signal could not be read — ${signals[unreadable].error}` };
510	      if (partial) {
511	        const absent = (term.signals ?? []).filter((n) => signals?.[n] === undefined);
512	        if (absent.length) { absent.forEach((n) => missing.add(n)); unknown = true; continue; }
513	      }
514	      let out;
515	      try { out = term.holds(signals, { arg: ref.arg, config, item, windowDays, now }) ?? {}; }
516	      catch (e) { return { error: `the precondition "${ref.name}" threw: ${e.message}` }; }
517	      if (out.error) return { error: `${ref.name}: ${out.error}` };
518	      outcomes.push({ ref, out });
519	    }
520	    const winner = outcomes.find((o) => o.out.holds === true);
521	    if (winner) {
522	      held.push(winner.out.reason ?? winner.ref.text);
523	      context.push(...(winner.out.context ?? []));
524	    } else if (unknown) {
525	      undecided = true;
526	    } else if (declined === null) {
527	      declined = outcomes.map((o) => o.out.reason ?? `${o.ref.text} does not hold`).join('; nor ');
528	    }
529	  }
530	  if (declined !== null) return { run: false, reason: declined };
531	  if (undecided) return { run: null, undecided: true, missing: [...missing] };
532	  return { run: true, reason: held.length ? held.join('; ') : 'no conditions stated — the item itself is the ask', context };
533	}
534

