1	// The queue's pre-policy "narrow diff" verdict, kept for the items and callers
2	// that still speak it. The general mechanism is `merge-policy.mjs` at this
3	// pack's root — `Merge: if-narrow` resolves there to the `narrow-diff` composite
4	// policy, and new callers go straight to that module and its CLI. What stays
5	// here is the original whole-diff verdict shape (`narrowVerdict`) and its CLI,
6	// both built on the primitives merge-policy now owns.
7	//
8	// Narrow means every changed file is one of:
9	//   - documentation — a Markdown/text file;
10	//   - a test — a file or directory the repo names as one;
11	//   - comments only — the code either side of the change is identical once the
12	//     comments are stripped;
13	//   - code, in at most ONE directory across the whole diff.
14	//
15	// THE LIMIT THAT BOUNDS THE VERDICT: a file `commentOnly` cannot answer for counts
16	// as code, so a comment-only edit in a language the parser does not model parks the
17	// run rather than merging it. That is the safe end, and it is deliberate — the
18	// verdict grants a merge nobody will look at.
19	
20	import path from 'node:path';
21	import {
22	  COMMENT_CHECKABLE, commentOnly, classifyPath,
23	} from '../../../src/contract/merge-policy.mjs';
24	import { diffEntries } from '../../../src/session/merge-policy-run.mjs';
25	
26	// Re-exported so a caller that asked this module keeps getting the same answers
27	// the policy engine gives.
28	export { COMMENT_CHECKABLE, commentOnly, classifyPath, diffEntries };
29	
30	// The verdict over a whole diff. `entries` are `{ file, before, after }`, contents
31	// null where the file was added or deleted. Returns the verdict and the WHY —
32	// which files forced it — because a run that parks has to say what it parked over.
33	export function narrowVerdict(entries) {
34	  const codeDirs = new Map();
35	  const kinds = [];
36	  for (const { file, before, after } of entries) {
37	    const kind = classifyPath(file);
38	    if (kind !== 'code') { kinds.push({ file, kind }); continue; }
39	    if (commentOnly(file, before, after)) { kinds.push({ file, kind: 'comments' }); continue; }
40	    const dir = path.dirname(file);
41	    if (!codeDirs.has(dir)) codeDirs.set(dir, []);
42	    codeDirs.get(dir).push(file);
43	    kinds.push({ file, kind: 'code' });
44	  }
45	  const dirs = [...codeDirs.keys()].sort();
46	  return {
47	    narrow: dirs.length <= 1,
48	    codeDirs: dirs,
49	    files: kinds,
50	    why: dirs.length <= 1
51	      ? (dirs.length === 0
52	        ? 'no code changed — documentation, tests and comments only'
53	        : `code changed in one directory (${dirs[0]}), beside documentation, tests and comment-only edits`)
54	      : `code changed in ${dirs.length} directories: ${dirs.join(', ')}`,
55	  };
56	}
57	
58	// --- the CLI ------------------------------------------------------------------
59	
60	async function main() {
61	  const argv = process.argv.slice(2);
62	  const at = (flag) => (argv.includes(flag) ? argv[argv.indexOf(flag) + 1] : null);
63	  const cwd = at('--root') ?? process.env.CLAUDE_PROJECT_DIR ?? process.cwd();
64	  const base = at('--base') ?? 'origin/main';
65	
66	  const entries = diffEntries({ base, cwd });
67	  if (entries.length === 0) {
68	    console.log('NARROW: no — this branch changes nothing against the base');
69	    return;
70	  }
71	  const verdict = narrowVerdict(entries);
72	  for (const { file, kind } of verdict.files) console.log(`  ${kind.padEnd(8)} ${file}`);
73	  console.log(`\nNARROW: ${verdict.narrow ? 'yes' : 'no'} — ${verdict.why}`);
74	}
75	
76	if (import.meta.url === `file://${process.argv[1]}`) {
77	  main().catch((e) => { console.error(`narrow-diff: ${e.message}`); process.exitCode = 1; });
78	}
