1	// Task discovery for the scheduler (docs/PRINCIPLES.md). One
2	// uniform scan of every ACTIVE pack's `tasks/<name>/task.json`, activation-gated
3	// by the repo's `packs` declaration exactly like checks and skills. Reuses the
4	// pack registry so the same scan works across all three layouts without knowing
5	// any of them: canon packs at `packs/`, a consumer's vendored canon at
6	// `.claudinite/shared/packs/`, and local packs at `.claudinite/local/packs/`
7	// (each pack carries its own resolved `dir`).
8	//
9	// Frequency filtering is deliberately NOT done here — discover returns every
10	// active, well-formed task; the scheduler run intersects them with the current anchors
11	// (queue/anchors.mjs). Keeping the two apart keeps each pure and separately
12	// testable. A task whose declaration fails to load or violates the declaration
13	// contract is dropped into `errors` (fail-soft, per-task), never sinking the
14	// scan.
15	
16	import { readdirSync, existsSync } from 'node:fs';
17	import { join, relative } from 'node:path';
18	import { loadPacks, isActive } from '../../../../engine/pack_loader/pack-registry.mjs';
19	import { normalizeTaskDeclaration, validateTaskDeclaration } from './task-contract.mjs';
20	import { findTaskDeclaration, loadTaskDeclaration } from './task-declaration.mjs';
21	import { loadTaskTerms } from './task-terms.mjs';
22	import { BUILT_IN_PACK, builtInTasksRoot } from './built-in-tasks.mjs';
23	
24	// The declaration file of every task an ACTIVE pack contributes, plus the engine's
25	// own built-in root (built-in-tasks.mjs). Sync — locating a declaration only reads
26	// directories; loading one is what needs `await` — so a check can make the same walk
27	// discovery makes rather than a second opinion of which declarations a repo has.
28	// Fail-soft in the same two places discovery is: an unreadable tasks/ and a folder
29	// carrying two declarations become errors, never a sunk scan.
30	export function taskDeclarationFiles(root, activePacks) {
31	  const errors = [];
32	  // The BUILT-IN root beside the pack scan (PRINCIPLES.md). The engine ships one
33	  // task of its own — the request implementer — so a marked issue is an ordinary
34	  // run rather than a special item shape. It is not a pack and declares nothing:
35	  // wherever the queue runs, it is active, which is also what stops any pack
36	  // opting itself into the fields only it may declare.
37	  const roots = activePacks.map((p) => ({ id: p.id, dir: join(p.dir, 'tasks') }));
38	  const builtIn = builtInTasksRoot(root);
39	  if (builtIn) roots.push({ id: BUILT_IN_PACK, dir: builtIn });
40	
41	  const found = [];
42	  for (const pack of roots) {
43	    if (!existsSync(pack.dir)) continue;
44	    let names;
45	    try {
46	      names = readdirSync(pack.dir, { withFileTypes: true })
47	        .filter((d) => d.isDirectory()).map((d) => d.name).sort();
48	    } catch (e) {
49	      errors.push({ pack: pack.id, what: `${pack.id}'s tasks/ is not a readable directory: ${e.message}`, fix: `make ${relative(root, pack.dir)} a directory (or remove it)` });
50	      continue;
51	    }
52	    for (const name of names) {
53	      const taskDir = join(pack.dir, name);
54	      const file = findTaskDeclaration(taskDir);
55	      if (file === null) continue;
56	      found.push({ pack: pack.id, name, taskDir, file });
57	    }
58	  }
59	  return { found, errors };
60	}
61	
62	// Discover every task the repo's active packs contribute. Returns
63	// `{ tasks, errors }` where each task is
64	// `{ pack, id, taskDir, taskPath, decl, terms }` — `taskPath` is the repo-relative
65	// path to the worker file's directory's task.md (the work item's first
66	// line), `decl` the validated declaration, and `terms` whatever precondition
67	// terms the task ships of its own (an empty map for most).
68	export async function discoverTasks(root, config) {
69	  const errors = [];
70	  const packs = await loadPacks({ localRoot: root });
71	  const active = packs.filter((p) => isActive(p, config));
72	
73	  const { found, errors: walkErrors } = taskDeclarationFiles(root, active);
74	  errors.push(...walkErrors);
75	
76	  const tasks = [];
77	  for (const { pack, name, taskDir, file } of found) {
78	    // The task's own precondition terms, loaded BEFORE the declaration: a
79	    // declaration naming one is well-formed only against the file that defines
80	    // it, so a terms file that will not import fails the task rather than
81	    // making its own conditions look like typos — and the door itself reads
82	    // them, to know whether a legacy declaration's conditions are ones the
83	    // scheduler could judge.
84	    let terms;
85	    try {
86	      terms = await loadTaskTerms(taskDir);
87	    } catch (e) {
88	      errors.push({ pack, task: name, what: `${relative(root, join(taskDir, 'preconditions.mjs'))} failed to import: ${e.message}`, fix: 'fix or remove the task\'s precondition terms' });
89	      continue;
90	    }
91	    let decl;
92	    try {
93	      // Canonical field names and the defaults from here on (legacy code-work
94	      // names accepted at the door, never re-checked downstream).
95	      decl = normalizeTaskDeclaration(await loadTaskDeclaration(file), terms);
96	    } catch (e) {
97	      errors.push({ pack, task: name, what: `${relative(root, file)} failed to load: ${e.message}`, fix: 'fix or remove the task' });
98	      continue;
99	    }
100	    const problems = validateTaskDeclaration(decl, terms);
101	    if (problems.length) {
102	      errors.push({ pack, task: name, what: `${relative(root, file)} is not a valid task declaration: ${problems.map((p) => p.what).join('; ')}`, fix: problems[0].fix });
103	      continue;
104	    }
105	    // A local pack's dir-name is its id (enforced by the registry); the task's
106	    // directory name should likewise match its declared id — a mismatch would
107	    // make the dispatch path and the declaration disagree.
108	    if (decl.id !== name) {
109	      errors.push({ pack, task: name, what: `task in ${relative(root, taskDir)} declares id "${decl.id}" but its directory is "${name}"`, fix: 'rename the directory to the task id, or set the id to the directory name' });
110	      continue;
111	    }
112	    tasks.push({
113	      pack,
114	      id: decl.id,
115	      taskDir,
116	      taskPath: `${relative(root, taskDir).split('\\').join('/')}/task.md`,
117	      decl,
118	      terms,
119	    });
120	  }
121	  return { tasks, errors };
122	}
