1	// Anchors — when a cadence's occurrence falls (docs/PRINCIPLES.md).
2	//
3	// The arithmetic lives in `calendar.mjs`; this module exposes exactly the two
4	// questions asked of it: "which period is current" (what a `schedule:at-most-`
5	// term measures a task's run history against) and "when does the next one open"
6	// (what the dashboard renders), plus the period a cadence repeats on, and the
7	// period a TASK keeps, read off its own cadence term.
8	//
9	// Pure and stateless: `now` is always injected, every value is UTC.
10	
11	import { anchorInstant, cadenceOf } from '../contract/calendar.mjs';
12	
13	const HOUR_MS = 3600e3;
14	const DAY_MS = 24 * HOUR_MS;
15	
16	// One period of a cadence word (`daily`, `weekly`, `monthly`, `manual` having
17	// none), in ms - the unit the repair phase's stale-ready rule counts in
18	// (PRINCIPLES.md) and the coarse step `nextAnchor` walks. An unrecognised word
19	// reads as a day: this feeds the repair phase's stale-ready bound and the
20	// precondition's signal window, so anything shorter parks a member's task
21	// needs-human on every sweep (PRINCIPLES.md).
22	export function periodMs(frequency) {
23	  if (frequency === 'weekly') return 7 * DAY_MS;
24	  if (frequency === 'monthly') return 31 * DAY_MS;
25	  if (frequency === 'manual') return null;
26	  return DAY_MS;
27	}
28	
29	// The period a TASK keeps, read off the cadence term its declaration states, and
30	// null for a task with no cadence term (asked at every tick, it runs on movement
31	// or when woken).
32	export function taskPeriodMs(decl) {
33	  const cadence = cadenceOf(decl?.preconditions);
34	  return cadence === null ? null : periodMs(cadence.cadence);
35	}
36	
37	// When the current period opened, as a Date. `manual` has none, nothing schedules
38	// it, so null is the whole answer.
39	export const mostRecentAnchor = anchorInstant;
40	
41	// When the next period opens, strictly after `now`, which is what a rolled item is
42	// stamped with. Derived by walking `mostRecentAnchor` forward rather than by adding
43	// a period, because months are not a fixed distance apart. The coarse step is under
44	// one period, so the loop advances by at most two steps and never overshoots.
45	export function nextAnchor(frequency, now) {
46	  if (frequency === 'manual') return null;
47	  const from = mostRecentAnchor(frequency, now).getTime();
48	  // An unreadable instant makes every comparison below false, so the walk would never
49	  // terminate. There is no next period of a moment that is not one.
50	  if (!Number.isFinite(from)) return null;
51	  const step = frequency === 'monthly' ? 28 * DAY_MS : periodMs(frequency);
52	  for (let t = from + step; ; t += step) {
53	    const candidate = mostRecentAnchor(frequency, new Date(t));
54	    if (candidate.getTime() > from) return candidate;
55	  }
56	}
