144	// A worker's returned verdict, rendered into the protocol the executor reads. Every
145	// key is optional, and a worker that returns nothing at all has simply done its work.
146	export function emitVerdict(verdict, { env = actionsEnv(), log = console.log, requestPath = null } = {}) {
147	  const out = verdict ?? {};
148	  if (out.triage) {
149	    const detail = out.triage.detail ? ` - ${out.triage.detail}` : '';
150	    log(`claudinite-needs-human: ${out.triage.kind}${detail}`);
151	  }
152	  if (out.requeue) {
153	    const reason = out.requeue.reason ? ` - ${out.requeue.reason}` : '';
154	    log(`claudinite-requeue: ${out.requeue.until}${reason}`);
155	  }
156	  if (out.requestAgent) {
157	    // The control signal is the file's EXISTENCE; its body carries only what the
158	    // named exception lets cross to the agent - what this run created, and the name
159	    // of the condition that woke it.
160	    const path = requestPath ?? env.CLAUDINITE_REQUEST_AGENT;
161	    if (!path) throw new Error('the worker requested the agent, but no CLAUDINITE_REQUEST_AGENT path was handed in');
162	    const { delivered = undefined, reason = undefined } = out.requestAgent === true ? {} : out.requestAgent;
163	    writeFileSync(path, JSON.stringify({ ...(delivered ? { delivered } : {}), ...(reason ? { reason } : {}) }));
164	  }
165	}
