167	// Import the module and run it. Separated from the entry guard so a test drives the
168	// whole wrapping - bag, verdict, failure line, timing - without spawning node.
169	export async function runWorkerModule(file, {
170	  env = actionsEnv(), taskDir = cwdTaskDir(), log = console.log, err = console.error, now = nowMs,
171	} = {}) {
172	  const id = `${env.CLAUDINITE_PACK ?? '?'}/${env.CLAUDINITE_TASK ?? '?'}`;
173	  const started = now();
174	  try {
175	    const mod = await import(pathToFileURL(resolve(taskDir, file)).href);
176	    if (typeof mod.worker !== 'function') {
177	      throw new Error(`${file} exports no \`worker\` function - the runner calls that export with the parameters bag`);
178	    }
179	    const verdict = await mod.worker(workerParams(env, taskDir));
180	    emitVerdict(verdict, { env, log });
181	    log(`${id}: worker done in ${((now() - started) / 1000).toFixed(1)}s`);
182	    // A triage verdict IS a failed run. The executor reads the marker only off a
183	    // non-zero exit - a worker that could park itself on a clean one would be
184	    // downgrading its own failure into a lane nobody watches - so a worker asking
185	    // for the park exits the way that park is reached.
186	    return { ok: !verdict?.triage };
187	  } catch (e) {
188	    // The worker's own diagnosis, where it made one: the executor reads an exit code
189	    // and cannot tell a missing scope from a bug in the module.
190	    if (e?.triage) err(`claudinite-needs-human: ${e.triage} - ${e.message}`);
191	    err(`${id} failed after ${((now() - started) / 1000).toFixed(1)}s: ${e?.message ?? e}`);
192	    if (e?.stack) err(e.stack);
193	    return { ok: false };
194	  }
195	}
196	
197	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
198	  const file = process.argv[2];
199	  if (!file) {
200	    console.error('worker-entry: the module to run is the first argument - the runner passes the task\'s code_worker_mjs');
201	    process.exitCode = 2;
202	  } else {
203	    // Started rather than awaited at the top level: a module under `packs/` may not
204	    // hold the evaluation open, and the exit code is set from the settled promise.
205	    runWorkerModule(file).then(({ ok }) => { if (!ok) process.exitCode = 1; });
206	  }
207	}
