1	// The merged-PR fields, derived. Pure by construction and separated from the listing
2	// that fetches them ([`read-prs.mjs`](read-prs.mjs)) for the same reason the fold's
3	// counting core is separated from its worker — and for one more: these two are the
4	// only part of the merged-PR read another pack needs, and they are published through
5	// `public/` to a PAGE that runs in a browser, where a module reaching for
6	// `process.env` or a node builtin does not load at all.
7	
8	// The closing keyword GitHub itself acts on, which is also what this repo's lifecycle
9	// asks a PR body to carry. The FIRST match wins: a PR closing several issues has one
10	// issue it is *for*, and it is the one named first.
11	const CLOSES_RE = /(?:^|\n)[^\S\n]*(?:closes|fixes|resolves)[^\S\n]+#(\d+)\b/i;
12	
13	export function closesIssueIn(body) {
14	  const n = Number(CLOSES_RE.exec(String(body ?? ''))?.[1]);
15	  return Number.isFinite(n) && n > 0 ? n : null;
16	}
17	
18	// A span in hours, to one decimal. Absent at either end is `null` — an unknown lead
19	// time, which is not a zero one — and so is a span whose ends arrive in the wrong
20	// order, which says the two clocks disagree rather than that the work took less than
21	// no time.
22	export function hoursBetween(from, to) {
23	  if (!from || !to) return null;
24	  const hours = (Date.parse(to) - Date.parse(from)) / 3600000;
25	  if (!Number.isFinite(hours) || hours < 0) return null;
26	  return Math.round(hours * 10) / 10;
27	}
