1	// THE ESCALATION SURFACE FOR A WORKFLOW THAT FAILED AS A WHOLE (docs/PRINCIPLES.md).
2	// A scheduled run reaches no one when it goes red — nothing is
3	// watching the Actions tab — so a run-level failure becomes a human-visible
4	// issue instead.
5	//
6	// ONE OPEN ISSUE, by a fixed title: create-or-comment, so a week of nightly
7	// failures is one thread rather than seven issues. The labels are ensured
8	// FIRST, because a first-run failure may precede any other label-ensure and
9	// GitHub 422s the write that applies an unknown label.
10	//
11	// The platform reporting its own failure IS an origin (`task:origin:github`),
12	// parked in the `failure` lane — the one a person diagnoses (#1119).
13	//
14	// This lives in the engine rather than in the workflows that call it because
15	// `.github/workflows/` is the one path an update cannot push into: a member's
16	// copy of a workflow moves only through a PR a human merges, while this module
17	// updates nightly like the rest of the engine.
18	
19	import { pathToFileURL } from 'node:url';
20	import { makeGh } from '../world/github.mjs';
21	import { actionRepoContext, runUrl } from '../world/actions.mjs';
22	import { ensureLabels, createIssue, comment } from '../world/github.mjs';
23	import { ORIGIN_GITHUB, STATUS_NEEDS_HUMAN_FAILURE } from '../../public/task-constants.mjs';
24	import { searchIssues } from '../world/github.mjs';
25	
26	// Not a queue label: this one marks the issue as the platform's own failure
27	// report rather than a work item, so it is defined here beside its only writer.
28	export const WORKFLOW_FAILURE = 'workflow-failure';
29	
30	export const FAILURE_LABELS = Object.freeze([
31	  { name: WORKFLOW_FAILURE, color: 'b60205', description: 'Claudinite scheduler: a scheduler run or task failed' },
32	  { name: ORIGIN_GITHUB, color: 'd4c5f9', description: 'Claudinite queue: filed by the platform itself — a workflow reporting its own failure' },
33	  { name: STATUS_NEEDS_HUMAN_FAILURE, color: 'b60205', description: 'Claudinite queue: parked — the run broke, diagnose and fix' },
34	]);
35	
36	// The open issue carrying exactly `title`, or null. Lowest number wins, so a past
37	// race that left two converges on the first and the duplicate stays inert.
38	//
39	// A search that does not answer returns null rather than throwing: filing a
40	// second issue is untidy, losing the failure report entirely is not.
41	export async function findOpenFailureIssue(gh, repo, title) {
42	  const want = title.trim();
43	  const q = encodeURIComponent(`repo:${repo} is:issue is:open in:title "${want}"`);
44	  const { status, json } = await searchIssues(gh, q);
45	  if (status !== 200 || !Array.isArray(json?.items)) return null;
46	  const exact = json.items
47	    .filter((i) => (i.title ?? '').trim() === want)
48	    .sort((a, b) => a.number - b.number);
49	  return exact.length ? exact[0].number : null;
50	}
51	
52	export async function reportWorkflowFailure(gh, repo, { title, body }) {
53	  await ensureLabels(gh, repo, FAILURE_LABELS);
54	  const open = await findOpenFailureIssue(gh, repo, title);
55	  if (open != null) {
56	    await comment(gh, repo, open, body);
57	    return { issue: open, created: false };
58	  }
59	  const { number } = await createIssue(gh, repo, {
60	    title, body, labels: FAILURE_LABELS.map((l) => l.name),
61	  });
62	  return { issue: number, created: true };
63	}
64	
65	// The URL of the run doing the reporting, republished here because the failure
66	// report is where every caller of it wants it.
67	export { runUrl };
68	
69	export const SCHEDULER_FAILURE_TITLE = 'Claudinite scheduler run failed';
70	
71	// The scheduler workflow's `report-failure` job. It runs only when the scheduler
72	// run or its drain went red, so it files unconditionally.
73	export async function runWorkflowFailureReport() {
74	  const { repo } = actionRepoContext();
75	  if (!repo) throw new Error('GITHUB_REPOSITORY is not set');
76	  const gh = makeGh();
77	  const { issue, created } = await reportWorkflowFailure(gh, repo, {
78	    title: SCHEDULER_FAILURE_TITLE,
79	    body: `The Claudinite scheduler run/drain run failed: ${runUrl()}`,
80	  });
81	  console.log(`- ${created ? 'filed' : 'commented on'} #${issue}`);
