1	// WHEN A BLOCKED ITEM MAY RUN (docs/PRINCIPLES.md; #1373 reversed an earlier
2	// attempt). One caller asks this question: the
3	// scheduler run, at every tick, over every open item. A close does not - releasing a
4	// dependent is deciding whether the world has moved on, which is what the
5	// scheduler run exists to re-derive, and a task execution converging its own
6	// item has no business relabelling a sibling work item to answer it.
7	//
8	// The backstop framing survives the reversal unchanged: nothing but the
9	// scheduler run's own pass ever releases a blocked item, so a chain link
10	// waits at most one scheduler run for its dependency to be noticed.
11	
12	import { STATUS_BLOCKED } from '../../public/task-constants.mjs';
13	import { isStatus, parseWorkItemBody } from '../../public/work-item-grammar.mjs';
14	import { nowMs as clockNowMs } from '../world/clock.mjs';
15	
16	// Is this item's wait over? `stateOf(n)` answers the state of a `Blocked-by`
17	// target that may not be a work item at all — an unknown number is never treated
18	// as closed, so an unreadable blocker DELAYS rather than releases (the
19	// convergence-not-prevention posture). An item in triage is nobody's to release.
20	export function isReleasable(item, { stateOf = () => null, nowMs = clockNowMs() } = {}) {
21	  if (item.state !== 'open' || !isStatus(item, STATUS_BLOCKED)) return false;
22	  const { notBefore, blockedBy } = parseWorkItemBody(item.body);
23	  const blockersDone = blockedBy.every((n) => stateOf(n) === 'closed');
24	  const timeReached = notBefore === null || nowMs >= new Date(notBefore).getTime();
25	  return blockersDone && timeReached;
26	}
