1	// The GitHub client and the operations a task's worker lands its output with,
2	// published for every pack — and the transport this pack's own port is built on.
3	//
4	// THREE THINGS, ONE FILE, IMPORTING NOTHING:
5	//
6	//   THE TRANSPORT. `makeGh` makes `gh(path) -> { status, json }`; `restCall` is the
7	//   same call for a caller holding a token rather than a made client; `graphqlCall`
8	//   is the endpoint for the two mutations REST does not offer. Every request this pack
9	//   makes passes through one of the three, which is what makes the outward edge
10	//   countable: `apiCallCount` is the run's API spend, a property of the transport and
11	//   never of any caller.
12	//
13	//   THE OPERATIONS A WORKER NEEDS. `dispatchWorkflow`, and the tracker issue a
14	//   recurring task logs every run to (`findOrCreateTracker`, `writeTracker`). A worker
15	//   that needs a further REST call asks for the operation to be published rather than
16	//   composing a path: `src/world/github.mjs` is the port that spells every other path
17	//   this pack calls, and it builds on the transport here.
18	//
19	//   THE ISSUE CALLS THE TRACKER MAKES, spelled here because the tracker is here and
20	//   this file imports nothing — the port re-exports them, so nothing else spells them.
21	//
22	// A non-2xx returns `{ status, json: null }` rather than throwing, so a 404 is data,
23	// not an error. Callers that must not mistake a refusal for an answer read the STATUS —
24	// a 403 from a repo whose Actions cannot write puts a plausible object where the
25	// result should be.
26	
27	const API = process.env.GITHUB_API_URL || 'https://api.github.com';
28	
29	// --- how many calls this process has made ---------------------------------------
30	// Every REST and GraphQL request this pack makes passes through one of the three
31	// functions below, which is what makes the outward edge countable at all: a run's
32	// API spend is a property of the PORT, not of any caller, and asking each caller to
33	// report its own would be a second count to drift.
34	//
35	// Process-wide because a run IS a process — the scheduler and the executor each get
36	// a fresh one — and the cost record the run prints is about that process. A request
37	// that failed still counts: it was made, it was billed against the rate limit, and
38	// a run that spent its budget on refusals spent it.
39	let apiCalls = 0;
40	
41	export const apiCallCount = () => apiCalls;
42	
43	// For a test driving several runs through one process. Nothing in a real run calls
44	// it: a run that reset its own counter mid-flight would report the remainder.
45	export const resetApiCallCount = () => { apiCalls = 0; };
46	
47	// The Action-side reader/writer. `packs/claudinite-tasks/` is the one place that
48	// legitimately uses the Action's `GITHUB_TOKEN` — everything session-side stays
49	// MCP-only (docs/PRINCIPLES.md).
50	//
51	// `path` is an API path beginning with `/` (e.g. `/repos/owner/name/commits`); the
52	// base URL and auth are applied here.
53	export function makeGh({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
54	  // `gh(path)` reads; `gh(path, { method, body })` writes (body JSON-encoded).
55	  return async function gh(path, { method = 'GET', body } = {}) {
56	    apiCalls += 1;
57	    const res = await fetchImpl(`${api}${path}`, {
58	      method,
59	      headers: {
60	        accept: 'application/vnd.github+json',
61	        'x-github-api-version': '2022-11-28',
62	        ...(token ? { authorization: `Bearer ${token}` } : {}),
63	        'user-agent': 'claudinite-scheduler',
64	        ...(body ? { 'content-type': 'application/json' } : {}),
65	      },
66	      ...(body ? { body: JSON.stringify(body) } : {}),
67	    });
68	    let json = null;
69	    try { json = await res.json(); } catch { json = null; }
70	    return { status: res.status, json };
71	  };
72	}
73	
74	// The same call for a caller that holds a token rather than a made client — the
75	// delivery lane, which is handed one per run. One implementation of the headers,
76	// so a client the landing lane uses cannot drift from the one the executor uses.
77	export async function restCall(token, path, { method = 'GET', body, api = API, fetchImpl = fetch } = {}) {
78	  apiCalls += 1;
79	  const res = await fetchImpl(`${api}${path}`, {
80	    method,
81	    headers: {
82	      authorization: `Bearer ${token}`,
83	      accept: 'application/vnd.github+json',
84	      'x-github-api-version': '2022-11-28',
85	      ...(body ? { 'content-type': 'application/json' } : {}),
86	    },
87	    body: body ? JSON.stringify(body) : undefined,
88	  });
89	  let json = null;
90	  try { json = await res.json(); } catch { /* empty body */ }
91	  return { status: res.status, json };
92	}
93	
94	// The GraphQL endpoint, for the two mutations REST does not offer. Returns the
95	// parsed body; the caller decides what an `errors` array means.
96	export async function graphqlCall(token, query, variables, { api = API, fetchImpl = fetch } = {}) {
97	  apiCalls += 1;
98	  const res = await fetchImpl(`${api}/graphql`, {
99	    method: 'POST',
100	    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
101	    body: JSON.stringify({ query, variables }),
102	  });
103	  return res.json().catch(() => null);
104	}
105	
106	// --- the issue calls the tracker makes ------------------------------------------
107	
108	// Replace an issue's body. The whole body, because that is the only shape the API
109	// offers — every caller reshapes the text it read rather than composing a new one.
110	export const setIssueBody = (gh, repo, number, body) =>
111	  gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { body } });
112	
113	// The raw issue PATCH and POST, for a caller that reads the status itself rather
114	// than taking one of the shaped writes above — the tracker, which fails soft on one
115	// call and loud on the next and so must see both.
116	export const patchIssue = (gh, repo, number, body) =>
117	  gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body });
118	
119	export const postIssue = (gh, repo, body) =>
120	  gh(`/repos/${repo}/issues`, { method: 'POST', body });
121	
122	// Issue search across the repo. Search is eventually consistent and rate-limited
123	// separately from the REST API, which is why the callers here treat an
124	// unsuccessful search as "no answer" rather than "nothing found".
125	export const searchIssues = (gh, query) => gh(`/search/issues?q=${query}&per_page=100`);
126	
127	export const comment = (gh, repo, number, body) =>
128	  gh(`/repos/${repo}/issues/${number}/comments`, { method: 'POST', body: { body } });
129	
130	// --- workflows -----------------------------------------------------------------
131	
132	// Fire a `workflow_dispatch`. It is how the queue CHAINS (PRINCIPLES.md) — a run
133	// that settled its item starts a fresh one rather than leaving the remainder for
134	// the cron — and `workflow_dispatch` is one of the two events the default
135	// `GITHUB_TOKEN` may fire, the explicit exemption in the same recursion guard that
136	// suppresses its label events, so no wider credential is involved.
137	//
138	// Judged by STATUS, never by the body: a token without `actions: write` 403s this
139	// POST with a plausible JSON body, and a body-only check would log it as sent.
140	export async function dispatchWorkflow(gh, repo, file, ref, inputs = null) {
141	  const { status } = await gh(`/repos/${repo}/actions/workflows/${file}/dispatches`, {
142	    method: 'POST', body: { ref, ...(inputs ? { inputs } : {}) },
143	  });
144	  return { ok: status === 204, status };
145	}
146	
147	// --- workflow runs and Pages ------------------------------------------------------
148	// The reads a worker makes after a dispatch: a dispatch answers 204 and names no run,
149	// so the caller finds the run it started by listing the workflow's newest ones.
150	export const listWorkflowRuns = (gh, repo, file, { event = 'workflow_dispatch', perPage = 10 } = {}) =>
151	  gh(`/repos/${repo}/actions/workflows/${file}/runs?event=${event}&per_page=${perPage}`);
152	
153	export const readWorkflowRun = (gh, repo, runId) => gh(`/repos/${repo}/actions/runs/${runId}`);
154	
155	// The repo's GitHub Pages site — the URL a deploy answers on. 404 when Pages is off.
156	export const readPagesSite = (gh, repo) => gh(`/repos/${repo}/pages`);
157	
158	// --- the standing tracker ----------------------------------------------------------
159	// A STANDING TRACKER — the one issue a recurring task logs every run to. This is a
160	// LIBRARY, not a phase: nothing in the scheduler knows a task has a tracker, no
161	// declaration carries one, and no task is expected to want one. A task that keeps
162	// an aggregated record calls these from its OWN code-work and passes the number to
163	// its agentic phase through the ordinary hand-off payload (`delivered.issue`,
164	// rendered into the work item by queue/code-work-run.mjs).
165	//
166	// It exists because two tasks had each grown a private copy of the same search, and
167	// the copies had already diverged in a way that matters — one filtered `is:open`,
168	// which never matches a tracker at rest and so opens a second one the moment
169	// anybody closes the first.
170	//
171	// TWO PROPERTIES THE LOOKUP IS SHAPED AROUND:
172	//
173	//   EXACT MATCH, NEVER THE SEARCH'S OWN RANKING. GitHub's `in:title` search is a
174	//   text match, so a title that is a prefix or near-twin of another task's comes
175	//   back too — and where sibling tasks keep sibling trackers, the top-ranked hit is
176	//   not reliably the right one. Every result is re-filtered on the trimmed title
177	//   being EQUAL to the one asked for.
178	//
179	//   A FAILED SEARCH IS NOT AN ABSENT TRACKER. `findTracker` returns null only for
180	//   a search that ran and matched nothing; anything else throws, because a caller
181	//   that treats a rate-limited search as "none exists" opens a fresh tracker on
182	//   every failure.
183	//
184	// Creation is deliberately a SEPARATE call. Whether a run with nothing to say
185	// should mint a tracker at all is the task's judgment — a sweep that found nothing
186	// may hold that its own scan is not news — so this module never creates as a side
187	// effect of looking.
188	
189	// The exact-title filter, pure so the ranking question is settled in a test rather
190	// than against a live repo's issue list. Lowest number wins: if a past race left
191	// two, every later run converges on the first and the duplicate stays inert.
192	export function pickTracker(items, title) {
193	  const want = title.trim();
194	  const exact = (items ?? [])
195	    .filter((i) => (i.title ?? '').trim() === want)
196	    .map((i) => ({ number: i.number, state: i.state }));
197	  if (!exact.length) return null;
198	  return exact.sort((a, b) => a.number - b.number)[0];
199	}
200	
201	// The tracker titled exactly `title`, or null if no issue carries it. Searches
202	// EVERY state: a tracker's resting state is closed, so a state-filtered lookup
203	// misses all of them.
204	//
205	// A tracker found OPEN is closed on the way back. Creation has closed since #951,
206	// but that only ever covered a tracker this code minted — one that predates the
207	// fix, or whose closing PATCH failed, had nothing anywhere that would ever look at
208	// its state again, so it sat open indefinitely (#904, open from 2026-08-16). The
209	// repair rides the lookup because every task's own run performs one, which is the
210	// only pass guaranteed to reach every tracker in the fleet.
211	export async function findTracker(gh, repo, title) {
212	  const want = title.trim();
213	  const q = encodeURIComponent(`repo:${repo} in:title "${want}"`);
214	  const { status, json } = await searchIssues(gh, q);
215	  if (status !== 200 || !Array.isArray(json?.items)) {
216	    throw new Error(`could not search for the tracker ${JSON.stringify(want)}: search returned ${status}`);
217	  }
218	  const exact = json.items.filter((i) => (i.title ?? '').trim() === want);
219	  const found = pickTracker(exact, want);
220	  if (!found) return null;
221	  // Fail-soft, and deliberately so: an unclosable tracker is untidy, never a
222	  // reason to fail the run that was about to write its record.
223	  if (found.state === 'open') {
224	    await patchIssue(gh, repo, found.number, { state: 'closed', state_reason: 'completed' }).catch(() => {});
225	  }
226	  return { number: found.number, duplicates: exact.length - 1 };
227	}
228	
229	// Create the tracker and close it — TWO calls, because issue creation always lands
230	// an issue open and ignores a `state` argument, so the single-call version left
231	// every tracker open across the fleet (#951).
232	export async function createTracker(gh, repo, title, body = null) {
233	  const want = title.trim();
234	  const created = await postIssue(gh, repo, { title: want, body: body ?? trackerSeedBody(want) });
235	  if (created.status >= 300 || !created.json?.number) {
236	    throw new Error(`could not create the tracker ${JSON.stringify(want)}: create returned ${created.status}`);
237	  }
238	  const number = created.json.number;
239	  const closed = await patchIssue(gh, repo, number, { state: 'closed', state_reason: 'completed' });
240	  return { number, leftOpen: closed.status >= 300 };
241	}
242	
243	// Find it, or create it — for a task that writes to its tracker on every run and
244	// therefore always wants one. A task whose run may have nothing to record calls
245	// `findTracker` alone and creates only once it has something to write.
246	export async function findOrCreateTracker(gh, repo, title) {
247	  const found = await findTracker(gh, repo, title);
248	  if (found) return { ...found, created: false };
249	  const made = await createTracker(gh, repo, title);
250	  return { number: made.number, duplicates: 0, created: true, leftOpen: made.leftOpen };
251	}
252	
253	// What a freshly-created tracker says before its first run writes to it. It names
254	// its own contract, because whoever finds it next finds it closed and empty.
255	export function trackerSeedBody(title) {
256	  return [
257	    `Standing tracker for the Claudinite task that logs to **${title}**.`,
258	    '',
259	    'This issue is a living document: the **body** is rewritten to the current picture each run,',
260	    'and each run adds a dated comment. Its closed state carries no meaning — nothing opens,',
261	    'closes or reopens it, and no run should be read as "resolved" because it is closed.',
262	    '',
263	    '_No run has written here yet._',
264	  ].join('\n') + '\n';
265	}
266	
267	// Write a run's state to the tracker: the BODY replaced with the current picture,
268	// and optionally one dated comment appended. The state is untouched, in either
269	// direction — the body is the live picture, the comments are the trail.
270	export async function writeTracker(gh, repo, number, { body, comment: note = null } = {}) {
271	  if (body !== undefined && body !== null) {
272	    const patched = await setIssueBody(gh, repo, number, body);
273	    if (patched.status >= 300) throw new Error(`could not refresh tracker #${number}: PATCH returned ${patched.status}`);
274	  }
275	  if (note) {
276	    const posted = await comment(gh, repo, number, note);
277	    if (posted.status >= 300) throw new Error(`could not comment on tracker #${number}: POST returned ${posted.status}`);
278	  }
279	  return number;
280	}
281

1	// Loading a task's OWN precondition terms — the extension mechanism the built-in
2	// vocabulary leaves room for (docs/PRINCIPLES.md).
3	// A task whose gate is its own (an age against a configured retention, a manifest
4	// against a release tag, a fleet read) ships `preconditions.mjs` beside its
5	// `task.json`, exporting `terms`: a map from term name to
6	// `{ signals, takesArg?, holds(signals, opts) }`. The term's code then lives
7	// beside its only consumer, so reading the declaration and reading the gate are
8	// one directory apart.
9	//
10	// Split from precondition-policy.mjs, which stays pure over the signals: this is
11	// the half that touches the filesystem, and the evaluator is handed the result.
12	
13	import { existsSync } from 'node:fs';
14	import { join } from 'node:path';
15	import { pathToFileURL } from 'node:url';
16	import { termsMap } from './precondition-policy.mjs';
17	
18	export const TASK_TERMS_FILE = 'preconditions.mjs';
19	
20	// The terms a task directory contributes — an empty map when it ships no file.
21	// A file that will not import THROWS: the caller (discovery, dispatch
22	// validation) reports the task as broken, which is the loud direction. A task
23	// whose gate cannot be loaded must not fall back to running unconditionally.
24	export async function loadTaskTerms(taskDir) {
25	  const file = join(taskDir, TASK_TERMS_FILE);
26	  if (!existsSync(file)) return new Map();
27	  return termsMap((await import(pathToFileURL(file).href)).terms);
28	}
29

