1	// The CODE-WORK phase of task execution (docs/PRINCIPLES.md): the
2	// deterministic first phase, run as a SUBPROCESS before the agentic phase (when
3	// there is one) — code work, Action-side, over the one sanctioned non-MCP
4	// surface (the Action GITHUB_TOKEN, inherited in `env`). Code-work and agentic
5	// work are similar, consecutive parts of one task execution; neither may decide
6	// to skip the run — that decision belongs to the precondition alone.
7	//
8	// The subprocess is the scheduler's child, so its `code_work_timeout`
9	// is a HARD kill: a manual timer SIGKILLs an overrun and the run is reported
10	// failed. Its cwd is the TASK directory, so a declared `node worker.mjs` resolves
11	// to the script beside task.json (the containment the contract enforces); the repo
12	// root and item context are handed in via CLAUDINITE_* env so the worker can act
13	// on the whole repo. Nothing the subprocess prints is threaded into the agent —
14	// code-work communicates only through the repository (PRINCIPLES.md).
15	//
16	// THE LOG IS NOT THAT CHANNEL. The child's output is ECHOED to the scheduler's own
17	// stdout/stderr as it arrives, so the Action log carries what the worker actually
18	// did. That is an observability decision, not a data channel: no agent reads the
19	// log, and PRINCIPLES.md's "communicate only through the repository" is untouched. It is echoed
20	// LIVE rather than dumped at exit for the case that needs it most — a worker SIGKILLed
21	// at its timeout, whose buffered output would otherwise die with it. Before this,
22	// a failed worker surfaced as a bare `code-work exited 1` plus a three-line
23	// stderr tail in an issue, and diagnosing one meant reproducing it by hand.
24	
25	import { existsSync, rmSync, readFileSync } from 'node:fs';
26	import { join } from 'node:path';
27	import { tmpdir } from 'node:os';
28	import { startProcess } from '../world/processes.mjs';
29	
30	// Run `command` as a subprocess bounded by `timeoutSeconds`. Resolves (never
31	// rejects) with { ok, timedOut, code, signal, stdout, stderr }: `ok` is a clean
32	// zero exit that did not time out. `taskDir` is the cwd; `env` is the full
33	// environment the child inherits (the caller injects GITHUB_TOKEN + CLAUDINITE_*).
34	// `echo` (default on) mirrors the child's output to this process as it arrives —
35	// injected rather than hardcoded so a test can capture it instead of polluting the
36	// test runner's own output.
37	export function runCodeWork(command, {
38	  taskDir, env, timeoutSeconds,
39	  echo = (chunk, stream) => (stream === 'stderr' ? process.stderr : process.stdout).write(chunk),
40	}) {
41	  return new Promise((resolve) => {
42	    // A cwd THAT NO LONGER EXISTS is the one spawn failure the caller cannot read.
43	    // Node reports it as an ENOENT on the command — `spawn /bin/sh ENOENT` under
44	    // `shell: true` — which names the one thing that is not missing, and sends
45	    // whoever reads it looking for a shell on the runner. The task directory can
46	    // genuinely vanish under a run in flight: one executor run drains several items
47	    // from one checkout, and an earlier item's mount update deletes a retired task's
48	    // directory out from under the items behind it.
49	    if (!existsSync(taskDir)) {
50	      resolve({ ok: false, timedOut: false, code: null, signal: null, stdout: '', stderr: `task directory ${taskDir} does not exist — nothing was run` });
51	      return;
52	    }
53	    // `detached` puts the shell and everything it spawns in their OWN process
54	    // group, which is what makes the kill below reach the worker: `shell: true`
55	    // means the direct child is `sh -c`, and signalling it alone leaves the
56	    // worker running — still acting on the repo, past a bound the scheduler has
57	    // already reported as enforced — while `close` waits on the stdio pipes the
58	    // survivor still holds.
59	    const child = startProcess(command, { cwd: taskDir, env, shell: true, detached: true });
60	    let stdout = '';
61	    let stderr = '';
62	    let timedOut = false;
63	    // Echo is best-effort: a worker's output must never be the thing that fails the
64	    // run, so a broken sink is swallowed rather than propagated.
65	    const mirror = (chunk, stream) => { try { echo?.(String(chunk), stream); } catch { /* the run matters, the echo does not */ } };
66	    const timer = setTimeout(() => {
67	      timedOut = true;
68	      // The hard kill — no grace period past the declared bound. Negative pid is
69	      // the whole group; if the group is already gone, so is the worker.
70	      try { process.kill(-child.pid, 'SIGKILL'); } catch { child.kill('SIGKILL'); }
71	    }, timeoutSeconds * 1000);
72	
73	    child.stdout?.on('data', (d) => { stdout += d; mirror(d, 'stdout'); });
74	    child.stderr?.on('data', (d) => { stderr += d; mirror(d, 'stderr'); });
75	    // A spawn error (command not found, etc.) is a failure, not a throw.
76	    child.on('error', (e) => {
77	      clearTimeout(timer);
78	      resolve({ ok: false, timedOut, code: null, signal: null, stdout, stderr: `${stderr}${e.message}` });
79	    });
80	    child.on('close', (code, signal) => {
81	      clearTimeout(timer);
82	      resolve({ ok: code === 0 && !timedOut, timedOut, code, signal, stdout, stderr });
83	    });
84	  });
85	}
86	
87	// The conditional-handoff signal (docs/PRINCIPLES.md, E4). A task with
88	// BOTH code-work AND a non-`none` agent_model hands off to the agent
89	// ONLY when its worker requests it — so a task can absorb its work into
90	// code-work and be AGENTLESS on the quiet nights. The scheduler hands the
91	// worker this path via CLAUDINITE_REQUEST_AGENT and hands off to an agent iff
92	// the worker created it. It is a pure control signal: the worker communicates
93	// DATA to the agent only through the repository, never through this file
94	// (docs/PRINCIPLES.md, "no code→agent data channel"). The hand-off condition must name work
95	// code-work COULD not do — never re-check whether the run should have happened;
96	// the precondition already decided that.
97	export function agentRequestPath({ pack, task, slotId }) {
98	  return join(tmpdir(), `claudinite-request-agent-${pack}-${task}-${slotId}`);
99	}
100	export function clearAgentRequest(path) { try { rmSync(path, { force: true }); } catch { /* nothing to clear */ } }
101	export function agentRequested(path) { return existsSync(path); }
102	
103	// …AND the artifacts that request refers to, plus why it was made. A worker writes
104	// JSON `{ delivered: { branch, pr, merged }, reason: { code, detail } }`, and the
105	// executor records both on the work item, which is where the agent reads them.
106	//
107	// This is the one thing that crosses the code→agent boundary as data (PRINCIPLES.md's named
108	// exception): identifiers for what this run created — a PR number, a branch ref — and
109	// the NAME of the condition that woke the agent. Never findings and never instructions:
110	// `reason.detail` says which gate fired and how many of what, and the findings
111	// themselves stay in the repo for the agent to re-run. Everything else still travels
112	// through the repository.
113	//
114	// Both keys are optional and their ABSENCE is meaningful, which is also what keeps an
115	// older vendored worker (one that predates a key) working: a worker that created
116	// nothing writes no `delivered` and the issue names none; a worker that does not know
117	// about `reason` writes none and the issue explains nothing, rather than asserting
118	// something false about why the agent is there.
119	export function readAgentRequest(path) {
120	  if (!existsSync(path)) return null;
121	  const raw = readFileSync(path, 'utf8').trim();
122	  if (!raw) return {};
123	  // A bare marker line (no payload) requests the agent and names no artifacts.
124	  try { return JSON.parse(raw); } catch { return {}; }
125	}
126	
127	// A one-line reason for the job summary / an issue comment when code-work
128	// fails — distinguishing a timeout kill from a non-zero exit.
129	export function codeWorkFailure(result) {
130	  if (result.timedOut) return 'code_work exceeded its code_work_timeout and was killed';
131	  if (result.code !== null) return `code-work exited ${result.code}`;
132	  return `code_work could not run: ${result.stderr.trim().split('\n').pop() || 'unknown error'}`;
133	}
134	
135	// THE WORKER'S OWN TRIAGE VERDICT. A failed worker is the only thing that knows
136	// why it failed — a 403 from a token without the scope it needs is a person's
137	// five-second fix, and an exception in its own code is a bug — and the executor,
138	// reading an exit code, cannot tell those apart. So a worker may say, on either
139	// stream, before it exits non-zero:
140	//
141	//     claudinite-needs-human: action — FLEET_GITHUB_TOKEN lacks Actions: write
142	//
143	// The kind is one of the triage kinds (`action`, `decision`, `approval`,
144	// `failure`). It NAMES WHAT THE PERSON MUST DO; it does not choose the park, which
145	// is `failure` for every failed run (#1452) — a worker that could downgrade its own
146	// non-zero exit into a non-blocking lane let the task re-file daily against a cause
147	// nobody had fixed. Both halves are rendered into the item's comment.
148	// The LAST marker wins, so a worker that sweeps many targets may revise its
149	// verdict as it goes. Read from the worker's output rather than from a file
150	// because it must survive the SIGKILL at `code_work_timeout` — output is echoed
151	// live, a file written at exit is not written at all.
152	const TRIAGE_MARKER = /^claudinite-needs-human:[ \t]*([a-z]+)\b[ \t]*(.*)$/gm;
153	export function readTriageMarker(text) {
154	  let last = null;
155	  for (const m of String(text ?? '').matchAll(TRIAGE_MARKER)) last = m;
156	  if (!last) return null;
157	  return { kind: last[1], detail: last[2].replace(/^[—\-:\s]+/, '').trim() || null };
158	}
159	
160	// THE WORKER'S REQUEUE ASK (#1530). An exit code has two answers — 0 closes the
161	// item done, non-zero parks it — and a worker whose subject is NOT YET THERE (a
162	// production verification whose release has not landed) needs the third: the run
163	// happened, found nothing wrong, and must come back later. So, before a clean
164	// exit, it may say when:
165	//
166	//     claudinite-requeue: 2026-09-01T12:00:00Z — not yet live: mode unstamped
167	//
168	// The executor stamps the instant as the item's `Not-before` and returns it to
169	// blocked; the scheduler's ordinary readiness pass releases it when the moment
170	// comes. Honoured only on an OK exit — a failed run is a failure whatever it
171	// printed — and read off the output like the triage marker, last one winning, so
172	// a worker may revise its wake as it works. The instant is normalized to UTC
173	// ISO; one that does not parse comes back as `until: null`, an ask the executor
174	// must refuse loudly rather than drop — the worker said "wait", and closing done
175	// on it would record a pass nobody measured.
176	const REQUEUE_MARKER = /^claudinite-requeue:[ \t]*(\S+)[ \t]*(.*)$/gm;
177	export function readRequeueMarker(text) {
178	  let last = null;
179	  for (const m of String(text ?? '').matchAll(REQUEUE_MARKER)) last = m;
180	  if (!last) return null;
181	  const at = new Date(last[1]);
182	  return {
183	    until: Number.isNaN(at.getTime()) ? null : at.toISOString(),
184	    reason: last[2].replace(/^[—\-:\s]+/, '').trim() || null,
185	  };
186	}
187

