1	// THE CONTINUATION OF A DEAD EXECUTOR RUN (docs/PRINCIPLES.md, S36).
2	//
3	// A run that dies — crash, timeout, cancellation, runner loss — never reaches its
4	// own re-dispatch, so without this the queue would sit until the next scheduled
5	// tick. The platform runs the calling job on a FRESH runner after any such death,
6	// and this fires that dispatch instead: the remainder drains in ~a minute, while
7	// the dead run's OWN item waits for the executing leash to reclaim it — nothing
8	// here touches that item.
9	//
10	// `continuation_depth` is the stop. A run that dies at startup — a broken engine,
11	// a revoked token — dies identically every time, and an unguarded continuation
12	// would dispatch itself for as long as that lasts. After MAX_DEPTH the chain
13	// stops and SAYS SO on the repo's workflow-failure issue: a queue that has quietly
14	// stopped draining is the one failure nothing else here would surface, since every
15	// individual run looks like an ordinary death.
16	
17	import { pathToFileURL } from 'node:url';
18	import { makeGh } from '../world/github.mjs';
19	import { actionRepoContext, actionsEnv, EXECUTOR_WORKFLOW_FILE } from '../world/actions.mjs';
20	import { dispatchWorkflow } from '../world/github.mjs';
21	import { reportWorkflowFailure, runUrl } from './workflow-failure.mjs';
22	
23	export const MAX_DEPTH = 3;
24	
25	export const CHAIN_FAILURE_TITLE = 'Claudinite executor chain failed repeatedly';
26	
27	// An absent, empty or unparseable depth is depth 0 — the first death in a chain.
28	// It must never read as a large number, which would silence the continuation
29	// exactly when the queue most needs it.
30	export const nextDepth = (raw) => {
31	  const n = Number(String(raw ?? '').trim());
32	  return (Number.isFinite(n) && n > 0 ? Math.floor(n) : 0) + 1;
33	};
34	
35	// The decision, separated from the CLI shell so it tests against a fake `gh`.
36	// Resolves to the continuation it made; throws when the chain is over, which is
37	// what turns the calling job red.
38	export async function continueOrEscalate(gh, repo, defaultBranch, depth) {
39	  if (depth <= MAX_DEPTH) {
40	    const { ok, status } = await dispatchWorkflow(gh, repo, EXECUTOR_WORKFLOW_FILE, defaultBranch,
41	      { continuation_depth: String(depth) });
42	    if (!ok) throw new Error(`could not continue the chain on ${defaultBranch}: ${status}`);
43	    console.log(`- the executor run died — dispatched a fresh one on ${defaultBranch} (continuation ${depth} of ${MAX_DEPTH})`);
44	    return { continued: depth };
45	  }
46	
47	  // The chain has died MAX_DEPTH times running: this is not one bad runner, and
48	  // dispatching another would spend the day proving it. Escalate to the same
49	  // one-open-issue surface the scheduler's own failures use, and let the next
50	  // scheduled tick be what tries again.
51	  const { issue, created } = await reportWorkflowFailure(gh, repo, {
52	    title: CHAIN_FAILURE_TITLE,
53	    body: `${MAX_DEPTH} consecutive executor runs died before finishing their item.`
54	      + ' The chain stops here; the next scheduled scheduler run will dispatch a fresh one.'
55	      + `\n\nThe last run: ${runUrl()}`,
56	  });
57	  console.log(`- ${created ? 'filed' : 'commented on'} #${issue}`);
58	  throw new Error(`the executor chain died ${MAX_DEPTH} times in a row — escalated`);
59	}
60	
61	export async function runExecutorContinuation() {
62	  const { repo, defaultBranch } = actionRepoContext();
63	  if (!repo) throw new Error('GITHUB_REPOSITORY is not set');
64	  await continueOrEscalate(makeGh(), repo, defaultBranch, nextDepth(actionsEnv().CLAUDINITE_CONTINUATION_DEPTH));
65	}
66	
67	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
68	  runExecutorContinuation().catch((e) => { console.error(e.message ?? e); process.exitCode = 1; });
69	}
70

