content.content:
1	// The verify-production code-work (#1530) — the I/O shell around probes.mjs. It
2	// runs Action-side, which is the whole reason this task exists: an agent session
3	// has no egress, so a verification whose artifact is a live URL (a Pages site, a
4	// deployed config) can only be read from here.
5	//
6	// Four verdicts, each its own exit:
7	//   invalid  — the spec is unreadable: the triage marker names every problem and
8	//              the exit is non-zero, so the item parks with the list.
9	//   not-live — a liveness probe failed: print the requeue marker with
10	//              now + Retry-every and exit clean; the executor re-arms the item.
11	//   pass     — comment the evidence on the item and exit clean; the executor
12	//              closes it done.
13	//   fail     — reopen Original-issue with the evidence (the verification did its
14	//              job by finding the fault, which is now that issue's), link it from
15	//              the item, and exit clean.
16	
17	import { humanTextOf } from '../../public/work-item-grammar.mjs';
18	import { parseVerificationSpec, runProbes, renderResult } from './probes.mjs';
19	import { getIssue, reopenIssue, comment as ghComment } from '../../src/world/github.mjs';
20	
21	const FETCH_TIMEOUT_MS = 30_000;
22	const BODY_CAP = 2 * 1024 * 1024;
23	
24	// One live fetch: bounded, redirect-following, body capped. A network error is
25	// retried once — a single blip must not reopen an issue — and the second failure
26	// is the answer.
27	export async function fetchOnce(url) {
28	  const attempt = async () => {
29	    const res = await fetch(url, { redirect: 'follow', signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });
30	    const body = (await res.text()).slice(0, BODY_CAP);
31	    return { status: res.status, body };
32	  };
33	  try { return await attempt(); } catch { return attempt(); }
34	}
35	
36	// The whole judgment, injectable for tests: reads the item, parses the spec out
37	// of the HUMAN half of its body (the machine block is the queue's), runs the
38	// probes, and lands the verdict's writes. Returns what `worker` turns into the verdict
39	// and an exit code.
40	export async function runVerification({ gh, repo, itemNumber, fetchUrl, now = () => new Date(), log = console.log }) {
41	  const { status, json: item } = await getIssue(gh, repo, itemNumber);
42	  if (status !== 200) throw new Error(`could not read item #${itemNumber}: ${status}`);
43	  const spec = parseVerificationSpec(humanTextOf(item.body));
44	  if (spec.problems.length) return { outcome: 'invalid', problems: spec.problems };
45	
46	  const live = await runProbes(spec.live, fetchUrl);
47	  for (const r of live) log(`liveness: ${renderResult(r)}`);
48	  if (!live.every((r) => r.ok)) {
49	    const firstFail = live.find((r) => !r.ok);
50	    return {
51	      outcome: 'not-live',
52	      until: new Date(now().getTime() + spec.retryEveryMs).toISOString(),
53	      reason: `not yet live: ${renderResult(firstFail)}`,
54	    };
55	  }
56	
57	  const verify = await runProbes(spec.verify, fetchUrl);
58	  for (const r of verify) log(`verify: ${renderResult(r)}`);
59	  const evidence = verify.map((r) => `- ${renderResult(r)}`).join('\n');
60	  if (verify.every((r) => r.ok)) {
61	    await ghComment(gh, repo, itemNumber, `Production verification PASSED. What was read:\n\n${evidence}`);
62	    return { outcome: 'pass' };
63	  }
64	
65	  // The verification did its job by finding the fault — which is now the
66	  // original issue's, reopened with what was asserted and what was read.
67	  await reopenIssue(gh, repo, spec.originalIssue);
68	  await ghComment(gh, repo, spec.originalIssue,
69	    `The production verification filed for this change (#${itemNumber}) FAILED against the live artifact:\n\n${evidence}\n\n`
70	    + 'The release is live (every liveness probe passed), so this is a fault in production, not a wait.');
71	  await ghComment(gh, repo, itemNumber,
72	    `Verification FAILED — reopened #${spec.originalIssue} with the evidence:\n\n${evidence}`);
73	  return { outcome: 'fail', originalIssue: spec.originalIssue };
74	}
75	
76	export async function worker({ repo, item, gh }) {
77	  const itemNumber = item.number;
78	  const verdict = await runVerification({ gh, repo, itemNumber, fetchUrl: fetchOnce });
79	
80	  if (verdict.outcome === 'invalid') {
81	    return { triage: { kind: 'action', detail: `this verification's probe spec is unreadable: ${verdict.problems.join('; ')}` } };
82	  }
83	  // NOT YET LIVE is the third answer an exit code does not have: the run happened,
84	  // found nothing wrong, and must come back when the release has landed.
85	  if (verdict.outcome === 'not-live') {
86	    return { requeue: { until: verdict.until, reason: verdict.reason } };
87	  }
88	  console.log(`verification ${verdict.outcome === 'pass' ? 'passed' : `failed — reopened #${verdict.originalIssue}`}`);
89	  return undefined;
90	}
91

diff --git a/packs/claudinite-tasks/src/contract/dormancy.mjs b/packs/claudinite-tasks/src/contract/dormancy.mjs
index 1d1e287..01d303f 100644
--- a/packs/claudinite-tasks/src/contract/dormancy.mjs
+++ b/packs/claudinite-tasks/src/contract/dormancy.mjs
@@ -5,7 +5,7 @@
 // WHY THIS LIVES IN THIS PACK. Every effect dormancy has is an effect on the queue —
 // nothing is instantiated, nothing is picked up, and nothing outside expects movement.
 // A repo that declares no tasks pack has no scheduler at all, so the word means nothing
-// there, and an engine that validated it for such a repo was answering for a mechanism
+// there, and an engine validating it for such a repo would be answering for a mechanism
 // it does not own. So the setting is one of this pack's parameters, declared where the
 // pack is:
 //
@@ -19,7 +19,7 @@
 //   - NO UPKEEP CEREMONY FROM OUTSIDE. Whatever looks at this repo from the outside
 //     reads the same declaration and asks it nothing about its upkeep: neither its
 //     scheduler nor its mount is judged, and no fleet-wide operation is run against it
-//     (owner, 2026-09-13). A scheduler TOLD to stop must not then be nagged for
+//     A scheduler TOLD to stop must not then be nagged for
 //     stopping, and a mount nothing will converge cannot be behind in a way anyone is
 //     going to fix — both verdicts would be findings with no owner. What a reader owes
 //     such a repo instead is the word "dormant" where those verdicts would have sat.
@@ -71,8 +71,8 @@ function declared(config) {
   if (own !== undefined) return own;
   // The retired spelling, underneath the pack entry so a converged member is never
   // overridden by a stale key its migration left behind. `raw` is the declaration as
-  // the member wrote it, which is where a top-level key survives now that the engine
-  // no longer normalizes one it does not own.
+  // the member wrote it, which is where a top-level key survives: the engine does not
+  // normalize one it does not own.
   // @legacy-tolerance advisory:legacy-shape-in-use retire:#1846
   return config.raw?.[DORMANT_CONFIG_KEY] ?? config[DORMANT_CONFIG_KEY];
 }

