content.content:
1	// The work item's grammar — the queue's one durable object (docs/PRINCIPLES.md),
2	// as the parse and serialize over its vocabulary (`task-constants.mjs`). An issue
3	// titled `[claudinite-work] <pack>/<task> [qualifier]`, whose labels are its state,
4	// whose body's first line is the task path, and whose optional body fields
5	// (`Not-before`, `Blocked-by`, and a request's `Request` / `Model`) are the only
6	// facts it carries beyond that.
7	//
8	// PURE, and deliberately the whole schema: everything else — anchors, guards,
9	// yields, leashes, verdicts — is computed fresh at every scheduler run and pick from the
10	// engine and the declarations at HEAD (PRINCIPLES.md). The label-and-field vocabulary
11	// is therefore the compatibility surface across engine versions, and this file is the
12	// one definition of how it is read and written: `src/` imports it from here, as does
13	// every other pack — the dashboard loads it unbundled in a browser, which is why
14	// nothing here reaches a Node built-in.
15	//
16	// Parse/serialize of those fields lives here and nowhere else (PRINCIPLES.md).
17	//
18	// Two imports, both frozen data: the vocabulary this grammar is over, and the
19	// pack-rename map, which the title parse needs to keep reading titles written before
20	// a rename (see parseWorkItemTitle).
21	import { canonicalPackId } from '../../../engine/pack_loader/renamed-packs.mjs';
22	import {
23	  WORK_PREFIX, PARK_PREFIX, STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR,
24	  STATUS_RUNNING_AGENT, STATUS_NEEDS_HUMAN_FAILURE, STATUS_DONE, STATUS_REJECTED, PARK_KINDS,
25	  PARK_STATUSES, STATUS_LABELS, ORIGIN_AD_HOC, ORIGIN_LABELS, ASKED_FOR_ORIGINS,
26	  LEGACY_BLOCKED, LEGACY_READY, LEGACY_EXECUTING, LEGACY_AGENT, NEEDS_HUMAN,
27	  OUTCOME_DELIVERED, OUTCOME_DONE, OUTCOME_OBSOLETE, LEGACY_TASK_DONE, LEGACY_TASK_OBSOLETE,
28	  ORIGIN_SCHEDULE, REQUEST_MODELS, NOT_BEFORE_FIELD, BLOCKED_BY_FIELD, ENDS_WHEN_FIELD,
29	  ENDS_WHEN_CLOSED, TARGET_BRANCH_FIELD, TARGET_PR_FIELD, SUPERSEDES_FIELD, WOKEN_FIELD,
30	  REQUEST_FIELD, MODEL_FIELD, MERGE_FIELD, MERGE_IF_NARROW, DELIVERED_HEADING,
31	  MACHINE_BLOCK_START, MACHINE_BLOCK_END, PROGRESS_HEADING, LAST_VERDICT_HEADING, TASK_TRAILER,
32	} from './task-constants.mjs';
33	
34	// WHICH PARK IS A BROKEN RUN. A park is not live, so no park holds its task's lane by
35	// itself: the scheduler asks the task again on its own conditions, and only a task
36	// declaring `last-run-not-failed` stops past its own failure. What this predicate
37	// tells apart is the park a person DIAGNOSES from the three that are a person's
38	// inbox — a PR waiting to be approved, a choice waiting to be made, a secret waiting
39	// to be set — which is the split every renderer alarms on and the run-history term
40	// reads (`parkKindOf`).
41	//
42	// A park wearing NO sub-label counts as broken, which is what makes this safe on the
43	// way in: every item parked by an engine older than the sub-labels, and every kind
44	// word a future engine invents that this one does not know, reads as "diagnose me"
45	// rather than quietly joining the mechanical lane.
46	export const isBlockingPark = (item) => statusOf(item) === STATUS_NEEDS_HUMAN_FAILURE;
47	
48	// --- the decode (PRINCIPLES.md, "legacy spellings — written never, read forever") --
49	// Labels are STORED DATA: open items filed by a fielded engine wear its spellings,
50	// closed items keep theirs forever, and members converge on their own schedules. So
51	// every reader here goes through one pass that maps every spelling ever written
52	// straight to today's — never through a literal comparison against one of them.
53	//
54	// The `task:*` entries come out when no OPEN item wears one (#1913); the two
55	// `outcome:*` entries never do, because a closed item's labels are stored data and
56	// dropping them would turn every historical run into an un-outcomed one.
57	// @legacy-tolerance advisory:none retire:#1913
58	const LEGACY_STATUS = new Map([
59	  [LEGACY_BLOCKED, STATUS_BLOCKED],
60	  [LEGACY_READY, STATUS_READY],
61	  [LEGACY_EXECUTING, STATUS_RUNNING_EXECUTOR],
62	  [LEGACY_AGENT, STATUS_RUNNING_AGENT],
63	  [LEGACY_TASK_DONE, STATUS_DONE], [OUTCOME_DONE, STATUS_DONE],
64	  [LEGACY_TASK_OBSOLETE, STATUS_REJECTED], [OUTCOME_OBSOLETE, STATUS_REJECTED],
65	]);
66	
67	// @legacy-tolerance advisory:none retire:#1913
68	const LEGACY_PARK_RE = /^task:needs-human-(.+)$/;
69	
70	// The park an issue's labels name, canonical, or null. Both shapes decode here:
71	// today's single `task:status:needs-human-<kind>` and the legacy pair
72	// (`needs-human` plus a sub-label). A kind nobody here knows — a bare legacy park,
73	// or a word a newer engine invented — reads as `failure`, the conservative lane.
74	function parkOf(names) {
75	  const kinds = [
76	    ...names.filter((n) => n.startsWith(PARK_PREFIX)).map((n) => n.slice(PARK_PREFIX.length)),
77	    ...names.map((n) => LEGACY_PARK_RE.exec(n)?.[1]).filter(Boolean),
78	  ];
79	  if (!kinds.length && !names.includes(NEEDS_HUMAN)) return null;
80	  return `${PARK_PREFIX}${PARK_KINDS.find((k) => kinds.includes(k)) ?? 'failure'}`;
81	}
82	
83	// Every distinct status an issue's labels decode to. One entry per status, so an
84	// item mid-flip — wearing a legacy spelling beside its canonical one — reads as the
85	// ONE status it is, and only genuinely conflicting labels read as more than one
86	// (the dashboard's `torn`).
87	export function statusesOn(issue) {
88	  const names = labelNames(issue);
89	  const out = new Set();
90	  const park = parkOf(names);
91	  if (park) out.add(park);
92	  for (const n of names) {
93	    if (STATUS_LABELS.includes(n) && !n.startsWith(PARK_PREFIX)) out.add(n);
94	    else if (LEGACY_STATUS.has(n)) out.add(LEGACY_STATUS.get(n));
95	  }
96	  return [...out];
97	}
98	
99	// THE status an issue wears, canonical, or null for one wearing none. A park wins
100	// over anything else present: a torn transition that left a state label beside a
101	// park must read as parked, or the queue would pick up an item a human owns.
102	export function statusOf(issue) {
103	  const worn = statusesOn(issue);
104	  return worn.find((s) => s.startsWith(PARK_PREFIX))
105	    ?? STATUS_LABELS.find((s) => worn.includes(s))
106	    ?? null;
107	}
108	
109	export const isStatus = (issue, status) => statusOf(issue) === status;
110	export const isParked = (issue) => (statusOf(issue) ?? '').startsWith(PARK_PREFIX);
111	export const parkKindOf = (issue) =>
112	  (isParked(issue) ? statusOf(issue).slice(PARK_PREFIX.length) : null);
113	
114	// The origin an issue wears, or null. Unlike the status there is no legacy
115	// spelling to fold in: `origin:schedule` is inert stored data (see ORIGIN_SCHEDULE),
116	// and reading it as an origin would put a marker nothing writes back into play.
117	export const originOf = (issue) =>
118	  labelNames(issue).find((n) => ORIGIN_LABELS.includes(n)) ?? null;
119	
120	// Every spelling that MEANS `status` — what a transition out of it has to clear,
121	// since the item may wear any engine's. Leaving a park clears every park spelling
122	// whatever its kind: a re-queue takes the item out of the human's hands entirely.
123	export function spellingsOf(status) {
124	  if (String(status ?? '').startsWith(PARK_PREFIX)) {
125	    return [...PARK_STATUSES, ...PARK_KINDS.map((k) => `task:needs-human-${k}`), NEEDS_HUMAN];
126	  }
127	  const legacy = [...LEGACY_STATUS].filter(([, canonical]) => canonical === status).map(([l]) => l);
128	  return [status, ...legacy];
129	}
130	
131	// A kind word (from a worker's own triage marker, or a call site) to the park it
132	// names. Anything unrecognised is a `failure`: a worker that misspells its class has
133	// a bug, which is exactly what that lane means.
134	export const triageLabelFor = (kind) =>
135	  (PARK_KINDS.includes(kind) ? `${PARK_PREFIX}${kind}` : STATUS_NEEDS_HUMAN_FAILURE);
136	
137	
138	// The stored-data rename rule, decode side: every spelling ever written maps
139	// STRAIGHT to the canonical word, in one pass — including `outcome:delivered`,
140	// which nothing writes any more but closed issues carry forever.
141	const OUTCOME_WORDS = new Map([[STATUS_DONE, 'done'], [STATUS_REJECTED, 'obsolete']]);
142	
143	// The one outcome an issue's labels carry, as the canonical word ('done',
144	// 'delivered', 'obsolete') or null. Everything that tallies or renders outcomes
145	// decodes through here, so a spelling change is one map entry and not a sweep.
146	export function outcomeOf(issue) {
147	  // `statusesOn` rather than `statusOf`: a closed item's terminal write is its
148	  // outcome even when a park label stands beside it, and park precedence is a
149	  // question about LIVE items — what the queue may pick up — not about history.
150	  const worn = statusesOn(issue);
151	  for (const [status, word] of OUTCOME_WORDS) if (worn.includes(status)) return word;
152	  return hasLabel(issue, OUTCOME_DELIVERED) ? 'delivered' : null;
153	}
154	
155	// GitHub hands labels back as objects on the issues API and as bare strings in
156	// some fixtures; accept either.
157	export const labelNames = (issue) =>
158	  (issue?.labels ?? []).map((l) => (typeof l === 'string' ? l : l?.name)).filter(Boolean);
159	
160	export const hasLabel = (issue, name) => labelNames(issue).includes(name);
161	
162	// Title. The optional qualifier exists ONLY for deliberately concurrent items —
163	// a fan-out naming its target — and it is part of the identity the same-title
164	// mutex reads (PRINCIPLES.md). Nothing ever encodes a date here: that was the slot
165	// grammar, and the issue number is the identity (PRINCIPLES.md).
166	export const workItemTitle = ({ pack, task, qualifier = null }) =>
167	  `${WORK_PREFIX} ${pack}/${task}${qualifier ? ` ${qualifier}` : ''}`;
168	
169	// pack and task ids are single path segments; the qualifier is whatever follows.
170	const TITLE_RE = /^\[claudinite-work\]\s+([^/\s]+)\/([^/\s]+)(?:\s+(\S.*))?$/;
171	
172	// The pack half is canonicalized on the way out. A work item's title is STORED
173	// DATA — it sits on an open GitHub issue that outlives any one converge — so items
174	// filed before a pack was renamed still carry the old spelling. Read literally, the
175	// scheduler run would not recognise its own live item, would file a second one beside it, and
176	// would leave the first orphaned in the queue with nothing ever draining it.
177	export function parseWorkItemTitle(title) {
178	  const m = TITLE_RE.exec(String(title ?? '').trim());
179	  return m ? { pack: canonicalPackId(m[1]), task: m[2], qualifier: m[3]?.trim() || null } : null;
180	}
181	
182	export const isWorkItemTitle = (title) => parseWorkItemTitle(title) !== null;
183	
184	// The `<pack>/<task>` id a WORKER PATH names — the identity half a marked issue's
185	// title cannot carry (PRINCIPLES.md), read off the path its machine block names. Two
186	// shapes, because tasks have two homes: the `tasks/` slot a declared pack contributes,
187	// and the queue's own built-in root. The `.claudinite/shared/` prefix is optional in
188	// both — a member's mount is there and the canon runs its own tree.
189	//
190	// THE BUILT-IN ROOT HAS TWO SPELLINGS, and both are permanent. The surface moved from
191	// `engine/scheduler/` to the tasks pack (#1317), so a live item minted before the move
192	// still names the engine path while every new one names the pack path; the wire id
193	// either produces is unchanged, which is what the move promised. Stored data is
194	// renamed on the DECODE side or it stops decoding, and here that failure is silent:
195	// this is the fallback for a marked issue, whose title is the requester's own words,
196	// so a path that yields null leaves the item unattributable rather than rejected.
197	//
198	// It is a PARSE, not a lookup: anything that must know the task exists at HEAD
199	// resolves the path against the discovered task set instead (the executor does).
200	const PACK_TASK_PATH_RE = /^(?:\.claudinite\/shared\/)?packs\/([^/]+)\/tasks\/([^/]+)\/[^/]+$/;
201	const BUILT_IN_TASK_PATH_RE = /^(?:\.claudinite\/shared\/)?(?:engine\/scheduler|packs\/claudinite-tasks)\/queue\/tasks\/([^/]+)\/[^/]+$/;
202	// The built-in spec's `public/` home, which new items name. `taskIdFromPath` is the
203	// DECODE side, so this is read forever beside the two above: an item minted today
204	// outlives any number of moves, and an undecodable path leaves it unattributable.
205	export const BUILT_IN_PUBLIC_TASK_PATH_RE = /^(?:\.claudinite\/(?:shared|local)\/)?packs\/claudinite-tasks\/public\/(implement-request)\.md$/;
206	
207	export function taskIdFromPath(path) {
208	  const p = String(path ?? '');
209	  const pack = PACK_TASK_PATH_RE.exec(p);
210	  if (pack) return { pack: canonicalPackId(pack[1]), task: pack[2] };
211	  const builtIn = BUILT_IN_TASK_PATH_RE.exec(p) ?? BUILT_IN_PUBLIC_TASK_PATH_RE.exec(p);
212	  return builtIn ? { pack: 'engine', task: builtIn[1] } : null;
213	}
214	
215	// STANDING OR AD-HOC, DERIVED (PRINCIPLES.md). A task's standing item is the one
216	// the scheduler files when the task says yes: its title names the task and nothing
217	// else, and the task it names is on the schedule. Everything else is ad-hoc — an
218	// unscheduled task's item (the scheduler never asks it) and every qualified item
219	// (a fan-out target, a request naming its issue), each of which may legitimately
220	// run beside the occurrence rather than being it.
221	//
222	// It is read off the item and the declaration at HEAD rather than off a label the
223	// creator applied, because the two could disagree: a marker says what its writer
224	// believed, the structure says what the item IS, and the guards that consume this
225	// (the live-item guard, the dedupe, the `after` yield) are only sound on the
226	// second. `scheduled` is whether the task the title names is asked by the
227	// scheduler (`isScheduledTask` in task-contract.mjs) — null when the repo no
228	// longer carries it, which is ad-hoc by the same rule.
229	export function isStandingItem(item, scheduled) {
230	  const parsed = parseWorkItemTitle(item?.title ?? item);
231	  return !!parsed && parsed.qualifier === null && scheduled === true;
232	}
233	
234	// A Merge/Automerge field value, fenced to what the policy engine can read: the
235	// canonical expression, or null for anything else. Fencing here is about SHAPE
236	// only — a well-formed policy naming a rule nobody defines rides through and
237	// fails closed at the verdict, loudly, which is better feedback than silently
238	// ignoring the ask. A policy of `nothing` is the default already, so it reads
239	// as absent.
240	//
241	// The grammar mirrors merge-policy.mjs's normalizePolicy — the semantic
242	// authority — and cannot import it: this module is deliberately pure (see the
243	// header), so the drift guard is the test that runs a value matrix through both
244	// sides (test/queue/request-mode.test.mjs).
245	const RULE_NAME = /^[a-z0-9]+(-[a-z0-9]+)*$/;
246	const PATH_SEGMENT = /^[A-Za-z0-9._-]+$/;
247	const policyName = (name) => {
248	  if (!name.startsWith('under:')) return RULE_NAME.test(name);
249	  const segments = name.slice('under:'.length).replace(/\/+$/, '').split('/');
250	  return segments.every((seg) => PATH_SEGMENT.test(seg) && seg !== '.' && seg !== '..');
251	};
252	// A term is `&&`-joined names, optionally reject:-prefixed. The value is returned
253	// CANONICAL — whitespace around `&&` collapsed — so an item body, and the trailer
254	// stamped from it, stay whitespace-free whatever a person typed.
255	function policyFieldValue(raw) {
256	  if (raw == null) return null;
257	  const value = String(raw).trim();
258	  if (['if-narrow', 'yes', 'true'].includes(value.toLowerCase())) return MERGE_IF_NARROW;
259	  if (value.toLowerCase() === 'anything') return 'anything';
260	  const terms = value.split(';').map((term) => {
261	    const prefix = term.trim().startsWith('reject:') ? 'reject:' : '';
262	    const names = term.trim().slice(prefix.length).split('&&').map((n) => n.trim());
263	    return { prefix, names, canonical: prefix + names.join('&&') };
264	  });
265	  const wellFormed = terms.length > 0
266	    && terms.every(({ names }) => names.every((n) => policyName(n) && n !== 'nothing'))
267	    && terms.some(({ prefix }) => !prefix);
268	  return wellFormed ? terms.map((t) => t.canonical).join(';') : null;
269	}
270	
271	const BLOCK_RE = /<!-- claudinite-item -->\n?([\s\S]*?)\n?<!-- \/claudinite-item -->/;
272	
273	// The machine's half of a body, or null where there is no block at all.
274	export const machineBlockOf = (body) => BLOCK_RE.exec(String(body ?? ''))?.[1] ?? null;
275	
276	// The machine's half to read fields out of: the block where there is one, the whole
277	// body otherwise.
278	export const itemFieldText = (body) => machineBlockOf(body) ?? String(body ?? '');
279	
280	// Replace the block, or append one to a body that has none. The human's text is
281	// never rewritten — an append lands after it, separated by a blank line.
282	export function withMachineBlock(body, block) {
283	  const text = String(body ?? '');
284	  const wrapped = `${MACHINE_BLOCK_START}\n${block.replace(/\s*$/, '')}\n${MACHINE_BLOCK_END}`;
285	  if (BLOCK_RE.test(text)) return text.replace(BLOCK_RE, wrapped);
286	  return `${text.replace(/\s*$/, '')}\n\n${wrapped}\n`;
287	}
288	
289	// Apply an edit to whichever half is the machine's. Every writer that reshapes an
290	// item body — a Context section, code-work's delivered list, a stamped
291	// `Not-before` — goes through here, so it edits the block on a marked issue and the
292	// whole body on a `[claudinite-work]` item, with one call site either way.
293	export function editItemBody(body, edit) {
294	  const block = machineBlockOf(body);
295	  return block === null ? edit(String(body ?? '')) : withMachineBlock(body, edit(block));
296	}
297	
298	// The human's half of a body — everything the machine block is not. A marked
299	// issue's PARAMETERS are read from here and never from the block: re-asking clears
300	// the status and leaves the previous run's block standing, and a parser that read
301	// the whole body would find that stale copy beside the person's own field.
302	export const humanTextOf = (body) => String(body ?? '').replace(BLOCK_RE, '').trim();
303	
304	const NOT_BEFORE_RE = /^Not-before:[ \t]*(.*)$/m;
305	const BLOCKED_BY_RE = /^Blocked-by:[ \t]*(.*)$/m;
306	const REQUEST_RE = /^Request:[ \t]*#?(\d+)/m;
307	const MODEL_RE = /^Model:[ \t]*(\S+)/m;
308	const MERGE_RE = /^Merge:[ \t]*(\S+)/m;
309	const ENDS_WHEN_RE = /^Ends-when:[ \t]*#(\d+)[ \t]+(\S+)[ \t]*$/m;
310	const TARGET_BRANCH_RE = /^Target-branch:[ \t]*(\S+)[ \t]*$/m;
311	const TARGET_PR_RE = /^Target-pr:[ \t]*#?(\d+)[ \t]*$/m;
312	const SUPERSEDES_RE = /^Supersedes:[ \t]*(.*)$/m;
313	const WOKEN_RE = /^Woken:[ \t]*(\S+)[ \t]*$/m;
314	
315	// Build a work item body. The first line is the task path — the only thing an
316	// executor reads to locate the worker, validated in code before anything trusts
317	// it. Everything behavior-defining (model, ceiling, worker content, code-work
318	// command) is read from the tracked task files at HEAD, never from here.
319	export function workItemBody({
320	  taskPath, notBefore = null, blockedBy = [], context = [], delivered = [], reason = null,
321	  request = null, model = null, merge = null, woken = null,
322	}) {
323	  const lines = [taskPath, ''];
324	  const fields = [];
325	  if (notBefore) fields.push(`${NOT_BEFORE_FIELD}: ${notBefore}`);
326	  if (blockedBy.length) fields.push(`${BLOCKED_BY_FIELD}: ${blockedBy.map((n) => `#${n}`).join(', ')}`);
327	  if (request) fields.push(`${REQUEST_FIELD}: #${request}`);
328	  if (model) fields.push(`${MODEL_FIELD}: ${model}`);
329	  if (merge) fields.push(`${MERGE_FIELD}: ${merge}`);
330	  if (woken) fields.push(`${WOKEN_FIELD}: ${woken}`);
331	  if (fields.length) lines.push(...fields, '');
332	  lines.push('Execute the Claudinite task above.');
333	  if (context.length) {
334	    lines.push(
335	      'The Context section below is binding scope — do not re-decide it.',
336	      '',
337	      '### Context',
338	      ...context.map((c) => `- ${c}`),
339	    );
340	  }
341	  if (reason) lines.push('', '### Why the agent is here', '', `- ${reason}`);
342	  if (delivered.length) lines.push('', `### ${DELIVERED_HEADING}`, '', ...delivered.map((d) => `- ${d}`));
343	  return lines.join('\n') + '\n';
344	}
345	
346	// The `Blocked-by` numbers a body names, from a work item's body or from an
347	// ORDINARY issue's — a request marked for implementation states what it waits on in
348	// the same field spelling, and adoption carries it onto the item it births (PRINCIPLES.md).
349	export function parseBlockedBy(body) {
350	  const bb = BLOCKED_BY_RE.exec(String(body ?? ''))?.[1] ?? '';
351	  return [...bb.matchAll(/#(\d+)/g)].map((m) => Number(m[1]));
352	}
353	
354	// Parse an item body back into the facts the scheduler run and the executor read. A body
355	// with no first line, or whose fields are absent, yields nulls — absence is
356	// meaningful everywhere here and is never filled in with a default.
357	export function parseWorkItemBody(body) {
358	  const text = itemFieldText(body);
359	  const taskPath = text.split('\n').map((l) => l.trim()).find((l) => l !== '') ?? null;
360	  const nb = NOT_BEFORE_RE.exec(text)?.[1]?.trim() || null;
361	  const blockedBy = parseBlockedBy(text);
362	  const request = REQUEST_RE.exec(text) ? Number(REQUEST_RE.exec(text)[1]) : null;
363	  // An unrecognised family reads as absent rather than as itself: the item's model
364	  // is behaviour-defining, so the only values that leave this parser are ones the
365	  // engine can actually dispatch at (PRINCIPLES.md).
366	  const askedModel = MODEL_RE.exec(text)?.[1] ?? null;
367	  const model = REQUEST_MODELS.includes(askedModel) ? askedModel : null;
368	  // Same fencing as the model: an authorization that does not read as a policy
369	  // expression reads as absent, and absent is the safe end of this field — a run
370	  // that cannot read its permission opens a pull request and waits.
371	  const merge = policyFieldValue(MERGE_RE.exec(text)?.[1] ?? null);
372	  // Same fencing again, and here it is what keeps the janitor honest: a condition
373	  // it cannot evaluate must read as "no end condition", never as one that is met.
374	  const ends = ENDS_WHEN_RE.exec(text);
375	  const endsWhen = ends && ends[2] === ENDS_WHEN_CLOSED ? Number(ends[1]) : null;
376	  const targetBranch = TARGET_BRANCH_RE.exec(text)?.[1] ?? null;
377	  const targetPr = TARGET_PR_RE.exec(text) ? Number(TARGET_PR_RE.exec(text)[1]) : null;
378	  const supersedes = [...(SUPERSEDES_RE.exec(text)?.[1] ?? '').matchAll(/#(\d+)/g)].map((m) => Number(m[1]));
379	  const woken = WOKEN_RE.exec(text)?.[1] ?? null;
380	  return { taskPath, notBefore: nb, blockedBy, request, model, merge, endsWhen, targetBranch, targetPr, supersedes, woken };
381	}
382	
383	// THE ITEM'S OWN FACTS, as a precondition term sees them (docs/PRINCIPLES.md): the
384	// body's fields plus the two the terms read that are not fields — the issue number,
385	// and whether somebody created or woke this item. `woken` is everything that is
386	// NOT the scheduler's own ask: an item stamped by a lever, one born ad-hoc (a
387	// marked issue, a chain link), and any qualified item (a fan-out target, a request
388	// naming its issue) — the scheduler files only unqualified planned items, so an
389	// item of any other shape exists because somebody asked, which is what the cadence
390	// terms need to know.
391	export function itemFacts(item) {
392	  if (!item) return null;
393	  const fields = parseWorkItemBody(item.body);
394	  const parsed = parseWorkItemTitle(item.title);
395	  const schedulesOwn = !!parsed && parsed.qualifier === null && !ASKED_FOR_ORIGINS.includes(originOf(item));
396	  return {
397	    ...fields,
398	    number: item.number ?? null,
399	    woken: fields.woken !== null || !schedulesOwn,
400	  };
401	}
402	
403	// WHAT A MARKED ISSUE ASKS FOR (docs/PRINCIPLES.md) — read from the
404	// person's own text at every adoption, so each ask names its parameters afresh and
405	// nothing stale outranks a new one.
406	//
407	// Whoever files the issue puts these on its FIRST LINES, as one block ahead of the
408	// prose — `basics/skills/do-later/SKILL.md` is where that placement is prescribed and
409	// argued. The parser does not care where they sit; a person editing the issue, and a
410	// retry rewriting `Not-before`, do.
411	//
412	// `gated` is whether the issue's AUTHOR holds push access. A body is editable by
413	// whoever opened the issue where a label was write-gated by the platform, so the
414	// three behaviour-defining fields are honoured only for an author who could have
415	// applied them as labels anyway; an ungated ask still runs, at the default task and
416	// model and with no authorization to land anything.
417	export function parseRequestFields(body, { gated = false } = {}) {
418	  const text = humanTextOf(body);
419	  const asked = {
420	    task: /^Task:[ \t]*(\S+)/m.exec(text)?.[1] ?? null,
421	    model: MODEL_RE.exec(text)?.[1] ?? null,
422	    automerge: /^Automerge:[ \t]*(.+?)[ \t]*$/m.exec(text)?.[1] ?? null,
423	  };
424	  const blockedBy = parseBlockedBy(text);
425	  const notBefore = NOT_BEFORE_RE.exec(text)?.[1]?.trim() || null;
426	  if (!gated) return { task: null, model: null, merge: null, blockedBy, notBefore, ungated: Object.values(asked).some(Boolean) };
427	  return {
428	    task: /^[^/\s]+\/[^/\s]+$/.test(asked.task ?? '') ? asked.task : null,
429	    // An unrecognised family reads as absent rather than failing the request: a run
430	    // nobody can start would look accepted forever.
431	    model: REQUEST_MODELS.includes(asked.model) ? asked.model : null,
432	    merge: policyFieldValue(asked.automerge),
433	    blockedBy,
434	    notBefore,
435	    ungated: false,
436	  };
437	}
438	
439	// The item's own `### Context` bullets, in order — the binding scope a hand-created
440	// item was born with. Read back rather than kept only for the agent to read,
441	// because an operator's PARAMETERS ride here: `create-work-item --context
442	// "REPOS=Alpha Beta"` is how a forced run says what it is running on, and the
443	// executor hands these lines to code-work as `CLAUDINITE_CONTEXT`.
444	//
445	// A section runs to the next `### ` heading or to the end of the body — the same
446	// bounds `withSection` writes to — and only `- ` bullets count, so the prose
447	// framing around a section contributes nothing.
448	function sectionLines(body, heading) {
449	  const lines = String(body ?? '').split('\n');
450	  const at = lines.findIndex((l) => l.trim() === `### ${heading}`);
451	  if (at === -1) return [];
452	  const out = [];
453	  for (const line of lines.slice(at + 1)) {
454	    if (line.startsWith('### ')) break;
455	    const m = /^-[ \t]+(.*)$/.exec(line);
456	    if (m) out.push(m[1].trim());
457	  }
458	  return out;
459	}
460	
461	export const parseContextLines = (body) => sectionLines(body, 'Context');
462	
463	// The item's own `### Progress` bullets — the running account a holder appends to
464	// while it works. Read back so a beat can add a line without losing the ones before
465	// it: nothing can edit a posted comment, so the body is the only surface a long run
466	// has that grows in place instead of by repetition.
467	export const parseProgressLines = (body) => sectionLines(body, PROGRESS_HEADING);
468	
469	// --- the roll's record ----------------------------------------------------------
470	
471	// The section a no-go roll keeps on the item: the last declined reason and the next
472	// wake, REPLACED on every roll (the item is a status line, not a log — the timeline
473	// carries the history). Serializer and parser live together so the shape has one
474	// home; the executor writes it, and anything answering "why didn't it run" — the
475	// dashboard above all — reads it back.
476	
477	export function lastVerdictLines({ at, reason, until }) {
478	  const lines = [`${at} — the precondition declined: ${reason}`];
479	  if (until) lines.push(`Asked again at ${until}.`);
480	  return lines;
481	}
482	
483	export function parseLastVerdict(body) {
484	  const lines = sectionLines(body, LAST_VERDICT_HEADING);
485	  // The reason may carry the separator itself, so the split is on the FIRST match.
486	  const first = /^(.*?) — the precondition declined: ([\s\S]*)$/.exec(lines[0] ?? '');
487	  if (!first) return null;
488	  const until = lines.map((l) => /^Asked again at (.*?)\.?$/.exec(l)).find(Boolean)?.[1] ?? null;
489	  return { at: first[1], reason: first[2], until };
490	}
491	
492	// Fold a second set of Context lines into the first, keeping order and dropping
493	// exact duplicates. Both sides are real scope — the item carries what its creator
494	// bound it to, the precondition adds what this occurrence found — and a set-write
495	// from either side would drop the other's.
496	export const mergeContext = (...groups) => [...new Set(groups.flat().filter((l) => l && l.trim()))];
497	
498	// Stamp (or clear) `Not-before` on an existing body, in place where the field is
499	// already present and directly under the task path otherwise. Text surgery rather
500	// than a rebuild: the body also carries the creating precondition's Context and
501	// code-work's Delivered section, which belong to whoever wrote them.
502	export function withNotBefore(body, iso) {
503	  const text = String(body ?? '');
504	  if (NOT_BEFORE_RE.test(text)) {
505	    return iso
506	      ? text.replace(NOT_BEFORE_RE, `${NOT_BEFORE_FIELD}: ${iso}`)
507	      : text.replace(/^Not-before:[ \t]*.*\n?/m, '');
508	  }
509	  if (!iso) return text;
510	  const lines = text.split('\n');
511	  const at = lines.findIndex((l) => l.trim() !== '');
512	  if (at === -1) return `${NOT_BEFORE_FIELD}: ${iso}\n`;
513	  lines.splice(at + 1, 0, '', `${NOT_BEFORE_FIELD}: ${iso}`);
514	  return lines.join('\n');
515	}
516	
517	// Stamp `Woken` on an existing body — the lever's write, same text surgery as
518	// `withNotBefore`. Re-stamping replaces the instant: an item woken twice was woken
519	// last at the later one, and the field says so once.
520	export function withWoken(body, iso) {
521	  return editItemBody(body, (text) => {
522	    if (WOKEN_RE.test(text)) return text.replace(WOKEN_RE, `${WOKEN_FIELD}: ${iso}`);
523	    const lines = String(text ?? '').split('\n');
524	    const at = lines.findIndex((l) => l.trim() !== '');
525	    if (at === -1) return `${WOKEN_FIELD}: ${iso}\n`;
526	    lines.splice(at + 1, 0, '', `${WOKEN_FIELD}: ${iso}`);
527	    return lines.join('\n');
528	  });
529	}
530	
531	// Stamp `Ends-when` on an existing body, same text surgery as `withNotBefore` and
532	// for the same reason: the body carries sections that belong to whoever wrote them.
533	// Re-stamping replaces the condition rather than adding a second one — a converge
534	// that runs twice on one item must not leave two ends.
535	export function withEndsWhen(body, number) {
536	  const text = String(body ?? '');
537	  const field = `${ENDS_WHEN_FIELD}: #${number} ${ENDS_WHEN_CLOSED}`;
538	  if (ENDS_WHEN_RE.test(text)) return text.replace(ENDS_WHEN_RE, field);
539	  const lines = text.split('\n');
540	  const at = lines.findIndex((l) => l.trim() !== '');
541	  if (at === -1) return `${field}\n`;
542	  lines.splice(at + 1, 0, '', field);
543	  return lines.join('\n');
544	}
545	
546	// Stamp the target's three lines, replacing whatever an earlier resolution left:
547	// a re-pick re-resolves, and the item must say what THIS episode works on, not
548	// both. A target with nothing to say (`none`, or no superseded set) clears its
549	// lines, and a body that never carried any is returned as it was. Same surgery as
550	// `withNotBefore`: the fields sit under the task path, ahead of the sections
551	// other writers own — and on a marked issue that path is the machine block's
552	// first line, never the person's prose, which is why this one routes through
553	// `editItemBody` itself rather than trusting every caller to.
554	export function withTarget(body, target) {
555	  return editItemBody(body, (text) => stampTarget(text, target));
556	}
557	
558	function stampTarget(body, target) {
559	  const wanted = [];
560	  if (target?.branch) wanted.push(`${TARGET_BRANCH_FIELD}: ${target.branch}`);
561	  if (target?.pr != null && target?.mode === 'amend') wanted.push(`${TARGET_PR_FIELD}: #${target.pr}`);
562	  if (target?.supersedes?.length) wanted.push(`${SUPERSEDES_FIELD}: ${target.supersedes.map((n) => `#${n}`).join(', ')}`);
563	  const stripped = String(body ?? '')
564	    .replace(/^Target-branch:[ \t]*.*\n?/gm, '')
565	    .replace(/^Target-pr:[ \t]*.*\n?/gm, '')
566	    .replace(/^Supersedes:[ \t]*.*\n?/gm, '');
567	  if (!wanted.length) return stripped === String(body ?? '') ? body : stripped;
568	  const lines = stripped.split('\n');
569	  const at = lines.findIndex((l) => l.trim() !== '');
570	  if (at === -1) return `${wanted.join('\n')}\n`;
571	  lines.splice(at + 1, 0, '', ...wanted);
572	  return lines.join('\n');
573	}
574	
575	// Set a section of an item body (the Context, code-work's Delivered, the agent's Why)
576	// — replacing one of the same heading if it is already there, appending otherwise.
577	//
578	// REPLACING IS THE WHOLE POINT, and appending was a live bug (#879). Every standing
579	// item is born carrying a `### Context`, and the hand-off writes Context again — so
580	// an append leaves TWO sections of that name, while the session is told to read "the
581	// issue's Context section", singular. The one it reads first is then the scheduler run's birth
582	// note and the binding scope is in the other, which fails silently whichever section
583	// the agent picks. It also grows: an item re-queued through hand-off twice carried a
584	// third.
585	//
586	// A section runs to the next `### ` heading or to the end of the body, so a replaced
587	// section keeps its position rather than migrating to the bottom — the body stays in
588	// the order a reader learned it.
589	export function withSection(body, heading, lines) {
590	  if (!lines.length) return body;
591	  const text = String(body ?? '').replace(/\s*$/, '');
592	  const section = [`### ${heading}`, '', ...lines.map((l) => `- ${l}`)];
593	  const existing = text.split('\n');
594	  const wanted = `### ${heading}`;
595	  const at = existing.findIndex((l) => l.trim() === wanted);
596	  if (at === -1) return `${text}\n\n${section.join('\n')}\n`;
597	  const after = existing.findIndex((l, i) => i > at && l.startsWith('### '));
598	  const tail = after === -1 ? [] : ['', ...existing.slice(after)];
599	  return `${[...existing.slice(0, at), ...section, ...tail].join('\n')}\n`;
600	}
601	
602	// IS THIS ISSUE AN ITEM? Two shapes, and the second is what the one-issue request
603	// model added (PRINCIPLES.md): a filed `[claudinite-work]` issue, or an ordinary
604	// issue somebody marked `task:origin:ad-hoc` that has been ADOPTED — the mark alone
605	// is a request awaiting adoption, not yet an item, and reading it as one would have
606	// the janitor's stateless-repair rule park the person's issue for having no status.
607	//
608	// WHAT SAYS IT WAS ADOPTED IS EITHER ARTIFACT, and that is the point: adoption
609	// writes the machine block AND the first status, and the mark beside them is a
610	// LABEL a person can take off at any moment. Gated on the mark alone, an adopted
611	// item whose requester removed it drops out of every read of the queue at once —
612	// the executor never picks it, the precondition never gets to see the withdrawal
613	// and decline it, and the janitor's rules cannot sweep what they cannot list, so
614	// the item sits `waiting-for-executor` forever with nothing left to move it. Same
615	// shape as `converge-item`'s refusal (missingbulb/Shepherd#360): a membership test
616	// gated on the single artifact it exists to validate refuses exactly the items
617	// that artifact went missing from.
618	//
619	// It lives with the vocabulary rather than with the listing that applies it because
620	// the dashboard asks it in a BROWSER, where the listing's GitHub port does not load.
621	export const isQueueItem = (issue) =>
622	  String(issue?.title ?? '').startsWith(WORK_PREFIX)
623	  || machineBlockOf(issue?.body) !== null
624	  || (labelNames(issue).includes(ORIGIN_AD_HOC) && statusOf(issue) !== null);
625	
626	// --- the task trailer -------------------------------------------------------------
627	
628	// `Claudinite-Task: <pack>/<task>` on its own line, anywhere in the message.
629	export const TASK_TRAILER_RE = /^Claudinite-Task:[ \t]*(\S+)[ \t]*$/m;
630	
631	// The trailer line to append to a commit message, or '' when the writer does not
632	// know which task it is running as (a hand-run worker, a member's own script) —
633	// so a caller can always interpolate the return value.
634	export const taskTrailer = (taskId) => (taskId ? `${TASK_TRAILER}: ${taskId}` : '');
635	
636	// `message` with the trailer appended, separated by a blank line so it lands in
637	// the message's trailer block. A message that already carries the trailer is
638	// returned untouched: the lanes compose (a worker's own message, then the merge
639	// commit built from it), and a doubled trailer reads as two tasks.
640	export function withTaskTrailer(message, taskId) {
641	  const line = taskTrailer(taskId);
642	  if (!line || TASK_TRAILER_RE.test(message ?? '')) return message ?? '';
643	  return `${(message ?? '').trimEnd()}\n\n${line}\n`;
644	}
645	
646	// Which task wrote this commit, or null when nothing did. `null` is UNKNOWN as
647	// much as it is "a person wrote it" — every caller pairs it with the older
648	// author/title/path exclusions, which is what still classifies history from
649	// before the trailer existed.
650	export function taskFromMessage(message) {
651	  const m = TASK_TRAILER_RE.exec(message ?? '');
652	  return m ? m[1] : null;
653	}
654

