content.content:
1	// The task declaration contract (docs/PRINCIPLES.md) — the single
2	// source of truth for what a `tasks/<name>/task.json` must carry.
3	// Both the author-time `task-declaration-shape` check and the executor-side
4	// `validate-dispatch` validate against this one function, so the accepted shape
5	// can never drift between the two surfaces.
6	
7	import { FREQUENCIES, CADENCES, cadenceTermFor, cadenceOf, normalizeCadenceTerms, scheduleTermFor } from './calendar.mjs';
8	import { MODEL_FAMILIES } from './model-map.mjs';
9	import { EXECUTING_LEASH_MS } from '../../public/task-constants.mjs';
10	import { normalizePolicy } from './merge-policy.mjs';
11	import { validatePreconditions, preconditionSignals } from './precondition-policy.mjs';
12	import { applyTaskDefaults } from './task-defaults.mjs';
13	
14	// A declared timeout is always a whole number of seconds, > 0.
15	const isPositiveInt = (n) => Number.isInteger(n) && n > 0;
16	
17	// A code-work command must stay inside its own task directory — no absolute
18	// path and no `..` traversal in the command string — the same containment the
19	// worker-file rule gives agent_instructions (docs/PRINCIPLES.md).
20	const escapesTaskDir = (cmd) => /(^|\s)\//.test(cmd) || cmd.includes('..');
21	
22	// Task execution is two similar, consecutive phases — deterministic CODE-WORK,
23	// then AGENTIC WORK — and the field names say so. Neither phase is named for
24	// the other: the code phase is not preparation for the agent, it is the first
25	// of two peers, and a task may declare only it.
26	
27	// The defaults live in task-defaults.mjs — a module with no imports, so the
28	// dashboard's browser bundle can fill them the way the loader does.
29	export { DEFAULT_AUTOMERGE, DEFAULT_AGENT_MODEL } from './task-defaults.mjs';
30	
31	// WHO MINTS AN OCCURRENCE, and WHAT MUST HOLD once one exists (docs/PRINCIPLES.md).
32	// Two fields, one sentence: `trigger` says whether the scheduler asks
33	// this task at every tick, `preconditions` says what has to be true for the run to
34	// go ahead — judged identically at a tick and at a pick. A `request` task is asked
35	// by nobody and runs from an item somebody created: a marked issue, a wake, a chain
36	// link, a fan-out target.
37	export const TRIGGER_SCHEDULE = 'schedule';
38	export const TRIGGER_REQUEST = 'request';
39	export const TRIGGERS = Object.freeze([TRIGGER_SCHEDULE, TRIGGER_REQUEST]);
40	
41	// Does this task have a deterministic work step at all, in either of the forms it
42	// may be declared in? Every reader asking "is there code-work here" asks through
43	// this, so the two forms cannot drift apart into one being honoured and the other
44	// silently skipped.
45	export const declaresCodeWork = (decl) =>
46	  decl?.code_work !== undefined || decl?.code_worker_mjs !== undefined;
47	
48	// The cadence a task keeps, as the term it states — `null` where it states none.
49	export const taskCadence = (decl) => cadenceOf(decl?.preconditions);
50	export const isScheduledTask = (decl) => decl?.trigger === TRIGGER_SCHEDULE;
51	
52	// Return the declaration with canonical field names and the defaults filled in.
53	// Non-objects pass through untouched so validateTaskDeclaration still reports
54	// them. Loaders (discover, resolve-dispatch) normalize once; everything
55	// downstream sees only `code_work` and never an absent defaulted field.
56	export function normalizeTaskDeclaration(decl) {
57	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) return decl;
58	  const out = { ...decl };
59	  // The editor's schema pointer, when a caller hands over a parsed task.json whole.
60	  delete out.$schema;
61	  // THE CADENCE-SPELLING DOOR (calendar.mjs, DUE_TERM). `due:<cadence>` is the same
62	  // term under the name it was introduced with, permanently accepted because a task
63	  // declaration is member-owned data no vendoring pass rewrites. Rewriting it here
64	  // means every reader downstream of a loaded declaration sees one spelling, and the
65	  // evaluator's own alias covers the callers that did not come through this door.
66	  out.preconditions = normalizeCadenceTerms(out.preconditions);
67	  // A declaration stating no conditions carries the empty expression from here on,
68	  // so every reader judges one array: at a pick it holds, at a tick it is never asked.
69	  if (out.preconditions === undefined) out.preconditions = [];
70	  return applyTaskDefaults(out);
71	}
72	
73	// What a task's run does to PULL REQUESTS (docs/PRINCIPLES.md, decision
74	// PRINCIPLES.md) — the write ceiling and the target in one word, resolved once by the
75	// executor before code-work and handed to both phases:
76	//   no_code_changes                  — never opens one.
77	//   fresh_pr                         — one on a freshly minted branch; the task's
78	//                                      earlier pull requests are left as they are.
79	//   amend_existing_or_create_new_pr  — pushes onto the task's newest open pull
80	//                                      request while it has no conflicts with its
81	//                                      base; a fresh branch otherwise.
82	//   supersede_existing_pr            — a fresh branch, and once the run's own pull
83	//                                      request exists the task's earlier ones close
84	//                                      as superseded (a green, unlanded one on an
85	//                                      auto-merge repo is landed instead).
86	// A declared MAXIMUM, not a promise: "no change" is always legal, and what (if
87	// anything) the run may then MERGE is the separate `automerge` policy — 'nothing',
88	// 'anything', or a list of diff classes merge-policy.mjs evaluates the actual diff
89	// against.
90	export const OUTCOMES = ['no_code_changes', 'fresh_pr', 'amend_existing_or_create_new_pr', 'supersede_existing_pr'];
91	export const OUTCOME_NO_PR = 'no_code_changes';
92	
93	// Whether a (canonical) outcome lets the run open a pull request at all — the
94	// half of the contract `automerge` hangs off.
95	export const opensPullRequest = (outcome) => outcome !== OUTCOME_NO_PR;
96	
97	// The declared ceiling, or null for a word that is not one. Callers hold raw
98	// declarations as often as normalized ones, so the question "is this a ceiling, and
99	// which" has one answer here rather than an `OUTCOMES.includes` at each site.
100	export const canonicalOutcome = (outcome) => (OUTCOMES.includes(outcome) ? outcome : null);
101	
102	// What must happen to a task's work item when a recovery path would re-execute it
103	// (docs/PRINCIPLES.md). `requeue` is the safe-side default for sweep-shaped
104	// work; `needs-human` is the at-most-once dial a one-shot side effect declares.
105	export const INTERRUPT_POLICIES = ['requeue', 'needs-human'];
106	
107	
108	// The signal-collector vocabulary (PRINCIPLES.md). A task collects only the union
109	// of what its due tasks declare. `fleet` is canon-only (consumers cannot declare
110	// it) — that restriction is enforced where signals are collected, not here; the
111	// shape check only asserts a declared name is a real collector.
112	export const SIGNAL_NAMES = [
113	  'commits', 'prs', 'issues', 'branches', 'release',
114	  'localPacks', 'sharedMount', 'conversationLogs', 'stamp', 'fleet', 'request',
115	];
116	
117	// `description` — what the task does, or why it exists, for the person reading the
118	// declaration or a roster of them: free prose, bounded so it stays a summary. It
119	// must not restate what the other fields already say (the cadence, the
120	// conditions, the policy, the files); the writing-tasks skill holds that rule,
121	// which no check can read.
122	export const DESCRIPTION_MAX_WORDS = 50;
123	export const wordCount = (text) => String(text).trim().split(/\s+/).filter(Boolean).length;
124	export function descriptionProblem(description) {
125	  if (typeof description !== 'string') return { what: `"description" is not a string`, fix: 'write one sentence or two saying what the task does or why it exists' };
126	  if (description.trim() === '') return { what: '"description" is empty', fix: 'say what the task does or why it exists, or drop the field' };
127	  const words = wordCount(description);
128	  if (words > DESCRIPTION_MAX_WORDS) return { what: `"description" runs to ${words} words`, fix: `keep it to ${DESCRIPTION_MAX_WORDS} words — a summary, not the README` };
129	  return null;
130	}
131	
132	// Validate one task declaration. Returns an array of `{ what, fix }` problems —
133	// empty means the declaration is well-formed. Pure: no I/O, no imports of the
134	// task itself; the caller supplies the already-loaded default export.
135	export function validateTaskDeclaration(raw, terms = new Map()) {
136	  const decl = normalizeTaskDeclaration(raw);
137	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) {
138	    return [{ what: 'task.json is not a declaration object', fix: 'write one JSON object: { "id", "description", "expected_outcome", … }' }];
139	  }
140	  const problems = [];
141	  const bad = (what, fix) => problems.push({ what, fix });
142	
143	  if (typeof decl.id !== 'string' || decl.id.trim() === '') {
144	    bad('the task has no string "id"', 'give the task an "id" matching its directory name');
145	  }
146	  // Optional at the door — nothing converges a member's task files — and judged
147	  // only when declared; the shape check asks for one where it is missing.
148	  if (decl.description !== undefined) {
149	    const problem = descriptionProblem(decl.description);
150	    if (problem) bad(problem.what, problem.fix);
151	  }
152	  // `precondition_signals` is retired with the function form it belonged to
153	  // (#1617). The union is DERIVED from the expression's terms, each of which
154	  // names what it reads, so the collector can never disagree with what the gate
155	  // actually consults — a declared list can, and that is the whole reason the
156	  // derived one replaced it.
157	  if (decl.precondition_signals !== undefined) {
158	    bad('"precondition_signals" is retired', 'drop it — the signal union is derived from the conditions, each of which names what it reads');
159	  }
160	  if (!MODEL_FAMILIES.includes(decl.agent_model)) {
161	    bad(`"agent_model" ${JSON.stringify(decl.agent_model)} is not a legal model family`, `set one of: ${MODEL_FAMILIES.join(', ')}`);
162	  }
163	  if (!OUTCOMES.includes(decl.expected_outcome)) {
164	    bad(`"expected_outcome" ${JSON.stringify(decl.expected_outcome)} is not a legal outcome ceiling`, `set one of: ${OUTCOMES.join(', ')}`);
165	  }
166	  // automerge - validated as a policy SHAPE only: whether every named
167	  // rule resolves is the policy engine's question, answered where the diff is
168	  // judged, and it fails closed there — never at author time, where the rule set
169	  // depends on which packs are active.
170	  if (opensPullRequest(decl.expected_outcome)) {
171	    if (decl.automerge === undefined) {
172	      bad(`a "${decl.expected_outcome}" task declares no "automerge"`, 'say what may land unreviewed: "nothing", "anything", or a list of diff classes, e.g. ["comment-only-changes", "readme-changes"]');
173	    } else {
174	      const policy = normalizePolicy(decl.automerge);
175	      if (policy.kind === 'invalid') {
176	        bad(`"automerge" is not a legal policy: ${policy.reason}`, 'set "nothing", "anything", or a list of rule names, each optionally reject:-prefixed');
177	      }
178	    }
179	  } else if (decl.automerge !== undefined) {
180	    bad(`a "${OUTCOME_NO_PR}" task declares "automerge"`, 'drop it — a task that opens no pull request has nothing to merge; or set expected_outcome: "fresh_pr"');
181	  }
182	  // agent_instructions — REQUIRED for an agentic task (agent_model !== 'none'):
183	  // that's the worker file the agent reads, and it has no default. A `none` task
184	  // runs no agent, so the field is not applicable and is neither required nor
185	  // validated when present.
186	  if (decl.agent_model !== 'none' && (typeof decl.agent_instructions !== 'string' || decl.agent_instructions.trim() === '')) {
187	    bad('an agentic task (agent_model !== "none") declares no string "agent_instructions"', 'point "agent_instructions" at the worker file beside task.json (e.g. "task.md")');
188	  }
189	  // REQUIRED, and stated: who mints an occurrence is the declaration's own answer,
190	  // never one inferred from the shape of its conditions. The two were one field for a
191	  // window, and a reader could not tell a task nobody asks from one whose conditions
192	  // merely happened to look unaskable.
193	  const triggerFix = `write one of: ${TRIGGERS.map((t) => `"${t}"`).join(', ')} — "${TRIGGER_SCHEDULE}" is asked by the scheduler at every tick, "${TRIGGER_REQUEST}" runs only from an item somebody creates`;
194	  if (decl.trigger === undefined) {
195	    bad('the task declares no "trigger"', triggerFix);
196	  } else if (!TRIGGERS.includes(decl.trigger)) {
197	    bad(`"${decl.trigger}" is not a legal trigger`, triggerFix);
198	  }
199	
200	  // ONE MECHANISM (#1617). `preconditions` — a list of named conditions, all of
201	  // which must hold — is the only gate a task declares. The `precondition`
202	  // function it replaced is retired rather than tolerated: two forms meant every
203	  // reader, every check and the evaluator itself had to ask which one was the
204	  // gate, and a task-local term does everything the function did while staying
205	  // pure over its inputs and testable at a chosen instant.
206	  //
207	  // A term answers three ways, not two: holds, does not hold, and `{ error }` —
208	  // it COULD NOT ANSWER. The third is a run failure rather than a verdict (F27):
209	  // a decline is a decision about the world, and one taken on an API that would
210	  // not answer is a guess whose write-backs cannot land.
211	  if (decl.precondition !== undefined) {
212	    bad('the task declares a "precondition" function, which is retired', 'move the gate into "preconditions" — a built-in condition, or a term this task\'s preconditions.mjs exports');
213	  }
214	  // `frequency` is retired with the calendar the scheduler used to keep: a task's
215	  // cadence is one of its own conditions, read off its own run history. Rejected by
216	  // NAME rather than ignored, and naming the term to write, so a declaration carrying
217	  // it is told its replacement instead of reading as a task that forgot its cadence.
218	  if (decl.frequency !== undefined) {
219	    const term = FREQUENCIES.includes(decl.frequency)
220	      ? cadenceTermFor(decl.frequency)
221	      : scheduleTermFor(`<${CADENCES.join('|')}>`);
222	    bad('the task declares "frequency", which is retired', term === null
223	      ? 'drop it and write "trigger": "request" - "manual" meant no schedule at all, which a declaration now says outright'
224	      : `write the cadence as a condition - "preconditions": ["${term}", …] - with "trigger": "schedule" beside it, and drop a "none"`);
225	  }
226	  // OPTIONAL (PRINCIPLES.md): a task may require nothing, and then every occurrence of
227	  // it runs. What is NOT read off this list is whether the scheduler asks the task —
228	  // `trigger` says that.
229	  if (decl.preconditions !== undefined) {
230	    for (const problem of validatePreconditions(decl.preconditions, terms)) bad(problem.what, problem.fix);
231	  }
232	
233	  /**
234	   * model_from_request — OPTIONAL, and reserved to the engine's own built-in task.
235	   * A task that declares it runs at the model the ITEM names (`Model:`, written by
236	   * the scheduler run from a write-gated label), falling back to `agent_model` when the item
237	   * names none. It is the only field that lets anything on an item define behaviour,
238	   * so it is fenced rather than waved through (docs/PRINCIPLES.md, "Requests"): the shape check accepts
239	   * only `true`, and discovery gives pack tasks no way to be the built-in one.
240	   */
241	  if (decl.model_from_request !== undefined && decl.model_from_request !== true) {
242	    bad(`"model_from_request" ${JSON.stringify(decl.model_from_request)} is not \`true\``,
243	      'drop the field — only the engine\'s built-in request task reads a model off its item, and every other task names its own agent_model');
244	  }
245	
246	  // Code-work (docs/PRINCIPLES.md) - OPTIONAL, and declared in one of two
247	  // forms. `code_worker_mjs` names the module; `code_work` names a whole command.
248	  // Never both: they answer the same question about the same phase, so a
249	  // declaration carrying each would leave which one runs to the reader.
250	  if (decl.code_work !== undefined && decl.code_worker_mjs !== undefined) {
251	    bad('both "code_work" and "code_worker_mjs" are declared', 'keep one - "code_worker_mjs" for a module the runner wraps, "code_work" for a command it only spawns');
252	  }
253	  if (decl.code_work !== undefined) {
254	    if (typeof decl.code_work !== 'string' || decl.code_work.trim() === '') {
255	      bad('"code_work" is present but not a non-empty string', 'set it to a command whose executable is a script beside task.json, e.g. "node prepare.mjs"');
256	    } else if (escapesTaskDir(decl.code_work)) {
257	      bad('"code_work" reaches outside the task directory (absolute path or "..")', 'reference a sibling script only, e.g. "node prepare.mjs"');
258	    }
259	  }
260	  // The WRAPPED form (owner, 2026-09-22): a module beside task.json exporting
261	  // `worker`, which the runner's own entry point imports and calls. What every raw
262	  // worker re-implemented - reading the CLAUDINITE_* environment, the exit code, the
263	  // failure line, the timing, the queue's markers - the runner supplies, so the
264	  // module is the work and nothing else. A file name, never a command: the runner
265	  // builds the command, and a second executable in this field would be two answers
266	  // to who runs the module.
267	  if (decl.code_worker_mjs !== undefined) {
268	    if (typeof decl.code_worker_mjs !== 'string' || decl.code_worker_mjs.trim() === '') {
269	      bad('"code_worker_mjs" is present but not a non-empty string', 'name the module beside task.json that exports `worker`, e.g. "worker.mjs"');
270	    } else if (/\s/.test(decl.code_worker_mjs.trim())) {
271	      bad('"code_worker_mjs" is a command rather than a file name', 'name the module alone, e.g. "worker.mjs" - the runner supplies the node invocation');
272	    } else if (!decl.code_worker_mjs.endsWith('.mjs')) {
273	      bad('"code_worker_mjs" does not name a .mjs module', 'the runner imports it and calls its `worker` export, so it is an ES module beside task.json');
274	    } else if (escapesTaskDir(decl.code_worker_mjs)) {
275	      bad('"code_worker_mjs" reaches outside the task directory (absolute path or "..")', 'name a sibling module only, e.g. "worker.mjs"');
276	    }
277	  }
278	  // Either form is a subprocess, so either carries the same hard bound.
279	  if (declaresCodeWork(decl)) {
280	    const field = decl.code_worker_mjs !== undefined ? 'code_worker_mjs' : 'code_work';
281	    if (!isPositiveInt(decl.code_work_timeout)) {
282	      bad(`"${field}" is set but "code_work_timeout" is not a positive integer`, 'add "code_work_timeout": the seconds after which the subprocess is killed and the task fails');
283	    } else if (decl.code_work_timeout * 1000 >= EXECUTING_LEASH_MS) {
284	      // F17: a code-work legally allowed to outlive the executing leash is reclaimed
285	      // WHILE ALIVE, and the failure is not one duplicate run but a livelock —
286	      // every tenure reclaimed before it can finish, code-work re-executing each
287	      // cycle, the occurrence never converging. The leash is the engine's, so the
288	      // comparison is made where a declaration is judged.
289	      bad(`"code_work_timeout" (${decl.code_work_timeout}s) reaches the executor's ${EXECUTING_LEASH_MS / 60e3}-minute claim leash`,
290	        `bound the work step under ${EXECUTING_LEASH_MS / 60e3} minutes - one that can outlive the leash is reclaimed while still running, and the item livelocks`);
291	    }
292	  }
293	
294	  // --- the work-item queue's three optional declarations (docs/PRINCIPLES.md) ---
295	
296	  // `schedule_after` — ordering, declared (PRINCIPLES.md). A list of `<pack>/<task>` ids this
297	  // task yields to WHILE THEY ARE LIVE THIS CYCLE. It compiles to the executor's
298	  // pick-time yield, never to a `Blocked-by` edge: a standing item that rolls
299	  // never closes, so blocked-by would starve every dependent of a quiet upstream
300	  // forever. The engine never learns what any named task does — it reads item
301	  // states, generically.
302	  if (decl.schedule_after !== undefined
303	      && !(Array.isArray(decl.schedule_after)
304	        && decl.schedule_after.every((s) => typeof s === 'string' && /^[^/\s]+\/[^/\s]+$/.test(s)))) {
305	    bad('"schedule_after" is not an array of "<pack>/<task>" ids', 'e.g. "schedule_after": ["claudinite-lifecycle/update"] — this task is not scheduled onto an executor while those are live this cycle');
306	  }
307	
308	  // `on_interrupt` — the ack-early/ack-late dial (PRINCIPLES.md). Most of this fleet's
309	  // tasks are sweep-shaped and converge safely on a re-run, so the default is
310	  // `requeue`. A genuinely one-shot side effect (a store submission, an external
311	  // notification) declares `needs-human`, and every recovery path that would
312	  // re-execute it — the leash reclaim, the hand-off retry — converges to triage
313	  // instead: at-most-once plus a human.
314	  if (decl.on_interrupt !== undefined && !INTERRUPT_POLICIES.includes(decl.on_interrupt)) {
315	    bad(`"on_interrupt" ${JSON.stringify(decl.on_interrupt)} is not a legal policy`, `set one of: ${INTERRUPT_POLICIES.join(', ')} (default "requeue")`);
316	  }
317	
318	  // `invocation_endpoint` — a NAME, never a URL (PRINCIPLES.md). The repo's config
319	  // maps the name to the URL and to the name of the Actions secret holding its
320	  // token, so no vendored pack file carries deployment detail or anything adjacent
321	  // to a credential. Reach is a property of which endpoint a task names, and of
322	  // nothing the task says about itself.
323	  if (decl.invocation_endpoint !== undefined
324	      && !(typeof decl.invocation_endpoint === 'string' && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(decl.invocation_endpoint))) {
325	    bad('"invocation_endpoint" is not a kebab-case endpoint name', 'name a key from the repo\'s taskScheduler.agenticTaskInvocationEndpoints map, e.g. "fleet" — never a URL');
326	  }
327	
328	  // The repo Actions secrets this task's code work needs configured (PRINCIPLES.md). Purely
329	  // DECLARATIVE — like a pack's adoption `questions`, its job is to drive the ask
330	  // (adoption interactively, the scheduler by owner issue), not to gate anything
331	  // here. So the only shape asserted is "a list of names"; whether the repo has
332	  // actually configured them is a fact about the repo, answered where the secrets
333	  // bundle is readable, never at author time.
334	  if (decl.code_work_required_secrets !== undefined
335	      && !(Array.isArray(decl.code_work_required_secrets) && decl.code_work_required_secrets.every((s) => typeof s === 'string' && s.trim() !== ''))) {
336	    bad('"code_work_required_secrets" is not an array of secret names', 'list the repo Actions secret names this task needs, e.g. ["SOME_API_KEY"]');
337	  }
338	
339	  // The one exception to "whether the repo has them is not our business": GitHub
340	  // reserves the `GITHUB_` prefix, answering "Secret names must not start with
341	  // GITHUB_" on the secret form. Such a name cannot be configured by anyone, so the
342	  // task parks forever on a secret its owner is refused — and only the declaration
343	  // can catch it, since the park reads as ordinary missing configuration.
344	  for (const name of (Array.isArray(decl.code_work_required_secrets) ? decl.code_work_required_secrets : [])) {
345	    if (typeof name === 'string' && name.toUpperCase().startsWith('GITHUB_')) {
346	      bad(`required secret "${name}" cannot be created — GitHub reserves the GITHUB_ prefix`,
347	        'rename it without that prefix, e.g. one carrying the pack\'s own name');
348	    }
349	    // The other namespace a secret cannot borrow. `CLAUDINITE_*` in a task file is the
350	    // code-work contract, and `task-code-work-env` reads every name outside that
351	    // contract as a variable nobody sets — which a delivered secret is not, so the
352	    // finding would be unfixable without renaming the secret anyway.
353	    if (typeof name === 'string' && name.toUpperCase().startsWith('CLAUDINITE_')) {
354	      bad(`required secret "${name}" sits in the code-work namespace, which its task's own code may not read`,
355	        'rename it outside CLAUDINITE_* — that prefix belongs to the variables code_work is handed');
356	    }
357	  }
358	
359	  // Execution bound (docs/PRINCIPLES.md) — an agentic task MUST
360	  // declare a positive-integer agent_execution_timeout: there is no default,
361	  // because a running agent always has a bound. Enforcement is best-effort (the
362	  // executor surfaces the value to the subagent). A `none` task runs no agent,
363	  // so it needs none.
364	  if (MODEL_FAMILIES.includes(decl.agent_model) && decl.agent_model !== 'none' && !isPositiveInt(decl.agent_execution_timeout)) {
365	    bad('an agentic task (agent_model !== "none") declares no positive-integer "agent_execution_timeout"', 'add "agent_execution_timeout": the seconds bounding the agentic run — generous; extreme protection, not a scheduling knob');
366	  }
367	
368	  // An agentless task (agent_model: none) runs no agent, so its ONLY work is
369	  // code-work — a `none` task with no code-work does nothing (PRINCIPLES.md, retiring
370	  // the in-process inline path). Require the command.
371	  if (decl.agent_model === 'none' && !declaresCodeWork(decl)) {
372	    bad('an agentless task (agent_model: "none") declares no work step', 'add "code_worker_mjs" (a none task does its work in that subprocess) - or give the task an agent_model');
373	  }
374	
375	  return problems;
376	}
377	
378	// The signals to collect for one task, derived from the terms its conditions
379	// name. There is nothing to reconcile: a declared list could disagree with what
380	// the gate actually consults, and the derived union cannot.
381	export function taskSignalNames(decl, terms = new Map()) {
382	  return preconditionSignals(decl?.preconditions ?? [], terms);
383	}
