1	// The two operator levers (docs/PRINCIPLES.md), which are the whole of
2	// urgency, forcing, fan-out and retry:
3	//
4	//   create-work-item <pack>/<task> [--urgent] [--context …] [--not-before ISO]
5	//                                  [--blocked-by #N,#M] [--qualifier text]
6	//                                  [--supersedes #N]
7	//   create-work-item --wake <#N> [--urgent]
8	//
9	// FORCING A SCHEDULED TASK IS WAKING ITS STANDING ITEM — strip `task:blocked`,
10	// clear `Not-before`, optionally add `task:urgent`. The same lever as the human
11	// re-queue out of `needs-human`, which is no accident: "run this now" and "retry
12	// this now" are the same operation on the same object. The executor still
13	// evaluates the precondition at pick, so a force that finds no work SAYS so where
14	// the operator reads it. The slot scheduler's whole forcing apparatus — its override
15	// bag, the forced-verdict path, the `~f` slot marker and the watermark exclusion —
16	// reduced to these two levers and was deleted (#974).
17	//
18	// FORCING AD-HOC WORK IS CREATING AN ITEM — a parameterized run, an unscheduled
19	// task's run, a fan-out target. Ad-hoc is STRUCTURAL (PRINCIPLES.md): an unscheduled
20	// task is never asked by the scheduler, and a qualified title is a different title
21	// from the standing one — so such an item is invisible to the scheduler run's
22	// guards in both directions, neither suppressing the next occurrence nor consuming
23	// it. Which is why an UNQUALIFIED item for a scheduled task is refused below: it
24	// would BE that task's standing item, and the scheduler run's dedupe would close
25	// one of the two. Every item made here is stamped `Woken:` — it exists because
26	// somebody asked, which is what the cadence terms read.
27	
28	import { pathToFileURL } from 'node:url';
29	import {
30	  STATUS_READY, STATUS_BLOCKED, URGENT, STATUS_REJECTED, QUEUE_LABELS, ORIGIN_MANUAL, EPISODE_MARKER,
31	} from '../../public/task-constants.mjs';
32	import {
33	  workItemTitle, workItemBody, withNotBefore, withWoken, statusesOn,
34	} from '../../public/work-item-grammar.mjs';
35	import { clearStatus } from '../items/apply-status.mjs';
36	import { isScheduledTask } from '../contract/task-contract.mjs';
37	import { repoRoot } from '../world/actions.mjs';
38	import { nowIso } from '../world/clock.mjs';
39	import { setIssueBody } from '../world/github.mjs';
40	
41	// The Context a hand-created item carries when the operator names none. Generic
42	// on purpose — it names the mechanism, not the task — because an item's Context is
43	// the agent's binding scope, and a forced item that carried none would read as a
44	// scope of nothing.
45	export const FORCED_CONTEXT =
46	  'Created by hand — no precondition asserts there is work to do. Do only what the task file specifies, and converge to a no-op if there is nothing.';
47	
48	export function parseArgs(argv) {
49	  const out = { urgent: false, context: [], blockedBy: [], notBefore: null, qualifier: null, supersedes: null, wake: null, target: null };
50	  for (let i = 0; i < argv.length; i += 1) {
51	    const a = argv[i];
52	    const next = () => argv[++i];
53	    if (a === '--urgent') out.urgent = true;
54	    else if (a === '--wake') out.wake = Number(String(next()).replace('#', ''));
55	    else if (a === '--context') out.context.push(next());
56	    else if (a === '--not-before') out.notBefore = next();
57	    else if (a === '--qualifier') out.qualifier = next();
58	    else if (a === '--supersedes') out.supersedes = Number(String(next()).replace('#', ''));
59	    else if (a === '--blocked-by') out.blockedBy.push(...String(next()).split(',').map((s) => Number(s.trim().replace('#', ''))).filter(Boolean));
60	    else if (!a.startsWith('--')) out.target = a;
61	  }
62	  return out;
63	}
64	
65	// Wake an item: clear its wait and put it back in the queue. Also the sanctioned
66	// road back from `needs-human` — nothing MECHANICAL ever re-queues a triage item,
67	// and the next pickup re-runs the precondition, which is what makes the retry safe
68	// even when the failed run half-did its work.
69	export async function wakeItem(gh, repo, number, { urgent = false } = {}) {
70	  const api = await import('../world/github.mjs');
71	  const issue = await api.readIssue(gh, repo, number);
72	  if (!issue) return { ok: false, error: `#${number} could not be read` };
73	  // `Woken:` is what lets the task's cadence terms hold at the next pick — the wake
74	  // stands in for the cadence (docs/PRINCIPLES.md) — while everything else it requires
75	  // still applies; a wake is the one write that stamps it.
76	  const body = withWoken(withNotBefore(issue.body ?? '', null), nowIso());
77	  if (body !== issue.body) await setIssueBody(gh, repo, number, body);
78	  // The episode boundary: every claim before this moment is dead, and arbitrating
79	  // over dead claims is what livelocks an item through reclaim cycles forever.
80	  await api.comment(gh, repo, number, `${EPISODE_MARKER}\nWoken by hand — cleared \`Not-before\` and returned this item to the queue.`);
81	  // Every status the item wears goes, in every spelling — a wake takes the item
82	  // back from whatever held it, and a park half-cleared (the state gone, its kind
83	  // still standing) is the torn shape the repair phase would have to repair.
84	  for (const status of statusesOn(issue)) await clearStatus(api, gh, repo, issue, status);
85	  await api.addLabel(gh, repo, number, STATUS_READY);
86	  if (urgent) await api.addLabel(gh, repo, number, URGENT);
87	  return { ok: true, number };
88	}
89	
90	// `scheduled` is whether the task is asked by the scheduler (its declared
91	// `trigger`), null where the caller does not know.
92	export async function createWorkItem(gh, repo, { pack, task, taskPath, scheduled = null, opts, log = console.log }) {
93	  const api = await import('../world/github.mjs');
94	  const { listOpenWorkItems } = await import('../items/read.mjs');
95	  const title = workItemTitle({ pack, task, qualifier: opts.qualifier });
96	
97	  // An unqualified item for a SCHEDULED task is that task's standing item by
98	  // construction, not a run beside it — the scheduler run would treat the pair as duplicate
99	  // standing items and close the younger. The two levers that do what the operator
100	  // meant are named rather than guessed at.
101	  if (scheduled === true && !opts.qualifier) {
102	    return { ok: false, error: `${pack}/${task} is on the schedule, so an unqualified item for it IS its standing item — the scheduler run would close one of the two as a duplicate. To run it now, wake its standing item (\`--wake #N\`, or the scheduler workflow's \`wake\` input); to run it beside the schedule, give this item a \`--qualifier\` naming what makes it a different run.` };
103	  }
104	
105	  // The pick-time mutex means a new item QUEUES behind an open twin rather than
106	  // running beside it, and the operator should know they are queueing, not jumping.
107	  const twin = (await listOpenWorkItems(gh, repo)).find((i) => (i.title ?? '').trim() === title);
108	  if (twin) log(`! #${twin.number} is an open item with this exact title — the new item will queue behind it, not run beside it`);
109	
110	  await api.ensureLabels(gh, repo, QUEUE_LABELS);
111	  const blocked = opts.notBefore !== null || opts.blockedBy.length > 0;
112	  const res = await api.createIssue(gh, repo, {
113	    title,
114	    body: workItemBody({
115	      taskPath,
116	      notBefore: opts.notBefore,
117	      blockedBy: opts.blockedBy,
118	      context: opts.context.length ? opts.context : [FORCED_CONTEXT],
119	      // Created by hand: the cadence terms hold on it.
120	      woken: nowIso(),
121	    }),
122	    // A hand-created item is `manual` by construction — a declared task, and
123	    // nobody's schedule asked for it — and the origin is worn for life beside
124	    // whatever status it holds (PRINCIPLES.md).
125	    labels: [ORIGIN_MANUAL, blocked ? STATUS_BLOCKED : STATUS_READY, ...(opts.urgent ? [URGENT] : [])],
126	  });
127	  if (!res.number) return { ok: false, error: `could not create the item: ${res.status}` };
128	
129	  if (opts.supersedes) {
130	    await api.comment(gh, repo, opts.supersedes, `Superseded by #${res.number}, a retry of this work created by hand.`);
131	    await api.addLabel(gh, repo, opts.supersedes, STATUS_REJECTED);
132	    await api.closeIssue(gh, repo, opts.supersedes, 'not_planned');
133	  }
134	  return { ok: true, number: res.number };
135	}
136	
137	// Exported because this module is run directly as a command: prose in a member's own local
138	// packs still addresses this command at that path, and nothing here can rewrite it.
139	export async function runCreateWorkItem() {
140	  const { makeGh } = await import('../world/github.mjs');
141	  const { actionRepoContext, repoRoot } = await import('../world/actions.mjs');
142	  const { discoverTasks } = await import('../contract/discover.mjs');
143	  const { loadConfig } = await import('../../../../engine/checks/helpers/repo-context.mjs');
144	
145	  const opts = parseArgs(process.argv.slice(2));
146	  const { repo } = actionRepoContext();
147	  if (!repo) { console.error('GITHUB_REPOSITORY not set'); process.exitCode = 1; return; }
148	  const gh = makeGh();
149	
150	  if (opts.wake) {
151	    const res = await wakeItem(gh, repo, opts.wake, { urgent: opts.urgent });
152	    if (!res.ok) { console.error(res.error); process.exitCode = 1; return; }
153	    console.log(`woke #${opts.wake}${opts.urgent ? ' (urgent)' : ''}`);
154	    return;
155	  }
156	  if (!opts.target || !opts.target.includes('/')) {
157	    console.error('usage: create-work-item <pack>/<task> [--urgent] [--context …] [--not-before ISO] [--blocked-by #N] [--qualifier text] [--supersedes #N]\n       create-work-item --wake <#N> [--urgent]');
158	    process.exitCode = 1;
159	    return;
160	  }
161	  const [pack, task] = opts.target.split('/');
162	  const root = repoRoot();
163	  const { tasks } = await discoverTasks(root, loadConfig(root));
164	  const found = tasks.find((t) => t.pack === pack && t.id === task);
165	  if (!found) { console.error(`no task "${opts.target}" in this repo's declared packs`); process.exitCode = 1; return; }
166	
167	  const res = await createWorkItem(gh, repo, { pack, task, taskPath: found.taskPath, scheduled: isScheduledTask(found.decl), opts });
168	  if (!res.ok) { console.error(res.error); process.exitCode = 1; return; }
169	  console.log(`created #${res.number} ${opts.target}${opts.urgent ? ' (urgent)' : ''}`);
170	}
171	
172	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
173	  runCreateWorkItem().catch((e) => { console.error(e); process.exitCode = 1; });
174	}
