1	// Executor-side deterministic validation of a dispatch issue, BEFORE any model
2	// judgment (docs/PRINCIPLES.md). Given the issue body, it asserts
3	// in code that the first line is a legal task path, the task file exists at HEAD,
4	// its pack is declared, and its `task.json` sibling parses to a well-formed
5	// declaration — then resolves the model and outcome ceiling the executor will
6	// enforce. An invalid dispatch is rejected (the executor de-labels it and
7	// converges it to needs-human), so a forged or mangled issue never runs.
8	//
9	// Pure over injected capabilities so it unit-tests without a repo or GitHub. It
10	// is NOT a CLI — the executor shell beside it, `resolve-dispatch.mjs`, is what
11	// drives it in production: that shell takes the issue body out of the label
12	// event's payload on disk and wires `exists`/`isPackDeclared`/`loadTask` to the
13	// checkout, so validating a dispatch costs no GitHub call at all.
14	
15	import { normalizeTaskDeclaration, validateTaskDeclaration } from '../contract/task-contract.mjs';
16	import { siblingTaskDeclaration } from '../contract/task-declaration.mjs';
17	import { resolveModel } from '../contract/model-map.mjs';
18	import { BUILT_IN_PACK, BUILT_IN_PATH_RE, BUILT_IN_PUBLIC_PATH_RE } from '../contract/built-in-tasks.mjs';
19	import { parseWorkItemBody } from '../../public/work-item-grammar.mjs';
20	
21	// The only shape a dispatch first line may take (PRINCIPLES.md). Anchored end to
22	// end — no query strings, no trailing junk, exactly one pack and one task
23	// segment under a packs/ root. The `.claudinite/(shared|local)/` prefix is
24	// OPTIONAL: a consumer's task path carries it (its canon is mounted at
25	// `.claudinite/shared/packs/`, its own packs at `.claudinite/local/packs/`),
26	// while the CANON repo runs its own tree and dispatches root-relative paths
27	// (`packs/<pack>/…` for its canon packs, `.claudinite/local/packs/<pack>/…` for
28	// its local packs). All three forms are legal; nothing else is.
29	export const DISPATCH_PATH_RE = /^(?:\.claudinite\/(?:shared|local)\/)?packs\/([^/]+)\/tasks\/([^/]+)\/task\.md$/;
30	
31	// The task path a dispatch body points at — its first line, trimmed.
32	export const dispatchFirstLine = (body) => String(body ?? '').split('\n')[0].trim();
33	
34	const reject = (reason, extra = {}) => ({ ok: false, reason, ...extra });
35	
36	// Validate a dispatch body. Capabilities (all injected for testability):
37	//   exists(path)        -> boolean   — does this repo-relative path exist at HEAD
38	//   isPackDeclared(id)  -> boolean   — is this pack active in .claudinite-settings.json
39	//   loadTask(declPath)  -> decl      — load the declaration file's object (throws on parse error)
40	// Returns { ok:true, pack, task, taskPath, model, resolvedModel, outcome },
41	// { ok:false, gone:true, pack, task, reason } — a well-formed dispatch whose task
42	// the repo NO LONGER CARRIES (file gone, sibling gone, pack undeclared): the
43	// executor CLOSES the issue as obsolete (owner, 2026-08-06) rather than parking
44	// it on needs-human, because a task that was removed or deactivated is not an
45	// anomaly a human needs to triage — or { ok:false, reason } for a genuinely
46	// malformed dispatch (bad path shape, unparseable declaration), which stays a
47	// needs-human convergence since it may be forgery or a broken task.
48	export function validateDispatchBody(body, { exists, isPackDeclared, loadTask, loadTerms = () => new Map() }) {
49	  const firstLine = dispatchFirstLine(body);
50	  // Two legal shapes: a pack task, and the engine's own built-in root
51	  // (docs/PRINCIPLES.md). The built-in one is not a pack and is never declared — wherever the
52	  // queue runs it is active — so it skips the declaration check rather than failing
53	  // it, and nothing else about validation differs.
54	  const builtIn = BUILT_IN_PATH_RE.exec(firstLine) ?? BUILT_IN_PUBLIC_PATH_RE.exec(firstLine);
55	  const m = builtIn ? [firstLine, BUILT_IN_PACK, builtIn[1]] : DISPATCH_PATH_RE.exec(firstLine);
56	  if (!m) return reject(`first line "${firstLine}" is not a valid task path (${DISPATCH_PATH_RE})`);
57	
58	  const [, pack, task] = m;
59	  const taskPath = firstLine;
60	
61	  const gone = (reason) => reject(reason, { gone: true, pack, task });
62	  if (!exists(taskPath)) return gone(`task file ${taskPath} does not exist at HEAD — the repo no longer carries this task`);
63	  const declPath = siblingTaskDeclaration(taskPath, exists);
64	  if (!declPath) return gone(`the task.json sibling of ${taskPath} is missing — the repo no longer carries this task`);
65	  if (!builtIn && !isPackDeclared(pack)) return gone(`pack "${pack}" is not declared in .claudinite-settings.json — this task is not active here`);
66	
67	  let decl;
68	  try {
69	    decl = normalizeTaskDeclaration(loadTask(declPath));
70	  } catch (e) {
71	    return reject(`${declPath} did not parse: ${e.message}`, { pack, task });
72	  }
73	  // The task's own precondition terms, prefetched by the shell exactly as the
74	  // declaration is: without them a task-local condition reads as a typo, and a
75	  // dispatch naming a perfectly good task would be rejected as malformed.
76	  let terms;
77	  try {
78	    terms = loadTerms(declPath);
79	  } catch (e) {
80	    return reject(`${declPath}'s preconditions.mjs did not parse: ${e.message}`, { pack, task });
81	  }
82	  const problems = validateTaskDeclaration(decl, terms);
83	  if (problems.length) return reject(`${declPath} is not a valid task declaration: ${problems.map((p) => p.what).join('; ')}`, { pack, task });
84	
85	  // The model a task that reads its item's choice runs at (PRINCIPLES.md). The field
86	  // is written by the scheduler run from a write-gated label and validated on the way out of
87	  // the parser, so an unrecognised family has already become absent here and the
88	  // declared default stands — a request nobody can run would look accepted forever.
89	  const model = (decl.model_from_request && parseWorkItemBody(body).model) || decl.agent_model;
90	
91	  return {
92	    ok: true,
93	    pack,
94	    task,
95	    taskPath,
96	    model,
97	    resolvedModel: resolveModel(model),
98	    outcome: decl.expected_outcome,
99	    // What the task authorizes to land unreviewed ('nothing' | 'anything' | a
100	    // rule list) — normalized above, so a legacy ceiling already carries its
101	    // equivalent. Null only for a `none` task, which opens nothing to merge.
102	    automerge: decl.automerge ?? null,
103	    // The best-effort run bound (docs/PRINCIPLES.md): the executor
104	    // surfaces it into the subagent's brief as "fail after N minutes". Always set
105	    // for an agentic task (the contract requires it); null for an agentless one.
106	    executionTimeout: decl.agent_execution_timeout ?? null,
107	  };
108	}
109

1	// The parse both of the executor's bags share.
2	//
3	// The executor hands its job's contexts to task code as JSON in a single environment
4	// variable — one bag for `secrets` (secrets-bag.mjs), one for `vars` (vars-bag.mjs).
5	// What the two do with a parsed bag differs sharply, which is why they are separate
6	// modules; how a bag is READ does not, which is why that part lives here rather than
7	// twice.
8	
9	// A bag's contents, or null when this job carries none. A malformed bag is null too:
10	// every caller already has a "this job carries no bag" path, and that path is a better
11	// answer than a crash inside a JSON parse.
12	export function parseBag(raw) {
13	  if (typeof raw !== 'string' || !raw) return null;
14	  try {
15	    const parsed = JSON.parse(raw);
16	    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null;
17	  } catch { return null; }
18	}
19

