1	// The scheduling CALENDAR: the frequency vocabulary and the period arithmetic
2	// (docs/PRINCIPLES.md). Pure and stateless. Given a frequency and a `now` it answers
3	// exactly one question, WHEN did that frequency's current period open.
4	//
5	// THE PERIOD IS THE UTC CALENDAR, and nothing a repo configures (#1995). A day opens
6	// at midnight UTC, a week on the Sunday that opened it, a month on its 1st. The
7	// retired `taskScheduler` anchor let a repo move those boundaries, which bought
8	// nothing any reader could use: its stated purpose was to order members ahead of the
9	// canon by an hour, and this repo's own record showed the cron's fire time wandering
10	// 68 minutes across one week, wider than the stagger it was supposed to guarantee.
11	// What it cost was a seam. Before the configured hour the current period was still
12	// yesterday's, so the same run read as consumed at 03:00 and as open at 09:00, and
13	// "has it run today" was never the question the term actually answered.
14	//
15	// There is no occurrence IDENTITY here, and that is the point: under the
16	// work-item queue an occurrence is identified by the item's issue number, so the
17	// calendar owns the instants and nothing else. `src/items/anchors.mjs` is the only
18	// consumer of the arithmetic; the vocabulary below is what the task contract and
19	// the author-time declaration check read.
20	//
21	// All times are UTC. This module never reads the clock itself, `now` is always
22	// injected, so every answer is deterministic and testable.
23	
24	// The legal frequency tokens — the vocabulary the runtime contract validates
25	// against and the author-time declaration check rejects anything outside.
26	//
27	// `manual` is the one non-cadence: a manual task has no occurrence at all, so the
28	// scheduler run never instantiates it and it runs only from an item created by hand
29	// (`src/schedule/create-work-item.mjs`, run directly). It exists for operator levers — work that
30	// answers no recurring question but wants a task's whole apparatus (declaration,
31	// contract validation, code-work, the work item) when a human pulls it.
32	export const FREQUENCIES = ['daily', 'weekly', 'monthly', 'manual'];
33	
34	const HOUR_MS = 3600 * 1000;
35	const DAY_MS = 24 * HOUR_MS;
36	
37	// Sunday opens the week, matching Date#getUTCDay's own 0.
38	const SUNDAY = 0;
39	
40	// When `frequency`'s current period opened, as a Date, or `null` for `manual`,
41	// which has no period at all. `now` may be a Date or anything the Date constructor
42	// accepts. A period that opens exactly at `now` is the current one.
43	export function anchorInstant(frequency, now) {
44	  const at = new Date(now);
45	  if (frequency === 'manual') return null;
46	
47	  const midnight = Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate());
48	  if (frequency === 'daily') return new Date(midnight);
49	  // Back to the Sunday that opened this week. Today counts when today IS Sunday.
50	  if (frequency === 'weekly') return new Date(midnight - ((at.getUTCDay() - SUNDAY + 7) % 7) * DAY_MS);
51	  if (frequency === 'monthly') return new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), 1));
52	
53	  throw new Error(`unknown frequency "${frequency}"`);
54	}
55	
56	// --- the cadence terms ----------------------------------------------------------
57	// How a task states WHEN it runs, inside its own `preconditions`
58	// (docs/PRINCIPLES.md): the engine keeps no calendar of its own, so the cadence is one of the
59	// task's conditions, read off its own run history at every scheduler tick.
60	//
61	//   schedule:at-most-<daily|weekly|monthly>   no run created or closed since this
62	//                                             UTC period opened
63	//
64	// The name states what the term is and is not. It is a RATE LIMIT on the scheduler's
65	// own asking, never a content gate, so it says nothing about whether there is work to
66	// do: that is what the conditions beside it are for. And it is about the schedule, so
67	// it yields to a person: a hand-woken item satisfies it without the run history being
68	// read at all.
69	//
70	// Whether a task is asked at all is its `trigger`, not the shape of this list: a
71	// task nothing asks may still state conditions, which are judged when somebody
72	// creates an item for it (the retired `frequency: manual` is `trigger: 'request'`).
73	//
74	// The parse lives here, beside the frequency vocabulary it replaces, and imports
75	// nothing: the dashboard's browser bundle reads a cadence the way the scheduler does.
76	export const CADENCES = ['daily', 'weekly', 'monthly'];
77	// What separates the alternatives inside one entry. The policy engine parses the same
78	// grammar; this module re-spells it so it stays import-free.
79	export const ALTERNATIVE_SEPARATOR = '||';
80	export const SCHEDULE_TERM = 'schedule';
81	export const AT_MOST_PREFIX = 'at-most-';
82	export const NOT_FAILED_TERM = 'last-run-not-failed';
83	export const NOT_PARKED_TERM = 'last-run-not-parked';
84	
85	// The term a cadence is stated as, and the cadence read back out of one. An argument
86	// outside the vocabulary reads back as null, which is what the author-time check reports.
87	export const scheduleTermFor = (cadence) => `${SCHEDULE_TERM}:${AT_MOST_PREFIX}${cadence}`;
88	export function cadenceOfScheduleArg(arg) {
89	  const text = String(arg ?? '');
90	  if (!text.startsWith(AT_MOST_PREFIX)) return null;
91	  const cadence = text.slice(AT_MOST_PREFIX.length);
92	  return CADENCES.includes(cadence) ? cadence : null;
93	}
94	
95	// `due:<cadence>`, the same term under the name it was introduced with. PERMANENT, not
96	// a migration window: a task declaration is
97	// member-owned data that no vendoring pass rewrites, so a member can carry the old
98	// spelling indefinitely and must keep working. `task-declaration-shape` is what stops a
99	// NEW declaration naming it, and `normalizeCadenceTerms` is the door that makes every
100	// reader downstream of a loaded declaration see one spelling.
101	export const DUE_TERM = 'due';
102	
103	// Rewrite every `due:<cadence>` in an expression to the current spelling, in place,
104	// leaving everything else byte-identical. Applied by `normalizeTaskDeclaration`.
105	export function normalizeCadenceTerms(preconditions) {
106	  if (!Array.isArray(preconditions)) return preconditions;
107	  return preconditions.map((entry) => (typeof entry === 'string'
108	    ? entry.split(ALTERNATIVE_SEPARATOR)
109	      .map((alt) => {
110	        const t = alt.trim();
111	        const cadence = t.startsWith(`${DUE_TERM}:`) ? t.slice(DUE_TERM.length + 1) : null;
112	        return cadence !== null && CADENCES.includes(cadence) ? alt.replace(t, scheduleTermFor(cadence)) : alt;
113	      })
114	      .join(ALTERNATIVE_SEPARATOR)
115	    : entry));
116	}
117	
118	// The term references an expression carries: each entry split on `||`, each
119	// reference `{ name, arg }` with the argument after the first colon. The same
120	// grammar precondition-policy.mjs parses, re-spelled here so this module stays
121	// import-free; the policy engine's parse is the one that validates.
122	const alternativesOf = (entry) => String(entry ?? '').split(ALTERNATIVE_SEPARATOR).map((t) => t.trim()).filter(Boolean)
123	  .map((t) => { const c = t.indexOf(':'); return c === -1 ? { name: t, arg: null } : { name: t.slice(0, c).trim(), arg: t.slice(c + 1).trim() }; });
124	const entriesOf = (preconditions) => (Array.isArray(preconditions) ? preconditions : []).map(alternativesOf);
125	
126	// The cadence a declaration states, as `{ kind: 'period', cadence }`, or null for a
127	// task with no cadence term (asked at every tick while it states any condition, it
128	// runs whenever those hold). The first cadence term wins. Both spellings are read
129	// here rather than only the current one, so a caller that did not come through the
130	// door, the dashboard lifting a declaration out of GitHub as text, gets the same answer.
131	export function cadenceOf(preconditions) {
132	  for (const ref of entriesOf(preconditions).flat()) {
133	    if (ref.name === SCHEDULE_TERM) {
134	      const cadence = cadenceOfScheduleArg(ref.arg);
135	      if (cadence) return { kind: 'period', cadence };
136	    }
137	    if (ref.name === DUE_TERM && CADENCES.includes(ref.arg)) return { kind: 'period', cadence: ref.arg };
138	  }
139	  return null;
140	}
141	
142	// Whether the declaration states any condition at all. Not a scheduling answer on
143	// its own — `trigger` is that — but what the contract's door reads to derive one
144	// for a declaration written before the field existed (#1789). An entry carrying
145	// only separators states nothing, which is why this is not a length test.
146	export const statesConditions = (preconditions) => entriesOf(preconditions).some((alts) => alts.length > 0);
147	
148	// A term gates when it is a whole conjunct of the expression — `['x', …]` gates,
149	// `['due:daily || x']` merely widens.
150	const gatesOn = (preconditions, term) =>
151	  entriesOf(preconditions).some((alts) => alts.length === 1 && alts[0].name === term && alts[0].arg === null);
152	
153	// A task stops past its own failure park only when it says so: nothing holds a
154	// task's lane but its own word — `last-run-not-failed` for that park alone, or
155	// `last-run-not-parked`, which holds behind all four and so answers this too.
156	export const holdsOnFailure = (preconditions) =>
157	  gatesOn(preconditions, NOT_FAILED_TERM) || gatesOn(preconditions, NOT_PARKED_TERM);
158	
159	// Whether the declaration holds its lane behind EVERY park, the three a person's
160	// inbox owns included. A reader showing what happens next needs the wider answer
161	// as well: a task held behind an approval park is not being asked on schedule,
162	// and an anchor shown there promises a run the task declines.
163	export const holdsOnAnyPark = (preconditions) => gatesOn(preconditions, NOT_PARKED_TERM);
164	
165	// What the retired `frequency` field always meant, as the term that says it now, or
166	// null for `manual`, which meant no schedule at all and so adds no term.
167	export const cadenceTermFor = (frequency) =>
168	  (frequency === 'manual' ? null : scheduleTermFor(frequency));
169

1	// THE REPAIR PHASE of the scheduler run (docs/PRINCIPLES.md) - the recovery that
2	// used to run once a day as a task of its own, planned here as ops the same run
3	// applies before it asks any task whether it wants to run.
4	//
5	// IT IS STILL A FALLBACK. Every rule below repairs something that already went
6	// wrong - a label swap that tore, a session that died, a park nobody answered, a
7	// terminal nobody closed - and the healthy flow of a task never passes through
8	// here: an item the machinery handled correctly is settled by whoever handled it,
9	// before any of this runs. A new rule here is a claim that a failure mode exists
10	// and that nothing nearer to it can close it out; the alternative to writing one
11	// is usually fixing the flow that left the mess. What changed when this moved is
12	// its siting and its latency, not its standing.
13	//
14	// AND IT ONLY EVER READS OPEN ITEMS. An item somebody closed is finished, park
15	// label and all: a person ending a park by closing its issue is an answer, not a
16	// state to repair, and nothing here reopens, re-labels or re-nags one.
17	//
18	// WHY IT RUNS BEFORE THE ASK. Repair frees what the ask then reads: closing an
19	// abandoned failure park releases the task's lane, and the occurrence the task is
20	// owed is filed in the same run rather than one tick later. That ordering is the
21	// whole reason this is a phase of the run and not a task behind it - a task's own
22	// repair could only ever land after the tick that filed it, and could never feed
23	// the drain gate that dispatches an executor for what it freed.
24	//
25	// The verdicts stay pure in `./repair-rules.mjs`; this module decides
26	// which op each verdict becomes and which of them may be threaded back into the
27	// item list the ask reads. The shell in `run.mjs` does the GitHub I/O.
28	
29	import {
30	  staleReadyItems, staleReadyComment, deadAgentItems, deadAgentComment,
31	  statelessItems, statelessComment, supersededItems, supersededComment, taskPathIndex,
32	  stuckBlockedItems, stuckBlockedComment,
33	  orphanedParkItems, orphanedParkComment, endedParkItems, endedParkComment,
34	  abandonedParkItems, abandonedParkComment, unclosedTerminalItems, unclosedTerminalComment,
35	  periodForTasks, scheduledForTasks,
36	} from './repair-rules.mjs';
37	import {
38	  STATUS_READY, STATUS_RUNNING_AGENT, STATUS_DONE, STATUS_REJECTED,
39	  STATUS_NEEDS_HUMAN_ACTION, STATUS_NEEDS_HUMAN_FAILURE, IN_REVIEW_LABEL,
40	} from '../../public/task-constants.mjs';
41	import {
42	  statusOf, parseWorkItemTitle, parseWorkItemBody, taskIdFromPath, spellingsOf,
43	} from '../../public/work-item-grammar.mjs';
44	
45	// The three ops this phase emits, each a label-and-body mechanic `run.mjs` applies:
46	//   { kind: 'escalate', issue, from, to, body }        status -> a park, item stays open
47	//   { kind: 'retire',   issue, from, to, body, close } status -> a terminal, issue closes
48	//   { kind: 'close-terminal', issue, body, close }     the close a torn transition never made
49	//   { kind: 'note', issue, body }                      a comment and nothing else
50	//
51	// `confirm` names the pure predicate the shell must see hold on a FRESH read before
52	// it writes. Only the three rules whose premise is a TRANSIENT carry one - "this
53	// looks torn", "nobody has touched this" - because a swap in flight is
54	// indistinguishable from one that tore and `items` is a snapshot seconds old (#1104:
55	// #1101 closed `task:done` at 12:50:13Z and was escalated at 12:50:21Z). The rules
56	// that turn on a clock over a stable label need no second read.
57	//
58	// `clearInReview` is the one write that lands on a DIFFERENT issue than the one the
59	// rule judged (a legacy shadow item's request issue, below).
60	
61	// Whether the ask may see this op's effect in the same run. An op the shell might
62	// decline on its fresh read must NOT be threaded: the plan would then hand the ask
63	// a world the run never wrote. Declining to thread costs at most one tick of lag on
64	// a rule that is already measured in hours or days, which is the safe direction.
65	const threadable = (op) => !op.confirm;
66	
67	// Apply an op's effect to the in-memory item, mirroring exactly what the shell
68	// writes - status cleared of EVERY spelling, the new label added, and for a retire
69	// the close itself. The cadence terms read these items (`signals/index.mjs` folds
70	// `ctx.items` into each task's run history), so an effect that is written to GitHub
71	// but not to the snapshot leaves the ask judging a world one write out of date.
72	function threadEffect(item, op) {
73	  if (op.from) {
74	    const gone = new Set(spellingsOf(op.from));
75	    item.labels = item.labels.filter((l) => !gone.has(l));
76	  }
77	  if (op.to && !item.labels.includes(op.to)) item.labels.push(op.to);
78	  if (op.kind === 'retire') {
79	    item.state = 'closed';
80	    item.closed_at = op.at;
81	  }
82	}
83	
84	// The whole phase. `open` is the open half of `items`; every lookup a rule needs
85	// that is not a label is injected, so the rules stay pure and the reads stay the
86	// shell's:
87	//   progressAt(item)   the newest progress comment on an item holding an agent
88	//   resolutionOf(n)    'merged' | 'closed' | null for a park's `Ends-when:` target
89	//   doneAfter(id, at)  the task's newest clean run closed after `at`, or null
90	//   isRequest(number)  true where job 4 owns this issue (below)
91	//   stateOf(n)         the state of a `Blocked-by` target, which need not be an item
92	export function planRepair({
93	  items = [], tasks = [], now, progressAt = () => null, resolutionOf = () => null,
94	  doneAfter = () => null, isRequest = () => false, stateOf = () => null,
95	}) {
96	  const open = items.filter((i) => i.state === 'open');
97	  const ops = [];
98	  const taken = new Set();
99	  const claim = (item) => { if (taken.has(item.number)) return false; taken.add(item.number); return true; };
100	
101	  // --- the closing rules, in their precedence order -------------------------
102	  // Naming the run that answered a park says more than naming the absence of a
103	  // task file, which says more than the clock running out on it.
104	  for (const item of supersededItems(open, { doneAfter })) {
105	    if (!claim(item)) continue;
106	    const p = parseWorkItemTitle(item.title) ?? taskIdFromPath(parseWorkItemBody(item.body).taskPath);
107	    const run = doneAfter(`${p.pack}/${p.task}`, item.updated_at ?? item.created_at);
108	    ops.push({
109	      kind: 'retire', rule: 'superseded', issue: item.number, from: statusOf(item), to: STATUS_REJECTED,
110	      close: 'not_planned', at: now, body: supersededComment(run),
111	    });
112	  }
113	
114	  const headPath = taskPathIndex(tasks);
115	  for (const item of orphanedParkItems(open, { tasks })) {
116	    if (!claim(item)) continue;
117	    const p = parseWorkItemTitle(item.title) ?? taskIdFromPath(parseWorkItemBody(item.body).taskPath);
118	    const id = `${p.pack}/${p.task}`;
119	    ops.push({
120	      kind: 'retire', rule: 'orphaned', issue: item.number, from: statusOf(item), to: STATUS_REJECTED,
121	      close: 'not_planned', at: now, body: orphanedParkComment(id, headPath.get(id) ?? null),
122	    });
123	  }
124	
125	  // THE RESOLUTION DECIDES THE OUTCOME; BOTH OUTCOMES CLOSE. A merged target means
126	  // the work landed and an unmerged one that it was rejected - and a person who
127	  // closed the pull request has already given their answer, so leaving their issue
128	  // open asks them to come back and say it a second time.
129	  for (const item of endedParkItems(open, { resolutionOf })) {
130	    if (!claim(item)) continue;
131	    const { endsWhen, request } = parseWorkItemBody(item.body);
132	    const resolution = resolutionOf(endsWhen);
133	    ops.push({
134	      kind: 'retire', rule: 'ended', issue: item.number, from: statusOf(item),
135	      to: resolution === 'merged' ? STATUS_DONE : STATUS_REJECTED,
136	      close: resolution === 'merged' ? 'completed' : 'not_planned',
137	      at: now, body: endedParkComment(endsWhen, resolution),
138	      // A LEGACY SHADOW ITEM told its request issue it was in review; nothing else
139	      // would ever take that back, and the review is over.
140	      clearInReview: request && request !== item.number ? { issue: request, label: IN_REVIEW_LABEL } : null,
141	    });
142	  }
143	
144	  for (const item of abandonedParkItems(open, now, { scheduledFor: scheduledForTasks(tasks) })) {
145	    if (!claim(item)) continue;
146	    ops.push({
147	      kind: 'retire', rule: 'abandoned', issue: item.number, from: statusOf(item), to: STATUS_REJECTED,
148	      close: 'not_planned', at: now, body: abandonedParkComment(), confirm: 'abandoned',
149	    });
150	  }
151	
152	  // The close a torn transition never made. It writes no label: the status is
153	  // already the right one, and the outcome comes from it.
154	  for (const item of unclosedTerminalItems(open, now)) {
155	    if (!claim(item)) continue;
156	    const status = statusOf(item);
157	    ops.push({
158	      kind: 'close-terminal', rule: 'unclosed', issue: item.number,
159	      close: status === STATUS_DONE ? 'completed' : 'not_planned',
160	      body: unclosedTerminalComment(status), confirm: 'unclosed',
161	    });
162	  }
163	
164	  // --- the escalations ------------------------------------------------------
165	  for (const item of staleReadyItems(open, now, { periodFor: periodForTasks(tasks) })) {
166	    if (!claim(item)) continue;
167	    ops.push({
168	      kind: 'escalate', rule: 'stale-ready', issue: item.number, from: STATUS_READY,
169	      to: STATUS_NEEDS_HUMAN_ACTION, body: staleReadyComment(item),
170	    });
171	  }
172	
173	  // FAILURE, not decision: a dead session is something the machine noticed, never a
174	  // choice a person made. The kind carries two consequences that both want that
175	  // reading - it is the only park a later clean run can supersede, and the only one
176	  // that holds the task's lane, so the generator stops filing a fresh occurrence
177	  // each anchor behind a run nobody has looked at.
178	  for (const item of deadAgentItems(open, now, { progressAt })) {
179	    if (!claim(item)) continue;
180	    ops.push({
181	      kind: 'escalate', rule: 'dead-agent', issue: item.number, from: STATUS_RUNNING_AGENT,
182	      // The body is the shell's: only it can read the hand-off comment that names
183	      // WHICH session died, and an escalation that cannot name one says less rather
184	      // than asserting something it does not know.
185	      to: STATUS_NEEDS_HUMAN_FAILURE, body: null, note: 'dead-agent',
186	      wedged: progressAt(item) != null,
187	    });
188	  }
189	
190	  // COMMENT ONLY, deliberately: labels untouched means the item still proceeds by
191	  // itself the moment its blockers resolve, and a human who decides it is dead
192	  // closes it by hand. It claims nothing, so an item this rule notes can still be
193	  // escalated or closed by a rule above - the note is about the wait, not the item's
194	  // state.
195	  for (const item of stuckBlockedItems(open, now, { stateOf })) {
196	    if (taken.has(item.number)) continue;
197	    const unresolved = parseWorkItemBody(item.body).blockedBy.filter((n) => stateOf(n) !== 'closed');
198	    ops.push({ kind: 'note', rule: 'stuck-dependency', issue: item.number, body: stuckBlockedComment(item, unresolved) });
199	  }
200	
201	  // A TORN ADOPTION IS NOT A TORN ITEM. Adoption writes the machine block and then
202	  // the status (`run.mjs` job 4), so a block with no status is the shape a failed
203	  // label call leaves - and it is exactly what job 4 re-adopts on the next run. It
204	  // reaches this rule looking identical to a swap that tore, so the issues job 4
205	  // owns are excluded here rather than parked out from under it.
206	  for (const item of statelessItems(open)) {
207	    if (isRequest(item.number)) continue;
208	    if (!claim(item)) continue;
209	    ops.push({
210	      kind: 'escalate', rule: 'stateless', issue: item.number, from: null,
211	      to: STATUS_NEEDS_HUMAN_FAILURE, body: statelessComment(), confirm: 'stateless',
212	    });
213	  }
214	
215	  // --- legacy cleanup -------------------------------------------------------
216	  // THE HOME FOR A RETIRED MECHANISM'S LEFTOVERS, deliberately kept as a named
217	  // place rather than a module: a rule here reads the items this phase has already
218	  // listed and costs no read of its own, which is the whole reason such a rule
219	  // belongs in this pass rather than in a sweep of its own.
220	  //
221	  // What lived here until the merge: the slot scheduler's `[claudinite-task]`
222	  // dispatch issues (#974), escalated when stale, re-armed when their trigger event
223	  // was lost. All three of its rules went when the task did. The re-arm and the
224	  // dead-claim were already no-ops - re-emitting a ready label for a trigger nothing
225	  // listens to arms nothing, and no session claims a dispatch issue any more - and
226	  // the escalation's population is a closed set that only shrinks. A member still
227	  // holding one closes it by hand, which is one issue, once.
228	  //
229	  // A future rule here states which retired mechanism it cleans up after and what
230	  // bounds its population, so the next reader can tell a live rule from one whose
231	  // world is gone.
232	
233	  // Thread what the shell is certain to write, so the ask judges this run's world.
234	  const byNumber = new Map(items.map((i) => [i.number, i]));
235	  const closed = new Set();
236	  for (const op of ops) {
237	    if (!threadable(op)) continue;
238	    const item = byNumber.get(op.issue);
239	    if (item) threadEffect(item, op);
240	    if (op.kind === 'retire') closed.add(op.issue);
241	  }
242	  return { ops, closed };
243	}
244

1	// Print one machine-readable execution record for the dispatch this executor
2	// session ran — `claudinite-task-exec v1 <pack>/<task> [<slot>] <status>`
3	// (run-record.mjs, the single home of the format). The executor runs this in
4	// code at step 4, right after converging its issue, so the record lands in the
5	// session transcript exactly as printed; the capture step ships the transcript
6	// to the conversation-logs branch, and the usage fold counts the statuses out
7	// of it deterministically. Hard-coded on purpose: the count must never depend
8	// on how an agent chose to phrase its final message.
9	//
10	// The code-decided terminal verdicts (`task-gone`, `invalid`) are printed by
11	// resolve-dispatch.mjs itself; this CLI exists for the two verdicts only the
12	// end of the run can know (`success`, `failed`).
13	//
14	// Usage: node record-exec.mjs <pack>/<task> <slot> <success|failed>
15	
16	import { pathToFileURL } from 'node:url';
17	import { renderTaskExec, TASK_EXEC_STATUSES } from '../items/run-record.mjs';
18	
19	export function execRecordLine(argv) {
20	  const [family, slotId, status] = argv;
21	  const m = /^([^/\s]+)\/([^/\s]+)$/.exec(family ?? '');
22	  if (!m) return { error: `first argument must be <pack>/<task>, got ${JSON.stringify(family ?? null)}` };
23	  if (!slotId) return { error: 'second argument must be the slot id (from the dispatch brief)' };
24	  if (!TASK_EXEC_STATUSES.includes(status)) {
25	    return { error: `third argument must be one of ${TASK_EXEC_STATUSES.join(', ')}, got ${JSON.stringify(status ?? null)}` };
26	  }
27	  return { line: renderTaskExec({ pack: m[1], task: m[2], slotId, status }) };
28	}
29	
30	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
31	  const { line, error } = execRecordLine(process.argv.slice(2));
32	  if (error) {
33	    console.error(`record-exec: ${error} — usage: node record-exec.mjs <pack>/<task> <slot> <${TASK_EXEC_STATUSES.join('|')}>`);
34	    process.exitCode = 2;
35	  } else {
36	    console.log(line);
37	  }
38	}
