content.content:
1	// The executor (docs/PRINCIPLES.md) — a pull worker over the queue. Each
2	// iteration: pick the next ready item, claim it by a verified lease, re-evaluate
3	// the precondition (the scheduler run asked once at the anchor; a chained stage
4	// re-derives world state rather than trusting a verdict passed forward), then on
5	// a go run code-work and either converge (agentless) or hand off to an agent
6	// session; on a no-go close the item with the reason on record — the next
7	// occurrence is the scheduler run's ask at the task's next anchor (#1115).
8	//
9	// An executor's whole interface is issue read/write plus the repo at HEAD, which
10	// is what makes it platform-agnostic: the reference deployment is a job in the
11	// vendored workflows (the scheduler run's post-scheduler run drain, and a `labeled`-event run for
12	// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
13	// enumerates executors; identity is self-declared in the claim comment.
14	//
15	// The pure decisions live at the top and test with fixtures; the shell below is
16	// the GitHub/code-work/invocation I/O around them.
17	
18	import { existsSync } from 'node:fs';
19	import { pathToFileURL } from 'node:url';
20	import { isSuspended, suspendedNotice } from '../world/hold.mjs';
21	import { HEARTBEAT_MS, heartbeatComment, withHeartbeat, realTimers } from '../items/heartbeat.mjs';
22	import { renderTaskExec, startRunCost } from '../items/run-record.mjs';
23	import { evaluatePrecondition } from '../contract/precondition.mjs';
24	import { declaresCodeWork, isScheduledTask } from '../contract/task-contract.mjs';
25	import { swapStatus, clearStatus } from '../items/apply-status.mjs';
26	import { pickOrder, taskIdOf, titleOf, running } from '../items/pick-order.mjs';
27	import { resolveTarget, closeSuperseded } from './target.mjs';
28	import { deliveryFor } from '../deliver/land-pr.mjs';
29	import { actionsEnv, repoRoot } from '../world/actions.mjs';
30	import { now as clockNow } from '../world/clock.mjs';
31	import { setIssueBody } from '../world/github.mjs';
32	import {
33	  STATUS_BLOCKED, STATUS_READY, URGENT, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT, requeueHint, 
34	  STATUS_DONE, STATUS_REJECTED, QUEUE_LABELS, QUEUED_LABEL, STATUS_NEEDS_HUMAN_ACTION,
35	  STATUS_NEEDS_HUMAN_APPROVAL, STATUS_NEEDS_HUMAN_FAILURE, CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
36	  DELIVERED_HEADING, LEGACY_DELIVERED_HEADINGS, LAST_VERDICT_HEADING,
37	} from '../../public/task-constants.mjs';
38	import {
39	  isStatus, isStandingItem, parseWorkItemTitle, parseWorkItemBody, taskIdFromPath,
40	  parseContextLines, mergeContext, withNotBefore, withSection, editItemBody, hasLabel,
41	  lastVerdictLines, withTarget, itemFacts,
42	} from '../../public/work-item-grammar.mjs';
43	
44	// The claim comment carries WHO and WHEN — the executor id and its run URL —
45	// because executor identity is an unbounded set and must never become a label
46	// (PRINCIPLES.md).
47	export const claimComment = ({ executor, runUrl, at }) =>
48	  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;
49	
50	// Who won the claim, out of an item's comments (PRINCIPLES.md). Three precisions,
51	// each an implicit assumption made explicit:
52	//
53	//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
54	//    `created_at` has one-second granularity, so simultaneous claims tie on time;
55	//    comment ids are server-assigned and strictly increasing — a total order the
56	//    protocol gets for free. Nothing here compares runner clocks.
57	//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
58	//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
59	//    and revert leaves one), and arbitrating over all of them makes a dead claim
60	//    outrank every future live claimant — the item then livelocks through reclaim
61	//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
62	//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
63	//    owner; it can only leave an item with no state label, which the repair phase
64	//    repairs.
65	export function claimWinner(comments = []) {
66	  const sorted = [...comments].sort((a, b) => a.id - b.id);
67	  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
68	  const claims = sorted
69	    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
70	    .filter((c) => !boundary || c.id > boundary.id);
71	  return claims[0] ?? null;
72	}
73	
74	// After WINNING a claim, re-verify the pick filters against live state (F15). The
75	// filters read possibly-stale state, so two executors can pass them simultaneously
76	// and claim DIFFERENT items the filters should have serialized — a twin pair, or
77	// an upstream and its dependent. The per-item lease cannot see that: it protects
78	// one item, not one title. If a conflicting item now holds an EARLIER claim
79	// (comment id — the same arbiter the lease trusts), this executor reverts its own
80	// claim and moves on. Bounded, deterministic, and the earlier claim never notices.
81	export function conflictsWithEarlierClaim(item, myClaimId, others, { taskAfter = () => [], scheduledOf = () => null, pathTo = () => null } = {}) {
82	  const idOf = (i) => taskIdOf(i, pathTo);
83	  const standing = (i) => isStandingItem(i, scheduledOf(idOf(i)));
84	  const upstreams = standing(item) ? taskAfter(idOf(item)) : [];
85	  return others.some((o) => {
86	    if (o.number === item.number) return false;
87	    if (!running(o)) return false;
88	    const conflicting = titleOf(o) === titleOf(item)
89	      || (upstreams.includes(idOf(o)) && standing(o));
90	    return conflicting && o.claimId != null && o.claimId < myClaimId;
91	  });
92	}
93	
94	// The no-go outcome (PRINCIPLES.md): every decline CLOSES the item with the
95	// reason. The roll — `Not-before` stamped, open-blocked, waiting out the period —
96	// is gone, and so is the schedule board: a scheduled task's next occurrence is
97	// the scheduler run's ask at its next tick, and the closed item is itself the
98	// history the task's cadence term reads (the period this item started in is
99	// consumed by it). `standing` marks whether the close should say so.
100	export function noGoPlan(item, task, now, reason) {
101	  return {
102	    kind: 'close',
103	    outcome: STATUS_REJECTED,
104	    stateReason: 'not_planned',
105	    reason,
106	    standing: isStandingItem(item, task?.decl ? isScheduledTask(task.decl) : null),
107	  };
108	}
109	
110	// --- the shell ----------------------------------------------------------------
111	
112	const nowIso = () => clockNow().toISOString();
113	
114	// Time `fn` under one of the run's phases, or just run it when this run is not
115	// timing itself. `finally`, so a phase that threw is still closed — the record is
116	// about where the wall clock went, and a run that died inside code-work spent that
117	// time whatever the exit was.
118	async function timed(cost, name, fn) {
119	  const end = cost ? cost.phase(name) : () => {};
120	  try { return await fn(); } finally { end(); }
121	}
122	
123	// ONE EXECUTOR RUN DRAINS THE QUEUE (docs/PRINCIPLES.md, reversing
124	// one-item-per-run). Actions bills each job's runtime rounded UP to the next
125	// minute, so a day's cost is the RUN count: a run that performed one item paid a
126	// whole invocation — checkout, setup, rounding — per item. So a run claims an
127	// item, sees it to its settle, then picks the next, and ends when nothing is
128	// pickable. Items still settle ONE AT A TIME: this moved the run boundary, not
129	// the occupancy model, and capacity is still executor width.
130	//
131	// What still starts a run is the enumerable list docs/PRINCIPLES.md names, each cause on the
132	// record: the scheduler run's drain job (dispatched only when that run leaves
133	// something pickable), a label event, an agent session's close-time drain, and
134	// the workflow's failure-continuation job when a run dies mid-drain. Self-
135	// re-dispatch retired with the one-item run — the remainder is this run's own.
136	//
137	// AN ITEM THIS RUN LET GO OF IS NEVER RE-ATTEMPTED BY IT. Losing a claim race
138	// leaves the item running under its winner, so the next pick simply does not see
139	// it — but a post-claim REVERT puts the item back to ready, and re-picking what
140	// this run just returned to the queue is an unbounded loop, not a retry. Both
141	// exits are therefore recorded in `standDown` and skipped for the rest of the
142	// run; the executor that won, and the scheduler run behind it, carry those.
143	//
144	// The loop terminates because every iteration either settles an item (which
145	// leaves the ready state) or stands down from one — and the only items that
146	// newly become pickable are the dependents a close releases, which is the
147	// chaining this exists to do. Its outer bound is the workflow's own timeout.
148	//
149	// Injected seams keep the run testable end to end without GitHub, code-work
150	// subprocesses or an invocation endpoint.
151	// `runCost` is the run's own stopwatch (run-record.mjs), supplied by the CLI below
152	// and left null everywhere else: a run driven by a test or the simulator is not a
153	// billed invocation and has no run id to file a cost under, so it times nothing and
154	// stamps nothing. Where one IS supplied, every item this run settles carries the
155	// record away with it — see `recordFor`.
156	export async function runExecutor({
157	  gh, repo, root, config, tasks, executorId, runUrl = null,
158	  now = () => clockNow(), random = Math.random, heartbeatMs = HEARTBEAT_MS,
159	  collectSignalsFor, runTaskCodeWork, invokeAgent, log = console.log,
160	  resolveTargetFor = null, runCost = null, timers = realTimers,
161	}) {
162	  const api = await import('../world/github.mjs');
163	  const { listOpenWorkItems } = await import('../items/read.mjs');
164	  const schedule = config.taskScheduler;
165	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
166	  const taskAfter = (id) => byId.get(id)?.decl?.schedule_after ?? [];
167	  const scheduledOf = (id) => (byId.has(id) ? isScheduledTask(byId.get(id).decl) : null);
168	  // A marked issue names its task by worker path, so the run needs the inverse of
169	  // the id map — built from the same task set, so a path this repo does not carry
170	  // resolves to nothing and the item is malformed rather than guessed at.
171	  const byPath = new Map(tasks.map((t) => [t.taskPath, `${t.pack}/${t.id}`]));
172	  const pathTo = (p) => byPath.get(p) ?? null;
173	  // THE TARGET SEAM (PRINCIPLES.md): which branch and pull request a run works on,
174	  // resolved from the task's declared outcome against the repo's open pull
175	  // requests. The member's delivery preference is what says whether a green
176	  // incumbent may be landed on the way; it is read once, from the same config the
177	  // hand-off reads.
178	  const resolveTargetOf = resolveTargetFor ?? ((task, at) => resolveTarget({
179	    gh, repo, taskId: `${task.pack}/${task.id}`, outcome: task.decl.expected_outcome,
180	    delivery: deliveryFor(config), now: at, log,
181	  }));
182	  const done = [];
183	  // Items this run has let go of — a lost race, a reverted claim — and must not
184	  // pick again. Without it a revert re-picks what it just returned to the queue.
185	  const standDown = new Set();
186	
187	  // A phase of a run that is not timing itself is a no-op pair, so the loop below
188	  // reads the same either way.
189	  const phase = (name) => (runCost ? runCost.phase(name) : () => {});
190	
191	  for (;;) {
192	    // Read live every time: the settle just made may have readied a dependent,
193	    // and another executor may have taken what was pickable a moment ago.
194	    const endPick = phase('pick');
195	    const open = await listOpenWorkItems(gh, repo);
196	    const candidate = pickOrder(open, { taskAfter, scheduledOf, random, pathTo })
197	      .find((i) => !standDown.has(i.number));
198	    endPick();
199	    if (!candidate) break;
200	
201	    // --- claim: the verified lease ------------------------------------------
202	    const endClaim = phase('claim');
203	    await swapStatus(api, gh, repo, candidate, STATUS_READY, STATUS_RUNNING_EXECUTOR);
204	    await api.comment(gh, repo, candidate.number, claimComment({
205	      executor: executorId, runUrl, at: nowIso(),
206	    }));
207	    const comments = await api.listComments(gh, repo, candidate.number);
208	    const winner = claimWinner(comments);
209	    const mine = [...comments]
210	      .sort((a, b) => a.id - b.id)
211	      .filter((c) => (c.body ?? '').includes(CLAIM_MARKER) && (c.body ?? '').includes(`executor \`${executorId}\``))
212	      .at(-1);
213	    if (!winner || winner.id !== mine?.id) {
214	      // The loser reverts nothing — the winner's labels already stand. It does
215	      // strike its own claim (F24): letting go covers losing too, and a claim left
216	      // behind here outlives the winner's episode and becomes the earliest of the
217	      // NEXT one, moving the livelock one episode along.
218	      await strikeClaim(api, gh, repo, mine);
219	      standDown.add(candidate.number);
220	      endClaim();
221	      log(`- #${candidate.number}: another executor holds this episode's earliest claim — leaving it to them`);
222	      continue;
223	    }
224	
225	    // --- post-claim re-verify (F15) -----------------------------------------
226	    const others = await withClaimIds(api, gh, repo, await listOpenWorkItems(gh, repo), candidate.number);
227	    if (conflictsWithEarlierClaim(candidate, winner.id, others, { taskAfter, scheduledOf, pathTo })) {
228	      await api.comment(gh, repo, candidate.number,
229	        `${EPISODE_MARKER}\nReverting this claim: a conflicting item holds an earlier claim this cycle. Returning the item to the queue.`);
230	      await swapStatus(api, gh, repo, candidate, STATUS_RUNNING_EXECUTOR, STATUS_READY);
231	      standDown.add(candidate.number);
232	      endClaim();
233	      log(`- #${candidate.number}: reverted — a conflicting item claimed earlier`);
234	      continue;
235	    }
236	    endClaim();
237	
238	    const outcome = await executeItem({
239	      api, gh, repo, root, config, schedule, byId, pathTo, item: candidate, executorId,
240	      claim: winner, now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
241	      resolveTargetOf, cost: runCost, phase, timers,
242	    });
243	    done.push({ issue: candidate.number, outcome });
244	  }
245	  return done;
246	}
