248	// Whether `claim` is still the item's live claim — the earliest of THIS episode,
249	// by the same arbiter the lease itself trusts. False where a reclaim's episode
250	// marker struck it, or where another executor now holds the item.
251	async function holdsClaim(api, gh, repo, item, claim) {
252	  if (!claim) return true;
253	  const winner = claimWinner(await api.listComments(gh, repo, item.number));
254	  return !!winner && winner.id === claim.id;
255	}
256	
257	// The claim id of each live item, so the post-claim verify can compare episodes.
258	// One comment read per conflicting-looking item, not per item in the repo.
259	async function withClaimIds(api, gh, repo, items, selfNumber) {
260	  const out = [];
261	  for (const i of items) {
262	    if (i.number === selfNumber || !running(i)) { out.push(i); continue; }
263	    const winner = claimWinner(await api.listComments(gh, repo, i.number));
264	    out.push({ ...i, claimId: winner?.id ?? null });
265	  }
266	  return out;
267	}
