269	// One claimed item, from validation through to a terminal state (or a hand-off).
270	async function executeItem({
271	  api, gh, repo, root, config, schedule, byId, pathTo = () => null, item, executorId, claim,
272	  now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log, resolveTargetOf,
273	  cost = null, phase = () => () => {}, timers,
274	}) {
275	  const parsed = parseWorkItemTitle(item.title);
276	  const { taskPath } = parseWorkItemBody(item.body);
277	  // A marked issue's identity is its machine block, not its title (PRINCIPLES.md): the id
278	  // is whichever task owns the worker path the block names.
279	  const id = parsed ? `${parsed.pack}/${parsed.task}` : pathTo(taskPath);
280	  const task = id ? byId.get(id) : null;
281	  // The exec record joins back to the work by pack and task, which a marked issue's
282	  // human title cannot supply — so the resolved id travels with the item.
283	  item.taskId = id;
284	
285	  // --- validate in code, before anything trusts the issue ------------------
286	  if (!taskPath || (!parsed && !id)) {
287	    await converge(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_NEEDS_HUMAN_FAILURE, claim,
288	      'This work item is malformed — its title or first body line does not name a task. Possible forgery; a human should look at it.', 'invalid');
289	    return 'needs-human';
290	  }
291	  if (!task) {
292	    await close(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_REJECTED, 'not_planned',
293	      `\`${id}\` is not a task this repo carries at HEAD (the pack may be undeclared, or the task removed). Closing obsolete.`, 'task-gone');
294	    return 'obsolete';
295	  }
296	  // THE SAME FACT, LEARNED LATER. The task set was built once, at the start of the
297	  // run; one run drains several items from one checkout, and an earlier item's own
298	  // work rewrites that checkout — the mount update deletes a retired task's
299	  // directory out from under the items behind it. So a task can resolve here and
300	  // not exist on disk — the same fact the branch above closes on, and it converges
301	  // the same way. Without this the run reaches code-work and spawns with a cwd that is gone
302	  // (missingbulb/Shepherd#300).
303	  if (!existsSync(task.taskDir)) {
304	    await close(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_REJECTED, 'not_planned',
305	      `\`${id}\` no longer exists in this checkout (\`${task.taskPath}\`) — it was removed while this run was in flight. Nothing ran. Closing obsolete.`, 'task-gone');
306	    return 'obsolete';
307	  }
308	  if (task.taskPath !== taskPath) {
309	    // A MISMATCH HAS TWO CAUSES AND ONLY ONE IS A PERSON'S PROBLEM (#1461). The guard
310	    // exists for a tampered or forged item, whose path names some OTHER task — that
311	    // parks. But an item open across a pack rename hits it too: only the title's id is
312	    // canonicalized (`parseWorkItemTitle`), so the body keeps naming the pre-rename
313	    // directory forever, and parking it strands the item AND holds the task's lane,
314	    // since nothing rewrites an item body. When the path resolves to this very task —
315	    // `taskIdFromPath` canonicalizes too — the item is merely stale, which is the
316	    // `!task` branch's verdict: close it obsolete and let the generator file a fresh
317	    // occurrence at today's path.
318	    const named = taskIdFromPath(taskPath);
319	    if (named && `${named.pack}/${named.task}` === id) {
320	      await close(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_REJECTED, 'not_planned',
321	        `This item names \`${id}\` at \`${taskPath}\`, where it no longer lives — the pack was renamed since the item `
322	        + `was filed, and the task is at \`${task.taskPath}\` now. An item's stored path is never rewritten, so this one `
323	        + 'can never run. Closing obsolete; the scheduler files a fresh occurrence at the current path.', 'task-gone');
324	      return 'obsolete';
325	    }
326	    await converge(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_NEEDS_HUMAN_FAILURE, claim,
327	      `This item's task path (\`${taskPath}\`) is not where \`${id}\` lives at HEAD (\`${task.taskPath}\`). Not running it.`, 'invalid');
328	    return 'needs-human';
329	  }
330	
331	  // --- the single precondition evaluation (PRINCIPLES.md) --------------------
332	  const at = now();
333	  // The item's own facts — its fields, its number, whether somebody woke it — are
334	  // what the terms judge over: a request item's verdict is about the issue it
335	  // names, which no signal bundle can single out on its own (PRINCIPLES.md), and
336	  // the cadence terms hold on a woken item (PRINCIPLES.md). The signals are collected FOR
337	  // THIS OCCURRENCE, its own run history excluding it.
338	  const fields = itemFacts(item);
339	  const signals = await collectSignalsFor(task, at, item);
340	  const verdict = evaluatePrecondition(task, signals, config.packConfig?.[task.pack] ?? {}, fields, at);
341	
342	  // A PRECONDITION THAT COULD NOT ANSWER IS A RUN FAILURE, NOT A VERDICT (F27). A
343	  // decline is a decision about the world; one taken on an API that would not answer
344	  // is a guess, and its write-backs cannot land — for a request that would strand
345	  // the issue armed-but-queued forever, the request silently eaten. So the item
346	  // parks open in the failure lane, where the ordinary re-queue lever retries it
347	  // once the API recovers, and nothing is written to whatever it could not read.
348	  if (verdict.error) {
349	    await converge(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_NEEDS_HUMAN_FAILURE, claim,
350	      `This run could not be decided: ${verdict.error}\n\nNothing ran and nothing was written. Re-queue this item (${requeueHint}) once the cause has cleared.`);
351	    log(`! #${item.number} ${id}: the precondition could not answer — ${verdict.error}`);
352	    return 'needs-human';
353	  }
354	
355	  if (verdict.run !== true) {
356	    const plan = noGoPlan(item, task, at, verdict.reason || 'no work');
357	    // A DECLINED REQUEST IS DISARMED IN THE SAME CONVERGENCE (PRINCIPLES.md).
358	    // Nothing else would: an issue left carrying `claude-queued` after its run was
359	    // refused is one no later scheduler run adopts and no person is told about, and one
360	    // whose mark — if re-applied — walks into the same refusal forever.
361	    // A LEGACY shadow item wrote its decline back to the issue it named. A marked
362	    // issue IS the item, so the decline's comment and its `rejected` status already
363	    // land where the person is looking and there is nothing to mirror (PRINCIPLES.md).
364	    if (fields.request && fields.request !== item.number) {
365	      await declineRequest(api, gh, repo, fields.request, item.number, plan.reason);
366	    }
367	    // A DECLINE IS A COMPLETED RUN, not a failure: the executor asked, got a
368	    // no, and closed the occurrence — so the record says `success` and the
369	    // reason sits beside it in the same comment.
370	    await close(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_REJECTED, 'not_planned',
371	      `The precondition declined: ${plan.reason}`
372	      + (plan.standing
373	        ? '\n\nThis task is asked again at the next scheduler run; a decline is recorded nowhere but here.'
374	        : ''), 'success');
375	    return 'obsolete';
376	  }
377	
378	  // --- code-work (unchanged contract), then converge or hand off -------------
379	  // The item's OWN Context is scope too, not decoration: an operator's parameters
380	  // (`create-work-item --context "REPOS=Alpha Beta"`) live there and nowhere else,
381	  // so code-work sees the union of what the item was created with and what this
382	  // occurrence's precondition added. Passing only the verdict's half is what made
383	  // a hand-created item's parameters unreachable (#974).
384	  const context = mergeContext(parseContextLines(item.body), verdict.context ?? []);
385	
386	  // --- the target: which pull request this run works on (PRINCIPLES.md) ------
387	  // Decided ONCE, here, between the go and the work, and handed to both phases —
388	  // code-work as environment, the agent as item fields — so neither phase
389	  // discovers, chooses or disposes of a pull request on its own. A read the
390	  // resolver could not make is a run failure like an unanswerable precondition
391	  // (F27): an unreadable pull request list looks exactly like an empty one, and
392	  // "nothing to amend" on that evidence stacks a duplicate.
393	  const target = await resolveTargetOf(task, at);
394	  if (target.error) {
395	    await converge(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_NEEDS_HUMAN_FAILURE, claim,
396	      `This run could not be given a target: ${target.error}\n\nNothing ran and nothing was written. Re-queue this item (${requeueHint}) once the cause has cleared.`);
397	    log(`! #${item.number} ${id}: the target could not be resolved — ${target.error}`);
398	    return 'needs-human';
399	  }
400	  log(`- #${item.number} ${id}: target — ${target.reason}`);
401	  if (target.landed) {
402	    // The previous delivery had concluded green and was landed by the resolution.
403	    // That IS this occurrence: the tree this run holds predates the merge, so the
404	    // work would re-deliver a diff already on the base. The next occurrence
405	    // converges from the moved base.
406	    await closeSuperseded({ gh, repo, numbers: target.supersedes, successor: target.landed, log });
407	    await close(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_DONE, 'completed',
408	      `Landed #${target.landed}, this task's previous delivery, which had concluded green and was never merged. `
409	      + 'The checkout this run holds predates that merge, so nothing else ran; the next occurrence converges from the moved base.', 'success');
