411	  }
412	
413	  if (declaresCodeWork(task.decl)) {
414	    // The work step may legitimately run for hours (PRINCIPLES.md). While it does, the
415	    // item's only sign of life is this beat — which is also what the scheduler run's leash
416	    // measures, so a long run is legal rather than reclaimed underneath itself.
417	    const endCodeWork = phase('code-work');
418	    const result = await withHeartbeat(() => runTaskCodeWork(task, { item, context, target }), {
