494	        return 'requeued';
495	      }
496	      // A run that deliberately left an UNMERGED PR is not finished, it is waiting
497	      // on a person — so the item stays OPEN at `task:needs-human-approval` rather
498	      // than closing as delivered. A park is not live, so the next occurrence is
499	      // filed on schedule around it and an unreviewed PR delays nobody but its
500	      // reviewer.
501	      if (result.openPr) {
502	        await converge(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_NEEDS_HUMAN_APPROVAL, claim,
503	          `Code-work did this run's work and opened a PR for you to approve:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
504	          + `\n\nMerge or close #${result.openPr}, then close this item. This task keeps running on schedule meanwhile.`, null);
505	        return 'needs-human';
506	      }
507	      await close(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_DONE, 'completed',
