516	  // An agentless task with no code-work does nothing (the contract forbids it).
517	  if (task.decl.agent_model === 'none') {
518	    await converge(cost, api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_NEEDS_HUMAN_FAILURE, claim,
