546	// Hand off to an agent session (PRINCIPLES.md). ONE call per item, ever — which is
547	// what lets this be as short as it is. The nonce goes on the item before the call
548	// and travels in the payload, so the session can prove the fire it arrived on is
549	// the hand-off this item recorded and stop if it is not.
550	async function handOff({ api, gh, repo, item, task, id, context, result, target = null, executorId, claim, invokeAgent, config, log, cost = null }) {
551	  const endHandOff = cost ? cost.phase('hand-off') : () => {};
552	  const nonce = `${item.number}-${Math.random().toString(36).slice(2, 10)}`;
553	  // Every section lands in the machine's half of the body — the whole body for a
554	  // filed item, the machine block for a marked issue, whose prose is the person's.
555	  const body = editItemBody(item.body, (machine) => {
556	    let out = machine;
557	    // The target's fields first, under the task path: the branch the session
558	    // pushes to, the pull request it amends, the ones its converge supersedes.
559	    if (target) out = withTarget(out, target);
560	    if (context.length) out = withSection(out, 'Context', context);
561	    if (result.delivered?.length) out = withSection(out, DELIVERED_HEADING, result.delivered);
562	    if (result.reason) out = withSection(out, 'Why the agent is here', [result.reason]);
563	    return out;
564	  });
565	  await setIssueBody(gh, repo, item.number, body);
566	
567	  await swapStatus(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT);
568	  // The hand-off is this run's LAST word on the item — the session converges it from
569	  // here — so the cost record rides this comment, where a terminal one would carry
570	  // it for an item the executor settled itself.
571	  await api.comment(gh, repo, item.number,
572	    `${HANDOFF_MARKER}\nHanded off by executor \`${executorId}\` — invocation nonce \`${nonce}\`.`
573	    + recordFor(item, null, cost));
574	
575	  const invocation = await invokeAgent({ task, item, nonce, config });
576	  if (invocation.ok) {
577	    await api.comment(gh, repo, item.number,
578	      `Agent session started${invocation.sessionUrl ? `: ${invocation.sessionUrl}` : ''}.`);
579	    log(`- #${item.number} ${id}: handed off${invocation.sessionId ? ` (${invocation.sessionId})` : ''}`);
580	    endHandOff();
581	    return 'agent';
582	  }
583	  if (invocation.answered) {
584	    // The endpoint refused, so no session exists and none will: a token, a URL or
585	    // a routine is wrong, and every future pick would be refused the same way.
586	    endHandOff();
587	    await converge(cost, api, gh, repo, item, STATUS_RUNNING_AGENT, STATUS_NEEDS_HUMAN_ACTION, claim,
588	      `Could not start an agent session: ${invocation.error}\n\nNo session was started. Fix the invocation endpoint, then re-queue this item (${requeueHint}).`);
589	    return 'needs-human';
590	  }
591	  // NOTHING CAME BACK, and this is the case the whole design turns on: the call
592	  // may have started a session. Re-queueing here is what would put two sessions on
593	  // one item, and converging to triage would kill a run that is very possibly
594	  // alive. So the item STAYS with the agent and says the outcome is unknown —
595	  // whichever way it went is then settled by a rule that already exists: a session
596	  // that started converges the item, and one that never did leaves the item silent
597	  // until the repair phase's agent leash sweeps it to triage.
598	  await api.comment(gh, repo, item.number,
599	    `The agent invocation got no answer: ${invocation.error}\n\n`
600	    + 'The session may or may not have started, so nothing here re-tries it — a second call could put two sessions on this item. '
601	    + 'If a session did start it will converge this item; if it did not, the repair phase\'s agent leash parks it for a human within a few hours.');
602	  log(`! #${item.number} ${id}: invocation unanswered — left with the agent, leash decides — ${invocation.error}`);
603	  endHandOff();
604	  return 'unknown';
605	}
