607	// LETTING GO OF AN OPEN ITEM KILLS YOUR CLAIM (PRINCIPLES.md, F24). An executor
608	// that stops owning an item without closing it — the roll, and every
609	// `needs-human` park — strikes its own claim by appending the episode marker to
610	// it. `claimWinner` already treats the last marker as the boundary, so a struck
611	// claim stops outranking anything and the next claimant wins on its first try.
612	//
613	// APPENDING rather than commenting is what lets the roll stay silent (PRINCIPLES.md): an
614	// hourly task that declines every hour adds no timeline entry. A successful
615	// hand-off deliberately does NOT strike — the episode is still live, owned by the
616	// agent session — and neither does a close, since nothing re-claims a closed item.
617	//
618	// Struck BEFORE the label swap, so the crash window degrades the safe way: an
619	// executor that dies between the two leaves the item `task:executing` with a
620	// spent claim, which the scheduler run's leash reclaim already recovers. Striking after
621	// would leave exactly the state this fixes — parked, re-queued by a human, and
622	// unclaimable forever.
623	async function strikeClaim(api, gh, repo, claim) {
624	  if (!claim || (claim.body ?? '').includes(EPISODE_MARKER)) return;
625	  await api.editComment(gh, repo, claim.id,
626	    `${claim.body}\n\n${EPISODE_MARKER}\nThis claim is spent — the executor released this item without closing it.`);
627	}
628	
629	// Every exit converges the item exactly once, with one comment saying what
630	// happened — the terminal-state discipline the incidents bought. The claim sits
631	// before the body so every state argument is grouped ahead of the prose.
632	//
633	// THE COMMENT CARRIES THE EXECUTION RECORD (docs/PRINCIPLES.md). Actions logs
634	// expire, and for an agentless run — the majority — the item is the only durable
635	// trace there will ever be, so the record goes where the item is rather than into
636	// a log that ages out. The bracketed field is this item's issue number, which is
637	// the only join from a record back to the work it describes.
638	// A status of `null` writes NO record, and that is the honest answer for a park
639	// that is not a failure: the vocabulary's `success` means "ran to completion and
640	// the issue was closed" and `failed` means the run broke, so an approval park —
641	// a run that succeeded and left a PR for a person — is neither. Absence is a
642	// state of its own; inventing a fifth status is a change to stored data every
643	// decoder in the fleet would have to learn.
644	// THE RUN'S COST RIDES THE SAME BLOCK (run-record.mjs). A scheduler tick can only
645	// print its cost into a log that expires; an executor run has items, so it writes
646	// the record where the record survives. Every item this run settles gets the
647	// counters AS THEY STAND at that moment, so a run that settled three items leaves
648	// three snapshots of one record — the reader keys on the run id and keeps the
649	// largest, which is the run's total as of its last item.
650	//
651	// A run that is not timing itself (a test, the simulator) supplies no `cost` and
652	// the block is exactly what it was.
653	const recordFor = (item, status, cost = null) => {
654	  // `item.taskId` is the resolved id — a marked issue's title names no task, so the
655	  // title parse alone would silently drop the record for every request run.
656	  const id = item.taskId ?? null;
657	  const parsed = status
658	    ? (id ? { pack: id.split('/')[0], task: id.split('/').slice(1).join('/') } : parseWorkItemTitle(item.title))
659	    : null;
660	  const lines = [
661	    ...(parsed ? [renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })] : []),
662	    ...(cost ? [cost.record()] : []),
663	  ];
664	  return lines.length ? `\n\n\`\`\`\n${lines.join('\n')}\n\`\`\`` : '';
665	};
666	
667	// Park an item for a human. ONE label: the park IS the status, and its kind is what
668	// the human is being asked for (PRINCIPLES.md). The two-label park it replaces could be
669	// half-applied, which was a torn state of its own.
670	async function converge(cost, api, gh, repo, item, from, park, claim, body, status = 'failed') {
671	  return timed(cost, 'converge', async () => {
672	    await strikeClaim(api, gh, repo, claim);
673	    await api.comment(gh, repo, item.number, body + recordFor(item, status, cost));
674	    await swapStatus(api, gh, repo, item, from, park);
675	  });
676	}
