678	// A close writes only to the item it holds (docs/PRINCIPLES.md; #1373 reversed
679	// an earlier attempt): a dependent this close may make due is released solely by the
680	// scheduler run's own readiness job, on its next pass, never here.
681	async function close(cost, api, gh, repo, item, from, outcome, stateReason, body, status) {
682	  return timed(cost, 'converge', async () => {
683	    await api.comment(gh, repo, item.number, body + recordFor(item, status, cost));
684	    await clearStatus(api, gh, repo, item, from);
685	    await api.addLabel(gh, repo, item.number, outcome);
686	    // A TERMINAL CLOSES THE ISSUE IT STANDS ON, marked or filed, and both terminals do
687	    // (PRINCIPLES.md, owner 2026-09-06). `done` means nothing is left to act on; `rejected`
688	    // means nothing will happen. Neither is a question, so neither leaves an open issue
689	    // behind asking a person to agree with a verdict already reached — and re-asking is
690	    // what it always was, clearing the status.
691	    await api.closeIssue(gh, repo, item.number, stateReason);
692	  });
693	}
