697	export async function runExecutorJob() {
698	  // THE OPERATOR HOLD, FIRST ACT (PRINCIPLES.md) — before the config load, before the
699	  // first API call, so a held queue reads nothing and writes nothing rather than
700	  // deriving the world and then declining to act on it.
701	  if (isSuspended()) { console.log('## Claudinite executor\n'); console.log(suspendedNotice()); return; }
702	  const { makeGh, apiCallCount } = await import('../world/github.mjs');
703	  const { actionRepoContext, actionsEnv, executorId, repoRoot, runUrlFor } = await import('../world/actions.mjs');
704	  const { discoverTasks } = await import('../contract/discover.mjs');
705	  const { loadConfig } = await import('../../../../engine/checks/helpers/repo-context.mjs');
706	  const { isDormant, dormancyErrors } = await import('../contract/dormancy.mjs');
707	  const { ensureLabels } = await import('../world/github.mjs');
708	  const { collectSignalsForTask } = await import('../signals/for-task.mjs');
709	  const { codeWorkRunner } = await import('./code-work-run.mjs');
710	  const { agentInvoker } = await import('../world/sessions.mjs');
711	
712	  const root = repoRoot();
713	  const { repo, defaultBranch } = actionRepoContext();
714	  if (!repo) { console.error('GITHUB_REPOSITORY not set - not in an Actions context'); process.exitCode = 1; return; }
715	  const config = loadConfig(root);
716	
717	  console.log('## Claudinite executor\n');
718	  for (const e of dormancyErrors(config)) console.log(`! ${e.what} — ${e.fix}`);
719	  if (isDormant(config)) {
720	    console.log('- this project declares its scheduler dormant — nothing is picked up');
721	    return;
722	  }
723	
724	  const gh = makeGh();
725	  const { tasks, errors } = await discoverTasks(root, config);
726	  for (const e of errors) console.log(`! ${e.what}`);
727	  await ensureLabels(gh, repo, QUEUE_LABELS);
728	
729	  const runUrl = actionsEnv().GITHUB_RUN_ID
730	    ? `${actionsEnv().GITHUB_SERVER_URL ?? 'https://github.com'}/${repo}/actions/runs/${actionsEnv().GITHUB_RUN_ID}`
731	    : null;
732	
733	  // WHAT THIS RUN COSTS (run-record.mjs). Only the real job times itself: a run id
734	  // is what the record is filed under, and a run without one is not a billed
735	  // invocation of anything.
736	  const runCost = startRunCost({
737	    workflow: 'executor', runId: actionsEnv().GITHUB_RUN_ID ?? null, apiCalls: apiCallCount,
738	  });
739	
740	  const done = await runExecutor({
741	    gh, repo, root, config, tasks,
742	    executorId: actionsEnv().CLAUDINITE_EXECUTOR_ID || `actions-${actionsEnv().GITHUB_RUN_ID ?? 'local'}`,
743	    runUrl,
744	    // A COLLECTOR PER PICK. The collector holds the checkout's facts for the span
745	    // it was built for, and a `code_work` step during a pick rewrites that
746	    // checkout — one built for the whole drain would answer the next item from the
747	    // pre-edit tree. The executor asks for an item exactly once, so building it
748	    // per ask is building it per pick.
749	    collectSignalsFor: (task, at, item) => collectSignalsForTask({ gh, repo, root, config, defaultBranch })(task, at, item),
750	    runTaskCodeWork: codeWorkRunner({ root, repo, defaultBranch }),
751	    invokeAgent: agentInvoker({ repo, config }),
752	    runCost,
753	  });
754	
755	  console.log(done.length
756	    ? done.map((d) => `- #${d.issue}: ${d.outcome}`).join('\n')
757	    : '- nothing ready to pick up');
758	  // Into the log as well as onto the items: a run that settled nothing has no item
759	  // to write on, and its cost — the pick that found an empty queue — is exactly the
760	  // figure a quiet day is made of.
761	  console.log(`\n${runCost.record()}`);
762	}
763	
764	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
765	  runExecutorJob().catch((e) => { console.error(e); process.exitCode = 1; });
766	}
