  1	// THE PRECONDITION SEAM — the one call that turns a discovered task plus its
  2	// collected signals into a verdict, and the window arithmetic a verdict is judged
  3	// over. Contract rather than stage: both stages ask it (the scheduler run at the
  4	// anchor, the executor again at pick), and what it means is fixed by the
  5	// declaration, not by who is asking.
  6	
  7	import { periodMs } from '../items/anchors.mjs';
  8	import { taskCadence } from './task-contract.mjs';
  9	import { evaluatePreconditions } from './precondition-policy.mjs';
 10	
 11	export const DAY_MS = 86400e3;
 12	export const SLACK_MS = 3600e3;
 13	
 14	// The window a task reads with no run of its own to measure from: its cadence
 15	// term's period, a day where it states none.
 16	export function defaultWindowMs(task) {
 17	  const cadence = taskCadence(task?.decl);
 18	  return (cadence === null ? DAY_MS : periodMs(cadence.cadence)) + SLACK_MS;
 19	}
 20	
 21	// The lookback in DAYS a verdict is judged over — what a term needs when its
 22	// dimension carries an age rather than a windowed flag of its own (the
 23	// conversation-logs branch reports how old its newest capture is, not whether one
 24	// landed). Read off the collected bundle, which is where the window was decided.
 25	export const windowDaysOf = (task, signals) => signals?.runs?.window?.days ?? defaultWindowMs(task) / DAY_MS;
 26	
 27	// Run one task's precondition. THE only place a precondition is ever called, so a
 28	// test that drives this drives what production drives — a precondition first
 29	// written to take `{ signals }` passed its own direct-call test and threw on every
 30	// real run, which is the failure this seam exists to make impossible.
 31	//
 32	// One form comes through here: the declarative `preconditions` expression, which
 33	// is the only gate a task may declare (#1617). It fails LOUD by construction — a
 34	// term that throws, an unknown name, an unreadable signal all return `{ error }`,
 35	// a run failure the caller parks rather than a decline taken on a guess.
 36	export function evaluatePrecondition(task, signals, packConfig = {}, item = null, at = null) {
 37	  return evaluatePreconditions({
 38	    preconditions: task.decl.preconditions,
 39	    signals,
 40	    config: packConfig,
 41	    item,
 42	    terms: task.terms,
 43	    // The window the signals were collected over, read off the bundle where it
 44	    // was decided (src/signals/for-task.mjs).
 45	    windowDays: windowDaysOf(task, signals),
 46	    // The instant this verdict is for — the same one the signals were collected
 47	    // for, so a clock-reading term and a windowed one cannot disagree about when
 48	    // "now" is.
 49	    now: at,
 50	  });
 51	}
