102	// Move `item` out of `fromStatus` (canonical — every spelling of it goes) and into
103	// the label `to`, which is whatever spelling this engine writes.
104	export async function swapStatus(api, gh, repo, item, fromStatus, to) {
105	  await clearStatus(api, gh, repo, item, fromStatus);
106	  return api.addLabel(gh, repo, item.number, to);
