141	// Every OPEN work item, oldest first. The whole queue is a page or two: a repo's
142	// standing items are one per scheduled task, plus whatever ad-hoc work exists.
143	export async function listOpenWorkItems(gh, repo) {
144	  const out = [];
145	  for (let page = 1; ; page += 1) {
146	    const { status, json } = await listOpenIssuesPage(gh, repo, page);
147	    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
148	    for (const i of json) {
149	      if (i.pull_request) continue;
150	      if (!isQueueItem(i)) continue;
151	      out.push(project(i));
152	    }
153	    if (json.length < 100) break;
154	  }
155	  return out;
156	}
157	
158	// Every work item that converged DONE, newest first — the closed half of the queue,
159	// and the only evidence the superseded-park rule (repair rule E) runs on.
160	//
161	// BOUNDED, unlike the open list: a long-lived repo's closed set is thousands of
162	// issues and the rule only ever asks "did this task run clean since <park>". Two
163	// pages of most-recently-updated is far past the horizon of any park worth closing,
164	// and a park older than that is stale for reasons this rule is not the fix for.
165	export async function listDoneWorkItems(gh, repo, { pages = 2 } = {}) {
166	  const out = [];
167	  for (let page = 1; page <= pages; page += 1) {
168	    const { status, json } = await listClosedIssuesPage(gh, repo, page);
169	    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
170	    for (const i of json) {
171	      if (i.pull_request) continue;
172	      if (!isQueueItem(i)) continue;
173	      if (statusOf(i) !== STATUS_DONE) continue;
174	      out.push(project(i));
175	    }
176	    if (json.length < 100) break;
177	  }
178	  return out;
179	}
180	// THE OPERATOR HOLD (docs/PRINCIPLES.md). One repository
181	// Actions variable stops the whole queue: every Claudinite workflow carries it
182	// into its env, and every engine entry point checks it as its FIRST act — before
183	// any read, like the dormancy gate beside it — and exits cleanly having fired
184	// nothing.
185	//
186	// Why a variable rather than a commit: cancelling one run means "move on", an
187	// intent the failure continuation and the leash already serve. Stopping the
188	// SYSTEM is a different intent, and the only lever that existed for it was
189	// dormancy, which needs a commit and an update to take effect and another to
190	// undo. A variable takes effect on the next run and clears the same way.
191	//
192	// What it freezes: STARTS. A run already past this gate finishes the drain it is
193	// in: killing live work would leave exactly the half-done state the leash exists to
194	// recover, and the value a run holds is the one it started with — `vars` reaches a
195	// job's env at start only, and the REST variables API that could re-read it is
196	// refused to the Actions GITHUB_TOKEN (403, and no `permissions:` key grants it),
197	// so a live re-read between items answered nothing on every member and was
198	// retired. A hold set mid-drain lands on the next run.
199	//
200	// Resume needs no code: clear the variable and the next scheduler run reclaims, readies and
201	// drains on its own. The impatient path is dispatching the SCHEDULER workflow, not
202	// the bare executor — the scheduler run is what re-derives the world.
203	
204	import { actionsEnv } from './actions.mjs';
205	import { varsBag } from './vars-bag.mjs';
206	
207	export const SUSPEND_ALL_VAR = 'CLAUDINITE_TASKS_SUSPEND_ALL';
208	
209	// Read from the vars bag where the job carries one (the executor), else from the
210	// named env copy: the scheduler workflow carries no bag, and stamps this one
211	// variable by name because it is the one variable the scheduler needs. A member
212	// executor that never received the bag still carries the named copy, and is served
213	// by the same fallback.
214	const suspendValue = (env) => varsBag(env)?.[SUSPEND_ALL_VAR] ?? env[SUSPEND_ALL_VAR];
215	
216	// Deliberately narrow: a variable somebody set to `false` or `0` to mean "off"
217	// must not read as on. Anything else — unset, empty, a word — is not a hold.
218	export const isSuspended = (env = actionsEnv()) =>
219	  ['true', '1', 'yes'].includes(String(suspendValue(env) ?? '').trim().toLowerCase());
220	
221	// The reader a batched drain once asked between items, kept at its name for a member's
222	// local pack that imports it. It answers what the run started with: the live re-read
223	// over the REST variables API it used to make is refused to the Actions token in every
224	// member (`repo-variables-through-the-bag`), so the answer never differed.
225	export const liveSuspendReader = (_gh, _repo, { env = actionsEnv() } = {}) => async () => isSuspended(env);
226	
227	// The one line every entry point prints when it parks, so a run that did nothing
228	// says WHY it did nothing — a silent clean exit is indistinguishable from a run
229	// that found no work.
230	export const suspendedNotice = () =>
231	  `- ${SUSPEND_ALL_VAR} is set: the queue is held. Nothing is picked up, created, readied or reclaimed.\n`
232	  + '  Clear the variable in repo settings (Settings → Secrets and variables → Actions → Variables) to resume;'
233	  + ' the next scheduled scheduler run recovers everything on its own.';
234	// The executor's per-task secret selection (docs/PRINCIPLES.md).
235	//
236	// WHAT THIS MODULE IS FOR NOW: making PRINCIPLES.md's claim true. A task's code-work
237	// gets exactly the names that task declared, selected here, where before every task's
238	// work step inherited the executor's whole environment and saw every stamped secret.
239	// That selection is independent of how the secrets arrive, and it is why this module
240	// survives the reversal below.
241	//
242	// THE BAG IS RETIRED (#1336, reversing #1301). The executor briefly carried one static
243	// line, `CLAUDINITE_SECRETS: ${{ toJSON(secrets) }}`, so the workflow would stop being
244	// a function of the task set — `.github/workflows/` is the one path an update cannot
245	// write, and a new secret therefore needs a human-merged PR in every member, which is
246	// what wedged one in #1296. But serialising the whole secrets context is the shape
247	// GitHub's malicious-workflow detection flags: every executor run parked with zero
248	// jobs until a person clicked Approve, silently, fleet-wide. The owner took the
249	// trade back — a rare human-merged PR beats a permanent human click on every run.
250	//
251	// So the workflow names its secrets again and NOTHING SETS THE BAG. The plain
252	// environment is therefore the LIVE source, and the bag READER is the tolerance: it
253	// stays because a member whose live executor still stamps one moves off it only
254	// through a human-merged PR of its own, and dropping the reader early would hand
255	// that member's code-work the whole blob, since the scrub in code-work-run.mjs goes
256	// with it. Its retirement is a fleet read rather than a canon release (#1914).
257	
258	import { parseBag } from './env-bag.mjs';
259	import { actionsEnv } from './actions.mjs';
260	
261	export const SECRETS_BAG_ENV = 'CLAUDINITE_SECRETS';
262	
263	// The parsed bag, or null when this job carries none. A malformed bag is null too:
264	// the caller's own "declared but not configured" posture then names the secret, which
265	// is a better answer than a crash inside a JSON parse.
266	export const secretsBag = (env = actionsEnv()) => parseBag(env[SECRETS_BAG_ENV]);
267	
268	// One secret's value, or undefined.
269	//
270	// LEGACY EXECUTOR WORKFLOWS ARE READ AT THE DOOR. A member's live
271	// `claudinite-executor.yml` moves only through a human-merged PR, so every member
272	// spends a window running this engine against a workflow that still stamps names
273	// directly and sets no bag. Reading `env[name]` when the bag does not carry it is
274	// what makes that window uneventful. The fallback comes out on #1642's window: a
275	// member's live workflow moves only through a human-merged PR, so the window is what
276	// that PR is given, and no census of who has merged it is available here.
277	export function secretValue(name, env = actionsEnv(), bag = secretsBag(env)) {
278	  // The bag holds every secret the repository has, so its own variable is not a
279	  // secret anyone may ask for by name — otherwise one declaration re-exports all of
280	  // them and the selection below means nothing.
281	  if (name === SECRETS_BAG_ENV) return undefined;
282	  const fromBag = bag?.[name];
283	  return fromBag === undefined ? env[name] : fromBag;
284	}
285	
286	// The declared subset, as an environment fragment: only the names asked for, only the
287	// ones this job actually carries. A name with no value is left out rather than set to
288	// an empty string, so a consumer can still tell unset from set-but-empty.
289	export function secretsFor(names = [], env = actionsEnv()) {
290	  const bag = secretsBag(env);
291	  const out = {};
292	  for (const name of names) {
293	    const value = secretValue(name, env, bag);
294	    if (value !== undefined) out[name] = value;
295	  }
296	  return out;
297	}

