1	// The task declaration as a file and as text — the half every reader can load,
2	// the dashboard's browser bundle included: no Node built-ins here. The fs half
3	// (finding and loading a folder's declaration) is task-declaration.mjs, which
4	// re-exports this.
5	//
6	// `task.json` is the declaration: plain data, pointing at `task.schema.json`
7	// through `$schema`, and readable by anything that can parse JSON. It is the
8	// only declaration file a task folder may carry.
9	
10	export const TASK_DECLARATION_FILE = 'task.json';
11	
12	// The file-listing form of the same fact, for the checks and the dashboard, which
13	// select a task folder out of a path list rather than probing a directory. Group 1
14	// is the task's directory name.
15	export const TASK_DECLARATION_PATH_RE = /(^|\/)tasks\/([^/]+)\/task\.json$/;
16	export const isTaskDeclarationPath = (path) => TASK_DECLARATION_PATH_RE.test(path);
17	
18	// A `task.json`'s text as the declaration object. `$schema` is the editor's
19	// pointer, not a field of the contract, and leaves here.
20	export function parseTaskDeclaration(text) {
21	  const decl = JSON.parse(text);
22	  if (decl !== null && typeof decl === 'object' && !Array.isArray(decl)) delete decl.$schema;
23	  return decl;
24	}
25	
26	// The order a declaration's keys are written in, grouped by what they say: what
27	// the task is, when it runs, what it may write, then the two phases — code work,
28	// then the agent. A key not listed keeps its place after the listed ones.
29	export const KEY_ORDER = [
30	  '$schema', 'id', 'description',
31	  'schedule_after', 'trigger', 'preconditions',
32	  'expected_outcome', 'automerge', 'on_interrupt', 'invocation_endpoint',
33	  'code_worker_mjs', 'code_work', 'code_work_timeout', 'code_work_required_secrets',
34	  'agent_model', 'model_from_request', 'agent_instructions', 'agent_execution_timeout',
35	];
36	export function orderTaskKeys(decl) {
37	  const rank = (k) => { const i = KEY_ORDER.indexOf(k); return i === -1 ? KEY_ORDER.length : i; };
38	  return Object.fromEntries(Object.entries(decl).sort(([a], [b]) => rank(a) - rank(b)));
39	}
40	
41	// --- reading a declaration as TEXT --------------------------------------------
42	//
43	// The author-time checks run over a file listing, not a module graph, and the
44	// dashboard renders other repos over the API where there is nothing to import.
45	// Both read the declaration's scalar fields out of its text — a `task.json`
46	// parsed whole.
47	//
48	// The uniform view: `has(key)` (the field is declared at all, whatever its
49	// value), `scalar(key)` (a string, number or boolean, else undefined),
50	// `list(key)` (a list of strings; null when declared but unreadable). `error`
51	// carries a JSON parse failure, in which case every reader answers "absent" and
52	// the caller reports the error. `code` is the raw text, for the callers that
53	// still pattern-match one thing (a sibling `preconditions.mjs`, say).
54	export function readDeclarationFields(code) {
55	  let obj = null;
56	  let error = null;
57	  try {
58	    obj = JSON.parse(code);
59	    if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) { error = 'not a JSON object'; obj = null; }
60	  } catch (e) {
61	    error = e.message;
62	  }
63	  const value = (key) => (obj && key !== '$schema' ? obj[key] : undefined);
64	  return {
65	    format: 'json',
66	    error,
67	    object: obj,
68	    code,
69	    has: (key) => value(key) !== undefined,
70	    scalar: (key) => (['string', 'number', 'boolean'].includes(typeof value(key)) ? value(key) : undefined),
71	    list: (key) => {
72	      const v = value(key);
73	      if (v === undefined) return undefined;
74	      return Array.isArray(v) && v.every((s) => typeof s === 'string') ? v : null;
75	    },
76	  };
77	}
