1	// Reading ONE transcript entry - the shapes every counter in this task asks
2	// about, in the one place that knows them. Both counting passes read entries
3	// (fold-usage.mjs counts what the session produced, corpus-use.mjs what the
4	// corpus did to it), and a shape spelled twice would let the two disagree about
5	// what a load or a human turn is.
6	
7	// A genuine human turn. POSITIVE test, deliberately: the transcript stamps a
8	// typed-by-a-person turn with `origin: { kind: 'human' }`, and everything else a
9	// user-role entry can be - a tool result, an injected/meta turn, a subagent's
10	// sidechain traffic, a compaction summary, a slash-command expansion, and (the one
11	// that matters most here) a scheduled-task firing, which carries
12	// `origin: { kind: 'task-notification', subkind: 'scheduled-trigger' }` - simply
13	// lacks that stamp. Testing FOR the human marker rather than against a list of
14	// automated ones means a new automated entry shape is excluded the day it appears
15	// instead of silently inflating the denominator.
16	//
17	// The honest boundary: an older harness wrote no `origin` at all. Those turns count
18	// as non-human, so a repo's very old captures under-report userMessages rather than
19	// over-reporting them. This is the most fragile line in the fold, which is why it is
20	// one function with a fixture per shape it excludes.
21	export function isUserMessage(entry) {
22	  return entry?.type === 'user' && entry?.origin?.kind === 'human';
23	}
24	
25	// A user-typed slash command. The harness expands `/name args` into a user entry
26	// whose string content opens with a `<command-name>` tag - the tag is the marker,
27	// so prose that merely mentions a slash command never counts. Returns the bare
28	// command name (no leading slash), or null.
29	const COMMAND_RE = /<command-name>\s*\/?([A-Za-z0-9:_-]+)\s*<\/command-name>/;
30	export function commandName(entry) {
31	  if (entry?.type !== 'user') return null;
32	  const content = entry?.message?.content;
33	  if (typeof content !== 'string') return null;
34	  return COMMAND_RE.exec(content)?.[1] ?? null;
35	}
36	
37	// Skill names loaded by an assistant entry: every `Skill` tool_use block's
38	// `input.skill`. Sidechain (subagent) entries are included by the caller - a
39	// subagent loading a skill is a load.
40	export function skillToolLoads(entry) {
41	  if (entry?.type !== 'assistant') return [];
42	  const content = entry?.message?.content;
43	  if (!Array.isArray(content)) return [];
44	  return content
45	    .filter((b) => b?.type === 'tool_use' && b?.name === 'Skill' && typeof b?.input?.skill === 'string')
46	    .map((b) => b.input.skill);
47	}
48	
49	// The tool_use blocks of an assistant entry, as { name, input, id }.
50	export function toolCalls(entry) {
51	  if (entry?.type !== 'assistant' || !Array.isArray(entry?.message?.content)) return [];
52	  return entry.message.content
53	    .filter((b) => b?.type === 'tool_use' && typeof b?.name === 'string')
54	    .map((b) => ({ name: b.name, input: b.input ?? {}, id: b.id }));
55	}
56	
57	// Every string value anywhere in one entry, newline-joined - the haystack the
58	// executor's exec records and the hooks' own log lines are fished out of. They are
59	// printed by code into tool results, but the model may also quote one back, and the
60	// harness records both, so every caller dedupes on the record it read rather than
61	// trusting any one entry shape.
62	export function entryText(value, out = []) {
63	  if (typeof value === 'string') out.push(value);
64	  else if (Array.isArray(value)) for (const v of value) entryText(v, out);
65	  else if (value && typeof value === 'object') for (const v of Object.values(value)) entryText(v, out);
66	  return out;
67	}
68

1	// The usage-fold work step - the module the runner calls `worker` on
2	// (cwd = this task dir, bounded by code_work_timeout).
3	// The whole task: no agent phase.
4	//
5	// It holds NO counting logic. The counting and folding are `fold-usage.mjs`, its
6	// SIBLING in this task folder — nothing outside this task uses them, so that is
7	// where they live and where their tests point. This file is the I/O shell:
8	//
9	//   1. fetch the orphan `conversation-logs` branch (plain local git — the branch is
10	//      in this repo, so one tree read plus one blob read per file beats any REST
11	//      round-trip, and there is no rate budget to spend);
12	//   2. count each capture file still in the raw retention window;
13	//   3. list the scheduler's and executor's completed workflow runs past the
14	//      `runsFoldedThrough` watermark (read-runs.mjs) — how often the machinery ran,
15	//      including the runs that opened no session at all;
16	//   4. list the work items that CLOSED past the `queueFoldedThrough` watermark
17	//      (read-queue.mjs) — what each occurrence came to, and the parks each collected;
18	//   4b. list the pull requests MERGED past the `prsFoldedThrough` watermark
19	//      (read-prs.mjs) — what each one took from opening, from its issue and from the
20	//      session that did the work;
21	//   5. read the local git history and the releases listing for the day series neither
22	//      of the above can answer — commits, lines and releases;
23	//   6. fold: hour rows over the last three days, day rows recomputed from scratch,
24	//      appended rows past their watermarks, week rows advanced past `foldedThrough`;
25	//   7. deliver the regenerated `.claudinite/local/usage.GENERATED.json` on a PR
26	//      that lands itself where this repo's delivery settings allow (the shared
27	//      landing helper owns those nuances — packs/claudinite-tasks/src/deliver/land-pr.mjs) — and
28	//      open NOTHING when the recompute is byte-identical apart from its stamp.
29	//
30	// The aggregate lives under `.claudinite/local/` because that is the repo-owned area
31	// the vendoring refresh never touches; the mount root itself is read-only canon.
