33	import { execFileSync } from 'node:child_process';
34	import { readFileSync } from 'node:fs';
35	import { join } from 'node:path';
36	import { baseTip, readAt, remoteUrl } from '../../public/delivery.mjs';
37	import { AUTOMERGE_TRAILER } from '../../src/contract/merge-policy.mjs';
