51	// The run's own logger, under the task's name and its item. Module-level because the
52	// helpers below log too; `worker` takes the one the runner built.
53	let log = console.log;
54	
55	const git = (root, args) => execFileSync('git', ['-C', root, ...args], {
56	  encoding: 'utf8',
57	  // A capture blob easily tops the default 1 MiB buffer — a long session's log then
58	  // dies mid-read and the day it lands in silently under-counts.
59	  maxBuffer: 256 * 1024 * 1024,
60	  stdio: ['ignore', 'pipe', 'pipe'],
61	});
