92	// Fetch the logs branch and return its capture files. Returns null when the branch
93	// does not exist — a repo that has never captured has nothing to fold, which is a
94	// clean no-op rather than a failure.
95	function logFiles(root, remote) {
96	  if (!git(root, ['ls-remote', '--heads', remote, BRANCH]).trim()) return null;
97	  git(root, ['fetch', '--quiet', remote, BRANCH]);
98	  const tip = git(root, ['rev-parse', 'FETCH_HEAD']).trim();
99	  const names = git(root, ['ls-tree', '--name-only', tip]).split('\n').filter(Boolean);
100	  return { tip, names: names.filter((n) => parseLogName(n) !== null).sort() };
101	}
102	
103	// --- the day series the sessions cannot answer --------------------------------
104	
105	// What landed, per day: commits on the base branch and the lines they moved. Local
106	// git, so it is free and recomputed every run — a counting fix heals the whole window
107	// the way the capture-derived rows do.
108	//
109	// A SHALLOW CHECKOUT IS THE NORMAL CASE in Actions, and it is why this returns a
110	// covered-from date rather than a map with zeroes in it: the history simply stops
111	// somewhere, and every day before that is UNKNOWN. Writing 0 for those days would
112	// draw a busy fortnight as an idle one, and the fold's own rule is that an absent
113	// source leaves no key at all.
114	//
115	// `COMMIT_MARK` opens each commit's block so the numstat lines that follow can be
116	// attributed to it. A control character rather than any printable prefix, because the
117	// only thing that can never appear at the start of a numstat line is something git
118	// cannot produce there. A merge commit shows no numstat and contributes a commit but
119	// no lines, which is right — its content arrived with the commits it merged.
120	const COMMIT_MARK = '\u0001';
121	
122	export function parseCommitLog(text) {
123	  const days = {};
124	  let date = null;
125	  for (const line of String(text ?? '').split('\n')) {
126	    if (line.startsWith(COMMIT_MARK)) {
127	      date = line.slice(1, 11) || null;
128	      if (date) (days[date] ??= { commits: 0, linesAdded: 0, linesRemoved: 0 }).commits += 1;
129	      continue;
130	    }
131	    if (!date || !line.trim()) continue;
132	    const m = /^(\d+|-)\t(\d+|-)\t/.exec(line);
133	    if (!m) continue;
134	    // `-` is a binary file: it has no line count, and counting it as 0 is the honest
135	    // reading — no LINES moved, whatever the bytes did.
136	    if (m[1] !== '-') days[date].linesAdded += Number(m[1]);
137	    if (m[2] !== '-') days[date].linesRemoved += Number(m[2]);
138	  }
139	  return days;
140	}
141	
142	// DEEPEN BEFORE READING. An Actions checkout is shallow — usually one commit — so the
143	// history the series below reads stops immediately and every day but today is unknown.
144	// One `git fetch --shallow-since` over the window fixes that for the price of a single
145	// git operation and no REST at all; the alternative, the commits API, costs one read
146	// per commit for its stats and is unbounded on a busy day.
147	//
148	// Guarded on the repo actually BEING shallow, because on a complete clone the same
149	// flag is not a deepen — it would truncate the history to the window.
150	//
151	// Returns which path ran, so the log says whether the deepen engaged: a fetch that
152	// silently did nothing and a checkout that never needed one produce the same series
153	// and must not read the same in the log.
154	export function deepenHistory(git, root, remote, base, sinceIso) {
155	  try {
156	    if (git(root, ['rev-parse', '--is-shallow-repository']).trim() !== 'true') return 'complete';
157	    git(root, ['fetch', '--quiet', `--shallow-since=${sinceIso}`, remote, base]);
158	    return 'deepened';
159	  } catch {
160	    // A server that will not deepen, or a window with no commits in it: the series is
161	    // read from whatever history is here, and `coveredFrom` still states where it starts.
162	    return 'unchanged';
163	  }
164	}
165	
166	export function commitSeries(git, root, sha, sinceIso) {
167	  let text = '';
168	  try {
169	    text = git(root, ['log', sha, `--since=${sinceIso}`, '--date=iso-strict', '--pretty=format:%x01%cI', '--numstat']);
170	  } catch {
171	    return null;                            // no readable history — the series is unknown, not empty
172	  }
173	  const days = parseCommitLog(text);
174	  // Where the available history actually starts. On a full clone that is the window;
175	  // on a shallow one it is wherever the fetch stopped, and days before it carry no key.
176	  let coveredFrom = sinceIso.slice(0, 10);
177	  try {
178	    if (git(root, ['rev-parse', '--is-shallow-repository']).trim() === 'true') {
179	      const oldest = git(root, ['log', sha, '--reverse', '--pretty=format:%cI']).split('\n')[0]?.slice(0, 10);
180	      if (oldest && oldest > coveredFrom) coveredFrom = oldest;
181	    }
182	  } catch { /* an older git without the flag — the window stands */ }
183	  return { days, coveredFrom };
184	}
185	
186	// Releases published per day. One REST read, recomputed every run like the git series.
187	// Absent (unreadable) leaves every day without the key rather than claiming a month
188	// with no releases in it.
189	export async function releaseSeries(reader, repo) {
190	  const list = await reader.json(`/repos/${repo}/releases?per_page=100`);
191	  if (!Array.isArray(list)) return null;
192	  const days = {};
193	  for (const r of list) {
194	    const at = r?.published_at ?? r?.created_at;
195	    if (!at) continue;
196	    const date = String(at).slice(0, 10);
197	    days[date] = (days[date] ?? 0) + 1;
198	  }
199	  // Newest-first and capped at one page: a repo publishing more than 100 releases
200	  // inside the window would under-report the far end. Stated rather than silently
201	  // truncated — the caller logs it.
202	  return { days, truncated: list.length >= 100 };
203	}
204	
205	// The two series above, merged into the per-day field map `foldUsage` takes: a day
206	// gets a key only from a source that could speak for it.
207	export function dayFieldsFrom({ commits = null, releases = null, ladder = [] }) {
208	  const out = {};
209	  for (const date of ladder) {
210	    const fields = {};
211	    if (commits && date >= commits.coveredFrom) {
212	      const row = commits.days[date] ?? { commits: 0, linesAdded: 0, linesRemoved: 0 };
213	      Object.assign(fields, row);
214	    }
215	    if (releases) fields.releases = releases.days[date] ?? 0;
216	    if (Object.keys(fields).length) out[date] = fields;
217	  }
218	  return out;
219	}
220	
221	// The window's UTC days, oldest first.
222	export function dayLadder(nowIso, days = DAY_WINDOW_DAYS) {
223	  const end = new Date(`${nowIso.slice(0, 10)}T00:00:00Z`).getTime();
224	  return Array.from({ length: days }, (_, i) => new Date(end - (days - 1 - i) * 86400000).toISOString().slice(0, 10));
225	}
