227	// --- main ---------------------------------------------------------------------
228	
229	export async function worker({ root, repo, token, defaultBranch, automerge, deliver, log: runLog }) {
230	  log = runLog;
231	  const base = defaultBranch ?? 'main';
232	  const remote = remoteUrl(repo, token);
233	
234	  // No logs branch is no longer "nothing to do": the capture-derived half of the
235	  // aggregate is empty, but every other source — the run listings, the queue's own
236	  // closed items, the git history — exists as soon as the repo has a scheduler, and a
237	  // repo whose sessions are all unattended is exactly the one worth counting.
238	  const found = logFiles(root, remote);
239	  if (found === null) log(`no ${BRANCH} branch — nothing captured yet; folding the run, queue and git sources only`);
240	
241	  let config = {};
242	  try { config = JSON.parse(readFileSync(settingsPath(root), 'utf8')); } catch { /* no declaration */ }
243	  const corpus = await mountedCorpus(root, config);
244	
245	  const files = (found?.names ?? []).map((name) => ({
246	    ...parseLogName(name),
247	    counts: countEntries(parseEntries(git(root, ['show', `${found.tip}:${name}`])), corpus),
248	  }));
249	
250	  // Prior state comes from the BASE TIP, never the working tree: the checkout may be
251	  // sitting on another task's branch, and the base is the only authority on what has
252	  // already been folded. A fold PR still open when the next run fires is rebuilt from
253	  // the base — days recompute statelessly and the watermark advances from the same
254	  // place, so nothing is ever counted twice.
255	  const baseSha = baseTip(root, remote, base);
256	  // Decoded on the way in: the prior file may have been written by any version of this
257	  // format, and the fold works in named counters throughout.
258	  let prior = {};
259	  try { prior = decodeUsage(JSON.parse(readAt(root, baseSha, USAGE_PATH) ?? '{}')); } catch { /* unparsable → refold */ }
260	
261	  const now = new Date().toISOString();
262	  const reader = makeReader({ token });
263	
264	  // The outside sources. Each is INDEPENDENTLY fail-soft: one that cannot be read
265	  // costs its own rows this run and leaves its own watermark where it was, because
266	  // the capture-derived counts do not depend on any of them and must not be lost with
267	  // one of them.
268	  const runs = await readRuns({ reader, repo, since: prior.runsFoldedThrough ?? null, now });
269	  if (runs.error) log(`${runs.error} — the hour rows' run counts are unchanged this run`);
270	
271	  const queue = await readQueueOutcomes({
272	    reader: makeQueueReader({ token }), repo, since: prior.queueFoldedThrough ?? null, now,
273	  });
274	  if (queue.error) log(`${queue.error} — the queue outcome rows are unchanged this run`);
275	
276	  const prs = await readMergedPrs({ reader, repo, since: prior.prsFoldedThrough ?? null, now });
277	  if (prs.error) log(`${prs.error} — the merged-PR rows are unchanged this run`);
278	
279	  const ladder = dayLadder(now);
280	  const windowStart = `${ladder[0]}T00:00:00Z`;
281	  log(`git history: ${deepenHistory(git, root, remote, base, windowStart)} for the window from ${ladder[0]}`);
282	  const commits = commitSeries(git, root, baseSha, windowStart);
283	  if (commits === null) log('the local git history could not be read — the commit and line rows are absent this run');
284	  else if (commits.coveredFrom > ladder[0]) {
285	    log(`this checkout's history starts at ${commits.coveredFrom} — days before it carry no commit or line counts`);
286	  }
287	  const releases = await releaseSeries(reader, repo);
288	  if (releases === null) log('the releases listing could not be read — the release rows are absent this run');
289	  else if (releases.truncated) log('more than 100 releases exist — the far end of the release series may be under-counted');
290	
291	  const today = now.slice(0, 10);
292	  const text = renderUsageFile(encodeUsage(foldUsage({
293	    files,
294	    prior,
295	    today,
296	    now,
297	    generated: now,
298	    runs: runs.runs,
299	    runsFoldedThrough: runs.watermark,
300	    queueRecords: queue.records,
301	    queueFoldedThrough: queue.watermark,
302	    prRecords: prRecordsFrom({ prs: prs.prs, files }),
303	    prsFoldedThrough: prs.watermark,
304	    dayFields: dayFieldsFrom({ commits, releases, ladder }),
305	  })));
306	
307	  // Compared WITHOUT the freshness stamp, which moves every run by construction: a
308	  // repo where nothing happened must still open nothing, and the stamp is the one line
309	  // that would otherwise make every hourly fold a PR.
310	  const landed = readAt(root, baseSha, USAGE_PATH);
311	  if (landed !== null && withoutStamp(landed) === withoutStamp(text)) {
312	    log(`${files.length} capture file(s) folded — recompute is byte-identical, nothing to deliver`);
313	    return;
314	  }
315	
316	  const pr = await deliver({
317	    files: { [USAGE_PATH]: text },
318	    // The arming trailer carries the task's own automerge, so the
319	    // automerge-policy-scope check re-measures this delivery's diff wherever the
320	    // PR's CI runs check_the_work — the code lane's equivalent of the agent
321	    // lane's stamp-before-merge.
322	    message: `Claudinite: fold usage metrics\n\n${AUTOMERGE_TRAILER}: ${automerge}`,
323	    title: 'Claudinite: usage fold',
324	    body: [
325	      `Regenerated \`${USAGE_PATH}\` from this repo's captured conversation logs, its`,
326	      "workflow run listings, the queue's own closed work items, its merged pull",
327	      'requests, and its git history.',
328	      '',
329	      'Hour rows cover the last three days; day rows are recomputed from scratch every',
330	      'run from the sources still readable; week rows are appended once, past the',
331	      '`foldedThrough` watermark. The run, queue and merged-PR rows are appended once',
332	      'past their own watermarks — all are rate-limited REST reads, not a local branch.',
333	      'A recompute that differs only in its `generated` stamp opens no PR at all.',
334	      'Machine-written — never hand-edit it.',
335	    ].join('\n'),
336	  });
337	  log(`${files.length} capture file(s), ${runs.runs.length} run(s), ${queue.records.length} closed item(s) `
338	    + `and ${prs.prs.length} merged PR(s) folded — `
339	    + `${pr.reused ? 'updated' : 'opened'} PR ${pr.number !== null ? `#${pr.number}` : `on ${pr.branch}`}`
340	    + `${pr.merged ? ' (landed)' : pr.delivery === 'review' ? ' (left for review)' : ''}`);
341	}
