1	// The queue's repair rules (docs/PRINCIPLES.md) — the recovery that needs
2	// judgment or a longer horizon than the run's own deterministic label mechanics. Each rule is
3	// pure, returning the items it claims plus the comment it would post; the
4	// scheduler run is the only I/O shell over them.
5	//
6	// REPAIR IS A FALLBACK (owner, 2026-09-06). Every rule below repairs something
7	// that already went wrong — a label swap that tore, a session that died, a park
8	// nobody answered, a terminal nobody closed — and the healthy flow of a task never
9	// passes through here: an item the machinery handled correctly is settled by
10	// whoever handled it, before any of this runs. So a new rule here is a claim that a
11	// failure mode exists and that nothing nearer to it can close it out; the
12	// alternative to writing one is usually fixing the flow that left the mess.
13	//
14	// AND IT ONLY EVER READS OPEN ITEMS. An item somebody closed is finished, park
15	// label and all: a person ending a park by closing its issue is an answer, not a
16	// state to repair, and nothing here reopens, re-labels or re-nags one.
17	//
18	// What is NOT here: the executing-leash reclaim, which is a deterministic label
19	// rule the run applies directly. Recovery still happens once, in one place per
20	// rule, in code, and never as a sweep inside a session that is executing
21	// something.
22	
23	import { taskPeriodMs } from '../items/anchors.mjs';
24	import { isScheduledTask } from '../contract/task-contract.mjs';
25	import {
26	  STATUS_READY, STATUS_RUNNING_AGENT, requeueHint, STATUS_BLOCKED, STATUS_DONE,
27	  STATUS_REJECTED, ASKED_FOR_ORIGINS, STATUS_NEEDS_HUMAN_FAILURE,
28	} from '../../public/task-constants.mjs';
29	import {
30	  isStatus, statusOf, isParked, parkKindOf, originOf, isStandingItem, parseWorkItemTitle,
31	  parseWorkItemBody, taskIdFromPath,
32	} from '../../public/work-item-grammar.mjs';
33	
34	export const AGENT_LEASH_MS = 3 * 3600e3;
35	// The park kinds a later clean run ANSWERS. Both name a broken thing — a failure is
36	// "read the trace", an action is "the token is missing" — so a run that converged
37	// clean is proof it is not broken any more. `approval` and `decision` are absent on
38	// purpose: those parks carry content a person still owes an answer to (an approval
39	// park typically holds an open PR), and a later success does not answer them. What
40	// DOES answer an approval park is that pull request resolving — rule G.
41	export const SUPERSEDABLE_PARKS = Object.freeze(['failure', 'action']);
42	export const STALE_READY_PERIODS = 2;
43	// How long a terminal status may stand on an open issue before rule H reads it as
44	// torn rather than in flight. A converge writes the label and the close within
45	// seconds of each other, so an hour is far past any live transition.
46	export const TERMINAL_OPEN_MS = 3600e3;
47	export const STUCK_BLOCKED_MS = 2 * 86400e3;
48	
49	const ms = (t) => (t == null ? null : new Date(t).getTime());
50	const idle = (item, now) => ms(now) - (ms(item.updated_at) ?? ms(item.created_at) ?? ms(now));
51	
52	// Rule A — STALE READY. An item no executor picked for ~2 of its own periods comes
53	// out of the queue as a human's problem. The period is read from the task's
54	// declared cadence term at HEAD (no title parsing — that was the slot grammar); an
55	// item whose task is unknown, or keeps no cadence, falls back to a day.
56	//
57	// WHICH TASK, on a marked issue: its title is the person's own, so the id comes
58	// from the worker path its machine block names — without that fallback a request
59	// nobody picks up would sit ready forever, the one item class no rule here covers.
60	export function staleReadyItems(open = [], now, { periodFor = () => null, factor = STALE_READY_PERIODS } = {}) {
61	  return open.filter((i) => {
62	    if (!isStatus(i, STATUS_READY)) return false;
63	    const parsed = parseWorkItemTitle(i.title) ?? taskIdFromPath(parseWorkItemBody(i.body).taskPath);
64	    if (!parsed) return false;
65	    const per = periodFor(`${parsed.pack}/${parsed.task}`) ?? 86400e3;
66	    // `readySince` is the item's last touch: every transition into ready is a
67	    // label write, so an item that has sat unread since then has not been touched.
68	    return idle(i, now) >= factor * per;
69	  });
70	}
71	
72	export const staleReadyComment = (item) => {
73	  const p = parseWorkItemTitle(item.title) ?? taskIdFromPath(parseWorkItemBody(item.body).taskPath);
74	  return `This work item for ${p ? `${p.pack}/${p.task}` : 'this task'} has sat \`${STATUS_READY}\` for over ~${STALE_READY_PERIODS} of its scheduling periods `
75	    + 'without an executor picking it up. Parking it for a human and taking it out of the queue.';
76	};
77	
78	// Rule B — THE AGENT LEASH. An item whose agent has not MOVED in ~3h means the
79	// session died or wedged. The hand-off comment names which session, so the
80	// escalation can say so.
81	//
82	// A beating session is judged on its progress, not its punctuality. `progressAt`
83	// answers when the beat's note last changed, so a run that keeps beating the same
84	// note is reclaimed on the same leash as one that went silent — otherwise the beat
85	// would buy immortality, and the signal would degrade from "work is happening" to
86	// "a process is alive". An item with no beats answers null and is judged the old
87	// way, off the issue clock: that is every item filed before the beat existed, and
88	// the assumption there is stated rather than discovered — a legitimately
89	// longer-running agent must touch its item, or it is declared dead.
90	export function deadAgentItems(open = [], now, { leashMs = AGENT_LEASH_MS, progressAt = () => null } = {}) {
91	  return open.filter((i) => {
92	    if (!isStatus(i, STATUS_RUNNING_AGENT)) return false;
93	    const moved = progressAt(i);
94	    const since = moved ? ms(now) - ms(moved) : idle(i, now);
95	    return since >= leashMs;
96	  });
97	}
98	
99	export const deadAgentComment = (item, sessionNote = null, { wedged = false } = {}) =>
100	  `This work item has carried \`${STATUS_RUNNING_AGENT}\` for over ${Math.round(AGENT_LEASH_MS / 3600e3)}h `
101	  + `${wedged ? 'without the work moving — the session kept beating, but every beat said the same thing' : 'with no activity'} — `
102	  + `the agent session that claimed it${sessionNote ? ` (${sessionNote})` : ''} never converged it. Parking it for a human.`;
103	
104	// Rule C — THE STUCK-DEPENDENCY SWEEP (F14). The stale-ready rule cannot see this
105	// at all: a blocked item is never ready. So a blocked item whose blockers have not
106	// resolved past the bound gets an escalation COMMENT and nothing else — labels
107	// untouched, so the item still proceeds by itself the moment its blockers resolve,
108	// and a human who decides it is dead closes it by hand.
109	//
110	// THE BOUND IS IDLENESS, NEVER AGE (owner, 2026-09-22). Measured from `created_at`
111	// the rule had no terminating condition: once an item crossed two days it matched
112	// on every pass for the rest of its life, and the sweep carried no once-only guard,
113	// so a chain link waiting on a long review collected one comment per run forever.
114	// Measured from the item's own last activity, the comment this rule posts resets
115	// the clock it is read from, which makes the comment its own guard: the next one is
116	// two idle days away, and a person or a run touching the item pushes it further out.
117	//
118	// Sleeping items (a future `Not-before`, blockers closed) never match: waiting for
119	// a time is the mechanism working.
120	export function stuckBlockedItems(open = [], now, { stateOf = () => null, boundMs = STUCK_BLOCKED_MS } = {}) {
121	  return open.filter((i) => {
122	    if (!isStatus(i, STATUS_BLOCKED)) return false;
123	    const { blockedBy } = parseWorkItemBody(i.body);
124	    if (!blockedBy.length) return false;
125	    if (blockedBy.every((n) => stateOf(n) === 'closed')) return false;
126	    return idle(i, now) >= boundMs;
127	  });
