173	// is its own work being done, which is rule G's `Ends-when` or a person.
174	//
175	// `doneAfter(taskId, since)` answers "the newest item for this task that converged
176	// done strictly after `since`", or null. The worker supplies it from the closed
177	// half of the queue; the rule stays pure and knows nothing about how it is read.
178	export function supersededItems(open = [], { doneAfter = () => null } = {}) {
179	  return open.filter((item) => {
180	    if (!isParked(item)) return false;
181	    if (ASKED_FOR_ORIGINS.includes(originOf(item))) return false;
182	    if (!SUPERSEDABLE_PARKS.includes(parkKindOf(item))) return false;
183	    const p = parseWorkItemTitle(item.title) ?? taskIdFromPath(parseWorkItemBody(item.body).taskPath);
184	    if (!p) return false;
185	    return doneAfter(`${p.pack}/${p.task}`, item.updated_at ?? item.created_at) != null;
186	  });
