213	// the whole queue. An item naming NO path is left alone for the same reason — that is
214	// the malformed shape `statelessItems` and the executor own, not a verdict about HEAD.
215	export const taskPathIndex = (tasks = []) => new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t.taskPath]));
