217	export function orphanedParkItems(open = [], { tasks = [] } = {}) {
218	  if (!tasks.length) return [];
219	  const headPath = taskPathIndex(tasks);
220	  return open.filter((item) => {
221	    if (!isParked(item)) return false;
222	    const { taskPath } = parseWorkItemBody(item.body);
223	    const p = parseWorkItemTitle(item.title) ?? taskIdFromPath(taskPath);
224	    if (!p) return false;
225	    const at = headPath.get(`${p.pack}/${p.task}`);
226	    if (at === undefined) return true;
227	    return !!taskPath && at !== taskPath;
228	  });
229	}
