231	// Two causes, two sentences, because the reader's next move differs: a retired task is
232	// nothing to chase, a relocated one already has a live occurrence somewhere.
233	export const orphanedParkComment = (id, headPath = null) => (headPath
234	  ? `This item names \`${id}\` at a path it no longer lives at — the pack was renamed since the item was filed, `
235	    + `and the task is at \`${headPath}\` now. An item's stored path is never rewritten, so this one can never run. `
236	    + 'Closing it obsolete; the scheduler files a fresh occurrence at the current path.'
237	  : `\`${id}\` is not a task this repo carries at HEAD — the pack may be undeclared, or the task retired. `
238	    + 'This item is parked on work that cannot run again, so it closes `task:status:rejected` rather than '
239	    + 'waiting for an answer that would change nothing.');
