241	// Rule G — THE ENDED PARK (#1468). A park states what a person owes; nothing watched
242	// for that debt being PAID. An approval park in particular holds an open pull
243	// request, which is why rule E excludes it — a later clean run does not answer it —
244	// so once the pull request merged the item sat open until somebody read it.
245	//
246	// `Ends-when: #<n> closed` is the item's own answer to "what would end this", and
247	// the resolution of that target is the verdict:
248	//
249	//   merged   → the work this park was holding LANDED, so the item is `done`
250	//   closed   → the task was REJECTED, so the item is `rejected`
251	//
252	// The distinction is the whole point of reading merged-ness rather than state: a
253	// park closed as `rejected` when its pull request in fact merged would report a
254	// delivered run as one that never happened.
255	//
256	// EITHER OUTCOME ENDS THE ITEM, and the shell closes the issue on both. A person
257	// who closed the pull request unmerged has already said what happens to this run;
258	// an item left open under that verdict is the queue asking them to say it twice.
259	//
260	// `resolutionOf(n)` answers `'merged' | 'closed' | null` — null for open, unknown,
261	// or unreadable, all of which mean the park stands. Only parked items: a live item
262	// is the machinery working, and an item still with an agent has not ended anything.
263	export function endedParkItems(open = [], { resolutionOf = () => null } = {}) {
264	  return open.filter((item) => {
265	    if (!isParked(item)) return false;
266	    const { endsWhen } = parseWorkItemBody(item.body);
267	    if (endsWhen == null) return false;
268	    return resolutionOf(endsWhen) != null;
269	  });
270	}
271	
272	export const endedParkComment = (target, resolution) => (resolution === 'merged'
273	  ? `#${target} merged, which is what this item was parked waiting for. Closing it \`${STATUS_DONE}\` — `
274	    + 'the work landed and there is nothing left for anyone to do here.'
275	  : `#${target} was closed without merging, which ends what this item was parked waiting for. `
276	    + `Closing it \`${STATUS_REJECTED}\` — nothing landed, so if the work is still wanted, re-queue it (${requeueHint}).`);
277	
278	// The period of a task, for rule A — read from the cadence term its declaration
279	// at HEAD states; null (a day, in rule A) for a task that keeps none.
280	export const periodForTasks = (tasks = []) => {
281	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
282	  return (id) => taskPeriodMs(byId.get(id)?.decl);
283	};
284	
285	// Rule H — THE UNCLOSED TERMINAL (#1526). A terminal status says the item is over:
286	// `done` means nothing is left for anyone to act on, `rejected` that nothing will
287	// happen. Every writer closes the issue in the same breath — so an open one wearing
288	// one is a transition that TORE, or a session that improvised its converge by hand
289	// and stopped at the label (#1220, #1265). Either way the item then reads as
290	// finished to every rule here and to the leash, while sitting open in the queue's
291	// count forever: the one state nothing else recovers.
292	//
293	// The close is the whole of the repair, and the outcome is the status's own — a
294	// `done` item closes `completed`, a `rejected` one `not_planned`. Nothing is
295	// relabelled: the status was already right, it was the close that never happened.
296	//
297	// TWO GUARDS, because this rule's premise is a torn write and a write in flight
298	// looks identical (#1104). The clock is the first: an item still inside
299	// `TERMINAL_OPEN_MS` is a converge that may simply not have reached its close call
300	// yet. The second is the worker's, a fresh read of the item immediately before
301	// acting — the snapshot this runs on is seconds old, and by now the converge may
302	// have finished on its own.
303	export function unclosedTerminalItems(open = [], now, { boundMs = TERMINAL_OPEN_MS } = {}) {
304	  return open.filter((item) => {
305	    if (item.state !== 'open') return false;
306	    const status = statusOf(item);
307	    if (status !== STATUS_DONE && status !== STATUS_REJECTED) return false;
308	    return idle(item, now) >= boundMs;
309	  });
310	}
311	
312	export const unclosedTerminalComment = (status) => (status === STATUS_DONE
313	  ? `This item carries \`${STATUS_DONE}\` — its run finished and nothing is left for anyone to act on — but it was never closed, `
314	    + 'so it has been sitting in the open queue looking like live work. Closing it, which is all the terminal was missing.'
315	  : `This item carries \`${STATUS_REJECTED}\` — it was taken out of the queue — but it was never closed, `
316	    + `so it has been sitting open looking like live work. Closing it; if the work is still wanted, re-queue it (${requeueHint}).`);
317	
318	// Rule I — THE ABANDONED FAILURE PARK (#1785). A `failure` park is the one kind that
319	// HOLDS THE TASK'S LANE (`isBlockingPark`, honoured in `planSchedulerRun` job 1), and
320	// that is what makes it the one kind with no terminating condition of its own. Rule E
321	// answers a park with a later clean run of the same task — but while this park stands
322	// no further occurrence is ever filed, so that answer can never arrive. The other
323	// three kinds all have one: `action` does not hold the lane, so later runs happen and
324	// rule E fires; `approval` ends when its pull request resolves (rule G); `decision` is
325	// a choice a person owes. `failure` alone sits forever
326	// (missingbulb/TLDR#275: parked by the agent leash, untouched for over three weeks).
327	//
328	// So the CLOCK is the answer here, and closing the item is the whole of it: the lane
329	// is released, the scheduler files a fresh occurrence, and a fault that is still there
330	// re-parks against a run from this week rather than leaving a month-old trace to read.
331	//
332	// STANDING ONLY, and structurally (`isStandingItem` against HEAD's declaration): the
333	// warrant is that this item is a FUNGIBLE OCCURRENCE, which is exactly what a
334	// qualified item, a `request` task's item and an adopted issue are not — each is
335	// somebody's own work, and no clock answers those. A task absent from HEAD states no
336	// trigger and so is not standing either; that item is rule F's.
337	export const ABANDONED_PARK_MS = 10 * 86400e3;
338	
339	export function abandonedParkItems(open = [], now, { scheduledFor = () => null, boundMs = ABANDONED_PARK_MS } = {}) {
340	  return open.filter((item) => {
341	    if (statusOf(item) !== STATUS_NEEDS_HUMAN_FAILURE) return false;
342	    const p = parseWorkItemTitle(item.title);
343	    if (!p) return false;
344	    if (!isStandingItem(item, scheduledFor(`${p.pack}/${p.task}`))) return false;
345	    return idle(item, now) >= boundMs;
346	  });
347	}
348	
349	export const abandonedParkComment = () =>
350	  `Nothing has touched this park in over ${Math.round(ABANDONED_PARK_MS / 86400e3)} days. Leaving it standing does not preserve the `
351	  + 'report — nobody is going to read it now, and where the task declares `last-run-not-failed` it also keeps the task from '
352	  + 'running again at all. A later clean run is '
353	  + `what would otherwise have closed this. Closing it \`${STATUS_REJECTED}\`: the next scheduled occurrence runs, and if the `
354	  + `fault is still there it parks again against a trace worth reading. If you were part-way through diagnosing it, re-queue it (${requeueHint}).`;
355	
356	// Whether a task at HEAD is on the schedule, for rule I's standing test — null for a
357	// task this repo no longer carries, which reads as not standing.
358	export const scheduledForTasks = (tasks = []) => {
359	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
360	  return (id) => (byId.has(id) ? isScheduledTask(byId.get(id).decl) : null);
361	};
362	
363	// The closed half of the queue, indexed for rule E: the task's newest run that
364	// converged clean AFTER a given moment, or null. Built from the items the run has
365	// already listed, so it costs no read of its own.
366	export function doneRunLookup(done = []) {
367	  const byTask = new Map();
368	  for (const d of done) {
369	    const p = parseWorkItemTitle(d.title) ?? taskIdFromPath(parseWorkItemBody(d.body).taskPath);
370	    if (!p) continue;
371	    const id = `${p.pack}/${p.task}`;
372	    if (!byTask.has(id)) byTask.set(id, []);
373	    byTask.get(id).push(d);
374	  }
375	  return (id, since) => {
376	    const at = new Date(since).getTime();
377	    const runs = (byTask.get(id) ?? [])
378	      .filter((d) => new Date(d.closed_at ?? d.updated_at).getTime() > at)
379	      .sort((a, b) => new Date(a.closed_at ?? a.updated_at) - new Date(b.closed_at ?? b.updated_at));
380	    return runs.at(-1) ?? null;
381	  };
382	}
