  1	// THE HOLDER'S SIGN OF LIFE (docs/PRINCIPLES.md).
  2	// A work step is the work: it may legitimately run for hours, and while it does
  3	// the item goes dark and the executing leash cannot tell it from a dead runner.
  4	// So the executor comments on its own item at a fixed interval, and the scheduler run's
  5	// reclaim measures silence from THAT rather than from a run-length cap.
  6	//
  7	// One mechanism, two things it buys: long work becomes legal (the run cap that
  8	// held the leash arithmetic together retires), and the item's timeline stays live
  9	// through work nobody can otherwise see.
 10	//
 11	// WHAT COUNTS AS ACTIVITY IS THE HOLDER'S OWN SIGNAL, never the issue's
 12	// `updated_at` (#924). Any comment moves `updated_at` — including one written by
 13	// an executor that LOST the claim race and let go — so a clock read off the issue
 14	// defers the reclaim of an item nobody is working on. The struck claims a lost
 15	// race leaves behind carry the episode marker, and are excluded here for exactly
 16	// that reason.
 17	
 18	import { nowMs } from '../world/clock.mjs';
 19	
 20	import { CLAIM_MARKER, EPISODE_MARKER, PROGRESS_HEADING } from '../../public/task-constants.mjs';
 21	import { parseProgressLines, withSection } from '../../public/work-item-grammar.mjs';
 22	
 23	export const HEARTBEAT_MARKER = '<!-- claudinite-heartbeat -->';
 24	
 25	// Comfortably inside the executing leash (60m), so a live holder is never
 26	// reclaimed on a single missed beat: it takes four in a row.
 27	export const HEARTBEAT_MS = 15 * 60e3;
 28	
 29	export const heartbeatComment = ({ executor, at, minutes }) =>
 30	  `${HEARTBEAT_MARKER}\nStill working: executor \`${executor}\`, ${minutes} minute(s) in, at ${at}.`;
 31	
 32	// When the current holder last said anything — the newest live claim or heartbeat.
 33	// A struck comment is not a signal: it says its author let the item go.
 34	export function lastLivenessAt(comments = []) {
 35	  const live = comments.filter((c) => {
 36	    const body = c.body ?? '';
 37	    if (body.includes(EPISODE_MARKER)) return false;
 38	    return body.includes(CLAIM_MARKER) || body.includes(HEARTBEAT_MARKER);
 39	  });
 40	  const times = live.map((c) => new Date(c.created_at ?? 0).getTime()).filter((t) => t > 0);
 41	  return times.length ? new Date(Math.max(...times)).toISOString() : null;
 42	}
 43	
 44	// The timer the beat hangs on. A seam for the same reason the clock beside it is
 45	// one: a harness that runs a work step in virtual minutes has no wall clock for a
 46	// real interval to fire against, so the beats would be missing from exactly the
 47	// timeline the executing leash is reading.
 48	export const realTimers = Object.freeze({
 49	  setInterval: (fn, ms) => setInterval(fn, ms),
 50	  clearInterval: (id) => clearInterval(id),
 51	});
 52	
 53	// Run `work` while beating. The beat is FAIL-SOFT — a comment that does not post
 54	// must never sink a run that is otherwise fine — but never silent: a run whose
 55	// heartbeat failed is one the leash may reclaim underneath it, and the log line is
 56	// the only way to tell that from a run that simply finished quickly.
 57	export async function withHeartbeat(work, { beat, intervalMs = HEARTBEAT_MS, log = () => {}, timers = realTimers }) {
 58	  if (!beat || !(intervalMs > 0)) return work();
 59	  const startedAt = nowMs();
 60	  let beats = 0;
 61	  const timer = timers.setInterval(() => {
 62	    const minutes = Math.round((nowMs() - startedAt) / 60e3);
 63	    Promise.resolve()
 64	      .then(() => beat(minutes))
 65	      .then(() => { beats += 1; })
 66	      .catch((e) => log(`! heartbeat ${beats + 1} did not post (${e?.message ?? e}) — the leash may reclaim this item mid-work`));
 67	  }, intervalMs);
 68	  // `unref` so a beat pending at exit cannot hold the process open past its work.
 69	  timer?.unref?.();
 70	  try {
 71	    return await work();
 72	  } finally {
 73	    timers.clearInterval(timer);
 74	    const minutes = Math.round((nowMs() - startedAt) / 60e3);
 75	    if (beats) log(`- work step ran ${minutes} minute(s) and beat ${beats} time(s)`);
 76	  }
 77	}
 78	
 79	// --- the agent phase's beat -----------------------------------------------------
 80	
 81	// The executor's beat above stops at the hand-off: its process exits, and an agent
 82	// session then holds the item for as long as its own work takes. Nothing beat there,
 83	// so the agent leash had only the issue's `updated_at` to read — the very clock this
 84	// file exists to stop trusting.
 85	//
 86	// The session cannot beat the way the executor does. It has no process of its own to
 87	// hang a timer on, and a scheduled wake reaches it between tool results rather than
 88	// during one, so a beat that must fire inside a long call cannot be promised. What it
 89	// can promise is a beat at each checkpoint its own work already has. Hence the
 90	// interval below is a CEILING the session is asked to stay under, not a timer.
 91	export const AGENT_BEAT_MS = 45 * 60e3;
 92	
 93	// Carries the same marker as the executor's beat, so `lastLivenessAt` counts an agent
 94	// beat as the holder's own signal without knowing which phase wrote it.
 95	export const agentBeatComment = ({ session, at, note }) =>
 96	  `${HEARTBEAT_MARKER}\nStill working${session ? `: ${session}` : ''} — ${note}, at ${at}.`;
 97	
 98	// One progress line, appended to the item body's own `### Progress` section.
 99	//
100	// APPENDED, not replaced: the body is the only surface a run can grow in place,
101	// because the GitHub toolset a session has offers comment creation and no comment
102	// edit. So the body carries the account and the beats carry the trail — the same
103	// split the standing trackers use, arrived at from the opposite direction.
104	export const withProgress = (body, line) =>
105	  withSection(body, PROGRESS_HEADING, [...parseProgressLines(body), line]);
106	
107	// WHEN THE WORK LAST MOVED, as distinct from when the holder last spoke.
108	//
109	// A beat resets the leash, so a session that beats punctually while wedged would
110	// never be reclaimed — the signal degrades from "work is happening" to "a process is
111	// alive", which is the failure the leash exists to catch. The beat already carries
112	// what separates them: its note is the progress (`9/15 groups triaged`), so a run of
113	// beats all saying the same thing is a wedged run, however punctual.
114	//
115	// Returns when the note last CHANGED — the oldest beat of the trailing run that all
116	// carry the newest one's note — or null when the item has no beats at all, which is
117	// the caller's signal to judge it the old way rather than to call it dead.
118	export function lastProgressAt(comments = []) {
119	  const beats = comments
120	    .filter((c) => (c.body ?? '').includes(HEARTBEAT_MARKER) && !(c.body ?? '').includes(EPISODE_MARKER))
121	    .map((c) => ({ at: new Date(c.created_at ?? 0).getTime(), note: beatNote(c.body ?? '') }))
122	    .filter((b) => b.at > 0)
123	    .sort((a, b) => a.at - b.at);
124	  if (!beats.length) return null;
125	  const newest = beats[beats.length - 1].note;
126	  let i = beats.length - 1;
127	  while (i > 0 && beats[i - 1].note === newest) i -= 1;
128	  return new Date(beats[i].at).toISOString();
129	}
130	
131	// The part of a beat that says where the work got to. Read off the comment rather
132	// than kept beside it: the beat a session posts through its own GitHub tools is the
133	// only copy, so the note has to survive the round trip through the rendered body.
134	const beatNote = (body) => {
135	  const line = body.split('\n').find((l) => l.startsWith('Still working')) ?? '';
136	  return (line.match(/ — (.*), at [^,]*\.$/)?.[1] ?? line).trim();
137	};
138	// The machine-readable records a task's execution leaves in an Actions log,
139	// and the parsers that read them back.
140	//
141	// THE SINGLE HOME OF THE RECORD FORMATS. Every line shape the machinery prints
142	// about its own work is rendered and parsed here — the two execution families
143	// below, and the per-run cost record at the foot of the file. A renderer that
144	// lived apart from its parser is how a format drifts from itself.
145	//
146	// TWO FAMILIES, ONE OF THEM HISTORICAL. `claudinite-task-run` was the SLOT
147	// scheduler's own line, one per due task per run; the slot scheduler is retired
148	// (#974) and nothing writes that line any more. The parser stays, and only the
149	// parser: Actions logs from before the retirement are still inside their retention
150	// window, and the usage fold still counts them. Nothing new should be taught this
151	// shape — `claudinite-task-exec` below is the live record.
152	//
153	// The counts these produce are exact within the Actions log retention window, and
154	// that is worth stating next to the capture-derived counts they land beside.
155	
156	import { nowMs } from '../world/clock.mjs';
157	
158	// The five things a slot scheduler run could do with a due task. One name per
159	// outcome, used verbatim as the counter key in the aggregate, so there is no
160	// mapping table between "what the run said" and "what the fold counted" to drift.
161	export const TASK_RUN_OUTCOMES = Object.freeze([
162	  // A dispatch issue was filed: an agent session ran this task.
163	  'agent',
164	  // The task ran with NO agent — an `agent_model: none` task (code-work is the
165	  // whole task), or an agentful one whose code-work requested no agent phase.
166	  // Kebab, not the declaration field's `code_work`: this word is a WIRE token,
167	  // constrained to the line format's `[a-z-]+` charset.
168	  'code-work',
169	  // Due, but its precondition said there was nothing to do.
170	  'skipped',
171	  // Its code-work failed; the run converged the task to a needs-human issue.
172	  'failed',
173	  // Due and past its precondition, but no NEW agent run started: this slot was
174	  // already dispatched (exactly-once), an earlier dispatch is still open
175	  // (at-most-one-open), or another task claimed the run exclusively. Work that
176	  // was wanted and did not happen this run.
177	  'deferred',
178	]);
179	
180	// An empty per-task counter row — every outcome present, zeros included, so a row's
181	// shape never depends on which outcomes a task happened to hit.
182	export const emptyTaskRun = () => Object.fromEntries(TASK_RUN_OUTCOMES.map((o) => [o, 0]));
183	
184	// The line format. `v1` is the shape's version: a reader that meets a `v2` line
185	// knows it is looking at something it was not written for, instead of silently
186	// half-parsing it.
187	export const TASK_RUN_TAG = 'claudinite-task-run';
188	const VERSION = 'v1';
189	
190	// Actions stamps every log line with its own timestamp before the command's output,
191	// so the parse tolerates that prefix — without it, a fetched log reads as having
192	// printed nothing at all.
193	const LINE_RE = new RegExp(
194	  String.raw`^(?:\S+\s+)?${TASK_RUN_TAG} ${VERSION} (\S+)/(\S+) \[(\S+)\] ([a-z-]+)\s*$`,
195	);
196	
197	// One line → `{ pack, task, slotId, outcome }`, or null for anything that is not a
198	// record of this version. Deliberately strict: an unknown outcome word is NOT a
199	// record, because counting it would mint a counter key nothing ever reads.
200	export function parseTaskRun(line) {
201	  const m = LINE_RE.exec(line);
202	  if (!m) return null;
203	  const [, pack, task, slotId, outcome] = m;
204	  if (!TASK_RUN_OUTCOMES.includes(outcome)) return null;
205	  return { pack, task, slotId, outcome };
206	}
207	
208	// Every record in one job log. The log is the whole job's output — this picks its
209	// own lines out of it and ignores everything else.
210	export function parseTaskRuns(text) {
211	  const out = [];
212	  for (const line of String(text ?? '').split('\n')) {
213	    const rec = parseTaskRun(line);
214	    if (rec) out.push(rec);
215	  }
216	  return out;
217	}
218	
219	// --- executor-side execution records ------------------------------------------
220	// The historical records above say what the retired slot scheduler DID with a due
221	// task; these record what an EXECUTOR SESSION did with the work it ran. Printed by executor-side code
222	// (resolve-dispatch on a terminal verdict, record-exec.mjs at convergence), they
223	// land in the session transcript, ride to the conversation-logs branch with the
224	// executor's capture step, and the usage fold counts them deterministically —
225	// the "task statuses out of the conversation logs" half of the census (owner,
226	// 2026-08-06). Same single-home rule: renderer and parser sit here together.
227	
228	export const TASK_EXEC_STATUSES = Object.freeze([
229	  // The dispatch ran to completion within its ceiling; the issue was closed.
230	  'success',
231	  // The run failed (task failure or ceiling violation); the item parked.
232	  'failed',
233	  // The dispatch named a task file the repo no longer carries — retired, its pack
234	  // undeclared, or the item's stored path left behind by a pack rename — and the
235	  // executor closed the issue as obsolete. Not a failure.
236	  'task-gone',
237	  // The dispatch was malformed (bad path shape, unparseable declaration) and was
238	  // parked without running.
239	  'invalid',
240	]);
241	
242	export const TASK_EXEC_TAG = 'claudinite-task-exec';
243	
244	// The bracketed field is the OCCURRENCE'S IDENTITY, which is a different thing under
245	// each dispatch mechanism: a slot id (`d2026-08-06`) where slots decide what runs, and
246	// the work item's issue number (`#867`) where the queue does. `slotId` keeps its name
247	// for the fielded records that already carry one; what it must never become is a
248	// constant, since it is the only join from a record back to the work it describes.
249	export const renderTaskExec = ({ pack, task, slotId, status }) =>
250	  `${TASK_EXEC_TAG} ${VERSION} ${pack}/${task} [${slotId ?? 'unknown'}] ${status}`;
251	
252	const EXEC_LINE_RE = new RegExp(
253	  String.raw`(?:^|\s)${TASK_EXEC_TAG} ${VERSION} (\S+)/(\S+) \[(\S+)\] ([a-z-]+)\s*$`,
254	);
255	
256	export function parseTaskExec(line) {
257	  const m = EXEC_LINE_RE.exec(line);
258	  if (!m) return null;
259	  const [, pack, task, slotId, status] = m;
260	  if (!TASK_EXEC_STATUSES.includes(status)) return null;
261	  return { pack, task, slotId, status };
262	}
263	
264	export function parseTaskExecs(text) {
265	  const out = [];
266	  for (const line of String(text ?? '').split('\n')) {
267	    const rec = parseTaskExec(line);
268	    if (rec) out.push(rec);
269	  }
270	  return out;
271	}
272	
273	// --- what one run of the machinery cost ----------------------------------------
274	// The two records above say what happened to a task; this says what the RUN that
275	// carried it spent — the API calls it made and the wall milliseconds each of its
276	// phases took. Together with the billed minutes read off the jobs listing, that is
277	// the whole cost side of the machinery's own usage file
278	// (packs/claudinite-tasks/tasks/tasks-usage-fold/README.md).
279	//
280	// WHERE IT IS READ FROM, and why the shape carries the run id. A scheduler tick
281	// owns no work item, so its record is only ever in the job log; an executor run
282	// writes its record onto every item it settles, beside the execution record above,
283	// because Actions logs expire and the item does not. One run therefore leaves
284	// SEVERAL copies of its record, each a snapshot of counters that only ever grow —
285	// so a reader keys on the run id and takes the largest it saw, which is the run's
286	// total as of its last item.
287	//
288	// WHICH MAKES EVERY FIGURE A FLOOR, and deliberately so. A stamp is written DURING
289	// the convergence it is part of, so an item's own converge time is never in its own
290	// stamp — it arrives in the next item's, and the last item's is simply never
291	// counted. The complete reading is the one the run prints into its log at the end.
292	// Under-counting is one-directional by construction, like every other figure in
293	// the file these records feed.
294	
295	export const RUN_COST_TAG = 'claudinite-run-cost';
296	
297	// The two workflows a record can describe. The same words the usage aggregates
298	// count runs under, so a record and the row it lands in cannot be spelled apart.
299	export const RUN_WORKFLOWS = Object.freeze(['scheduler', 'executor']);
300	
301	// The phases each workflow times, in the order they happen. A phase word is a WIRE
302	// token like the outcome words above, constrained to the line format's `[a-z-]+`
303	// charset — `code-work` is the same token the task-run vocabulary already spells.
304	export const RUN_PHASES = Object.freeze({
305	  scheduler: Object.freeze(['list', 'ask', 'repair', 'drain']),
306	  executor: Object.freeze(['pick', 'claim', 'code-work', 'hand-off', 'converge']),
307	});
308	
309	// Every phase word, once — the vocabulary a reader expands a record against.
310	export const ALL_RUN_PHASES = Object.freeze(
311	  [...new Set([...RUN_PHASES.scheduler, ...RUN_PHASES.executor])],
312	);
313	
314	// A phase that did not happen leaves NO key rather than a zero, and an `apiCalls`
315	// the printer could not read leaves the `calls=` field off entirely: this file's
316	// whole discipline is that unknown is a state of its own, and a run that never
317	// reached its hand-off is not a run whose hand-off took no time.
318	export function renderRunCost({ workflow, runId, apiCalls = null, phaseMs = {} }) {
319	  const phases = ALL_RUN_PHASES
320	    .filter((p) => Number.isFinite(phaseMs?.[p]))
321	    .map((p) => `${p}=${Math.round(phaseMs[p])}`);
322	  return [
323	    `${RUN_COST_TAG} ${VERSION} ${workflow} [${runId ?? 'unknown'}]`,
324	    ...(Number.isFinite(apiCalls) ? [`calls=${apiCalls}`] : []),
325	    ...phases,
326	  ].join(' ');
327	}
328	
329	// Actions stamps its own timestamp before the command's output, and an executor's
330	// copy rides inside a fenced block in an issue comment — so the head of the line
331	// is tolerated exactly as the two parsers above tolerate it.
332	const COST_LINE_RE = new RegExp(
333	  String.raw`(?:^|\s)${RUN_COST_TAG} ${VERSION} ([a-z-]+) \[(\S+)\]((?: [a-z-]+=\d+)*)\s*$`,
334	);
335	
336	// One line → `{ workflow, runId, apiCalls, phaseMs }`, or null for anything that is
337	// not a record of this version. An unknown WORKFLOW word rejects the whole line —
338	// there is no row to count it under. An unknown PHASE word is dropped and the rest
339	// of the record stands, which is what lets a record printed by a newer engine still
340	// be read for the phases this one knows.
341	export function parseRunCost(line) {
342	  const m = COST_LINE_RE.exec(line);
343	  if (!m) return null;
344	  const [, workflow, runId, fields] = m;
345	  if (!RUN_WORKFLOWS.includes(workflow)) return null;
346	  let apiCalls = null;
347	  const phaseMs = {};
348	  for (const field of fields.trim().split(/\s+/).filter(Boolean)) {
349	    const [name, value] = field.split('=');
350	    const n = Number(value);
351	    if (name === 'calls') apiCalls = n;
352	    else if (ALL_RUN_PHASES.includes(name)) phaseMs[name] = n;
353	  }
354	  return { workflow, runId, apiCalls, phaseMs };
355	}
356	
357	export function parseRunCosts(text) {
358	  const out = [];
359	  for (const line of String(text ?? '').split('\n')) {
360	    const rec = parseRunCost(line);
361	    if (rec) out.push(rec);
362	  }
363	  return out;
364	}
365	
366	// The accumulator a run times itself with. `phase(name)` opens a phase and returns
367	// the function that closes it; re-opening a name ADDS to it, because the executor's
368	// loop passes through pick, claim and converge once per item and the record is the
369	// run's, not the item's.
370	//
371	// The clock comes through the world's port for the same reason every other reading
372	// of it does; `apiCalls` is a reader the caller supplies rather than an import,
373	// which keeps the REST paths out of this module. A caller that has no counter to
374	// offer leaves the field unread, and the record then carries no `calls=`.
375	export function startRunCost({ workflow, runId = null, apiCalls = () => null, now = nowMs }) {
376	  const phaseMs = {};
377	  return {
378	    phase(name) {
379	      const from = now();
380	      return () => { phaseMs[name] = (phaseMs[name] ?? 0) + (now() - from); };
381	    },
382	    // The record as it stands NOW — a snapshot, which is exactly what each of the
383	    // executor's several stamps is. Callers print it; nothing here writes anywhere.
384	    record() {
385	      const calls = apiCalls();
386	      return renderRunCost({ workflow, runId, apiCalls: calls, phaseMs });
387	    },
388	  };
389	}

