content.content:
1	// The `fleet` signal reader (docs/PRINCIPLES.md) — the members
2	// aggregate the CANON repo's fleet-scoped tasks (growth-promote,
3	// growth-discover-packs) decide from. A consumer cannot
4	// declare `fleet`; only the canon repo's scheduler builds it, over the fleet PAT
5	// (`FLEET_GITHUB_TOKEN` — the census's existing credential, the one token that
6	// can enumerate every repo the owner owns; the Action's default GITHUB_TOKEN sees
7	// only this repo). queue/signals.mjs invokes this ONLY when the picked task declares `fleet`, so
8	// an ordinary night pays nothing for the fleet enumeration.
9	//
10	// Pure over an injected `fleetGh` (the same `gh(path) -> { status, json }` shape
11	// the other collectors take), so the whole reader tests against a fake `gh` with
12	// no live GitHub — exactly like signals/index.mjs. The one place the real
13	// FLEET_GITHUB_TOKEN is read is `makeFleetGh`, at the I/O edge.
14	//
15	// This deliberately ports the retired central planner's per-member probes (the
16	// `fleetMembers` bundle the old central planner stamped on the home repo) into
17	// the per-repo scheduler, adapted for the `local/packs` rename (both roots
18	// accepted through the migration) and carrying each member's provenance stamp so
19	// the retire guard can read per-repo apply evidence.
20	
21	import { makeGh } from '../world/github.mjs';
22	import { packEntryId } from '../../../../engine/pack_loader/pack-registry.mjs';
23	// Local-pack roots, canonical first — a window commit touching either is a local
24	// -pack change (promote's trigger). Both are live until the Phase 4 cleanup drops
25	// the legacy dual root. One definition, shared with the per-repo probes.
26	import { LOCAL_PACK_ROOT } from '../world/git.mjs';
27	import { SETTINGS_FILE } from '../../../../engine/settings-file.mjs';
28	// The one definition of dormancy, shared with every other fleet reader: a second
29	// notion of it would sweep exactly the members that had already opted out. It is the
30	// scheduler's own parameter, so it is read from the pack that owns the scheduler.
31	import { isDormant } from '../contract/dormancy.mjs';
32	import { actionsEnv } from '../world/actions.mjs';
33	import { readCommit } from '../world/github.mjs';
34	
35	async function paged(gh, path) {
36	  const out = [];
37	  for (let page = 1; ; page += 1) {
38	    const sep = path.includes('?') ? '&' : '?';
39	    const { status, json } = await gh(`${path}${sep}per_page=100&page=${page}`);
40	    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
41	    out.push(...json);
42	    if (json.length < 100) break;
43	  }
44	  return out;
45	}
46	
47	// A repo mounts Claudinite iff it carries the tracked declaration file — the one
48	// membership signal every member has whatever its mount shape (the same test the
49	// census's isCovered uses: activePacks are read from it, so a mount marker with
50	// no declaration is a half-adoption that must classify as uncovered).
51	function parseChecks(contentB64) {
52	  try { return JSON.parse(Buffer.from(contentB64, 'base64').toString('utf8')); }
53	  catch { return null; }
54	}
55	
56	// The member's declared packs (BARE ids, either declaration form), each entry's
57	// config (id -> config, so home-only gates honor per-pack settings like the
58	// growth promote opt-out), the per-repo scheduling cutover marker, and the
59	// vendored-mount provenance stamp (retire's per-repo apply evidence).
60	function readDeclaration(checks) {
61	  const entries = Array.isArray(checks?.packs) ? checks.packs : [];
62	  const activePacks = entries.map((e) => packEntryId(e)).filter((id) => typeof id === 'string');
63	  const packConfigs = {};
64	  for (const e of entries) {
65	    if (e && typeof e === 'object' && typeof e.id === 'string' && e.config !== undefined) {
66	      packConfigs[packEntryId(e)] = e.config;
67	    }
68	  }
69	  const schedulesItself = checks?.taskScheduler !== undefined && checks?.taskScheduler !== null;
70	  const stamp = checks?.claudinite ?? null;
71	  return {
72	    dormant: isDormant(checks),
73	    activePacks,
74	    packConfigs,
75	    schedulesItself,
76	    stamp: stamp ? { updated: stamp.updated ?? null, ref: stamp.ref ?? null } : null,
77	  };
78	}
79	
80	// Did a default-branch commit in the window touch this member's local packs (the
81	// real promote trigger — a member that changed product code but not its local
82	// packs has nothing to lift up)? Scans only the window's commits (a handful) and
83	// stops at the first hit; a commit whose files can't be read contributes nothing.
84	async function localPacksChangedInWindow(gh, fullName, defaultBranch, sinceIso) {
85	  const list = await paged(gh, `/repos/${fullName}/commits?sha=${encodeURIComponent(defaultBranch)}&since=${sinceIso}`);
86	  for (const c of list) {
87	    if (!c?.sha) continue;
88	    const detail = await readCommit(gh, fullName, c.sha);
89	    const files = detail.status === 200 ? (detail.json?.files ?? []) : [];
90	    if (files.some((f) => typeof f.filename === 'string' && f.filename.startsWith(LOCAL_PACK_ROOT))) return true;
91	  }
92	  return false;
93	}
94	
95	// Build one member's record from its declaration plus the local-pack window scan.
96	// `sinceIso` bounds the window. Whether the member HAS local packs is not probed:
97	// adoption seeds `.claudinite/local/packs/<repo>/` and the nightly deliberately
98	// never re-seeds or removes it, so the answer was yes for every member and the
99	// probe was one contents read per member per collection. An undeclared repo is
100	// still skipped — it is not a member anything plans for.
101	async function buildMember(gh, repo, sinceIso) {
102	  const fullName = repo.full_name;
103	  const defaultBranch = repo.default_branch || 'main';
104	  const decl = readDeclaration(repo.checks);
105	  const localChanged = decl.activePacks.length
106	    ? await localPacksChangedInWindow(gh, fullName, defaultBranch, sinceIso)
107	    : false;
108	  return {
109	    repo: fullName,
110	    defaultBranch,
111	    activePacks: decl.activePacks,
112	    packConfigs: decl.packConfigs,
113	    localPacksChanged: localChanged,
114	    schedulesItself: decl.schedulesItself,
115	    stamp: decl.stamp,
116	  };
117	}
118	
119	// Read the fleet aggregate: every COVERED member the owner owns (excluding the
120	// canon repo itself, forks, archived repos, and members declaring themselves
121	// dormant), each with its declaration +
122	// local-pack window probe. Pure over `fleetGh`. Returns `{ owner, members, error }`;
123	// `error` is set (and `members` empty) when enumeration itself failed or returned
124	// nothing — a fleet task's precondition treats an errored/empty fleet as "no work
125	// I can prove", never as "the fleet is empty" (the census's own refuse-on-empty
126	// rule: an empty enumeration is a wrong-token/scope symptom, not consent).
127	export async function readFleet(fleetGh, { owner, canonRepo, sinceIso }) {
128	  const ownerLc = String(owner).toLowerCase();
129	  const mine = await paged(fleetGh, '/user/repos?affiliation=owner');
130	  const owned = mine.filter((r) => r?.owner?.login?.toLowerCase() === ownerLc);
131	  if (owned.length === 0) {
132	    return { owner: ownerLc, members: [], error: `enumeration returned no repos owned by ${ownerLc} — wrong token user or scope` };
133	  }
134	  const members = [];
135	  for (const r of owned.sort((a, b) => a.name.localeCompare(b.name))) {
136	    const fullName = r.full_name;
137	    if (fullName.toLowerCase() === String(canonRepo).toLowerCase()) continue; // the canon doesn't mount itself
138	    if (r.archived || r.fork) continue;
139	    const res = await fleetGh(`/repos/${fullName}/contents/${SETTINGS_FILE}`);
140	    if (res.status !== 200 || !res.json?.content) continue; // uncovered - no tracked declaration
141	    const checks = parseChecks(res.json.content);
142	    if (!checks) continue; // unparsable declaration → not a member we can plan for
143	    // Declared dormant → out of the recurring work, which is the only thing this
144	    // signal feeds. Skipped HERE rather than in each consuming precondition, so a
145	    // dormant member costs neither an opus sweep nor the per-member probes below.
146	    if (isDormant(checks)) continue;
147	    members.push(await buildMember(fleetGh, { full_name: fullName, default_branch: r.default_branch, checks }, sinceIso));
148	  }
149	  return { owner: ownerLc, members };
150	}
151	
152	// The I/O edge: build a fleet `gh` from FLEET_GITHUB_TOKEN, or null when the
153	// secret isn't set (a consumer, or the canon before the secret is provisioned) —
154	// the collector then leaves ctx.fleet null and returns null, so the
155	// fleet tasks' preconditions skip rather than crash.
156	export function makeFleetGh(env = actionsEnv()) {
157	  const token = env.FLEET_GITHUB_TOKEN;
158	  if (!token) return null;
159	  return makeGh({ token });
160	}
