  1	// COMPATIBILITY SHIM — this module is `code-work-run.mjs` now (the 2026-08-18
  2	// phase-language rename, #1012). The path survives for the reason
  3	// `packs/claudinite-tasks/test/engine-pack-lane-shims.test.mjs` sets out in full: the
  4	// engine lane and the pack lane deliver separately, so a member holds the new
  5	// engine beside an old pack for a while, and a fielded `core` pack still imports
  6	// this path from `task-prework-env.mjs`.
  7	//
  8	// WHAT IS HERE. Only the symbols a fielded pack version imports, under the names
  9	// that version spells them. Which those are is derived from history by that test,
 10	// not from a list here.
 11	//
 12	// WHEN IT GOES. When no member's stamped `packVersions` names a `core` version
 13	// that still imports this path — read the field, do not guess a release.
 14	export { CODE_WORK_ENV_VARS as PREWORK_ENV_VARS } from './code-work-run.mjs';
  1	// THE TARGET — which pull request a run works on (docs/PRINCIPLES.md,
  2	// docs/PRINCIPLES.md). A task's `expected_outcome` says what its run does to pull
  3	// requests; the executor resolves that into a concrete branch and pull request
  4	// ONCE, after the precondition said go and before code-work, and hands the
  5	// answer to both phases (code-work as environment, the agent as item fields).
  6	// Neither phase discovers, chooses or disposes of a pull request on its own —
  7	// that was three independent decisions in three places, and a task could not
  8	// even say "append to my open pull request".
  9	//
 10	// A task's open pull requests are recognised two ways, either sufficient: the
 11	// branch prefix this module mints (`claudinite/<pack>/<task>/`), or the
 12	// `Claudinite-Task:` trailer on the pull request's head commit — the authority the
 13	// movement signals already read, which is what still finds a pull request a lane
 14	// opened under its own branch name before the executor minted them.
 15	//
 16	// `planTarget` is pure over what was read; `resolveTarget` is the I/O shell that
 17	// reads it. A read the shell cannot make is `{ error }` — a run failure the
 18	// executor parks, never a guess: an unreadable pull request list looks exactly
 19	// like an empty one, and "nothing to amend" on that evidence stacks a duplicate.
 20	
 21	import { pullDisposition } from '../deliver/land-pr.mjs';
 22	import { taskFromMessage, taskTrailer } from '../../public/work-item-grammar.mjs';
 23	import { canonicalOutcome, opensPullRequest } from '../contract/task-contract.mjs';
 24	import { deleteBranchRef, listOpenPulls, readCommit, readPull, listRunsForSha, mergePull, closePull, comment as postComment } from '../world/github.mjs';
 25	
 26	export const TARGET_MODES = Object.freeze(['none', 'fresh', 'amend']);
 27	
 28	// Every branch the executor mints lives under one root, and every task under its
 29	// own prefix beneath it — which is what makes the prefix a family, not a guess.
 30	export const BRANCH_ROOT = 'claudinite';
 31	export const taskBranchPrefix = (taskId) => `${BRANCH_ROOT}/${taskId}/`;
 32	
 33	// One branch per run, dated and seeded: two runs on one day must not collide, and
 34	// a name that carries its date is one a person can read a week later.
 35	export const mintBranch = (taskId, now, seed) =>
 36	  `${taskBranchPrefix(taskId)}${new Date(now).toISOString().slice(0, 10)}-${seed}`;
 37	export const newSeed = () => Math.random().toString(36).slice(2, 8);
 38	
 39	// This task's open pull requests, newest first. `headTaskOf(pr)` answers which task
 40	// the pull request's head commit names, for the ones the prefix does not settle.
 41	export function taskPullsOf(pulls, taskId, headTaskOf = () => null) {
 42	  const prefix = taskBranchPrefix(taskId);
 43	  return (pulls ?? [])
 44	    .filter((p) => String(p?.head?.ref ?? '').startsWith(prefix) || headTaskOf(p) === taskId)
 45	    .sort((a, b) => b.number - a.number);
 46	}
 47	
 48	// What a target becomes in code-work's environment — three variables in every
 49	// mode, so a worker can tell "no target" from "an executor that sets none".
 50	export const targetEnv = (target) => ({
 51	  CLAUDINITE_TARGET_MODE: target?.mode ?? 'none',
 52	  CLAUDINITE_TARGET_BRANCH: target?.branch ?? '',
 53	  CLAUDINITE_TARGET_PR: target?.pr == null ? '' : String(target.pr),
 54	});
 55	
 56	// The decision, pure. `incumbents` are this task's open pull requests newest
 57	// first; `mergeable` is the newest one's answer where the outcome amends;
 58	// `disposition` is `pullDisposition`'s verdict on the newest where the outcome
 59	// supersedes, with `merge` meaning the shell already landed it.
 60	//
 61	//   { mode, branch, pr, supersedes, landed, reason }
 62	//   mode      — 'none' | 'fresh' | 'amend'
 63	//   branch    — the branch the run pushes to (null under 'none')
 64	//   pr        — the pull request an amend pushes onto (null otherwise)
 65	//   supersedes — pull requests to close once this run's own exists
 66	//   landed    — the incumbent the shell merged, whose landing ends this occurrence
 67	export function planTarget({ outcome, incumbents = [], mergeable = null, disposition = null, branch }) {
 68	  const canonical = canonicalOutcome(outcome);
 69	  if (!canonical) throw new Error(`"${outcome}" is not a legal outcome ceiling`);
 70	  const none = (reason) => ({ mode: 'none', branch: null, pr: null, supersedes: [], landed: null, reason });
 71	  const fresh = (reason) => ({ mode: 'fresh', branch, pr: null, supersedes: [], landed: null, reason });
 72	  const newest = incumbents[0] ?? null;
 73	
 74	  if (!opensPullRequest(canonical)) return none('this task changes no code');
 75	  if (canonical === 'fresh_pr') return fresh('a fresh branch; earlier pull requests of this task are left as they are');
 76	
 77	  // A task declared to amend has NO PREROGATIVE to open a second pull request
 78	  // (owner, 2026-09-22). "Create new" names one situation - there is nothing to
 79	  // amend - and a conflicted or unjudgeable incumbent is not that situation. The
 80	  // run either works, by resolving the conflict on the branch it was given, or it
 81	  // fails; a quiet fork leaves the first pull request open and accumulating beside
 82	  // the second, which is how one task came to hold two.
 83	  if (canonical === 'amend_existing_or_create_new_pr') {
 84	    if (!newest) return fresh('no open pull request of this task to amend');
 85	    if (mergeable === null) {
 86	      return { error: `#${newest.number}'s mergeability could not be read, and this task amends rather than forks - nothing ran` };
 87	    }
 88	    return {
 89	      mode: 'amend', branch: newest.head.ref, pr: newest.number, supersedes: [], landed: null,
 90	      reason: mergeable
 91	        ? `amending #${newest.number}, which has no conflicts with its base`
 92	        : `amending #${newest.number}, which CONFLICTS with its base - resolve that conflict as part of this run, by merging the base branch in; do not open a second pull request`,
 93	    };
 94	  }
 95	
 96	  // supersede_existing_pr
 97	  if (!newest) return fresh('no open pull request of this task to supersede');
 98	  const numbers = incumbents.map((p) => p.number);
 99	  if (disposition === 'merge') {
100	    // The previous delivery had concluded green and was never landed — the exact
101	    // member whose CI outruns the landing budget every day, which the next-cycle
102	    // disposal used to rescue. Landing it is finishing this task's own delivery;
103	    // the tree this run holds predates that merge, so the occurrence ends here and
104	    // the next one converges from the moved base.
105	    return {
106	      ...none(`landed #${newest.number}, this task's previous delivery, which had concluded green — the occurrence ends there`),
107	      landed: newest.number, supersedes: numbers.slice(1),
108	    };
109	  }
110	  return {
111	    mode: 'fresh', branch, pr: null, supersedes: numbers, landed: null,
112	    reason: `a fresh branch; ${numbers.map((n) => `#${n}`).join(', ')} close as superseded once this run's pull request exists`,
113	  };
114	}
115	
116	const defaultSleep = (ms) => new Promise((resolve) => { setTimeout(resolve, ms); });
117	
118	// GitHub computes `mergeable` lazily: the first read after a push answers null
119	// while it works. Three reads two seconds apart cover the documented delay; an
120	// answer that never comes fails the run, so the item is parked and re-queued
121	// rather than given a target nobody could justify.
122	const MERGEABLE_READS = 3;
123	const MERGEABLE_WAIT_MS = 2000;
124	
125	async function deleteRef(gh, repo, ref, log) {
126	  if (!ref) return;
127	  const res = await deleteBranchRef(gh, repo, ref);
128	  if (res.status !== 204) log(`could not delete branch ${ref} (HTTP ${res.status})`);
129	}
130	
131	// The I/O shell. Reads nothing for the two outcomes that involve no existing pull
132	// request; for the other two, lists the open pull requests, recognises this
133	// task's, and reads exactly what the plan needs of the newest — its mergeability
134	// for an amend, the runs on its head for a supersede (landing it there when
135	// `delivery` allows and the runs concluded green).
136	export async function resolveTarget({
137	  gh, repo, taskId, outcome, delivery, now, seed = newSeed(), sleep = defaultSleep, log = console.log,
138	}) {
139	  const canonical = canonicalOutcome(outcome);
140	  if (!canonical) return { error: `"${outcome}" is not a legal outcome ceiling` };
141	  const branch = mintBranch(taskId, now, seed);
142	  if (canonical === 'no_code_changes' || canonical === 'fresh_pr') return planTarget({ outcome: canonical, incumbents: [], branch });
143	
144	  const listed = await listOpenPulls(gh, repo);
145	  if (listed.status !== 200 || !Array.isArray(listed.json)) {
146	    return { error: `could not list the open pull requests in ${repo} (${listed.status}) — an unreadable list is not an empty one` };
147	  }
148	  // One head-commit read per open pull request the prefix does not settle: the
149	  // trailer is what still recognises a pull request a lane opened under its own
150	  // branch name before the executor minted them.
151	  const prefix = taskBranchPrefix(taskId);
152	  const heads = new Map();
153	  for (const p of listed.json) {
154	    if (String(p?.head?.ref ?? '').startsWith(prefix) || !p?.head?.sha) continue;
155	    const res = await readCommit(gh, repo, p.head.sha);
156	    heads.set(p.number, res.status === 200 ? taskFromMessage(res.json?.commit?.message) : null);
157	  }
158	  const incumbents = taskPullsOf(listed.json, taskId, (p) => heads.get(p.number) ?? null);
159	  const newest = incumbents[0] ?? null;
160	  if (!newest) return planTarget({ outcome: canonical, incumbents, branch });
161	
162	  if (canonical === 'amend_existing_or_create_new_pr') {
163	    let mergeable = null;
164	    for (let n = 0; n < MERGEABLE_READS; n += 1) {
165	      if (n) await sleep(MERGEABLE_WAIT_MS);
166	      const res = await readPull(gh, repo, newest.number);
167	      if (res.status !== 200) break;
168	      if (typeof res.json?.mergeable === 'boolean') { mergeable = res.json.mergeable; break; }
169	    }
170	    return planTarget({ outcome: canonical, incumbents, mergeable, branch });
171	  }
172	
173	  // supersede_existing_pr — judged by the runs on the newest incumbent's head,
174	  // exactly as the next-cycle disposal judged it. An unreadable head is `close`:
175	  // the successor this run opens gets its own chance to land.
176	  const runsRes = await listRunsForSha(gh, repo, newest.head?.sha ?? '');
177	  const runs = runsRes.status === 200
178	    ? (runsRes.json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }))
179	    : null;
180	  let disposition = runs ? pullDisposition({ delivery, runs }) : 'close';
181	  if (disposition === 'merge') {
182	    const res = await mergePull(gh, repo, newest.number,
183	      { merge_method: 'squash', commit_message: taskTrailer(taskId) });
184	    if (res.status === 200) {
185	      log(`landed #${newest.number} — ${taskId}'s previous delivery had concluded green and was never merged`);
186	      await deleteRef(gh, repo, newest.head?.ref, log);
187	    } else {
188	      log(`could not land #${newest.number} (${res.status}: ${res.json?.message ?? 'no message'}) — superseding it instead`);
189	      disposition = 'close';
190	    }
191	  }
192	  return planTarget({ outcome: canonical, incumbents, disposition, branch });
193	}
194	
195	// Close the pull requests a run superseded, now that its own (`successor`) exists:
196	// a comment saying by what, the close, and the dead branch tidied. Best-effort
197	// throughout — the successor is the deliverable, and one already closed by hand,
198	// or unreadable, is logged and left.
199	export async function closeSuperseded({ gh, repo, numbers = [], successor, log = console.log }) {
200	  for (const number of numbers) {
201	    const read = await readPull(gh, repo, number);
202	    if (read.status !== 200) { log(`could not close #${number} (${read.status}) — leaving it`); continue; }
203	    await postComment(gh, repo, number,
204	      `Superseded by #${successor}, a later run of the same task. Closing this one.`);
205	    const closed = await closePull(gh, repo, number);
206	    if (closed.status !== 200) { log(`could not close #${number} (${closed.status}) — leaving it`); continue; }
207	    log(`closed #${number} — superseded by #${successor}`);
208	    await deleteRef(gh, repo, read.json?.head?.ref, log);
209	  }
210	}
  1	// THE POST-SCHEDULER-RUN DRAIN (docs/PRINCIPLES.md). The
  2	// scheduler run's own concurrency group serializes scheduler runs — its
  3	// duplicate-standing-item self-heal depends on exactly that — and a drain running
  4	// inside the group would make each tick queue behind the previous one's work,
  5	// which the heartbeat, by making long work legal, turned from theoretical into
  6	// likely. So the drain DISPATCHES the executor workflow rather than being one: it
  7	// starts in its own group, on its own runner, and this step's success means "the
  8	// drain was started", never "the drain finished".
  9	//
 10	// This is the guaranteed delivery. A `task:ready` label event may be lost; this
 11	// fires on every tick that left something pickable, so a lost event is latency
 12	// lost and never work lost.
 13	//
 14	// The workflow gates this step on the scheduler run's own `pickable` output — an
 15	// executor dispatched into an empty queue costs a full billed invocation to find
 16	// nothing. That gate weakens no delivery: what a lost label event would have
 17	// delivered is exactly what the scheduler run's parting look already saw.
 18	
 19	import { pathToFileURL } from 'node:url';
 20	import { makeGh } from '../world/github.mjs';
 21	import { actionRepoContext, EXECUTOR_WORKFLOW_FILE } from '../world/actions.mjs';
 22	import { dispatchWorkflow } from '../world/github.mjs';
 23	
 24	// The dispatch itself, separated from the shell so it runs against a fake `gh`.
 25	// Judged by status, never by the body: a token without `actions: write` 403s this
 26	// POST with a plausible JSON body, and a run that logged `ok` for it would leave the
 27	// queue undrained with nothing saying so.
 28	export async function dispatchDrain(gh, repo, defaultBranch, log = console.log) {
 29	  const { ok, status } = await dispatchWorkflow(gh, repo, EXECUTOR_WORKFLOW_FILE, defaultBranch);
 30	  if (!ok) throw new Error(`could not dispatch ${EXECUTOR_WORKFLOW_FILE} on ${defaultBranch}: ${status}`);
 31	  log(`- dispatched the executor on ${defaultBranch} to drain whatever this scheduler run created`);
 32	  return { dispatched: EXECUTOR_WORKFLOW_FILE, ref: defaultBranch };
 33	}
 34	
 35	// The shell the frozen entry point runs: it builds the real world and hands it to
 36	// the decision above.
 37	export async function runDrainDispatch() {
 38	  const { repo, defaultBranch } = actionRepoContext();
 39	  if (!repo) throw new Error('GITHUB_REPOSITORY is not set');
 40	  return dispatchDrain(makeGh(), repo, defaultBranch);
 41	}
 42	
 43	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
 44	  runDrainDispatch().catch((e) => { console.error(e); process.exitCode = 1; });
 45	}

