1	// The tasks fold's SECOND source: what each occurrence came to, how long each step
2	// of it took, and what the executor run behind it spent.
3	//
4	// ONE READ PER ITEM, and that is the whole reason this module exists rather than
5	// calling the session fold's queue reader. That reader answers outcomes and parks
6	// off an item's EVENTS listing, which is exactly the right read for what it wants.
7	// This fold wants three things off one item — the parks, the four latencies between
8	// its label events, and the `claudinite-run-cost` record its executor left in a
9	// comment — and the TIMELINE endpoint carries labelings, comments and the close in
10	// one paged listing. Two listings per item to answer one item is the cost worth
11	// avoiding, so the timeline is read and the events reader is left where it is.
12	//
13	// APPEND-ONCE past the caller's watermark, for the reason the session fold's queue
14	// read is: a CLOSED item is settled — its outcome label is written at convergence
15	// and nothing later moves it — so an item is counted on the one fold that first sees
16	// it closed and never again. The boundary is `closed_at` and not `updated_at`, for
17	// the same reason again: the listing is asked for everything TOUCHED since the mark.
18	//
19	// FAIL-SOFT per item: a timeline that cannot be read costs that item its parks, its
20	// latencies and its cost record, and keeps its outcome row.
21	
22	import { isQueueItem } from '../../src/items/read.mjs';
23	import { taskOf, parkKindOf } from '../usage-fold/read-queue.mjs';
24	import { STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT } from '../../public/task-constants.mjs';
25	import { outcomeOf, spellingsOf } from '../../public/work-item-grammar.mjs';
26	import { parseRunCosts } from '../../src/items/run-record.mjs';
27	
28	// How far back the FIRST read looks with no mark yet — the day tier's own width, as
29	// the session fold's queue read does, so one fold populates the whole window.
30	export const FIRST_READ_LOOKBACK_DAYS = 30;
31	
32	export const lookbackFrom = (nowIso, days = FIRST_READ_LOOKBACK_DAYS) =>
33	  new Date(new Date(nowIso).getTime() - days * 86400000).toISOString();
34	
35	// Every spelling of the two mid-flight statuses, so an item that ran under an older
36	// engine still reports its latencies rather than reading as never picked up.
37	const PICKED = new Set(spellingsOf(STATUS_RUNNING_EXECUTOR));
38	const HANDED_OFF = new Set(spellingsOf(STATUS_RUNNING_AGENT));
39	
40	const minutesBetween = (from, to) => {
41	  const a = Date.parse(from ?? '');
42	  const b = Date.parse(to ?? '');
43	  if (!Number.isFinite(a) || !Number.isFinite(b) || b < a) return null;
44	  return Math.round((b - a) / 60000);
45	};
46	
47	// The first instant a label from `names` was applied, out of a timeline listing.
48	// FIRST, not last: an item re-queued by hand is picked twice, and the latency being
49	// measured is the queue's own — how long the item waited for an executor after it
50	// was filed.
51	export function firstLabeledAt(timeline, names) {
52	  for (const e of timeline ?? []) {
53	    if (e?.event !== 'labeled') continue;
54	    if (names.has(String(e?.label?.name ?? ''))) return e.created_at ?? null;
55	  }
56	  return null;
57	}
58	
59	// The park kinds one item collected, DEDUPED: an item that bounced between a person
60	// and the machine twice was parked for that kind once, as far as "how often did this
61	// task need a human" is concerned.
62	export function parksIn(timeline) {
63	  const kinds = new Set();
64	  for (const e of timeline ?? []) {
65	    if (e?.event !== 'labeled') continue;
66	    const kind = parkKindOf(e?.label?.name);
67	    if (kind) kinds.add(kind);
68	  }
69	  return [...kinds];
70	}
71	
72	// The cost records an item's comments carry. An item is normally settled by ONE
73	// executor run, but a re-queued one is settled by another, so every record found is
74	// returned and the fold keys them by run id.
75	export function costsIn(timeline) {
76	  const out = [];
77	  for (const e of timeline ?? []) {
78	    if (e?.event !== 'commented') continue;
79	    out.push(...parseRunCosts(e?.body));
80	  }
81	  return out;
82	}
83	
84	// The four latencies, in minutes. `tickToItem` needs the scheduler run that filed
85	// the item, which is not on the item at all: it is the newest scheduler run that had
86	// STARTED when the item was created, out of the runs this fold read. Where that run
87	// is outside the window, the slot is ABSENT — the gap is unknown, not instant.
88	//
89	// Every other slot is absent where its far end never happened: an agentless item has
90	// no hand-off, an item nobody picked has no pick. A zero there would read as an
91	// instant that was in fact a thing that did not occur.
92	export function latencyOf({ item, timeline, schedulerRuns = [] }) {
93	  const createdAt = item?.created_at ?? null;
94	  const pickedAt = firstLabeledAt(timeline, PICKED);
95	  const handedOffAt = firstLabeledAt(timeline, HANDED_OFF);
96	  const closedAt = item?.closed_at ?? null;
97	
98	  let tickAt = null;
99	  for (const run of schedulerRuns) {
100	    if (!run?.startedAt || !createdAt || run.startedAt > createdAt) continue;
101	    if (tickAt === null || run.startedAt > tickAt) tickAt = run.startedAt;
102	  }
103	
104	  const row = {
105	    tickToItemMinutes: minutesBetween(tickAt, createdAt),
106	    itemToPickMinutes: minutesBetween(createdAt, pickedAt),
107	    pickToHandOffMinutes: minutesBetween(pickedAt, handedOffAt),
108	    handOffToConvergeMinutes: minutesBetween(handedOffAt, closedAt),
109	  };
110	  // An absent slot leaves no key, so the encoder writes `null` for it rather than a
111	  // measured zero.
112	  return Object.fromEntries(Object.entries(row).filter(([, v]) => v !== null));
113	}
114	
115	// One closed item → a record, or null when it is not this fold's business.
116	export function recordFor(issue, since) {
117	  if (!isQueueItem(issue)) return null;
118	  const closedAt = issue?.closed_at ?? null;
119	  if (!closedAt) return null;
120	  if (since && closedAt <= since) return null;
121	  const task = taskOf(issue);
122	  if (!task) return null;
123	  return {
124	    date: closedAt.slice(0, 10), closedAt, ...task,
125	    outcome: outcomeOf(issue) ?? 'none',
126	    number: issue?.number ?? null,
127	    created_at: issue?.created_at ?? null,
128	    // Filled by the caller from the item's own timeline, and left `null` — never
129	    // `[]` or `{}` — where that listing could not be read.
130	    parks: null, latency: null, costs: null,
131	  };
132	}
133	
134	export async function readTimeline({ reader, repo, number, maxPages = 2 }) {
135	  const out = [];
136	  for (let page = 1; page <= maxPages; page += 1) {
137	    const batch = await reader.json(`/repos/${repo}/issues/${number}/timeline?per_page=100&page=${page}`);
138	    if (!Array.isArray(batch) || batch.length === 0) return page === 1 ? null : out;
139	    out.push(...batch);
140	    if (batch.length < 100) break;
141	  }
142	  return out;
143	}
144	
145	// The whole read: `{ records, watermark, error? }`.
146	export async function readClosedItems({
147	  reader, repo, since, now, schedulerRuns = [], maxPages = 5,
148	}) {
149	  const from = since || lookbackFrom(now);
150	  const records = [];
151	  try {
152	    for (let page = 1; page <= maxPages; page += 1) {
153	      const path = `/repos/${repo}/issues?state=closed&sort=updated&direction=desc`
154	        + `&since=${encodeURIComponent(from)}&per_page=100&page=${page}`;
155	      const batch = await reader.json(path);
156	      if (!Array.isArray(batch) || batch.length === 0) break;
157	      for (const issue of batch) {
158	        if (issue?.pull_request) continue;          // the issues endpoint answers with both
159	        const rec = recordFor(issue, since);
160	        if (rec) records.push({ rec, issue });
161	      }
162	      if (batch.length < 100) break;
163	    }
164	  } catch {
165	    return { records: [], watermark: since, error: 'the closed work items could not be listed' };
166	  }
167	
168	  // One timeline read per item, and only for the items this fold is seeing close for
169	  // the first time — the watermark above is what bounds the cost.
170	  for (const { rec, issue } of records) {
171	    if (rec.number === null) continue;
172	    let timeline = null;
173	    try { timeline = await readTimeline({ reader, repo, number: rec.number }); } catch { timeline = null; }
174	    if (timeline === null) continue;
175	    rec.parks = parksIn(timeline);
176	    rec.latency = latencyOf({ item: issue, timeline, schedulerRuns });
177	    rec.costs = costsIn(timeline);
178	  }
179	
180	  const out = records.map((r) => r.rec);
181	  const newest = out.map((r) => r.closedAt).sort().pop() ?? null;
182	  return { records: out, watermark: newest ?? since ?? null };
183	}
184

1	// The tasks fold's FIRST source: what each run of the machinery cost.
2	//
3	// The run LISTINGS are not re-derived here — `readRuns` in the session fold's own
4	// task folder already reads exactly this source, two calls flat however many runs
5	// are in the window, and a second implementation of the same listing is a second
6	// thing to drift. What this module adds is the two reads that listing cannot make:
7	//
8	//   - THE JOBS LISTING, one call per run, because Actions bills per JOB and the run
9	//     listing carries no job timings at all. A run's billed minutes are the sum over
10	//     its jobs of each job's wall time rounded up to a whole minute.
11	//   - THE JOB LOG, for a SCHEDULER run only. A tick owns no work item, so the
12	//     `claudinite-run-cost` record it printed exists nowhere but its log. An
13	//     executor run's record rides the items it settled, which the item reader picks
14	//     up for free.
15	//
16	// THE BUDGET, stated here because it is the reason the module is shaped this way.
17	// Per fold: 2 run listings, flat; 1 jobs listing per run this fold is seeing for the
18	// first time; and, for at most `SCHEDULER_RUNS_PER_FOLD` scheduler runs, at most
19	// `JOB_LOGS_PER_RUN` log reads each. On this repo's cadence — the scheduler's two
20	// ticks a day and the executor runs a quiet queue dispatches — that is under ten
21	// calls a day, which `test/tasks/tasks-usage-fold/read-run-costs.test.mjs` asserts
22	// by counting the fetches a representative day makes.
23	//
24	// `MAX_RUN_READS` is the runaway guard rather than the budget: a day that somehow
25	// produced hundreds of runs stops at the cap, leaves the watermark at the last run
26	// fully read, and says so — the next fold continues from exactly there. Reading a
27	// repo's whole rate limit to measure it would be the fold costing more than the
28	// thing it measures.
29	//
30	// FAIL-SOFT per read, like every source in both folds: a jobs listing that cannot be
31	// read costs that run its minutes and nothing else, and a log that cannot be read
32	// costs that tick its cost record. Neither takes the run counts down with it.
33	
34	import { makeReader as makeJsonReader, readRuns, WATCHED_WORKFLOWS } from '../usage-fold/read-runs.mjs';
35	import { parseRunCosts } from '../../src/items/run-record.mjs';
36	
37	const API = process.env.GITHUB_API_URL || 'https://api.github.com';
38	
39	// At most this many scheduler runs have their log read in one fold — the two ticks
40	// a day the cron fires, plus one fold's slack for a late fire.
41	export const SCHEDULER_RUNS_PER_FOLD = 2;
42	
43	// Within one of those runs, at most this many job logs are read. A tick's record is
44	// printed by the run job, which the jobs listing returns first; the second read
45	// exists for a member whose workflow orders its jobs the other way. Skipped jobs are
46	// never read — they have no log.
47	export const JOB_LOGS_PER_RUN = 2;
48	
49	// The runaway guard on per-run reads in one fold. Not the budget — see the header.
50	export const MAX_RUN_READS = 40;
51	
52	// The reader this module needs: JSON like the session fold's, plus text for a log.
53	// `fetchImpl` is injected so the tests drive it without a network.
54	export function makeReader({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
55	  const headers = {
56	    accept: 'application/vnd.github+json',
57	    'x-github-api-version': '2022-11-28',
58	    'user-agent': 'claudinite-tasks-usage-fold',
59	    ...(token ? { authorization: `Bearer ${token}` } : {}),
60	  };
61	  const { json } = makeJsonReader({ token, api, fetchImpl });
62	  return {
63	    json,
64	    async text(path) {
65	      // The logs endpoint answers a redirect to a blob; `fetch` follows it, and a
66	      // run whose logs have aged out of retention answers 404 — which is an ANSWER,
67	      // not a failure: that tick's cost is simply unrecoverable now.
68	      const res = await fetchImpl(`${api}${path}`, { headers });
69	      if (res.status !== 200) return null;
70	      try { return await res.text(); } catch { return null; }
71	    },
72	  };
73	}
74	
75	// HOW A JOB'S MINUTES ARE COUNTED. Each job's wall time — `completed_at` minus
76	// `started_at` — rounded UP to a whole minute, summed over the run's jobs.
77	//
78	// THE ROUNDING RULE IS UNVERIFIED FROM HERE. #1872 asks for it to be checked against
79	// GitHub's billing documentation and cited; a session in this repo cannot reach
80	// `docs.github.com` at all (the egress proxy refuses the domain), so the rule below
81	// is the one this repo already states for itself in `src/execute/loop.mjs` —
82	// "Actions bills each job's runtime rounded UP to the next minute" — and not a
83	// reading of the docs. Confirming it against
84	// docs.github.com/en/billing/concepts/product-billing/github-actions needs an
85	// unblocked environment, and this function is the only place the rule is encoded.
86	//
87	// A job with no `completed_at` (still running, or killed without one) contributes
88	// NO minutes rather than zero, and the run's total is absent when no job could be
89	// measured at all — unknown is a state of its own here as everywhere else.
90	export function billedMinutes(jobs) {
91	  let minutes = null;
92	  for (const job of jobs ?? []) {
93	    const from = Date.parse(job?.started_at ?? '');
94	    const to = Date.parse(job?.completed_at ?? '');
95	    if (!Number.isFinite(from) || !Number.isFinite(to) || to < from) continue;
96	    minutes = (minutes ?? 0) + Math.ceil((to - from) / 60000);
97	  }
98	  return minutes;
99	}
100	
101	// One run's jobs, or null when the listing could not be read.
102	export async function readJobs(reader, repo, runId) {
103	  const json = await reader.json(`/repos/${repo}/actions/runs/${runId}/jobs?per_page=100`);
104	  return Array.isArray(json?.jobs) ? json.jobs : null;
105	}
106	
107	// A job that produced a log at all. A skipped job has none, and asking for one
108	// spends a call on a 404.
109	const ran = (job) => job?.conclusion !== 'skipped' && job?.conclusion != null;
110	
111	// The cost record a scheduler tick printed, out of its jobs' logs. Reads at most
112	// `budget` of them, stopping at the first that carries one.
113	export async function readCostFromLog(reader, repo, jobs, { budget = JOB_LOGS_PER_RUN } = {}) {
114	  let reads = 0;
115	  for (const job of (jobs ?? []).filter(ran)) {
116	    if (reads >= budget) break;
117	    reads += 1;
118	    const text = await reader.text(`/repos/${repo}/actions/jobs/${job.id}/logs`);
119	    // The LAST record in the log, not the first: a tick prints its record once, at
120	    // the end, and a log that somehow carries two is a re-run whose later line is
121	    // the one that describes the whole of it.
122	    const found = parseRunCosts(text).at(-1);
123	    if (found) return { record: found, reads };
124	  }
125	  return { record: null, reads };
126	}
127	
128	// The whole read: `{ runs, watermark, error?, truncated }`.
129	//
130	//   runs      — [{ id, startedAt, workflow, conclusion, jobs, minutesBilled, cost }],
131	//               oldest first. `jobs` is a count and `minutesBilled` a number, each
132	//               null where the jobs listing could not be read; `cost` is the parsed
133	//               `claudinite-run-cost` record for a scheduler tick whose log carried
134	//               one, null otherwise (an executor's arrives with its items).
135	//   watermark — the newest run START this fold read IN FULL. A run the cap stopped
136	//               before leaves the mark behind it, so the next fold re-reads exactly
137	//               what it missed.
138	export async function readRunCosts({ reader, repo, since, now, maxRunReads = MAX_RUN_READS }) {
139	  const listed = await readRuns({ reader, repo, since, now });
