410	      // A 403/404 here is a real answer: the caller may not read collaborators, or
411	      // this login is not one. The first is a repo-configuration fault and the
412	      // second is the ordinary "a stranger opened it" case, and only the API can
413	      // tell them apart — so a 404 is `none` and anything else stops the read.
414	      let value;
415	      if (res.status === 200) value = res.json?.role_name ?? res.json?.permission ?? 'none';
416	      else if (res.status === 404) value = 'none';
417	      else { failed = `the permission API answered ${res.status} for @${login}`; value = 'none'; }
418	      permissions.set(login, value);
419	      return value;
420	    };
421	
422	    const author = json.user?.login ?? null;
423	    const authorPermission = await permissionOf(author);
424	    // The approval phrase is only worth a permission read on the comments that
425	    // carry it, so an issue with a long thread costs one read per distinct blesser.
426	    const comments = await paged(gh, `/repos/${ctx.repo}/issues/${number}/comments`);
427	    const approvals = [];
428	    for (const c of comments) {
429	      const login = c.user?.login ?? null;
430	      if (!login || !APPROVAL_RE.test(c.body ?? '')) continue;
431	      approvals.push({ login, permission: await permissionOf(login) });
432	    }
433	    if (failed) return { number, unreadable: true, error: failed };
434	
435	    return {
436	      number,
437	      state: json.state,
438	      labels: (json.labels ?? []).map((l) => l.name ?? l),
439	      // STILL MARKED, in any spelling this repo's issues may carry: the origin the
440	      // one-issue model applies, and the two retired `claude-*` labels a shadow item's
441	      // issue wears. Withdrawing is removing what marked it, whichever that was.
442	      queued: (json.labels ?? []).map((l) => l.name ?? l)
443	        .some((l) => [ORIGIN_AD_HOC, QUEUED_LABEL, REQUEST_LABEL].includes(l)),
444	      author,
445	      authorPermission,
446	      approvals,
447	    };
448	  },
449	
450	  // THE RUN HISTORY (docs/PRINCIPLES.md): this task's own unqualified work
451	  // items over the horizon, newest first, the item under evaluation excluded — what
452	  // the cadence terms and the since-last-run window read. Off `ctx.items` where the
453	  // caller already holds the queue (the scheduler run fetched it, so the whole
454	  // repo's tasks cost no read); off the ISSUES list API otherwise (the executor at
455	  // pick) — never the search index (S6/F11), and `since` bounded to the horizon so
456	  // a long-lived repo's closed history is not paged.
457	  //
458	  // A qualified item (a fan-out target, a request naming its issue) is not a run of
459	  // the task's standing occurrence and is not evidence of one; it is invisible here.
460	  async runs(gh, ctx) {
461	    if (!ctx.task?.pack || !ctx.task?.id) throw new Error('the runs collector needs the task whose history it reads');
462	    const title = workItemTitle({ pack: ctx.task.pack, task: ctx.task.id });
463	    const horizonIso = new Date(new Date(ctx.now).getTime() - RUN_HORIZON_DAYS * 86400e3).toISOString();
464	    const items = ctx.items ?? await readWorkItems(gh, ctx.repo, `state=all&since=${encodeURIComponent(horizonIso)}`);
465	    // A run begins at the pick. An item nobody has picked yet, or that was closed
466	    // before anyone picked it, still wears the status it waited in — open, or
467	    // beside the terminal label the scheduler's dedupe, orphan and supersede
468	    // writes add (a person's close adds nothing; the executor's own close always
469	    // swaps it out). It never ran and never declined, so it is not a run:
470	    // counted, two twins decline each other at pick and a deduped one spends the
471	    // period on the survivor (SCENARIOS F32), and a hand-closed item stands
472	    // between `last-run-not-failed` and the failure park behind it.
473	    const unpicked = (i) => statusesOn(i).some((s) => s === STATUS_BLOCKED || s === STATUS_READY);
474	    const list = items
475	      .filter((i) => String(i.title ?? '').trim() === title && i.number !== ctx.item?.number && !unpicked(i))
476	      .map((i) => ({
477	        number: i.number,
478	        createdAt: i.created_at,
479	        closedAt: i.closed_at ?? null,
480	        state: i.state,
481	        status: statusOf(i),
482	        park: parkKindOf(i),
483	        outcome: outcomeOf(i),
484	        woken: parseWorkItemBody(i.body ?? '').woken !== null,
485	      }))
486	      .sort((a, b) => b.number - a.number);
487	    return { list, horizonDays: RUN_HORIZON_DAYS };
488	  },
489	
490	  // THE OPEN QUEUE - every open work item in the repo, whichever task it belongs
491	  // to, in the shape the janitor's rules read. Deliberately the one dimension
492	  // `issues` hides: that collector drops work items so the queue's own churn
493	  // cannot wake an issue-gated task (F8), which leaves the queue itself
494	  // unobservable - and a task whose subject IS the queue then has nothing to gate
495	  // on. Only a term naming `queue` sees it, so the exclusion above stands for
496	  // everyone else.
497	  //
498	  // Served off `ctx.items` where the caller already holds the queue - the
499	  // scheduler run listed it before asking anybody, so this costs no read at the
500	  // tick, which is what makes it affordable on a daily task's gate. The executor
501	  // at pick holds none and reads the open list.
502	  async queue(gh, ctx) {
503	    if (ctx.items) return { open: ctx.items.filter((i) => i.state === 'open') };
504	    const raw = await readWorkItems(gh, ctx.repo, 'state=open');
505	    return {
506	      open: raw.map((i) => ({
507	        number: i.number, title: i.title, body: i.body ?? '', state: i.state,
508	        labels: labelNames(i), created_at: i.created_at, closed_at: i.closed_at ?? null,
509	        updated_at: i.updated_at,
510	      })),
511	    };
512	  },
513	
514	  async fleet(gh, ctx) {
515	    return ctx.fleet ?? null;
516	  },
517	};
518	
519	// Every work item matching `scope`, off the issues list. A page that
520	// could not be read THROWS — the collector then records `{ error }` and every
521	// term over it fails loud — because a truncated history reads as a shorter one,
522	// and "no run in this period" on that evidence is a double run. The open queue
523	// reads the same way for the same reason: a page that never arrived is a repair
524	// nobody is asked to make.
525	async function readWorkItems(gh, repo, scope) {
526	  const out = [];
527	  for (let page = 1; ; page += 1) {
528	    const q = `${scope}&sort=created&direction=desc&per_page=100&page=${page}`;
529	    const { status, json } = await listIssuesByQuery(gh, repo, q);
530	    if (status !== 200 || !Array.isArray(json)) throw new Error(`the work-item list could not be read at page ${page} (${status})`);
531	    for (const i of json) {
532	      if (i.pull_request || !isQueueItem(i)) continue;
533	      out.push(i);
534	    }
535	    if (json.length < 100) break;
536	  }
537	  return out;
538	}
539	
540	export const SIGNAL_COLLECTORS = Object.keys(COLLECTORS);
541	
542	// Collect exactly the requested signal names into one object. An unknown name is
543	// ignored (the task-declaration-shape check rejects those at author time); a
544	// collector that throws records `{ error }` under its key rather than sinking the
545	// whole collection (per-signal isolation).
546	export async function collectSignals(gh, ctx, names) {
547	  const out = {};
548	  // Commit-derived collectors share one window read.
549	  if (names.some((n) => ['commits', 'localPacks', 'sharedMount', 'stamp'].includes(n)) && !ctx.commits) {
550	    try { ctx = { ...ctx, commits: await readWindowCommits(gh, ctx.repo, ctx.defaultBranch, ctx.sinceIso) }; } catch { /* collectors re-read on demand */ }
551	  }
552	  for (const name of names) {
553	    const collect = COLLECTORS[name];
554	    if (!collect) continue;
555	    try { out[name] = await collect(gh, ctx); }
556	    catch (e) { out[name] = { error: e.message }; }
557	  }
558	  return out;
559	}
560

