content.content:
 1	// THE AUTOMERGE VERDICT, AS A COMMAND — the landing lane runs this before it may
 2	// merge, and quotes the `AUTOMERGE:` line it prints (deliver-pr.md):
 3	//
 4	//   node <this file> --base origin/main --policy 'comment-only-changes;readme-changes'
 5	//
 6	// It sits here rather than beside the policy engine because reading the diff is a
 7	// world edge — git, the environment, the checkout — and what a task's `automerge`
 8	// MEANS may not depend on who is asking. `src/contract/merge-policy.mjs` decides;
 9	// this reads the world and prints.
10	
11	import { policyVerdict, declaredMergeRules } from '../contract/merge-policy.mjs';
12	import { runGit } from '../world/processes.mjs';
13	import { actionsEnv, repoRoot } from '../world/actions.mjs';
14	
15	const git = (args, cwd) => runGit(args, {
16	  cwd, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, stdio: ['ignore', 'pipe', 'ignore'],
17	});
18	
19	// The content of `file` at `ref`, or null when it does not exist there (an added
20	// file) — the same answer a deleted file's "after" gets.
21	function contentAt(ref, file, cwd) {
22	  try {
23	    return git(['show', `${ref}:${file}`], cwd);
24	  } catch {
25	    return null;
26	  }
27	}
28	
29	// The diff this branch carries against `base`, read from the merge base so
30	// commits that landed on the base meanwhile are not counted as this run's work.
31	export function diffEntries({ base, cwd = repoRoot() }) {
32	  // The checkouts these runs work in are shallow, where `merge-base` has no common
33	  // ancestor to find; the base ref itself is then the honest comparison point.
34	  let mergeBase;
35	  try {
36	    mergeBase = git(['merge-base', base, 'HEAD'], cwd).trim();
37	  } catch {
38	    mergeBase = base;
39	  }
40	  const names = git(['diff', '--name-only', mergeBase, 'HEAD'], cwd).split('\n').map((l) => l.trim()).filter(Boolean);
41	  return names.map((file) => ({
42	    file,
43	    before: contentAt(mergeBase, file, cwd),
44	    after: contentAt('HEAD', file, cwd),
45	  }));
46	}
47	
48	// --- the CLI ------------------------------------------------------------------
49	// What the landing lane runs before it may merge:
50	//   node <this file> --base origin/main --policy 'comment-only-changes;readme-changes'
51	// Prints one line per changed file and a final `AUTOMERGE: yes|no — why` verdict
52	// line the worker quotes. Pack-declared rules resolve from the repo's ACTIVE
53	// packs (loaded here, not at import time — discovery re-importing this module
54	// mid-evaluation must find no work started).
55	async function main() {
56	  const argv = process.argv.slice(2);
57	  const at = (flag) => (argv.includes(flag) ? argv[argv.indexOf(flag) + 1] : null);
58	  const cwd = at('--root') ?? actionsEnv().CLAUDE_PROJECT_DIR ?? repoRoot();
59	  const base = at('--base') ?? 'origin/main';
60	  const policy = at('--policy');
61	  if (policy === null) {
62	    console.error('merge-policy: --policy is required (the task\'s automerge, or the item\'s Merge: value)');
63	    process.exitCode = 2;
64	    return;
65	  }
66	
67	  const { loadPacks } = await import('../../../../engine/pack_loader/pack-registry.mjs');
68	  const { loadConfig } = await import('../../../../engine/checks/helpers/repo-context.mjs');
69	  const packs = await loadPacks({ localRoot: cwd });
70	  const { rules, errors } = declaredMergeRules(packs, loadConfig(cwd));
71	  for (const e of errors) console.error(`merge-policy: ${e}`);
72	
73	  const entries = diffEntries({ base, cwd });
74	  const verdict = policyVerdict({ policy, entries, declaredRules: rules, ruleErrors: errors });
75	  for (const { file, verdict: v } of verdict.files) console.log(`  ${v.padEnd(32)} ${file}`);
76	  console.log(`\nAUTOMERGE: ${verdict.mergeable ? 'yes' : 'no'} — ${verdict.why}`);
77	}
78	
79	if (import.meta.url === `file://${process.argv[1]}`) {
80	  main().catch((e) => { console.error(`merge-policy: ${e.message}`); process.exitCode = 1; });
81	}

