454	// The shell around the decision: one write to each channel, one exit. Returns
455	// the code rather than exiting so the printing is testable on its own.
456	export function emitResult({ code, fields, advice }) {
457	  if (fields) console.log(block(fields));
458	  if (advice) console.error(`resolve-dispatch: ${advice}`);
459	  return code;
460	}
