345	  if (op.confirm === 'abandoned') {
346	    return abandonedParkItems([fresh], now, { scheduledFor: scheduledForTasks(tasks) }).length > 0;
347	  }
348	  if (op.confirm === 'unclosed') return unclosedTerminalItems([fresh], now).length > 0;
