351	
352	// Apply one repair op. Returns whether it was written, so the caller can tell a
353	// dropped verdict from a landed one in its own log.
354	export async function applyRepairOp({ gh, repo, op, now, tasks, agentComments, api, log, problems = [] }) {
355	  const { comment, addLabel, removeLabel, closeIssue } = api;
356	  if (op.confirm) {
357	    const { readIssue } = await import('../world/github.mjs');
358	    if (!stillHolds(op, await readIssue(gh, repo, op.issue), { now, tasks })) {
359	      log(`- #${op.issue} settled between this run's read and its write - left alone`);
360	      return false;
361	    }
362	  }
363	  const body = op.body ?? (op.note === 'dead-agent'
364	    ? deadAgentComment({ number: op.issue }, sessionNote(agentComments?.get(op.issue) ?? []), { wedged: op.wedged })
365	    : null);
366	  if (body) await comment(gh, repo, op.issue, body);
367	  // Every spelling of the status being left goes: the item may have been filed by an
368	  // engine older than this one, and a swap that named one spelling would leave the
369	  // other standing (`apply-status`). What replaces it is ONE label.
370	  if (op.from) await clearStatus({ removeLabel }, gh, repo, { number: op.issue }, op.from);
371	  if (op.to) await addLabel(gh, repo, op.issue, op.to);
372	  if (op.close) await closeIssue(gh, repo, op.issue, op.close);
373	  if (op.clearInReview) {
374	    const res = await removeLabel(gh, repo, op.clearInReview.issue, op.clearInReview.label);
375	    if (res && res.status && res.status >= 400 && res.status !== 404) {
376	      problems.push(`could not clear ${op.clearInReview.label} on #${op.clearInReview.issue} (${res.status})`);
377	    }
378	  }
379	  log(op.kind === 'note'
380	    ? `- noted #${op.issue} (${op.rule})`
381	    : `- repaired #${op.issue} (${op.rule})${op.to ? ` -> ${op.to}` : ''}${op.close ? ` - closed ${op.close}` : ''}`);
382	  return true;
383	}
384	
385	// --- the forced wake (PRINCIPLES.md) ----------------------------------------------
386	
387	// Which standing items a `wake` dispatch names. Forcing a scheduled task IS waking
388	// its standing item, and this is that same lever reached from OUTSIDE the repo: the
389	// fleet enforcer dispatches this workflow with the task ids it wants run now, and
390	// the member wakes its own items with its own token. The enforcer therefore needs
391	// no issue access anywhere — the fan-out model the enforcer's sweeps are built on, where
392	// the enforcer dispatches and the member executes.
393	//
394	// An id is `pack/task` or a bare `task` resolved against this repo's own discovered
395	// tasks, so a caller spanning many members never has to know any one member's pack
396	// layout. Every id that matches nothing comes back in `unmatched`: a force whose
397	// report counts only what it woke reads as coverage it did not have.
398	//
399	// An item already in flight (`task:ready`, `task:executing`, `task:agent`) is left
400	// alone and reported as `already`, never re-woken — an episode boundary dropped on
401	// a live claim is exactly the livelock F18 describes.
402	//
403	// WHEN THE STANDING ITEM DOES NOT EXIST, forcing MINTS it (PRINCIPLES.md's other lever). A
404	// task that completes closes its item, and the next one appears only when the
405	// task next says yes — so between the two there is nothing to wake, and that gap
406	// is the common case rather than an edge: a daily task is missing its item for
407	// most of the day. A force that reported "nothing to wake" there would fail on
408	// most members most of the time, which is precisely what a fleet-wide converge
409	// lever must not do. The minted item is an ordinary standing item — same title,
410	// no qualifier — stamped `Woken:` so the task's cadence terms hold on it (a
411	// person's wake stands in for the cadence) while everything else it requires
412	// still applies; it is the task's live item, so the scheduler asks nothing beside it.
413	//
414	// A WOKEN-GATED task is the exception, and never minted: it has no standing item
415	// to stand in for — an item exists only because an issue named the task (a
416	// verification's `Task:` line, a marked request), and a bare one carries nothing
417	// its worker can read, so it can only park (#1721). Its items keep their own
418	// titles, so the force reaches them by the task path in the machine block: every
419	// open one not in flight is woken, and none at all is reported, never papered
420	// over with a mint.
421	export function planWake(spec, tasks = [], items = []) {
422	  const ids = String(spec ?? '').split(/[\s,]+/).map((s) => s.trim()).filter(Boolean);
423	  const wake = []; const create = []; const already = []; const unmatched = [];
424	  for (const id of ids) {
425	    const [a, b] = id.includes('/') ? id.split('/') : [null, id];
426	    const owners = tasks.filter((t) => t.id === b && (a === null || t.pack === a));
427	    if (owners.length !== 1) {
428	      unmatched.push({ id, why: owners.length ? `${owners.length} declared packs own a "${b}" task — name it as pack/task` : 'no declared pack owns a task by that name' });
429	      continue;
430	    }
431	    const owner = owners[0];
432	    const { pack, id: task } = owner;
433	    if (!isScheduledTask(owner.decl)) {
434	      const routed = items.filter((i) => {
435	        if (i.state !== 'open') return false;
436	        const byPath = taskIdFromPath(parseWorkItemBody(i.body).taskPath);
437	        return !!byPath && byPath.pack === pack && byPath.task === task;
438	      });
439	      if (!routed.length) {
440	        unmatched.push({ id, why: `"${pack}/${task}" is not on the schedule and has no open item — nothing stands for it to mint, so an item exists only where an issue names the task` });
441	        continue;
442	      }
443	      for (const item of routed) {
444	        if (IN_FLIGHT.includes(statusOf(item))) already.push({ id, issue: item.number });
445	        else wake.push({ id: `${pack}/${task}`, issue: item.number });
446	      }
447	      continue;
448	    }
449	    const item = items.find((i) => {
450	      if (i.state !== 'open') return false;
451	      const parsed = parseWorkItemTitle(i.title);
452	      return parsed && parsed.pack === pack && parsed.task === task;
453	    });
454	    if (!item) { create.push({ id: `${pack}/${task}`, pack, task, taskPath: owner.taskPath }); continue; }
455	    if (IN_FLIGHT.includes(statusOf(item))) { already.push({ id, issue: item.number }); continue; }
456	    wake.push({ id: `${pack}/${task}`, issue: item.number });
457	  }
458	  return { wake, create, already, unmatched };
459	}
460	
461	// The Context a forced standing item carries. It says the force is the only reason
462	// the item exists, because the executor still evaluates the precondition at pick:
463	// a force that finds no work must roll with its reason on record, not invent work.
464	export const FORCED_WAKE_CONTEXT =
465	  'Minted by a force — this task had no open standing item at the time. The wake stands in for the task\'s cadence; every other condition is still evaluated at pick, so converge to a no-op if there is nothing to do.';
466	
467	// The statuses that mean someone already holds this item — decoded, so an item any
468	// engine version filed answers the same. `running-agent` counts: the work is with a
469	// session, and waking would hand a second executor the same item.
470	const IN_FLIGHT = [STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT];
471	
472	// --- CLI: the thin I/O shell the vendored scheduler run workflow invokes ---------------
473	// Reads the work-item list, plans, applies. All GitHub access is the Action's
474	// GITHUB_TOKEN. Dormancy is the first gate, before any read — a project that has
475	// said it is out of the recurring work should not pay for the list that proves it.
476	
477	// Every WORK ITEM, state=all, via the ISSUES list API — never the search index
478	// (S6/F11: search is eventually consistent, and a family list that misses a
479	// just-created item mints a duplicate standing item). Bounded by the scheduled
480	// families' need for closed history: closed items are only interesting back to the
481	// widest period, so the listing stops once it is past that.
482	//
483	// MEMBERSHIP IS `isQueueItem`, the shared predicate, and not the title prefix
484	// (#1497). An adopted marked issue IS an item under the one-issue model
485	// (docs/PRINCIPLES.md) and keeps the person's own title forever, so a prefix test drops exactly
486	// that class — and job 2 is the ONLY site that releases a blocked item, so an
487	// ad-hoc item born blocked on a `Not-before:` sat sleeping past its instant with
488	// nothing left to wake it (#1267, #1349, #1351, #1396). The executor and the
489	// repair rules already read the queue through this predicate; this list was the one that
490	// did not.
491	export async function listWorkItems(gh, repo, { since = null, state = 'all' } = {}) {
492	  const out = [];
493	  for (let page = 1; ; page += 1) {
494	    const q = `state=${state}&sort=created&direction=desc&per_page=100&page=${page}`
495	      + (since ? `&since=${encodeURIComponent(since)}` : '');
496	    const { status, json } = await listIssuesByQuery(gh, repo, q);
497	    // A page that could not be read is not the end of the list. Breaking on it
498	    // truncates the queue mid-pagination and the run plans against the remainder:
499	    // a standing item whose page never arrived reads as absent, and the run mints a
500	    // second one beside it.
501	    if (status !== 200 || !Array.isArray(json)) {
502	      throw new Error(`could not list work items in ${repo} at page ${page} (${status}) — a truncated queue is not a shorter one`);
503	    }
504	    if (json.length === 0) break;
505	    for (const i of json) {
506	      if (i.pull_request) continue;
507	      if (!isQueueItem(i)) continue;
508	      out.push({
509	        number: i.number, title: i.title, body: i.body ?? '', state: i.state,
510	        labels: labelNames(i), created_at: i.created_at, closed_at: i.closed_at,
511	        updated_at: i.updated_at,
512	      });
513	    }
514	    if (json.length < 100) break;
515	  }
516	  return out;
517	}
518	
519	// Every OPEN issue carrying the mark and NO status, via the ISSUES list API
520	// filtered by label — never the search index, for the same reason the work-item
521	// list is not (S6/F11): a mark this list misses is a request that silently waits an
522	// hour, and one it misses TWICE is a request nobody notices was never picked up.
523	//
524	// The author's push permission comes back with each issue, because adoption gates
525	// the body's parameters on it (PRINCIPLES.md) and the payload's `author_association` is not
526	// that fact: `MEMBER` is any org member whatever their repo permission, and
527	// `COLLABORATOR` includes read-only collaborators (F30). A read that cannot answer
528	// leaves the flag `null`, which gates the parameters off — the safe end of a field
529	// that chooses a task, a model, or the right to land a change without review.
530	export async function listMarkedIssues(gh, repo, { permissionOf = null } = {}) {
531	  const out = [];
532	  const push = permissionOf ?? (async (login) => {
533	    const res = await collaboratorPermission(gh, repo, login);
534	    if (res.status === 404) return false;
535	    if (res.status !== 200) return null;
536	    return ['admin', 'maintain', 'write'].includes(res.json?.role_name ?? res.json?.permission ?? 'none');
537	  });
538	  const cache = new Map();
539	  // ONE QUERY PER MARK, unioned here. GitHub's `labels` filter is CONJUNCTIVE — a
540	  // comma-separated list selects the issues carrying EVERY name on it — so asking
541	  // for both marks at once asks for issues wearing both, which nothing does. The
542	  // retired `claude-task` spelling keeps working for whoever has it in muscle memory
543	  // or in a template, decoded forever like every legacy spelling (PRINCIPLES.md), and that
544	  // costs a second listing rather than a wider one.
545	  const seen = new Map();
546	  for (const label of [ORIGIN_AD_HOC, REQUEST_LABEL]) {
547	    for (let page = 1; ; page += 1) {
548	      const q = `state=open&labels=${encodeURIComponent(label)}&per_page=100&page=${page}`;
549	      const { status, json } = await listIssuesByQuery(gh, repo, q);
550	      // A list that could not be READ is not a list that is EMPTY, and the two are
551	      // indistinguishable downstream: adoption simply finds nothing to do and the run
552	      // reports success. Every request then waits for a person to notice, which is
553	      // the one thing this lane exists so nobody has to do.
554	      if (status !== 200 || !Array.isArray(json)) {
555	        throw new Error(`could not list open issues marked \`${label}\` in ${repo} (${status}) — an unreadable request list is not an empty one`);
556	      }
557	      if (json.length === 0) break;
558	      for (const i of json) {
559	        if (i.pull_request) continue;
560	        // A filed work item wearing the mark is not a request awaiting adoption: it is
561	        // already an item, and re-adopting one would rewrite its body under the run
562	        // holding it.
563	        if ((i.title ?? '').startsWith(WORK_PREFIX)) continue;
564	        // ANY status means this mark has been adopted — the exactly-once guard (PRINCIPLES.md).
565	        // Filtering here rather than in the plan keeps the permission reads to the
566	        // issues actually awaiting adoption.
567	        if (statusOf(i) !== null) continue;
568	        // An issue wearing both spellings comes back from both listings; it is one
569	        // request, and adopting it twice would rewrite the body of the item the first
570	        // adoption just made.
571	        if (seen.has(i.number)) continue;
572	        const author = i.user?.login ?? null;
573	        if (author && !cache.has(author)) cache.set(author, await push(author));
574	        seen.set(i.number, {
575	          number: i.number, title: i.title, body: i.body ?? '', state: i.state,
576	          labels: labelNames(i), author, authorHasPush: author ? cache.get(author) : null,
577	        });
578	      }
579	      if (json.length < 100) break;
580	    }
581	  }
582	  out.push(...seen.values());
583	  return out;
584	}
