586	// Which `Blocked-by` targets this run still has to read. A target need not be a
587	// work item — a fan-in blocks on whatever its children are — so states come from
588	// the fetched items first and a direct read otherwise, and `known` is what has
589	// already been answered.
590	//
591	// A marked issue's blockers count the same way: adoption decides whether the item
592	// it births is born blocked or ready, and an unread state is never `closed`, so a
593	// missing read delays the request rather than releasing it (PRINCIPLES.md).
594	//
595	// Extracted from `main` so it can be called at all. Nothing else here drives
596	// `main`, whose body is I/O against a live Action, so an identifier it names and
597	// never imports resolves at run time or not at all — and the request half went
598	// three days without executing once, behind an adoption list that was always
599	// empty (#1354).
600	export function blockersToResolve(items, requests, known) {
601	  const wanted = new Set();
602	  for (const i of items) {
603	    if (i.state !== 'open' || !isStatus(i, STATUS_BLOCKED)) continue;
604	    for (const n of parseWorkItemBody(i.body).blockedBy) if (!known.has(n)) wanted.add(n);
605	  }
606	  for (const r of requests) {
607	    for (const n of parseBlockedBy(r.body)) if (!known.has(n)) wanted.add(n);
608	  }
609	  return wanted;
610	}
