632	  collectSignalsFor, wake = '', log = console.log, setOutput = setStepOutput,
633	  phase = () => () => {},
634	}) {
635	  const { ensureLabels, addLabel, removeLabel, comment, closeIssue, createIssue, listComments } = await import('../world/github.mjs');
