637	  // Closed items matter only back to the run-history horizon — the longest any
638	  // cadence term looks; older history can never change a verdict.
639	  const since = new Date(new Date(now).getTime() - RUN_HORIZON_DAYS * 86400e3).toISOString();
640	  const endList = phase('list');
641	  // TWO LISTINGS, and the split is load-bearing. `since` filters on UPDATED time,
642	  // so a single horizoned listing cannot see an item nobody has touched since the
643	  // horizon - a blocked item sleeping on a far `Not-before`, a claim that went
644	  // silent and stayed silent. The OPEN half is therefore listed whole, however old
645	  // its youngest write, and the horizon is applied only to the CLOSED half, where
646	  // it is the run-history window the cadence terms actually read. The open half is
647	  // bounded by the open queue, which is small on every repo; the horizon is what
648	  // keeps the closed half from paging through the repository's whole history.
649	  const items = [
650	    ...await listWorkItems(gh, repo, { state: 'open' }),
651	    ...await listWorkItems(gh, repo, { state: 'closed', since }),
652	  ];
653	  const requests = await listMarkedIssues(gh, repo);
654	
655	  const known = new Map(items.map((i) => [i.number, i.state]));
656	  for (const n of blockersToResolve(items, requests, known)) {
657	    const { status, json } = await getIssue(gh, repo, n);
658	    known.set(n, status === 200 ? json?.state ?? null : null);
659	  }
660	
661	  // One comment read per EXECUTING item — never per item in the repo — so the
662	  // reclaim can measure the holder's own silence rather than the issue's.
663	  for (const item of items) {
664	    if (item.state !== 'open' || !isStatus(item, STATUS_RUNNING_EXECUTOR)) continue;
665	    item.livenessAt = lastLivenessAt(await listComments(gh, repo, item.number));
666	  }
667	
668	  // THE REPAIR PHASE'S OWN READS, and the only two the merge added. Both are
669	  // bounded by a handful of items in one state rather than by the queue: a comment
670	  // read per item holding an AGENT - the leash measures the holder's own progress,
671	  // which only its comments carry - and one issue read per park naming an
672	  // `Ends-when:` target, of which there are as many as there are approval parks.
673	  // Everything else the repair rules need is already in the two listings above.
674	  const agentComments = new Map();
675	  for (const item of items) {
676	    if (item.state !== 'open' || !isStatus(item, STATUS_RUNNING_AGENT)) continue;
677	    agentComments.set(item.number, await listComments(gh, repo, item.number));
678	  }
679	  const resolutions = new Map();
680	  for (const item of items) {
