 21	// every one after it. Lazy rather than a static or top-level-awaited import because
 22	// a module under `packs/` may do no work while it is being evaluated: discovery
 23	// imports every `pack.mjs` before activation is consulted.
 24	let modulesPromise = null;
 25	function signalModules() {
 26	  modulesPromise ??= Promise.all([import('./index.mjs'), import('./context.mjs')]);
