 35	// actually ran — a `rejected` item declined at pick and did nothing, so it does not
 36	// move the seam — anchors it at its start; none in the horizon falls back to the
 37	// task's default.
 38	export function windowFromRuns(task, runs, now) {
 39	  const nowMs = new Date(now).getTime();
 40	  const last = (runs?.list ?? []).find((r) => r.outcome !== 'obsolete');
 41	  const sinceMs = last && Number.isFinite(new Date(last.createdAt).getTime())
 42	    ? new Date(last.createdAt).getTime()
 43	    : nowMs - defaultWindowMs(task);
 44	  return { sinceIso: new Date(sinceMs).toISOString(), days: (nowMs - sinceMs) / DAY_MS };
