161	// the slug already and should not have to trust the environment for both halves.
162	export const runUrlFor = (repo, env = process.env) => (env.GITHUB_RUN_ID
163	  ? `${env.GITHUB_SERVER_URL ?? 'https://github.com'}/${repo}/actions/runs/${env.GITHUB_RUN_ID}`
