 51	      const res = await fetchImpl(`${api}${path}`, { headers });
 52	      if (res.status !== 200) return null;
 53	      try { return await res.json(); } catch { return null; }
 54	    },
 55	  };
 56	}
 57	
 58	// The task an item belongs to. A filed item says so in its title; an ADOPTED marked
 59	// issue keeps the person's own title and says so in the machine block its body carries
 60	// — the same two-step the dashboard's own reader makes, so a request-shaped run is not
 61	// silently counted as belonging to no task.
 62	export function taskOf(issue) {
 63	  const fromTitle = parseWorkItemTitle(issue?.title);
 64	  if (fromTitle) return { pack: fromTitle.pack, task: fromTitle.task };
 65	  const fromBody = taskIdFromPath(parseWorkItemBody(issue?.body).taskPath);
 66	  return fromBody ? { pack: fromBody.pack, task: fromBody.task } : null;
 67	}
 68	
 69	// --- the parks an item collected -------------------------------------------------
 70	// A park is a label an item WORE, so the only record of one is the label event that
 71	// applied it — the item's final labels say where it ended, never where it stopped on
 72	// the way. So each closed item's event listing is read once, on the fold that first
 73	// sees it closed, under the queue's own watermark.
 74	//
 75	// The kinds are decoded exactly as `parkOf` decodes them for a live item: today's
 76	// single `task:status:needs-human-<kind>`, the two-label era's `task:needs-human-<kind>`
 77	// sub-label, and a kind no engine here knows reading as `failure` — the conservative
 78	// lane, so a park whose word this code predates is never dropped.
 79	// @legacy-tolerance advisory:none retire:#1913
 80	const LEGACY_PARK_RE = /^task:needs-human-(.+)$/;
 81	
 82	export function parkKindOf(label) {
 83	  const name = String(label ?? '');
 84	  if (name === NEEDS_HUMAN) return 'failure';
 85	  const kind = name.startsWith(PARK_PREFIX)
 86	    ? name.slice(PARK_PREFIX.length)
 87	    : LEGACY_PARK_RE.exec(name)?.[1] ?? null;
 88	  if (kind === null) return null;
 89	  return PARK_KINDS.includes(kind) ? kind : 'failure';
 90	}
 91	
 92	// The park kinds one item collected, DEDUPED: an item bounced between a person and the
 93	// machine twice was parked for that kind once as far as "how often did this task need a
 94	// human" is concerned. `null` — never `[]` — when the listing could not be read, so an
 95	// unknown park count stays distinguishable from a clean run.
 96	export async function readParks({ reader, repo, number }) {
 97	  let events = null;
 98	  try { events = await reader.json(`/repos/${repo}/issues/${number}/events?per_page=100`); } catch { return null; }
 99	  if (!Array.isArray(events)) return null;
100	  const kinds = new Set();
101	  for (const event of events) {
102	    if (event?.event !== 'labeled') continue;
103	    const kind = parkKindOf(event?.label?.name);
104	    if (kind) kinds.add(kind);
105	  }
106	  return [...kinds];
107	}
108	
109	// One closed item → a record, or null when it is not this fold's business.
110	export function recordFor(issue, since) {
111	  if (!isQueueItem(issue)) return null;
112	  const closedAt = issue?.closed_at ?? null;
113	  if (!closedAt) return null;
114	  if (since && closedAt <= since) return null;
115	  const task = taskOf(issue);
116	  if (!task) return null;
117	  return {
118	    date: closedAt.slice(0, 10), closedAt, ...task, outcome: outcomeOf(issue) ?? 'none',
119	    number: issue?.number ?? null,
120	    // Filled by the caller from the item's own event listing; `null` until then, and
121	    // `null` still if that listing could not be read.
122	    parks: null,
123	  };
124	}
125	
126	// The whole read: `{ records, watermark, error? }`.
127	export async function readQueueOutcomes({ reader, repo, since, now, maxPages = 5 }) {
128	  const from = since || lookbackFrom(now);
129	  const records = [];
130	  try {
131	    for (let page = 1; page <= maxPages; page += 1) {
132	      const path = `/repos/${repo}/issues?state=closed&sort=updated&direction=desc`
133	        + `&since=${encodeURIComponent(from)}&per_page=100&page=${page}`;
134	      const batch = await reader.json(path);
135	      if (!Array.isArray(batch) || batch.length === 0) break;
136	      for (const issue of batch) {
137	        if (issue?.pull_request) continue;         // the issues endpoint answers with both
138	        const rec = recordFor(issue, since);
139	        if (rec) records.push(rec);
140	      }
141	      if (batch.length < 100) break;
142	    }
143	  } catch {
144	    return { records: [], watermark: since, error: 'the closed work items could not be listed' };
145	  }
146	  // One listing per item, and only for the items this fold is seeing close for the
147	  // first time — the watermark above is what bounds the cost. An item whose listing
148	  // fails keeps `parks: null` and its outcome row regardless.
149	  for (const rec of records) {
150	    if (rec.number === null) continue;
151	    rec.parks = await readParks({ reader, repo, number: rec.number });
152	  }
153	  const newest = records.map((r) => r.closedAt).sort().pop() ?? null;
154	  return { records, watermark: newest ?? since ?? null };
155	}
156	import { finding } from '../../../engine/checks/helpers/findings.mjs';
157	import {
158	  AUTOMERGE_TRAILER, AUTOMERGE_TRAILER_RE, policyVerdict, declaredMergeRules,
159	} from '../src/contract/merge-policy.mjs';
160	
161	// The armed-auto-merge gate: when a branch says it intends to land itself under
162	// a granular policy, the diff must actually sit inside that policy — re-checked
163	// here, at the Stop hook and on every PR, so a run that mis-measured (or lied
164	// about) its own diff goes red before GitHub's queued auto-merge can fire.
165	//
166	// SELF-GATING BY THE TRAILER, the shape improve-comments-scope keys on its
167	// pinned commit subject: a landing run stamps `Claudinite-Automerge-Policy:
168	// <expr>` into its final commit message (deliver-pr.md owns when), so this rule
169	// runs everywhere the pack is active and costs ~nothing on a branch that armed
170	// nothing. No trailer, no findings — a wide PR left open for review must stay
171	// green, since red CI would get it closed as failed rather than read. The LAST
172	// trailer on the branch wins: a run that re-measured after amending its scope
173	// states its final intent last.
174	//
175	// The policy is re-evaluated from the trailer, not re-read from the task
176	// declaration, because the branch may BE the thing changing declarations; what
177	// keeps the trailer honest is the policy engine's own self-widening guard — no
178	// granular policy covers a change to the policy sources — plus the landing lane
179	// only merging on the same verdict this rule computes.
180	const rule = {
181	  id: 'automerge-policy-scope',
182	  on_fail: 'block',
183	  scope: 'work',
184	  doc: 'packs/claudinite-tasks/README.md',
185	  description: 'A branch that stamps the Claudinite-Automerge-Policy trailer — its run intends to land its own PR — carries only a diff that policy actually covers',
186	  why: 'the trailer is a claim that this diff may merge with nobody looking; a diff outside the declared classes is exactly the unreviewed change the policy exists to stop, and only a check can hold the claim to the measurement',
187	
188	  run(work) {
189	    if (work.onDefaultBranch()) return [];
190	    // work.commits is newest-first (git log order), so the newest commit's
191	    // trailer — the branch's final stated intent — is the first match.
192	    const armed = work.commits.map((m) => AUTOMERGE_TRAILER_RE.exec(m)?.[1]).find(Boolean);
193	    if (armed === undefined) return [];
194	
195	    const deleted = new Set(work.deleted);
196	    const entries = [...new Set([...work.changedFiles, ...work.deleted])].sort().map((file) => ({
197	      file,
198	      before: work.readBase(file),
199	      after: deleted.has(file) ? null : work.read(file),
200	    }));
201	    const { rules, errors } = declaredMergeRules(work.packs, work.config);
202	    const verdict = policyVerdict({ policy: armed, entries, declaredRules: rules, ruleErrors: errors });
203	    if (verdict.mergeable) return [];
204	
205	    return verdict.problems.map((p) => finding(rule, {
206	      file: p.file ?? '(branch)',
207	      what: `this branch armed auto-merge (${AUTOMERGE_TRAILER}: ${armed}) but ${p.what}`,
208	      fix: p.file
209	        ? `revert or split out ${p.file}, or drop the trailer from the branch's last commit and leave the PR for review — never widen the policy to fit the diff`
210	        : 'make the diff satisfy the armed policy, or drop the trailer and leave the PR for review',
211	    }));
212	  },
213	};
214	
215	export default rule;

