  1	// THE GITHUB PORT. Every REST path this pack calls is spelled in this module or in
  2	// the published client it builds on (`public/github.mjs`), and nowhere else: a
  3	// caller names the OPERATION it wants — read this issue, swap this label, merge this
  4	// pull request — and never the URL that performs it. That is what makes the outward
  5	// edge countable and replaceable; a module that spelled its own path would be a
  6	// second GitHub client nothing knows about.
  7	//
  8	// The transport is `gh(path) -> { status, json }`, made by the client's `makeGh` and
  9	// passed to every operation as its first argument. It stays an injected function rather than
 10	// a bound client because the whole pack tests against a fake `gh`, and because the
 11	// fleet planner supplies its own reader over a different token.
 12	//
 13	// A non-2xx returns `{ status, json: null }` rather than throwing, so a 404 (no
 14	// release yet, missing file) is data, not an error. Callers that must not mistake
 15	// a refusal for an answer read the STATUS — a 403 from a repo whose Actions cannot
 16	// write puts a plausible object where the result should be.
 17	//
 18	// LABEL WRITES ARE GRANULAR, ALWAYS (docs/PRINCIPLES.md): add and remove NAMED
 19	// labels (POST/DELETE), never write the label SET (PUT). A set-write replaces from
 20	// a stale snapshot and clobbers concurrent transitions — a bug class GitHub's own
 21	// CLI shipped (cli/cli#4861) — and with a scheduler run and several executors all
 22	// moving labels at once, that is a correctness rule rather than a style preference.
 23	
 24	import { actionsEnv } from './actions.mjs';
 25	import { varsBag } from './vars-bag.mjs';
 26	// The transport, the call counter and the issue calls the tracker spells for itself
 27	// all live in the published client; this port is every OTHER path, over that
 28	// transport, and re-exports those so every caller in this pack still names one module.
 29	import {
 30	  makeGh, restCall, graphqlCall, apiCallCount, resetApiCallCount,
 31	  setIssueBody, patchIssue, postIssue, searchIssues, comment, dispatchWorkflow,
 32	  listWorkflowRuns, readWorkflowRun, readPagesSite,
 33	} from '../../public/github.mjs';
 34	
 35	export {
 36	  makeGh, restCall, graphqlCall, apiCallCount, resetApiCallCount,
 37	  setIssueBody, patchIssue, postIssue, searchIssues, comment, dispatchWorkflow,
 38	  listWorkflowRuns, readWorkflowRun, readPagesSite,
 39	};
 40	
 41	// --- issues -------------------------------------------------------------------
 42	
 43	export const readIssue = async (gh, repo, number) => {
 44	  const { status, json } = await gh(`/repos/${repo}/issues/${number}`);
 45	  return status === 200 ? json : null;
 46	};
 47	
 48	// The same read, with the status kept — for a caller that must tell "closed" from
 49	// "could not be read".
 50	export const getIssue = (gh, repo, number) => gh(`/repos/${repo}/issues/${number}`);
 51	
 52	export const setIssueTitle = (gh, repo, number, title) =>
 53	  gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { title } });
 54	
 55	export const reopenIssue = (gh, repo, number) =>
 56	  gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { state: 'open' } });
 57	
 58	export const closeIssue = (gh, repo, number, stateReason = 'completed') =>
 59	  gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { state: 'closed', state_reason: stateReason } });
 60	
 61	export async function createIssue(gh, repo, { title, body, labels = [] }) {
 62	  const { status, json } = await gh(`/repos/${repo}/issues`, { method: 'POST', body: { title, body, labels } });
 63	  // The STATUS is read, not just the body: a 403 from a repo whose Actions cannot
 64	  // create issues puts an error object where the issue should be, and a body-only
 65	  // destructure turns that refusal into a plausible object whose `.number` is
 66	  // simply undefined.
 67	  return { status, number: status >= 200 && status < 300 ? json?.number ?? null : null, json };
 68	}
 69	
 70	// One page of the repo's open issues, oldest first — the order the queue reads its
 71	// items in, so a page boundary cannot reorder them.
 72	export const listOpenIssuesPage = (gh, repo, page) =>
 73	  gh(`/repos/${repo}/issues?state=open&sort=created&direction=asc&per_page=100&page=${page}`);
 74	
 75	// One page of recently closed issues, newest first — a bounded look back over
 76	// settled items rather than the whole history.
 77	export const listClosedIssuesPage = (gh, repo, page) =>
 78	  gh(`/repos/${repo}/issues?state=closed&sort=updated&direction=desc&per_page=100&page=${page}`);
 79	
 80	// The issues listing under a caller-composed query string (already encoded): the
 81	// label/state/since filters each reader needs, without this module having to know
 82	// every combination.
 83	export const listIssuesByQuery = (gh, repo, query) => gh(`/repos/${repo}/issues?${query}`);
 84	
 85	// --- labels -------------------------------------------------------------------
 86	
 87	// Ensure every label exists before any is applied. Load-bearing, not cosmetic:
 88	// GitHub does not create a label when you apply one (the issues API 422s on an
 89	// unknown label), so the thing that assigns a label must guarantee it first.
 90	// Idempotent (201 created / 422 already exists are both success) and self-healing
 91	// — a deleted label reappears on the next run.
 92	export async function ensureLabels(gh, repo, labels) {
 93	  for (const { name, color, description } of labels) {
 94	    const res = await gh(`/repos/${repo}/labels`, { method: 'POST', body: { name, color, description } });
 95	    if (res.status === 201) continue;                       // created to spec — nothing further
 96	    if (res.status === 422) {
 97	      // The NAME is taken; that says nothing about the colour or description. A
 98	      // label GitHub auto-created (applying an unknown name to an issue mints it
 99	      // grey `ededed`, no description) would keep those defaults for good, because
100	      // POST 422s forever. So reconcile the shape, not just the existence — that
101	      // is what makes the self-healing claim above true for drift and not only for
102	      // deletion. PATCH is idempotent: an already-correct label is a no-op write.
103	      const fix = await gh(`/repos/${repo}/labels/${encodeURIComponent(name)}`, {
104	        method: 'PATCH', body: { color, description },
105	      });
106	      if (fix.status !== 200) console.log(`! could not reconcile label "${name}": ${fix.status}`);
107	      continue;
108	    }
109	    console.log(`! could not ensure label "${name}": ${res.status}`);
110	  }
111	}
112	
113	export const addLabel = (gh, repo, number, name) =>
114	  gh(`/repos/${repo}/issues/${number}/labels`, { method: 'POST', body: { labels: [name] } });
115	
116	// A label that is already absent 404s; that is the desired end state, so it is
117	// success. Nothing here reads the response beyond reporting it.
118	export const removeLabel = (gh, repo, number, name) =>
119	  gh(`/repos/${repo}/issues/${number}/labels/${encodeURIComponent(name)}`, { method: 'DELETE' });
120	
121	// The swap every state transition makes. Remove-then-add, and NOT atomic —
122	// GitHub has no atomic label swap. That is safe because labels are visibility and
123	// the pick filter, never the arbiter (the claim comments are); what a torn swap
124	// CAN leave is an open item wearing no state label at all, which the repair phase
125	// repairs (docs/PRINCIPLES.md).
126	export async function swapLabel(gh, repo, number, from, to) {
127	  await removeLabel(gh, repo, number, from);
128	  return addLabel(gh, repo, number, to);
129	}
130	
131	// --- comments -----------------------------------------------------------------
132	
133	// The ONE sanctioned edit to a comment, and the reason the arbitration record is
134	// no longer strictly append-only: an executor striking its OWN claim on the way
135	// out (docs/PRINCIPLES.md). Only a claim's author ever edits it, so a claim can be
136	// withdrawn but never forged earlier, and comment ids still give the total order
137	// arbitration reads.
138	export const editComment = (gh, repo, commentId, body) =>
139	  gh(`/repos/${repo}/issues/comments/${commentId}`, { method: 'PATCH', body: { body } });
140	
141	export const listComments = async (gh, repo, number) => {
142	  const out = [];
143	  for (let page = 1; ; page += 1) {
144	    const { status, json } = await gh(`/repos/${repo}/issues/${number}/comments?per_page=100&page=${page}`);
145	    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
146	    out.push(...json);
147	    if (json.length < 100) break;
148	  }
149	  return out;
150	};
151	
152	// --- permission ---------------------------------------------------------------
153	
154	// A collaborator's permission on the repo — how the queue tells an owner's word
155	// from a passer-by's. A non-200 is "cannot tell", never "no permission".
156	export const collaboratorPermission = (gh, repo, login) =>
157	  gh(`/repos/${repo}/collaborators/${encodeURIComponent(login)}/permission`);
158	
159	// --- pull requests ------------------------------------------------------------
160	
161	export const listOpenPulls = (gh, repo) => gh(`/repos/${repo}/pulls?state=open&per_page=100`);
162	
163	export const readPull = (gh, repo, number) => gh(`/repos/${repo}/pulls/${number}`);
164	
165	export const mergePull = (gh, repo, number, body) =>
166	  gh(`/repos/${repo}/pulls/${number}/merge`, { method: 'PUT', body });
167	
168	export const closePull = (gh, repo, number) =>
169	  gh(`/repos/${repo}/pulls/${number}`, { method: 'PATCH', body: { state: 'closed' } });
170	
171	// --- refs, branches and trees --------------------------------------------------
172	
173	// Delete a branch ref. 204 is the success; anything else is litter left behind,
174	// never a failed run — the branch is not the deliverable.
175	export const deleteBranchRef = (gh, repo, ref) =>
176	  gh(`/repos/${repo}/git/refs/heads/${encodeURIComponent(ref)}`, { method: 'DELETE' });
177	
178	export const readBranch = (gh, repo, branch) => gh(`/repos/${repo}/branches/${branch}`);
179	
180	export const readTree = (gh, repo, ref) => gh(`/repos/${repo}/git/trees/${ref}`);
181	
182	// --- commits, runs and releases --------------------------------------
183	
184	export const readCommit = (gh, repo, sha) => gh(`/repos/${repo}/commits/${sha}`);
185	
186	export const listRunsForSha = (gh, repo, sha) =>
187	  gh(`/repos/${repo}/actions/runs?head_sha=${sha}&per_page=100`);
188	
189	export const latestRelease = (gh, repo) => gh(`/repos/${repo}/releases/latest`);
190	
191	// A repository Actions variable, answered from the executor's vars bag in the shape the
192	// REST read once returned. Kept at this name for a member's local pack that imports it;
193	// the API route itself is never asked, because the Actions GITHUB_TOKEN is refused on it
194	// in every member (`repo-variables-through-the-bag`).
195	export const readRepoVariable = async (_gh, _repo, name, env = actionsEnv()) => {
196	  const bag = varsBag(env);
197	  return bag && name in bag ? { status: 200, json: { name, value: String(bag[name]) } } : { status: 404, json: null };
198	};
  1	// The tasks-usage-fold work step - the module the runner calls `worker` on
  2	// (cwd = this task dir, bounded by code_work_timeout). The whole
  3	// task: no agent phase.
  4	//
  5	// It holds NO counting logic. The counting and folding are `fold-tasks-usage.mjs`,
  6	// its sibling; the reads are `read-run-costs.mjs` and `read-items.mjs` beside it.
  7	// This file is the I/O shell:
  8	//
  9	//   1. read the prior file from the BASE TIP — never the working tree, which may be
 10	//      sitting on another task's branch;
 11	//   2. list the scheduler's and the executor's completed runs past
 12	//      `runsFoldedThrough`, and for each read its jobs (the billed minutes) and, for
 13	//      a scheduler tick, its log (the cost record a tick has nowhere else to leave);
 14	//   3. list the work items that CLOSED past `queueFoldedThrough` and read each one's
 15	//      timeline — its outcome, the parks it collected, the four latencies its label
 16	//      events answer, and the executor's cost record riding its comments;
 17	//   4. fold: hour rows over the last three days, day rows over the last month, week
 18	//      rows advanced past `foldedThrough`;
 19	//   5. deliver the regenerated `.claudinite/local/tasks-usage.GENERATED.json`, and
 20	//      open NOTHING when the recompute is byte-identical apart from its stamp.
 21	//
 22	// THE API BUDGET, which is the reason the reads are shaped as they are. Per fold:
 23	// two run listings, flat; one jobs listing per run this fold has not seen; at most
 24	// four job-log reads (two scheduler ticks a day, at most two jobs each); one issues
 25	// listing page; and one timeline read per item closing for the first time. On this
 26	// repo's own cadence — two ticks a day, a quiet queue — the run half of that is
 27	// under ten calls a day, which `test/tasks/tasks-usage-fold/read-run-costs.test.mjs`
 28	// asserts by counting the fetches a representative day makes.
 29	//
 30	// The aggregate lives under `.claudinite/local/` because that is the repo-owned area
 31	// the vendoring refresh never touches; `merge=ours` reaches it through the mount's
 32	// own `.gitattributes`, whose `*GENERATED*` pattern the engine converges.
 33	
 34	import { readFileSync } from 'node:fs';
 35	import { baseTip, readAt, remoteUrl } from '../../public/delivery.mjs';
 36	import { AUTOMERGE_TRAILER } from '../../src/contract/merge-policy.mjs';
 37	import {
 38	  encodeTasksUsageFile, decodeTasksUsageFile, renderTasksUsageFile, withoutStamp, TASKS_USAGE_PATH,
 39	} from '../../src/items/tasks-usage-format.mjs';
 40	import { foldTasksUsage } from './fold-tasks-usage.mjs';
 41	import { makeReader, readRunCosts } from './read-run-costs.mjs';
 42	import { readClosedItems } from './read-items.mjs';
 43	import { settingsPath } from '../../../../engine/settings-file.mjs';
 44	
 45	
 46	const PR_BRANCH_PREFIX = 'claudinite/tasks-usage-fold';
 47	const PACK_ID = 'claudinite-tasks';
 48	
 49	// The run's own logger, under the task's name and its item. Module-level because the
 50	// helpers below log too; `worker` takes the one the runner built.
 51	let log = console.log;
 52	
 53	// What a minute of Actions costs this repo, from the pack's own config. UNSET IS
 54	// NOT ZERO: a public repo bills nothing and a private one bills something, and a
 55	// fold that wrote `spend: 0` for the second would be stating a figure nobody gave
 56	// it. Absent, no row in the file carries a spend at all and a reader says so.
 57	export function minuteRateFrom(config, packId = PACK_ID) {
 58	  const rate = config?.packConfig?.[packId]?.actionsMinuteRate;
 59	  return typeof rate === 'number' && Number.isFinite(rate) && rate >= 0 ? rate : null;
 60	}
 61	
 62	export async function worker({ root, repo, token, defaultBranch, automerge, deliver, log: runLog }) {
 63	  log = runLog;
 64	  const base = defaultBranch ?? 'main';
 65	  const remote = remoteUrl(repo, token);
 66	
 67	  let config = {};
 68	  try { config = JSON.parse(readFileSync(settingsPath(root), 'utf8')); } catch { /* no declaration */ }
 69	  const minuteRate = minuteRateFrom(config);
 70	  if (minuteRate === null) log('no `actionsMinuteRate` in this pack\'s config — the file records minutes and no spend');
 71	
 72	  const baseSha = baseTip(root, remote, base);
 73	  let prior = {};
 74	  try { prior = decodeTasksUsageFile(JSON.parse(readAt(root, baseSha, TASKS_USAGE_PATH) ?? '{}')); } catch { /* unparsable → refold */ }
 75	
 76	  const now = new Date().toISOString();
 77	  const reader = makeReader({ token });
 78	
 79	  // Each source is INDEPENDENTLY fail-soft: one that cannot be read costs its own
 80	  // rows this run and leaves its own watermark where it was, so the next fold
 81	  // retries exactly what it missed.
 82	  const runs = await readRunCosts({ reader, repo, since: prior.runsFoldedThrough ?? null, now });
 83	  if (runs.error) log(`${runs.error} — the run and cost rows are unchanged this run`);
 84	  if (runs.truncated) log('more runs are waiting than one fold reads — the watermark stops at the last one measured');
 85	
 86	  const items = await readClosedItems({
 87	    reader, repo, since: prior.queueFoldedThrough ?? null, now,
 88	    schedulerRuns: runs.runs.filter((r) => r.workflow === 'scheduler'),
 89	  });
 90	  if (items.error) log(`${items.error} — the outcome, park and latency rows are unchanged this run`);
 91	
 92	  const today = now.slice(0, 10);
 93	  const text = renderTasksUsageFile(encodeTasksUsageFile(foldTasksUsage({
 94	    prior,
 95	    today,
 96	    now,
 97	    generated: now,
 98	    minuteRate,
 99	    runs: runs.runs,
100	    runsFoldedThrough: runs.watermark,
101	    items: items.records,
102	    queueFoldedThrough: items.watermark,
103	  })));
104	
105	  // Compared WITHOUT the freshness stamp, which moves every run by construction: a
106	  // day on which nothing ran must still open nothing.
107	  const landed = readAt(root, baseSha, TASKS_USAGE_PATH);
108	  if (landed !== null && withoutStamp(landed) === withoutStamp(text)) {
109	    log(`${runs.runs.length} run(s) and ${items.records.length} closed item(s) folded — recompute is byte-identical, nothing to deliver`);
110	    return;
111	  }
112	
113	  const pr = await deliver({
114	    stamp: today, branchPrefix: PR_BRANCH_PREFIX,
115	    files: { [TASKS_USAGE_PATH]: text },
116	    message: `Claudinite: fold tasks usage\n\n${AUTOMERGE_TRAILER}: ${automerge}`,
117	    title: 'Claudinite: tasks usage fold',
118	    body: [
119	      `Regenerated \`${TASKS_USAGE_PATH}\` from this repo's scheduler and executor run`,
120	      "listings, each run's jobs, the cost records those runs printed, and the work",
121	      'items that have closed since the last fold.',
122	      '',
123	      'Per day and per workflow: runs, jobs, billed minutes and — only where this',
124	      "pack's config carries `actionsMinuteRate` — the spend they imply. Per run: the",
125	      'API calls it made and its wall time per phase. Per task: what its occurrences',
126	      'came to, the parks they collected, and the four latency samples their label',
127	      'events answer.',
128	      '',
129	      'Every tier is appended once past its own watermark; a recompute that differs',
130	      'only in its `generated` stamp opens no pull request at all. Machine-written —',
131	      'never hand-edit it.',
132	    ].join('\n'),
133	  });
134	  log(`${runs.runs.length} run(s) and ${items.records.length} closed item(s) folded — `
135	    + `${pr.reused ? 'updated' : 'opened'} PR ${pr.number !== null ? `#${pr.number}` : `on ${pr.branch}`}`
136	    + `${pr.merged ? ' (landed)' : pr.delivery === 'review' ? ' (left for review)' : ''}`);
137	}

