  1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
  2	import { stripComments } from '../../../engine/checks/helpers/code-scanning.mjs';
  3	import { FREQUENCIES, CADENCES, scheduleTermFor, cadenceTermFor, cadenceOf } from '../src/contract/calendar.mjs';
  4	import { MODEL_FAMILIES } from '../src/contract/model-map.mjs';
  5	import {
  6	  OUTCOMES, OUTCOME_NO_PR, DEFAULT_AGENT_MODEL, descriptionProblem, normalizeTaskDeclaration,
  7	  TRIGGERS, TRIGGER_SCHEDULE, TRIGGER_REQUEST,
  8	} from '../src/contract/task-contract.mjs';
  9	import { validatePreconditions, termsMap, preconditionNeedsItem } from '../src/contract/precondition-policy.mjs';
 10	import { TASK_DECLARATION_PATH_RE, readDeclarationFields } from '../src/contract/task-declaration-text.mjs';
 11	
 12	// Every scheduler task is a `tasks/<name>/task.json` carrying the declaration
 13	// contract (docs/PRINCIPLES.md) with legal enum values. This
 14	// asserts that shape statically at author time — the executor and scheduler
 15	// validate the same contract at run time (task-contract.mjs), so an illegal
 16	// condition/model/outcome, or a missing field, is caught here first.
 17	//
 18	// RELEVANCE FIRST (engine/checks/README.md): gated on a task declaration file
 19	// existing, so the check is inert on any repo without tasks. Static text over the
 20	// self-contained file — a `task.json` parsed whole — keyed off the canonical enum
 21	// lists so the legal values never drift from the runtime validator.
 22	
 23	// The term names the task's own `preconditions.mjs` exports, read as text: the
 24	// check runs over a file listing, not a module graph, so it recognises a
 25	// task-local condition by the key that defines it. A term the file computes
 26	// rather than spells is not found, and its declaration reads as unknown — which
 27	// is the same "write it so a reader can see it" the literal rule above states.
 28	// Read as TEXT, never imported: a check must not execute a member's own module. So
 29	// each term is its name plus the two properties of it a declaration can be wrong
 30	// about — `needsItem`, which decides whether the term can be judged at a tick at
 31	// all, and `takesArg`, which decides whether the declaration may carry one after
 32	// the colon. Either quote style, because a member's file is its author's.
 33	const TERM_NAME = /^ {2}['"]([^'"]+)['"]:/gm;
 34	function siblingTerms(ctx, taskFile) {
 35	  const text = ctx.read(taskFile.replace(/task\.json$/, 'preconditions.mjs'));
 36	  if (text === null) return new Map();
 37	  const body = stripComments(text);
 38	  const start = body.indexOf('export const terms');
 39	  if (start === -1) return new Map();
 40	  const section = body.slice(start);
 41	  const named = [...section.matchAll(TERM_NAME)];
 42	  return termsMap(Object.fromEntries(named.map((m, i) => {
 43	    const block = section.slice(m.index, named[i + 1]?.index ?? section.length);
 44	    return [m[1], {
 45	      signals: [],
 46	      needsItem: /\bneedsItem\s*:\s*true\b/.test(block),
 47	      takesArg: /\btakesArg\s*:\s*true\b/.test(block),
 48	    }];
 49	  })));
 50	}
 51	
 52	const rule = {
 53	  id: 'task-declaration-shape',
 54	  on_fail: 'block',
 55	  description: 'A tasks/<name>/task.json carries the task contract (id, description, trigger, preconditions, expected_outcome) with legal enum values, a stated trigger saying who mints an occurrence and a well-formed precondition expression stating when the task runs; an agentic task names its worker file and bounds its run, and any code_work carries a timeout and stays task-local',
 56	  doc: 'packs/claudinite-tasks/README.md',
 57	  why: 'the scheduler run and executor read agent_model/expected_outcome/preconditions from this file, not the work item — an illegal or missing value means a task never fires, fires wrong, or writes past its ceiling',
 58	
 59	  run(ctx) {
 60	    const out = [];
 61	    for (const file of ctx.files.filter((f) => TASK_DECLARATION_PATH_RE.test(f))) {
 62	      const text = ctx.read(file);
 63	      if (text === null) continue;
 64	      const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));
 65	      const advise = (what, fix) => out.push(finding(rule, { file, on_fail: 'advise', what, fix }));
 66	
 67	      const decl = readDeclarationFields(text);
 68	      if (decl.error) {
 69	        flag(`is not a JSON object: ${decl.error}`, 'write one JSON object: { "id", "description", "preconditions", "expected_outcome", … }');
 70	        continue;
 71	      }
 72	      const str = (key) => (typeof decl.scalar(key) === 'string' ? decl.scalar(key) : null);
 73	      const hasNum = (...keys) => keys.some((key) => typeof decl.scalar(key) === 'number');
 74	
 75	      const enumField = (key, legal) => {
 76	        const v = str(key);
 77	        if (v === null) flag(`declares no "${key}"`, `add "${key}": one of ${legal.join(', ')}`);
 78	        else if (!legal.includes(v)) flag(`"${key}" is "${v}", not a legal value`, `use one of: ${legal.join(', ')}`);
 79	      };
 80	      // `frequency` is retired (docs/PRINCIPLES.md): the cadence is a condition in
 81	      // `preconditions`, and nothing reads the field any more. BLOCKING, unlike the
 82	      // renames below, because the runtime contract rejects it too - a declaration
 83	      // carrying it no longer runs, so saying so at author time is the whole point.
 84	      // Flagged by NAME rather than left unrecognised, so its author is told the term
 85	      // to write instead of reading as a task that simply forgot its cadence.
 86	      if (decl.has('frequency')) {
 87	        const declared = str('frequency');
 88	        const term = FREQUENCIES.includes(declared) ? cadenceTermFor(declared) : scheduleTermFor(`<${CADENCES.join('|')}>`);
 89	        flag('declares "frequency", which is retired', term === null
 90	          ? 'drop the field, and a "none" beside it, and write "trigger": "request" - "manual" meant no schedule at all'
 91	          : `write the cadence as a condition - "preconditions": [${JSON.stringify(term)}, …] - with "trigger": "schedule" beside it, and drop a "none"`);
 92	      }
 93	      // `trigger` says whether the scheduler asks this task at every tick, and is
 94	      // REQUIRED: nothing derives it from the shape of the conditions any more, so a
 95	      // declaration stating none fails contract validation and the task never runs.
 96	      // Blocking here is what turns that into an edit an author can make, at the line
 97	      // the field goes on, rather than a silent absence from the scheduler's roster.
 98	      //
 99	      // Beside the value, one pairing cannot work: a `schedule` task whose expression
100	      // reads the ITEM has nothing to be judged against at a tick — the scheduler's
101	      // own ask carries no item — so the term errors on every tick and the task's lane
102	      // fills with failed runs rather than ever declining.
103	      if (!decl.has('trigger')) {
104	        flag('declares no "trigger"',
105	          `add "trigger": one of ${TRIGGERS.join(', ')}. "${TRIGGER_SCHEDULE}" is asked by the scheduler at every tick, "${TRIGGER_REQUEST}" runs only from an item somebody creates`);
106	      } else {
107	        const trigger = str('trigger');
108	        if (trigger === null || !TRIGGERS.includes(trigger)) {
109	          flag(`"trigger" is ${JSON.stringify(decl.scalar('trigger') ?? null)}, not a legal value`,
110	            `use one of: ${TRIGGERS.join(', ')} — "${TRIGGER_SCHEDULE}" is asked by the scheduler at every tick, "${TRIGGER_REQUEST}" runs only from an item somebody creates`);
111	        } else if (trigger === TRIGGER_SCHEDULE && decl.list('preconditions')
112	          && preconditionNeedsItem(decl.list('preconditions'), siblingTerms(ctx, file))) {
113	          flag('a "schedule" task states a condition that reads the item itself',
114	            `write "trigger": "${TRIGGER_REQUEST}" — a condition about one item can only be judged once an item exists, and the scheduler's ask at a tick has none, so this task would fail every tick instead of declining`);
115	        } else if (trigger === TRIGGER_REQUEST && cadenceOf(decl.list('preconditions'))) {
116	          // Inert, not merely redundant, which is why this blocks: nothing asks a
117	          // request task, so every occurrence of it is an item somebody created,
118	          // every such item carries `Woken:`, and a wake stands in for the cadence.
119	          // The term cannot decline a single run, and reads as though it could.
120	          flag('a "request" task states a cadence term',
121	            'drop the term — nothing asks this task, so every item of it is one somebody created and carries `Woken:`, which satisfies a cadence; the term can never decline a run, it only reads as though it limits the lever');
122	        }
123	      }
124	
125	      // agent_model is OPTIONAL: absent means no agent (task-defaults.mjs), so the
