1	// The counting and folding core of the tasks-usage fold. Pure: it takes what the
2	// readers found, the prior file and today's UTC date, and returns the next file's
3	// named-counter shape. Nothing here reads a clock, a network or a disk.
4	//
5	// APPEND-ONCE, EVERY TIER. Each source is a rate-limited listing read past its own
6	// watermark, so a run or an item is folded on the one pass that first sees it and
7	// never again — there is no local source to recompute from, unlike the session fold's
8	// capture files. Both watermarks are monotone over settled facts (a completed run's
9	// start does not move; a closed item's outcome is written at convergence), which is
10	// the whole exactly-once mechanism.
11	//
12	// UNKNOWN IS NOT ZERO, throughout. A run whose jobs listing could not be read
13	// contributes to `runs` and leaves `jobs` and `minutesBilled` alone; a repo with no
14	// `actionsMinuteRate` carries no `spend` anywhere; a latency whose far end never
15	// happened has no key. An accumulator starts a field at the first bucket that
16	// actually carries it rather than seeding every bucket with a zero.
17	
18	import {
19	  TASKS_USAGE_FIELDS, BUCKET_FIELDS, WORKFLOW_FIELDS, RUN_FIELDS, LATENCY_FIELDS,
20	  QUEUE_OUTCOMES, COUNTER_GROUPS, WEEK_GROUPS, HOUR_GROUPS, hourKey, sortKeys,
21	} from '../../src/items/tasks-usage-format.mjs';
22	import { PARK_KINDS } from '../../public/task-constants.mjs';
23	
24	// How long an hour row lives — three days, the session fold's own window, so the
25	// two files' live tiers reach the same distance back.
26	export const HOUR_WINDOW_HOURS = 72;
27	
28	// How long a day row lives. A month, again matching the session file, because the
29	// cost panels read a month of days and the week rows keep what falls out.
30	export const DAY_WINDOW_DAYS = 30;
31	
32	export const withinHourWindow = (key, nowIso, hours = HOUR_WINDOW_HOURS) => {
33	  const age = (new Date(`${String(nowIso).slice(0, 13)}:00:00Z`) - new Date(`${key}:00:00Z`)) / 3600000;
34	  return Number.isFinite(age) && age >= 0 && age < hours;
35	};
36	
37	export const withinDayWindow = (date, today, days = DAY_WINDOW_DAYS) => {
38	  const age = (new Date(`${today}T00:00:00Z`) - new Date(`${date}T00:00:00Z`)) / 86400000;
39	  return Number.isFinite(age) && age >= 0 && age < days;
40	};
41	
42	// An empty bucket: every counter group present and no scalar at all, so a field
43	// starts from the first thing that has an opinion about it.
44	const emptyBucket = (groups) => Object.fromEntries(groups.map((g) => [g, {}]));
45	
46	// Add `n` into `row[field]`, starting the field at the first contribution rather
47	// than at zero. `null`/`undefined` adds nothing — that is the whole unknown-is-not-
48	// zero rule in one function.
49	function add(row, field, n) {
50	  if (!Number.isFinite(n)) return;
51	  row[field] = (row[field] ?? 0) + n;
52	}
53	
54	// Merge one counter row into another, field-wise, under the same rule.
55	function addRow(into, from, fields) {
56	  for (const f of fields) add(into, f, from?.[f]);
57	}
58	
59	// --- what the runs cost ----------------------------------------------------------
60	
61	// One run's contribution to a bucket: its workflow's row, the bucket's own scalars,
62	// and — in the tiers that carry it — the per-run entry keyed by the run id.
63	//
64	// A run is counted under the day and hour its START falls in, never its end: a run
65	// that crossed midnight was a run of the day it began, which is also the day the
66	// listing's own watermark orders it by.
67	export function addRunToBucket(bucket, run, { minuteRate = null, withRunCosts = true } = {}) {
68	  const workflow = (bucket.workflows[run.workflow] ??= {});
69	  const spend = minuteRate !== null && Number.isFinite(run.minutesBilled)
70	    ? run.minutesBilled * minuteRate
71	    : null;
72	
73	  for (const [field, n] of [['runs', 1], ['jobs', run.jobs], ['minutesBilled', run.minutesBilled], ['spend', spend]]) {
74	    add(workflow, field, n);
75	    add(bucket, field, n);
76	  }
77	
78	  if (!run.cost) return bucket;
79	  // The cost record's own figures: into the bucket's scalars always, and into the
80	  // per-run map where the tier keeps one.
81	  add(bucket, 'apiCalls', run.cost.apiCalls);
82	  for (const [phase, ms] of Object.entries(run.cost.phaseMs ?? {})) add(bucket, phase, ms);
83	  if (withRunCosts) {
84	    const entry = (bucket.runCosts[String(run.id)] ??= {});
85	    add(entry, 'apiCalls', run.cost.apiCalls);
86	    for (const [phase, ms] of Object.entries(run.cost.phaseMs ?? {})) add(entry, phase, ms);
87	  }
88	  return bucket;
89	}
90	
91	// The executor's cost records arrive with the ITEMS rather than with the runs, and
92	// one run leaves a snapshot on every item it settled. So they are collected per run
93	// id and reduced by MAXIMUM: the counters only ever grow within a run, so the
94	// largest snapshot is the run's total as of its last item. Taking the sum would
95	// count one run's whole spend once per item it touched.
96	export function costsByRun(items) {
97	  const out = new Map();
98	  for (const item of items ?? []) {
99	    for (const cost of item.costs ?? []) {
100	      const prior = out.get(cost.runId);
101	      if (!prior) { out.set(cost.runId, cost); continue; }
102	      out.set(cost.runId, {
103	        ...cost,
104	        apiCalls: Math.max(prior.apiCalls ?? -Infinity, cost.apiCalls ?? -Infinity),
105	        phaseMs: Object.fromEntries(
106	          [...new Set([...Object.keys(prior.phaseMs ?? {}), ...Object.keys(cost.phaseMs ?? {})])]
107	            .map((p) => [p, Math.max(prior.phaseMs?.[p] ?? 0, cost.phaseMs?.[p] ?? 0)]),
108	        ),
109	      });
110	    }
111	  }
112	  // A max over an empty set is `-Infinity`, which is not a count: fold it back to
113	  // "no opinion" so the encoder writes `null`.
114	  for (const [id, cost] of out) {
115	    if (!Number.isFinite(cost.apiCalls)) out.set(id, { ...cost, apiCalls: null });
116	  }
117	  return out;
118	}
119	
120	// The runs a fold saw, with each executor run's cost record attached from the items
121	// it settled. A run the item side knows about but the run listing does not is NOT
122	// invented here: the listing is what says a run happened, and a stray record on an
123	// item whose run fell outside the window is one this fold simply has no bucket for.
124	export function withItemCosts(runs, items) {
125	  const byRun = costsByRun(items);
126	  return (runs ?? []).map((run) => (run.cost ? run : { ...run, cost: byRun.get(String(run.id)) ?? null }));
127	}
128	
129	// --- what the items came to -------------------------------------------------------
130	
131	export function addItemToDay(day, item) {
132	  const key = `${item.pack}/${item.task}`;
133	  const outcome = QUEUE_OUTCOMES.includes(item.outcome) ? item.outcome : 'none';
134	  add((day.queue[key] ??= {}), outcome, 1);
135	  // `parks: null` is a timeline that could not be read — unknown, so nothing is
136	  // written; an empty array is a real answer and writes nothing either, because a
137	  // task that needed no human has no park to count.
138	  for (const kind of item.parks ?? []) {
139	    if (PARK_KINDS.includes(kind)) add((day.parks[key] ??= {}), kind, 1);
140	  }
141	  if (item.latency && Object.keys(item.latency).length) {
142	    day.latency[String(item.number)] = { ...item.latency };
143	  }
144	  return day;
145	}
146	
147	// --- the tiers ---------------------------------------------------------------------
148	
149	export function foldHours({ prior = {}, runs = [], now, minuteRate = null }) {
150	  const hours = {};
151	  for (const [key, row] of Object.entries(prior)) {
152	    if (!withinHourWindow(key, now)) continue;
153	    hours[key] = { ...emptyBucket(HOUR_GROUPS), ...structuredClone(row) };
154	  }
155	  for (const run of runs) {
156	    const key = hourKey(run.startedAt);
157	    if (!withinHourWindow(key, now)) continue;
158	    addRunToBucket((hours[key] ??= emptyBucket(HOUR_GROUPS)), run, { minuteRate, withRunCosts: true });
159	  }
160	  return hours;
161	}
162	
163	export function foldDays({ prior = {}, runs = [], items = [], today, minuteRate = null }) {
164	  const days = {};
165	  for (const [date, row] of Object.entries(prior)) {
166	    if (!withinDayWindow(date, today)) continue;
167	    days[date] = { ...emptyBucket(COUNTER_GROUPS), ...structuredClone(row) };
168	  }
169	  for (const run of runs) {
170	    const date = String(run.startedAt ?? '').slice(0, 10);
171	    if (!date || !withinDayWindow(date, today)) continue;
172	    addRunToBucket((days[date] ??= emptyBucket(COUNTER_GROUPS)), run, { minuteRate, withRunCosts: true });
173	  }
174	  for (const item of items) {
175	    if (!item.date || !withinDayWindow(item.date, today)) continue;
176	    addItemToDay((days[item.date] ??= emptyBucket(COUNTER_GROUPS)), item);
177	  }
178	  return days;
179	}
180	
181	// The ISO-8601 week a UTC date falls in, `YYYY-Www` — computed rather than
182	// approximated, because an off-by-one would mis-file a whole week's row.
183	export function isoWeek(date) {
184	  const d = new Date(`${date}T00:00:00Z`);
185	  const day = (d.getUTCDay() + 6) % 7;                 // Mon=0 … Sun=6
186	  d.setUTCDate(d.getUTCDate() - day + 3);              // the week's Thursday
187	  const year = d.getUTCFullYear();
188	  const firstThursday = new Date(Date.UTC(year, 0, 4));
189	  const offset = (firstThursday.getUTCDay() + 6) % 7;
190	  firstThursday.setUTCDate(firstThursday.getUTCDate() - offset + 3);
191	  const week = 1 + Math.round((d - firstThursday) / (7 * 86400000));
192	  return `${year}-W${String(week).padStart(2, '0')}`;
193	}
194	
195	// The days to fold into weeks this run: every day that closed strictly after the
196	// watermark and strictly before today, in order. Days close strictly in order, so a
197	// single monotone mark is the whole exactly-once mechanism.
198	export function daysToFold(days, foldedThrough, today) {
199	  return Object.keys(days)
200	    .filter((d) => d < today && (!foldedThrough || d > foldedThrough))
201	    .sort();
202	}
203	
204	// Add one day row into its week row, append-once. `days` counts the rows absorbed,
205	// so a fold outage longer than a source's reach declares its own hole rather than
206	// under-reporting silently.
207	export function addDayToWeek(week, day) {
208	  const w = week ?? emptyBucket(WEEK_GROUPS);
209	  for (const group of WEEK_GROUPS) w[group] ??= {};
210	  add(w, 'days', 1);
211	  addRow(w, day, BUCKET_FIELDS);
212	  for (const group of WEEK_GROUPS) {
213	    for (const [key, row] of Object.entries(day[group] ?? {})) {
214	      // The latency map is SAMPLES keyed by item, not counters: a week absorbs each
215	      // sample as it stands rather than summing two days' readings of one item.
216	      if (group === 'latency') { w.latency[key] = { ...row }; continue; }
217	      const into = (w[group][key] ??= {});
218	      addRow(into, row, TASKS_USAGE_FIELDS[group]);
219	    }
220	  }
221	  return w;
222	}
223	
224	// --- the whole file ----------------------------------------------------------------
225	
226	export function foldTasksUsage({
227	  prior = {}, today, now = null, generated = null, minuteRate = null,
228	  runs = [], runsFoldedThrough = null, items = [], queueFoldedThrough = null,
229	}) {
230	  const withCosts = withItemCosts(runs, items);
231	  const days = foldDays({ prior: prior.days ?? {}, runs: withCosts, items, today, minuteRate });
232	  const weeks = structuredClone(prior.weeks ?? {});
233	  let foldedThrough = prior.foldedThrough ?? null;
234	
235	  for (const date of daysToFold(days, foldedThrough, today)) {
236	    const key = isoWeek(date);
237	    weeks[key] = addDayToWeek(weeks[key], days[date]);
238	    foldedThrough = date;
239	  }
240	
241	  return {
242	    generated,
243	    foldedThrough,
244	    runsFoldedThrough: runsFoldedThrough ?? prior.runsFoldedThrough ?? null,
245	    queueFoldedThrough: queueFoldedThrough ?? prior.queueFoldedThrough ?? null,
246	    // The rate every `spend` in this file was computed at. Carried forward from the
247	    // prior file when this repo declares none, so a file that once priced its rows
248	    // still says what they were priced at.
249	    minuteRate: minuteRate ?? prior.minuteRate ?? null,
250	    hours: sortKeys(foldHours({
251	      prior: prior.hours ?? {}, runs: withCosts, now: now ?? `${today}T23:59:59Z`, minuteRate,
252	    })),
253	    days: sortKeys(days),
254	    weeks: sortKeys(weeks),
255	  };
256	}
257	
258	export { WORKFLOW_FIELDS, RUN_FIELDS, LATENCY_FIELDS };
259

1	// tasks-usage-fold's own precondition term.
2	//
3	// The fold's trigger is MOVEMENT IN THE MACHINERY — a scheduler tick or an executor
4	// run that this file has not counted yet — and no built-in term can say that: every
5	// movement condition reads the project's commits, issues, pull requests and
6	// captures, and a repo whose only activity is its own queue is silent by all four.
7	//
8	// What the term reads instead is the file's OWN WATERMARK, which is the cheapest
9	// honest evidence there is: `runsFoldedThrough` advances on every fold that read a
10	// run, so a mark still standing before the scheduler's most recent anchor means at
11	// least one tick has come and gone unfolded. That is the mark's own movement rather
12	// than standing state — it flips false the moment a fold catches up, and true again
13	// at the next tick — and it costs no API call at all, which matters on a term asked
14	// at every tick of every day.
15	//
16	// WHAT IT CANNOT SEE, stated rather than implied: it does not know how MANY runs are
17	// waiting, only that the mark is behind. A repo whose scheduler has stopped
18	// entirely is not asked at all, so there is nothing for this term to decline there.
19	
20	import { readFileSync } from 'node:fs';
21	import { mostRecentAnchor } from '../../src/items/anchors.mjs';
22	import { decodeTasksUsageFile, TASKS_USAGE_PATH } from '../../src/items/tasks-usage-format.mjs';
23	
24	// The mark the last fold left, read from the checkout the run holds. Null for a repo
25	// that has never folded — which is movement by definition, since everything its
26	// machinery has ever done is unread.
27	export function foldedThroughAt(root) {
28	  try {
29	    return decodeTasksUsageFile(JSON.parse(readFileSync(`${root}/${TASKS_USAGE_PATH}`, 'utf8'))).runsFoldedThrough;
30	  } catch {
31	    return null;
32	  }
33	}
34	
35	export const terms = {
36	  'runs-since-fold': {
37	    signals: [],
38	    holds(_signals, { now }) {
39	      // The scheduler and the executor both run with the checkout as their working
40	      // directory, and the fold's own worker takes the same root the same way.
41	      const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
42	      const mark = foldedThroughAt(root);
43	      if (!mark) return { holds: true, reason: 'nothing has been folded yet — every run this repo has made is uncounted' };
44	      const at = mostRecentAnchor('daily', now).toISOString();
45	      return mark < at
46	        ? { holds: true, reason: `runs are folded through ${mark}, before this UTC day opened at ${at}: the machinery has run since` }
47	        : { holds: false, reason: `runs are folded through ${mark}, inside the UTC day that opened at ${at}: nothing has run since the last fold` };
48	    },
49	  },
50	};
51

1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	import { stripComments } from '../../../engine/checks/helpers/code-scanning.mjs';
3	import { CODE_WORK_ENV_VARS } from '../src/execute/code-work-run.mjs';
4	
5	// A task's code may read only the CLAUDINITE_* variables code-work is actually
6	// handed (`codeWorkEnv`, docs/PRINCIPLES.md). Anything else is a variable
7	// nobody sets, which fails in the one way nothing catches: `process.env.X` is
8	// `undefined`, the worker's parse of it yields an empty result, and the run goes
9	// green having quietly done something other than what it was asked.
10	//
11	// That is not hypothetical. Three fleet tasks took their parameters through
12	// `CLAUDINITE_OVERRIDES`, the slot scheduler's manual-run bag, which the queue has
13	// never set — so `REPOS` could not bound a sweep and `DRY_RUN` could not withhold
14	// its writes, and every run of the fleet-wide baseline lever was unscoped and live
15	// (#974). A dropped parameter channel defaults to the operation's most dangerous
16	// mode, not a safe one.
17	//
18	// GENERIC BY CONSTRUCTION: the legal set is the key set of the object the executor
19	// builds, imported rather than restated, so a variable added to or removed from the
20	// code-work contract changes what this accepts with no edit here.
21	// A task's own code. Tests are out: a test naming a retired variable is naming it
22	// as a fixture, which is exactly what a regression test for this rule must be free
23	// to do.
24	const TASK_FILE = /(^|\/)tasks\/[^/]+\/.+\.mjs$/;
25	const TEST_FILE = /\.test\.mjs$/;
26	const READS = /\bCLAUDINITE_[A-Z0-9_]+\b/g;
27	
28	const rule = {
29	  id: 'task-code-work-env',
30	  on_fail: 'block',
31	  description: 'A task\'s code reads only the CLAUDINITE_* environment variables code_work is handed (CLAUDINITE_REPO_ROOT, CLAUDINITE_REPO, CLAUDINITE_DEFAULT_BRANCH, CLAUDINITE_ITEM, CLAUDINITE_PACK, CLAUDINITE_TASK, CLAUDINITE_CONTEXT, CLAUDINITE_REQUEST_AGENT, CLAUDINITE_TARGET_MODE, CLAUDINITE_TARGET_BRANCH, CLAUDINITE_TARGET_PR)',
32	  doc: 'packs/claudinite-tasks/README.md',
33	  why: 'a variable nothing sets reads as undefined and the run still goes green — a parameter channel that has stopped being delivered leaves the operation in its unscoped, unguarded mode with no signal at all',
34	
35	  run(ctx) {
36	    const out = [];
37	    for (const file of ctx.files.filter((f) => TASK_FILE.test(f) && !TEST_FILE.test(f))) {
38	      const text = ctx.read(file);
39	      if (text === null) continue;
40	      // Comments strip in BOTH directions: this rule's own prose names the retired
41	      // variable, and so does any note explaining why a task stopped reading one.
42	      const seen = new Set(stripComments(text).match(READS) ?? []);
43	      for (const name of [...seen].sort()) {
44	        if (CODE_WORK_ENV_VARS.includes(name)) continue;
45	        out.push(finding(rule, {
46	          file,
47	          what: `reads \`${name}\`, which code_work never sets`,
48	          fix: `take the value from the item's Context (\`CLAUDINITE_CONTEXT\`, one line per bullet, set by \`create-work-item --context\`) — the code_work contract sets ${CODE_WORK_ENV_VARS.join(', ')} and nothing else`,
49	        }));
50	      }
51	    }
52	    return out;
53	  },
54	};
55	
56	export default rule;
57

