1	// Post-hoc enforcement of a task's declared outcome ceiling (per-project-scheduling
2	// docs/PRINCIPLES.md). The executor runs this in code AFTER the subagent finishes:
3	// the outcome is a ceiling enforced, not merely requested in prose, so a `none`
4	// task that opened a PR — or a task that merged one with nothing authorized —
5	// fails the run and converges to needs-human. "No change" is always legal.
6	//
7	// This seam judges LANE-LEVEL facts only (did the run open, did it merge). A
8	// granular `automerge` policy permits the merge here; whether the actual
9	// diff sat inside the policy is the policy engine's verdict (merge-policy.mjs),
10	// made where the tree is readable — the landing lane's CLI and the
11	// automerge-policy-scope work check.
12	//
13	// Pushes to non-default branches (e.g. the conversation-logs prune) are outside
14	// the PR taxonomy (PRINCIPLES.md) and are not judged here — the caller passes only
15	// what the task did to PULL REQUESTS.
16	
17	import { canonicalOutcome, opensPullRequest } from '../contract/task-contract.mjs';
18	import { normalizePolicy } from '../contract/merge-policy.mjs';
19	
20	// Verify what a task actually did against its declared ceiling.
21	//   outcome      - the declared outcome, one of `OUTCOMES`
22	//   automerge — the declared merge policy; absent reads as 'nothing', and an
23	//                  unparsable one the same — a permission that cannot be read
24	//                  was never granted
25	//   openedPr     — did the run open a pull request?
26	//   mergedPr     — did the run merge (or arm auto-merge on) a pull request?
27	// Returns { ok, violation } — violation is null when within the ceiling.
28	export function verifyOutcome({ outcome, automerge, openedPr = false, mergedPr = false }) {
29	  const ceiling = canonicalOutcome(outcome);
30	  const policy = automerge ?? 'nothing';
31	  if (!ceiling) {
32	    return { ok: false, violation: `unknown outcome ceiling "${outcome}"` };
33	  }
34	  // Merging implies a PR exists; treat a merge as also having opened one so a
35	  // caller that only reports mergedPr is still judged correctly.
36	  const opened = openedPr || mergedPr;
37	
38	  if (!opensPullRequest(ceiling) && opened) {
39	    return { ok: false, violation: `a "${ceiling}" task must not open or merge a pull request` };
40	  }
41	  if (mergedPr) {
42	    const norm = normalizePolicy(policy);
43	    if (norm.kind === 'nothing' || norm.kind === 'invalid') {
44	      return { ok: false, violation: 'a task whose automerge authorizes nothing must not merge a pull request' };
45	    }
46	  }
47	  return { ok: true, violation: null };
48	}
49

1	// The LOCAL-DISK half of the signal collectors' `ctx` (per-project-scheduling
2	// PRINCIPLES.md). Two collectors read facts off `ctx` that no GitHub read can
3	// supply — the shipped manifest version and whether this repo publishes at all
4	// (`release.manifestVersion`, `release.shipsPipeline`), and the configured log
5	// retention (`conversationLogs.retentionDays`). The scheduler runs Action-side
6	// INSIDE the repo checkout, so both are readable from the checkout itself:
7	// no API call, no rate budget, no base64 round-trip, and the tree read is the
8	// same tree the run would ship.
9	//
10	// This deliberately sits BESIDE the collectors rather than inside them. The
11	// collectors stay pure over an injected `ctx` (`ctx.X ?? null`), so the whole
12	// signal layer still unit-tests against a fake `gh` with no repo on disk; this
13	// module is the one place that touches the filesystem, and signals/context.mjs folds its
14	// result into the ctx it hands the collectors.
15	
16	import { readFileSync, readdirSync } from 'node:fs';
17	import { join } from 'node:path';
18	
19	// Where a repo's own packs live. One definition, shared by the `localPacks`
20	// collector's path test and the fleet reader's per-member window scan, so "where
21	// a local pack lives" cannot drift between the two. Spelled '/'-separated because
22	// both readers match paths that came off git or the GitHub API.
23	export const LOCAL_PACK_ROOT = '.claudinite/local/packs/';
24	
25	// Where a browser-extension manifest may sit, in the order the retired gate
26	// probed them (recovered from the pack's deleted run_daily gate): the first one
27	// carrying a `version` wins. Absent/unparsable/versionless → null, which the
28	// consuming precondition reads as "no manifest version to judge".
29	const MANIFEST_PATHS = ['manifest.json', 'src/manifest.json', 'public/manifest.json', 'dist/manifest.json'];
30	
31	function readManifestVersion(root) {
32	  for (const path of MANIFEST_PATHS) {
33	    let json;
34	    try { json = JSON.parse(readFileSync(join(root, path), 'utf8')); } catch { continue; }
35	    if (json?.version) return String(json.version);
36	  }
37	  return null;
38	}
39	
40	// Does this repo PUBLISH — does it carry the release orchestrator (by `name:`, since
41	// a repo may host the pipeline's own reusable workflows at the same paths without
42	// being a publisher, as Claudinite's core tree does) or a release config? Either is
43	// enough, and the pair is the release standard's own test.
44	//
45	// The spelling lives here rather than being imported because the engine depends on no
46	// pack; the release pack's own SHIPS_PIPELINE_* regexes are the other copy, and the
47	// drift test beside them fails if the two disagree.
48	const SHIPS_PIPELINE_TEXT = /^(?:name:\s*['"]?(?:Release to Chrome Store|Release)['"]?\s*|manifest_path=.*)$/m;
49	
50	function readShipsReleasePipeline(root) {
51	  const candidates = [];
52	  try {
53	    for (const e of readdirSync(join(root, '.github/workflows'), { withFileTypes: true })) {
54	      if (e.isFile() && /\.ya?ml$/.test(e.name)) candidates.push(join('.github/workflows', e.name));
55	    }
56	  } catch { /* no workflows directory — the release config may still say it ships */ }
57	  candidates.push('.github/release.config');
58	  return candidates.some((rel) => {
59	    try { return SHIPS_PIPELINE_TEXT.test(readFileSync(join(root, rel), 'utf8')); } catch { return false; }
60	  });
61	}
62	
63	// The log-retention window, in days, from the declared packs' entry config
64	// (`retention_days` in .claudinite-settings.json). Read through the caller's
65	// existing per-pack config reader rather than a second settings parser, and
66	// keyed by the PARAMETER, not by a pack name — core does not name the pack that
67	// happens to declare it. First declared pack carrying a numeric value wins.
68	function readRetentionDays(packIds, packConfigFor) {
69	  for (const id of packIds) {
70	    const value = packConfigFor(id)?.retention_days;
71	    if (typeof value === 'number' && Number.isFinite(value)) return value;
72	  }
73	  return null;
74	}
75	
76	// The ctx facts, read off the checkout at `root`. Every probe degrades to
77	// null/false rather than throwing: a missing file, an unreadable directory, and
78	// malformed JSON are all "nothing to judge", never a failed scheduler run.
79	export function localSignalContext(root, { packIds = [], packConfigFor = () => ({}) } = {}) {
80	  return {
81	    manifestVersion: readManifestVersion(root),
82	    shipsReleasePipeline: readShipsReleasePipeline(root),
83	    retentionDays: readRetentionDays(packIds, packConfigFor),
84	  };
85	}
