1	// The usage fold's FOURTH source: what each merged pull request took.
2	//
3	// The dashboard's lead-time figures — issue → merged, session → merged, opened →
4	// merged — reach further back than one page of live issue reads, so they come from
5	// here. What this carries is DURATIONS, one row per merged PR, never percentiles: a
6	// week's p50 is not derivable from its days' p50s, so the quantile is the reader's
7	// reduction over whatever window it draws and the fold's job is to carry the sample.
8	//
9	// APPEND-ONCE past `prsFoldedThrough`, bounded on `merged_at` for the same reason the
10	// queue read is bounded on `closed_at`: a merge is settled and never moves, so an item
11	// is counted on the one fold that first sees it and never again.
12	//
13	// FAIL-SOFT per source, like every other read here: an unreadable listing costs the PR
14	// rows this run and leaves the mark where it was. A closing issue that cannot be read
15	// costs that one PR's `issueLeadHours` and nothing else.
16	
17	import { lookbackFrom } from './read-queue.mjs';
18	// The two pure field derivations, in their own module so the page that shares them
19	// never loads this file's reader with them.
20	import { closesIssueIn, hoursBetween } from '../../src/items/pr-fields.mjs';
21	
22	export { closesIssueIn, hoursBetween };
23	
24	// The listing, plus one narrow read per merged PR that names a closing issue.
25	// `{ prs, watermark, error? }`.
26	export async function readMergedPrs({ reader, repo, since, now, maxPages = 5 }) {
27	  // The pulls endpoint takes no `since`, so the window is applied here: on a first read
28	  // with no mark, the day tier's own width, so one fold populates the whole window.
29	  const from = since || lookbackFrom(now);
30	  const prs = [];
31	  try {
32	    for (let page = 1; page <= maxPages; page += 1) {
33	      const batch = await reader.json(
34	        `/repos/${repo}/pulls?state=closed&sort=updated&direction=desc&per_page=100&page=${page}`,
35	      );
36	      if (!Array.isArray(batch) || batch.length === 0) break;
37	      for (const pr of batch) {
38	        const mergedAt = pr?.merged_at ?? null;
39	        if (!mergedAt || mergedAt <= from) continue;
40	        prs.push({
41	          number: pr.number,
42	          mergedAt,
43	          createdAt: pr?.created_at ?? null,
44	          closesIssue: closesIssueIn(pr?.body),
45	          issueCreatedAt: null,
46	        });
47	      }
48	      if (batch.length < 100) break;
49	    }
50	  } catch {
51	    return { prs: [], watermark: since, error: 'the merged pull requests could not be listed' };
52	  }
53	
54	  for (const pr of prs) {
55	    if (pr.closesIssue === null) continue;
56	    try {
57	      const issue = await reader.json(`/repos/${repo}/issues/${pr.closesIssue}`);
58	      pr.issueCreatedAt = issue?.created_at ?? null;
59	    } catch { /* one unreadable issue costs its own lead time and no other row */ }
60	  }
61	
62	  const newest = prs.map((p) => p.mergedAt).sort().pop() ?? null;
63	  return { prs, watermark: newest ?? since ?? null };
64	}
65	
66	// The listing and the capture files, joined into the day-row records `foldPrs` takes.
67	//
68	// `sessionToMergeHours` is the one figure neither source answers alone: the session
69	// that did the work is the capture file whose NAME carries this PR's number — or,
70	// for a capture keyed to an issue, the number of the issue this PR closes — and its
71	// earliest stamp is when that work started. A PR nothing captured under — or whose
72	// capture has aged out of the logs branch's retention — has no session end, and the
73	// slot is `null` rather than a zero.
74	export function prRecordsFrom({ prs = [], files = [] }) {
75	  const startedByPr = new Map();
76	  const startedByIssue = new Map();
77	  for (const file of files) {
78	    if (!file?.stamp) continue;
79	    const [map, key] = file.pr > 0 ? [startedByPr, file.pr] : file.issue > 0 ? [startedByIssue, file.issue] : [];
80	    if (!map) continue;
81	    const first = map.get(key);
82	    if (first === undefined || file.stamp < first) map.set(key, file.stamp);
83	  }
84	  const started = (pr) => startedByPr.get(pr.number) ?? (pr.closesIssue ? startedByIssue.get(pr.closesIssue) : null) ?? null;
85	  return prs.map((pr) => ({
86	    date: pr.mergedAt.slice(0, 10),
87	    number: pr.number,
88	    leadHours: hoursBetween(pr.createdAt, pr.mergedAt),
89	    issueLeadHours: hoursBetween(pr.issueCreatedAt, pr.mergedAt),
90	    sessionToMergeHours: hoursBetween(started(pr), pr.mergedAt),
91	  }));
92	}
93

1	// The usage fold's SECOND source: what the repo's own machinery did, per hour. The
2	// capture files say what happened inside a session; this says how often a session was
3	// started at all — and, more to the point, how often the scheduler ran and decided
4	// there was nothing to start.
5	//
6	// TWO WORKFLOWS, ONE LISTING EACH. The scheduler's runs and the executor's, filtered
7	// to completed ones, newest-first from the API and returned oldest-first so a
8	// truncated pass leaves a watermark the next fold continues from.
9	//
10	// IT READS NO JOB LOGS. Its predecessor did — two calls per run — to recover the slot
11	// scheduler's per-task records, and that writer is gone (#974): nothing has printed
12	// one since, so those calls now buy nothing at any cadence, let alone hourly. What a
13	// run DID with each task is read from the queue's own items instead (read-queue.mjs),
14	// which is the record that replaced it. So the cost here is two calls per fold, flat,
15	// however many runs are in the window.
16	//
17	// FORWARD-ONLY, past `runsFoldedThrough`, and only over COMPLETED runs — an
18	// in-progress run has no conclusion to count, and leaving the watermark behind it is
19	// what lets the next fold count it properly rather than as a run that never failed.
20	//
21	// FAIL-SOFT. An unreadable listing degrades this one source to "nothing new this run"
22	// and leaves the watermark where it was; the capture-derived counts do not depend on
23	// it and must not be lost with it.
24	
25	import { SCHEDULER_WORKFLOW_FILE, EXECUTOR_WORKFLOW_FILE } from '../../src/world/actions.mjs';
26	
27	const API = process.env.GITHUB_API_URL || 'https://api.github.com';
28	
29	// The two workflows and the name each is counted under in the hour rows. The words are
30	// the aggregate's own counter keys (`usage-format.mjs`), so they are spelled once.
31	export const WATCHED_WORKFLOWS = Object.freeze([
32	  { workflow: 'scheduler', file: SCHEDULER_WORKFLOW_FILE },
33	  { workflow: 'executor', file: EXECUTOR_WORKFLOW_FILE },
34	]);
35	
36	// How far back the FIRST fold looks when the aggregate carries no run watermark yet.
37	// The hour tier is three days wide, so anything older would be read and immediately
38	// pruned.
39	export const FIRST_FOLD_LOOKBACK_DAYS = 3;
40	
41	// A tiny REST reader — JSON only, since nothing here fetches a log any more.
42	// `fetchImpl` is injected so the tests drive it without a network.
43	export function makeReader({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
44	  const headers = {
45	    accept: 'application/vnd.github+json',
46	    'x-github-api-version': '2022-11-28',
47	    'user-agent': 'claudinite-usage-fold',
48	    ...(token ? { authorization: `Bearer ${token}` } : {}),
49	  };
50	  return {
51	    async json(path) {
52	      const res = await fetchImpl(`${api}${path}`, { headers });
53	      if (res.status !== 200) return null;
54	      try { return await res.json(); } catch { return null; }
55	    },
56	  };
57	}
58	
59	export const lookbackFrom = (nowIso, days = FIRST_FOLD_LOOKBACK_DAYS) =>
60	  new Date(new Date(nowIso).getTime() - days * 86400000).toISOString();
61	
62	// One workflow's completed runs started strictly after `since`, oldest first.
63	export async function workflowRuns(reader, repo, file, { since, maxPages = 3 }) {
64	  const runs = [];
65	  for (let page = 1; page <= maxPages; page += 1) {
66	    const path = `/repos/${repo}/actions/workflows/${file}/runs`
67	      + `?status=completed&per_page=100&page=${page}&created=%3E%3D${encodeURIComponent(String(since).slice(0, 10))}`;
68	    const json = await reader.json(path);
69	    const batch = json?.workflow_runs;
70	    if (!Array.isArray(batch) || batch.length === 0) break;
71	    for (const run of batch) {
72	      const at = run.run_started_at || run.created_at;
73	      if (!at || !run.id) continue;
74	      if (at <= since) continue;        // already folded (the `created` filter is day-grained)
75	      runs.push({ id: run.id, startedAt: at, conclusion: run.conclusion ?? null });
76	    }
77	    if (batch.length < 100) break;
78	  }
79	  return runs;
80	}
81	
82	// The whole read: `{ runs, watermark, error? }`.
83	//   runs      — [{ startedAt, workflow, conclusion, id }], oldest first across both
84	//               workflows, so the hour rows accumulate in order.
85	//   watermark — the new `runsFoldedThrough`: the newest run start actually read, or
86	//               the old mark when nothing was read. One mark for both workflows, which
87	//               is safe because it only ever moves to a time both listings were read
88	//               past.
89	export async function readRuns({ reader, repo, since, now }) {
90	  const from = since || lookbackFrom(now);
91	  const runs = [];
92	  try {
93	    for (const { workflow, file } of WATCHED_WORKFLOWS) {
94	      for (const run of await workflowRuns(reader, repo, file, { since: from })) {
95	        runs.push({ ...run, workflow });
96	      }
97	    }
98	  } catch {
99	    return { runs: [], watermark: since, error: 'the workflow run listings could not be read' };
100	  }
101	  runs.sort((a, b) => (a.startedAt < b.startedAt ? -1 : a.startedAt > b.startedAt ? 1 : a.id - b.id));
102	  return { runs, watermark: runs.length ? runs[runs.length - 1].startedAt : since };
103	}
104

1	// The coded production-validation grammar and judgment (#1530) — pure, no I/O.
2	// A verification issue states declarative PROBES on its first lines, each one
3	// URL and one assertion, in two classes with distinct failure meanings:
4	//
5	//   Live-probe:   <url> :: <assertion>   — the liveness gate. Any failing means
6	//                                          the release has not landed: the run
7	//                                          re-arms and comes back, and nothing
8	//                                          is judged.
9	//   Verify-probe: <url> :: <assertion>   — the verification itself, judged only
10	//                                          once every liveness probe passes. Any
11	//                                          failing is a real fault in production.
12	//
13	// Both classes are REQUIRED: without a liveness gate a verify failure cannot be
14	// told from a release that simply has not happened, and would reopen the
15	// original issue over nothing.
16	//
17	// Assertions, after the `::`:
18	//   status <n>                       the response code itself (the one op a
19	//                                    non-2xx response can pass)
20	//   [not ]contains <text>            body carries the literal text
21	//   [not ]matches /<re>/[flags]      body matches the JS regex
22	//   json <path> exists               dotted path resolves to a value
23	//   json <path> == <value>           strict-deep equality with the JSON value
24	//   json <path> != <value>           its negation
25	//   json <path> >= <value>           dotted identifiers compared segment-wise
26	//                                    numeric — '60821.10' is ten past '60821.3',
27	//                                    where floats and string order both lie
28	
29	export const LIVE_FIELD = 'Live-probe';
30	export const VERIFY_FIELD = 'Verify-probe';
31	export const RETRY_FIELD = 'Retry-every';
32	export const ORIGINAL_FIELD = 'Original-issue';
33	
34	const UNIT_MS = { minute: 60_000, hour: 3_600_000, day: 86_400_000, week: 7 * 86_400_000 };
35	
36	// `<count> <unit>` and nothing else. Null for anything unreadable — absence is a
37	// problem the caller names, never a default cadence nobody chose.
38	export function parseRetryEvery(text) {
39	  const m = /^(\d+)\s*(minute|hour|day|week)s?$/i.exec(String(text ?? '').trim());
40	  return m ? Number(m[1]) * UNIT_MS[m[2].toLowerCase()] : null;
41	}
42	
43	// One assertion, or null for a line that reads as none. Values after json ops are
44	// JSON literals; one that does not parse is taken as a bare string, so
45	// `== fleet` and `== "fleet"` assert the same thing.
46	export function parseAssertion(text) {
47	  const s = String(text ?? '').trim();
48	  let m;
49	  if ((m = /^status\s+(\d{3})$/.exec(s))) return { op: 'status', status: Number(m[1]) };
50	  if ((m = /^(not\s+)?contains\s+(.+)$/.exec(s))) {
51	    return { op: 'contains', negate: !!m[1], text: m[2] };
52	  }
53	  if ((m = /^(not\s+)?matches\s+\/(.*)\/([a-z]*)$/.exec(s))) {
54	    try {
55	      // Compiled here so an unreadable pattern is a parse problem, not a run crash.
56	      void new RegExp(m[2], m[3]);
57	    } catch { return null; }
58	    return { op: 'matches', negate: !!m[1], source: m[2], flags: m[3] };
59	  }
60	  if ((m = /^json\s+(\S+)\s+exists$/.exec(s))) return { op: 'json-exists', path: m[1] };
61	  if ((m = /^json\s+(\S+)\s+(==|!=|>=)\s+(.+)$/.exec(s))) {
62	    const raw = m[3].trim();
63	    let value;
64	    try { value = JSON.parse(raw); } catch { value = raw; }
65	    const op = { '==': 'json-eq', '!=': 'json-ne', '>=': 'json-gte' }[m[2]];
66	    return { op, path: m[1], value };
67	  }
68	  return null;
69	}
70	
71	// Dotted identifiers compared segment-wise numeric, a missing segment counting
72	// zero. Kept string-typed end to end — '60820.10' and '60820.1' are different
73	// versions and the same float. A non-numeric segment falls back to string order
74	// for that segment.
75	export function compareDotted(a, b) {
76	  const as = String(a).split('.');
77	  const bs = String(b).split('.');
78	  for (let i = 0; i < Math.max(as.length, bs.length); i += 1) {
79	    const [x, y] = [as[i] ?? '0', bs[i] ?? '0'];
80	    const [nx, ny] = [Number(x), Number(y)];
81	    const cmp = Number.isNaN(nx) || Number.isNaN(ny)
82	      ? x.localeCompare(y)
83	      : nx - ny;
84	    if (cmp !== 0) return cmp < 0 ? -1 : 1;
85	  }
86	  return 0;
87	}
88	
89	const dig = (value, path) => path.split('.').reduce(
90	  (v, seg) => (v !== null && typeof v === 'object' ? v[seg] : undefined), value);
91	
92	const deepEq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
93	
94	// Judge one assertion against one response ({ status, body }). Returns
95	// { ok, observed } — the observation is what was actually read, which is the
96	// evidence half of every verdict this task reports.
97	export function evaluateAssertion(assertion, { status, body }) {
98	  if (assertion.op === 'status') {
99	    return { ok: status === assertion.status, observed: `HTTP ${status}` };
100	  }
101	  if (status < 200 || status >= 300) return { ok: false, observed: `HTTP ${status}` };
102	  if (assertion.op === 'contains') {
103	    const found = body.includes(assertion.text);
104	    return { ok: found !== assertion.negate, observed: found ? 'text present' : 'text absent' };
105	  }
106	  if (assertion.op === 'matches') {
107	    const found = new RegExp(assertion.source, assertion.flags).test(body);
108	    return { ok: found !== assertion.negate, observed: found ? 'pattern present' : 'pattern absent' };
109	  }
110	  // The json ops.
111	  let parsed;
112	  try { parsed = JSON.parse(body); } catch { return { ok: false, observed: 'body is not JSON' }; }
113	  const actual = dig(parsed, assertion.path);
114	  const observed = actual === undefined ? `${assertion.path} absent` : `read ${JSON.stringify(actual)}`;
115	  if (assertion.op === 'json-exists') return { ok: actual !== undefined, observed };
116	  if (actual === undefined) return { ok: assertion.op === 'json-ne', observed };
117	  if (assertion.op === 'json-eq') return { ok: deepEq(actual, assertion.value), observed };
118	  if (assertion.op === 'json-ne') return { ok: !deepEq(actual, assertion.value), observed };
119	  return { ok: compareDotted(actual, assertion.value) >= 0, observed };
120	}
121	
122	// Parse a verification issue's human text into the spec the worker runs. Every
123	// gap or unreadable line is a PROBLEM by name — the item then parks with the
124	// list rather than half-running a spec that silently dropped a probe.
125	export function parseVerificationSpec(text) {
126	  const problems = [];
127	  const live = [];
128	  const verify = [];
129	  const probeRe = new RegExp(`^(${LIVE_FIELD}|${VERIFY_FIELD}):[ \\t]*(.*)$`, 'gm');
130	  for (const m of String(text ?? '').matchAll(probeRe)) {
131	    const [field, rest] = [m[1], m[2].trim()];
132	    const parts = /^(\S+)\s*::\s*(.+)$/.exec(rest);
133	    const url = parts?.[1] ?? null;
134	    const assertion = parts ? parseAssertion(parts[2]) : null;
135	    if (!url || !/^https?:\/\//.test(url) || !assertion) {
136	      problems.push(`unreadable ${field} line: \`${rest}\` — expected \`https://… :: <assertion>\``);
137	      continue;
138	    }
139	    (field === LIVE_FIELD ? live : verify).push({ url, assertion, raw: parts[2].trim() });
140	  }
141	  const originalIssue = (() => {
142	    const m = new RegExp(`^${ORIGINAL_FIELD}:[ \\t]*#?(\\d+)`, 'm').exec(String(text ?? ''));
143	    return m ? Number(m[1]) : null;
144	  })();
145	  const retryRaw = new RegExp(`^${RETRY_FIELD}:[ \\t]*(.+)$`, 'm').exec(String(text ?? ''))?.[1]?.trim() ?? null;
146	  const retryEveryMs = parseRetryEvery(retryRaw);
147	
148	  if (!live.length) problems.push(`no ${LIVE_FIELD}: line — without a liveness gate, "not deployed yet" and "deployed and broken" are indistinguishable`);
149	  if (!verify.length) problems.push(`no ${VERIFY_FIELD}: line — nothing would be verified`);
150	  if (!originalIssue) problems.push(`no ${ORIGINAL_FIELD}: line — a failing verification would have nowhere to land`);
151	  if (!retryEveryMs) problems.push(`no readable ${RETRY_FIELD}: line — expected \`<count> <minutes|hours|days|weeks>\``);
152	  return { originalIssue, retryEveryMs, retryRaw, live, verify, problems };
153	}
154	
155	// Run one probe class. Each URL is fetched ONCE however many probes read it;
156	// `fetchUrl(url)` resolves to { status, body } or throws, and a throw fails the
157	// probe with the error as its observation rather than the run.
158	export async function runProbes(probes, fetchUrl) {
159	  const responses = new Map();
160	  const results = [];
161	  for (const probe of probes) {
162	    if (!responses.has(probe.url)) {
163	      responses.set(probe.url, await fetchUrl(probe.url).catch((e) => ({ error: e.message })));
164	    }
165	    const response = responses.get(probe.url);
166	    results.push(response.error
167	      ? { probe, ok: false, observed: `fetch failed: ${response.error}` }
168	      : { probe, ...evaluateAssertion(probe.assertion, response) });
169	  }
170	  return results;
171	}
172	
173	export const renderResult = ({ probe, ok, observed }) =>
174	  `${ok ? 'PASS' : 'FAIL'} — ${probe.url} :: ${probe.raw} — ${observed}`;
175

